RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT EXISTS (SELECT 1 FROM pm.contacts WHERE id = p_contact_id AND deleted_at IS NULL)
$$;

