RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT EXISTS (
    SELECT 1 FROM pm.portal_updates update_row
    JOIN pm.projects project ON project.id = update_row.project_id
    WHERE update_row.id = p_update_id AND update_row.deleted_at IS NULL AND project.deleted_at IS NULL
