-- ============================================================
-- FUNCTION GRANTS (20261123000400_function_grants.sql)
-- The anon key executes no pm function; members (authenticated) execute only
-- what policies, defaults, checks and the app's session RPCs need.
-- ============================================================

DO $grants$
DECLARE
  -- Functions a signed-in member may execute.
  member_functions text[] := ARRAY[
    -- Row policies (pm tables and storage) call these as the member.
    'can_access_file_entity', 'can_access_lead', 'can_access_project', 'can_access_task',
    'can_manage_inbox', 'can_read_activity', 'can_read_all_tasks', 'can_read_inbox',
    'can_read_message', 'can_read_task_row', 'can_see_reminder', 'current_team_member_id',
    'current_team_member_role', 'has_permission', 'module_enabled',
    'contact_is_live', 'credential_is_live', 'file_entity_is_live', 'invoice_is_live',
    'lead_is_live', 'portal_update_is_live', 'project_is_live', 'retainer_is_live',
    'task_is_live', 'time_entry_is_live',
    -- Column defaults and check constraints evaluate these on a member's write.
    'workspace_currency', 'email_inbox_verification_code', 'email_is_address',
    'email_is_hostname', 'email_domain_is_public',
    -- RPCs the browser and session clients call.
    'save_task', 'convert_lead', 'requeue_webhook_delivery', 'mark_task_seen',
    'mark_tasks_seen', 'my_task_updates', 'agent_analytics_window',
    'save_project_invoice_with_allocations', 'project_invoice_payments',
    'record_invoice_payment', 'remove_invoice_payment', 'save_project_retainer',
    'schedule_retainer_amount', 'set_retainer_shares', 'generate_retainer_period',
    'retainer_due_periods', 'save_project_billing_plan', 'billing_forecast',
    'set_invoice_line_shares', 'list_trash', 'soft_delete_record', 'restore_record',
    'suggest_project_invoice_number', 'retainer_accruing_lines', 'set_credential_members',
    'review_time_entries', 'record_team_member_payout', 'set_task_parent',
    -- agent_analytics_window runs as the caller and calls these.
    'agent_analytics_int', 'agent_analytics_num', 'agent_analytics_ts',
    -- Read-only and scoped to the caller; kept for installs' own code.
    'is_admin', 'get_team_directory', 'get_my_access_context',
    'get_accessible_time_entries', 'get_accessible_credential_metadata', 'invoice_hours_draft'
  ];
  fn record;
  target text;
BEGIN
  FOR fn IN
    SELECT p.oid, p.proname, p.prokind,
           format('%I.%I(%s)', n.nspname, p.proname, pg_get_function_identity_arguments(p.oid)) AS signature,
           has_function_privilege('service_role', p.oid, 'EXECUTE') AS service_had
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'pm'
      AND p.prokind IN ('f', 'p')
      AND p.prorettype NOT IN ('trigger'::regtype, 'event_trigger'::regtype)
      AND NOT EXISTS (
        SELECT 1 FROM pg_depend d
        WHERE d.classid = 'pg_proc'::regclass AND d.objid = p.oid AND d.deptype = 'e'
      )
  LOOP
    target := CASE WHEN fn.prokind = 'p' THEN 'PROCEDURE ' ELSE 'FUNCTION ' END || fn.signature;
    EXECUTE 'REVOKE EXECUTE ON ' || target || ' FROM PUBLIC, anon';
    IF fn.proname = ANY (member_functions) THEN
      EXECUTE 'GRANT EXECUTE ON ' || target || ' TO authenticated';
    ELSE
      EXECUTE 'REVOKE EXECUTE ON ' || target || ' FROM authenticated';
    END IF;
    -- Revoking PUBLIC must not take away what the service role ran before.
    IF fn.service_had THEN
      EXECUTE 'GRANT EXECUTE ON ' || target || ' TO service_role';
    END IF;
  END LOOP;
END
$grants$;

ALTER DEFAULT PRIVILEGES IN SCHEMA pm REVOKE EXECUTE ON FUNCTIONS FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA pm_custom REVOKE EXECUTE ON FUNCTIONS FROM anon;

-- ============================================================
-- AGENT WORK BLOCKS (20261124000000_agent_work_blocks.sql)
-- Claims (work leases, and assignments a claim made going back to the pool),
-- incident keys (one open task per dedupe_key, repeats counted on it) and
-- per-agent rules (self-assign, close and create policy, escalation). Claims
-- and repeat counts are bookkeeping, not edits. Claim and pick-up functions
-- are service role only.
-- ============================================================

-- ---------------------------------------------------------------------------
-- Columns
-- ---------------------------------------------------------------------------

ALTER TABLE pm.tasks
  ADD COLUMN IF NOT EXISTS claimed_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS claimed_at timestamptz,
  ADD COLUMN IF NOT EXISTS claim_expires_at timestamptz,
  ADD COLUMN IF NOT EXISTS dedupe_key text,
  ADD COLUMN IF NOT EXISTS occurrences integer NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS last_occurred_at timestamptz,
  ADD COLUMN IF NOT EXISTS claim_assigned boolean NOT NULL DEFAULT false;

ALTER TABLE pm.tasks DROP CONSTRAINT IF EXISTS tasks_dedupe_key_length;
ALTER TABLE pm.tasks
  ADD CONSTRAINT tasks_dedupe_key_length CHECK (dedupe_key IS NULL OR length(dedupe_key) BETWEEN 1 AND 200);
ALTER TABLE pm.tasks DROP CONSTRAINT IF EXISTS tasks_occurrences_positive;
ALTER TABLE pm.tasks
  ADD CONSTRAINT tasks_occurrences_positive CHECK (occurrences >= 1);

COMMENT ON COLUMN pm.tasks.claimed_by IS
  'The member working on this task right now (a work lease). Free again once claim_expires_at has passed.';
COMMENT ON COLUMN pm.tasks.claim_expires_at IS
  'When the claim runs out unless the holder extends it. A past time means the task is free.';
COMMENT ON COLUMN pm.tasks.claim_assigned IS
  'The claim assigned its holder (it picked up unassigned work): releasing it unassigns the holder, and once it runs out another member may claim the task, which moves the assignment.';
COMMENT ON COLUMN pm.tasks.dedupe_key IS
  'An incident key: while this task is open, creating a task with the same key in the project counts a repeat here instead.';
COMMENT ON COLUMN pm.tasks.occurrences IS
  'How many times the incident behind this task happened (1 for a task without repeats).';

-- One open task per incident key in a project; a done or trashed task frees the key.
CREATE UNIQUE INDEX IF NOT EXISTS tasks_open_dedupe_key
  ON pm.tasks (project_id, dedupe_key)
  WHERE dedupe_key IS NOT NULL AND status <> 'done' AND deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_tasks_claimed_by
  ON pm.tasks (claimed_by) WHERE claimed_by IS NOT NULL;

ALTER TABLE pm.team_members
  ADD COLUMN IF NOT EXISTS agent_self_assign boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS agent_close_policy text NOT NULL DEFAULT 'close',
  ADD COLUMN IF NOT EXISTS agent_create_policy text NOT NULL DEFAULT 'live',
  ADD COLUMN IF NOT EXISTS agent_escalate_to uuid REFERENCES pm.team_members(id) ON DELETE SET NULL;

ALTER TABLE pm.team_members DROP CONSTRAINT IF EXISTS team_members_agent_close_policy_check;
ALTER TABLE pm.team_members
  ADD CONSTRAINT team_members_agent_close_policy_check CHECK (agent_close_policy IN ('close', 'review'));
ALTER TABLE pm.team_members DROP CONSTRAINT IF EXISTS team_members_agent_create_policy_check;
ALTER TABLE pm.team_members
  ADD CONSTRAINT team_members_agent_create_policy_check CHECK (agent_create_policy IN ('live', 'approval'));
ALTER TABLE pm.team_members DROP CONSTRAINT IF EXISTS team_members_agent_escalate_not_self;
ALTER TABLE pm.team_members
  ADD CONSTRAINT team_members_agent_escalate_not_self CHECK (agent_escalate_to IS DISTINCT FROM id);

COMMENT ON COLUMN pm.team_members.agent_self_assign IS
  'Agents only: may pick up (claim) unassigned work, which assigns it to them.';
COMMENT ON COLUMN pm.team_members.agent_close_policy IS
  'Agents only: close (setting done finishes the task) or review (done moves the task to in_review instead).';
COMMENT ON COLUMN pm.team_members.agent_create_policy IS
  'Agents only: live (new tasks go live) or approval (a new task becomes a task suggestion to approve).';
COMMENT ON COLUMN pm.team_members.agent_escalate_to IS
  'Agents only: who this agent escalates to. Unset: the Owner.';

ALTER TABLE pm.task_suggestions ALTER COLUMN goal_id DROP NOT NULL;

-- ---------------------------------------------------------------------------
-- Claims and repeats are bookkeeping, not edits
-- ---------------------------------------------------------------------------

-- Finishing a task also ends its claim (its assignment stays). Claims never
-- move updated_at. A task that is open again (reopened, restored from Trash,
-- moved to another project) gives up its incident key when another open task
-- in its project holds it now: that one keeps counting the repeats. Security
-- definer so it sees that task whoever makes the change.
CREATE OR REPLACE FUNCTION pm.handle_task_before_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF new.status = 'done' AND old.status IS DISTINCT FROM 'done' THEN
    new.completed_at = now();
    new.claimed_by = NULL;
    new.claimed_at = NULL;
    new.claim_expires_at = NULL;
    new.claim_assigned = false;
  ELSIF new.status IS DISTINCT FROM 'done' THEN
    new.completed_at = NULL;
  END IF;

  IF new.dedupe_key IS NOT NULL AND new.status <> 'done' AND new.deleted_at IS NULL
     AND (old.status = 'done' OR old.deleted_at IS NOT NULL OR new.project_id IS DISTINCT FROM old.project_id)
     AND EXISTS (
       SELECT 1 FROM pm.tasks t
       WHERE t.project_id = new.project_id AND t.dedupe_key = new.dedupe_key
         AND t.status <> 'done' AND t.deleted_at IS NULL AND t.id <> new.id
     ) THEN
    new.dedupe_key = NULL;
  END IF;

  IF (to_jsonb(new) - ARRAY['sort_order', 'updated_at', 'claimed_by', 'claimed_at', 'claim_expires_at', 'claim_assigned'])
     IS DISTINCT FROM (to_jsonb(old) - ARRAY['sort_order', 'updated_at', 'claimed_by', 'claimed_at', 'claim_expires_at', 'claim_assigned']) THEN
    new.updated_at = now();
  ELSE
    new.updated_at = old.updated_at;
  END IF;

  RETURN new;
END;
$$;

-- Any change to the claim holder's own assignment (a person or a PATCH
-- removing or adding them) makes it a person's: claim_assigned clears, so no
-- claim undoes it. The claim functions set it again after their own changes.
CREATE OR REPLACE FUNCTION pm.forget_claim_assignment()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    UPDATE pm.tasks SET claim_assigned = false
    WHERE id = OLD.task_id AND claim_assigned AND claimed_by = OLD.member_id;
  ELSE
    UPDATE pm.tasks SET claim_assigned = false
    WHERE id = NEW.task_id AND claim_assigned AND claimed_by = NEW.member_id;
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.forget_claim_assignment() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS forget_claim_assignment ON pm.task_assignees;
CREATE TRIGGER forget_claim_assignment
  AFTER INSERT OR DELETE ON pm.task_assignees
  FOR EACH ROW EXECUTE FUNCTION pm.forget_claim_assignment();

CREATE OR REPLACE FUNCTION pm.log_task_activity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_meta jsonb := jsonb_build_object('task_id', NEW.id, 'task_title', NEW.title);
  v_fields text[];
  v_ignore text[] := ARRAY['status', 'sort_order', 'completed_at', 'created_at', 'updated_at', 'deleted_at', 'deleted_by', 'parent_task_id',
    'claimed_by', 'claimed_at', 'claim_expires_at', 'claim_assigned', 'occurrences', 'last_occurred_at'];
  v_parent record;
BEGIN
  IF NEW.parent_task_id IS NOT NULL THEN
    SELECT id, title INTO v_parent FROM pm.tasks WHERE id = NEW.parent_task_id;
    v_meta := v_meta || jsonb_build_object('parent_task_id', v_parent.id, 'parent_task_title', v_parent.title);
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.parent_task_id IS NOT NULL THEN
      PERFORM pm.log_team_activity('subtask.added', 'task', NEW.id::text, NEW.project_id,
        format('Added subtask "%s" to "%s"', NEW.title, v_parent.title), v_meta);
    ELSE
      PERFORM pm.log_team_activity('task.created', 'task', NEW.id::text, NEW.project_id,
        format('Created task "%s"', NEW.title), v_meta);
    END IF;
    RETURN NULL;
  END IF;
  -- The Trash trigger logs moves to Trash and restores.
  IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    RETURN NULL;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'done' THEN
      PERFORM pm.log_team_activity('task.completed', 'task', NEW.id::text, NEW.project_id,
        format('Completed task "%s"', NEW.title), v_meta);
    ELSIF OLD.status = 'done' THEN
      PERFORM pm.log_team_activity('task.reopened', 'task', NEW.id::text, NEW.project_id,
        format('Reopened task "%s"', NEW.title), v_meta);
    ELSE
      PERFORM pm.log_team_activity('task.moved', 'task', NEW.id::text, NEW.project_id,
        format('Moved task "%s" to %s', NEW.title, pm.activity_status_label(NEW.status)),
        v_meta || jsonb_build_object('from', OLD.status, 'to', NEW.status));
    END IF;
  END IF;

  IF NEW.parent_task_id IS DISTINCT FROM OLD.parent_task_id THEN
    IF NEW.parent_task_id IS NOT NULL THEN
      PERFORM pm.log_team_activity('task.nested', 'task', NEW.id::text, NEW.project_id,
        format('Moved "%s" under "%s"', NEW.title, v_parent.title), v_meta);
    ELSE
      PERFORM pm.log_team_activity('task.promoted', 'task', NEW.id::text, NEW.project_id,
        format('Made "%s" a top-level task', NEW.title), v_meta || jsonb_build_object('from_parent_task_id', OLD.parent_task_id));
    END IF;
  END IF;

  -- A subtask's project follows its parent: the parent's move (or the
  -- nesting above) already says so.
  IF NEW.parent_task_id IS NOT NULL THEN
    v_ignore := v_ignore || ARRAY['project_id', 'project_goal_id'];
  END IF;
  v_fields := pm.activity_changed_fields(to_jsonb(NEW), to_jsonb(OLD), v_ignore);
  IF cardinality(v_fields) > 0 THEN
    PERFORM pm.log_team_activity('task.updated', 'task', NEW.id::text, NEW.project_id,
      format('Edited task "%s"', NEW.title), v_meta || jsonb_build_object('fields', to_jsonb(v_fields)));
  END IF;
  RETURN NULL;
END;
$$;

-- The task's own fields. Reordering, the completion stamp, Trash, the source
-- stamp, claims and repeat counts are not changes anyone needs to read.
CREATE OR REPLACE FUNCTION pm.record_task_row_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_ignore text[] := ARRAY['sort_order', 'completed_at', 'created_at', 'updated_at', 'deleted_at', 'deleted_by',
    'created_via', 'created_by_key_id', 'created_note',
    'claimed_by', 'claimed_at', 'claim_expires_at', 'claim_assigned', 'occurrences', 'last_occurred_at'];
BEGIN
  IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    RETURN NULL;
  END IF;
  -- A subtask moving with its parent is the parent's change, not its own.
  IF NEW.parent_task_id IS NOT NULL AND NEW.parent_task_id IS NOT DISTINCT FROM OLD.parent_task_id THEN
    v_ignore := v_ignore || ARRAY['project_id', 'project_goal_id'];
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM pm.record_task_event(NEW.id, 'status');
  ELSIF cardinality(pm.activity_changed_fields(to_jsonb(NEW), to_jsonb(OLD), v_ignore)) > 0 THEN
    PERFORM pm.record_task_event(NEW.id, 'edit');
  END IF;
  RETURN NULL;
END;
$$;

-- ---------------------------------------------------------------------------
-- Claims
-- ---------------------------------------------------------------------------

-- Who holds a task's claim, for a refusal that says who and until when.
CREATE OR REPLACE FUNCTION pm.task_claim_holder(p_task pm.tasks)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT jsonb_build_object(
    'member_id', p_task.claimed_by,
    'member_name', (SELECT m.name FROM pm.team_members m WHERE m.id = p_task.claimed_by),
    'claimed_at', p_task.claimed_at,
    'expires_at', p_task.claim_expires_at
  )
$$;

REVOKE ALL ON FUNCTION pm.task_claim_holder(pm.tasks) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.task_claim_holder(pm.tasks) TO service_role;

-- Takes a task for p_member_id for p_lease_minutes (1 to 240), atomically:
-- only when nobody holds a live claim on it, or the same member already does
-- (then it renews and keeps claimed_at). A previous holder's claim that ran
-- out takes the assignment it made with it. p_assign also assigns the task to
-- the member (claim_assigned), only while nobody else is assigned. Who may
-- claim is decided by the caller (the API) before this runs. Outcomes:
-- claimed, renewed, held (someone else holds it: holder says who and until
-- when), assigned_elsewhere, not_found.
CREATE OR REPLACE FUNCTION pm.claim_task(
  p_task_id uuid,
  p_member_id uuid,
  p_lease_minutes integer DEFAULT 30,
  p_assign boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_task pm.tasks;
  v_renew boolean;
  v_same boolean;
  v_drop_previous boolean;
BEGIN
  IF p_member_id IS NULL THEN
    RAISE EXCEPTION 'A claim needs a member' USING ERRCODE = '22023';
  END IF;
  IF p_lease_minutes IS NULL OR p_lease_minutes < 1 OR p_lease_minutes > 240 THEN
    RAISE EXCEPTION 'A claim lasts 1 to 240 minutes' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_task FROM pm.tasks WHERE id = p_task_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;
  IF v_task.claimed_by IS NOT NULL AND v_task.claimed_by <> p_member_id AND v_task.claim_expires_at > now() THEN
    RETURN jsonb_build_object('outcome', 'held', 'holder', pm.task_claim_holder(v_task));
  END IF;
  v_same := v_task.claimed_by IS NOT DISTINCT FROM p_member_id;
  v_renew := v_same AND v_task.claim_expires_at > now();
  -- Someone else's claim is over here; an assignment it made goes with it.
  v_drop_previous := v_task.claimed_by IS NOT NULL AND NOT v_same AND v_task.claim_assigned;
  IF p_assign AND EXISTS (
    SELECT 1 FROM pm.task_assignees
    WHERE task_id = p_task_id AND member_id <> p_member_id
      AND NOT (v_drop_previous AND member_id = v_task.claimed_by)
  ) THEN
    RETURN jsonb_build_object('outcome', 'assigned_elsewhere');
  END IF;
  IF v_drop_previous THEN
    DELETE FROM pm.task_assignees WHERE task_id = p_task_id AND member_id = v_task.claimed_by;
  END IF;
  IF p_assign THEN
    INSERT INTO pm.task_assignees (task_id, member_id) VALUES (p_task_id, p_member_id)
    ON CONFLICT (task_id, member_id) DO NOTHING;
  END IF;
  UPDATE pm.tasks SET
    claimed_by = p_member_id,
    claimed_at = CASE WHEN v_renew THEN v_task.claimed_at ELSE now() END,
    claim_expires_at = now() + make_interval(mins => p_lease_minutes),
    claim_assigned = CASE WHEN v_same THEN v_task.claim_assigned OR p_assign ELSE p_assign END
  WHERE id = p_task_id
  RETURNING * INTO v_task;
  RETURN jsonb_build_object('outcome', CASE WHEN v_renew THEN 'renewed' ELSE 'claimed' END, 'task', to_jsonb(v_task));
END;
$$;

REVOKE ALL ON FUNCTION pm.claim_task(uuid, uuid, integer, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.claim_task(uuid, uuid, integer, boolean) TO service_role;

-- The holder renews its claim for p_lease_minutes from now (a heartbeat).
-- Outcomes: extended, held (someone else holds it now), not_held (nobody
-- does: claim it again), not_found.
CREATE OR REPLACE FUNCTION pm.extend_task_claim(
  p_task_id uuid,
  p_member_id uuid,
  p_lease_minutes integer DEFAULT 30
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_task pm.tasks;
BEGIN
  IF p_lease_minutes IS NULL OR p_lease_minutes < 1 OR p_lease_minutes > 240 THEN
    RAISE EXCEPTION 'A claim lasts 1 to 240 minutes' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_task FROM pm.tasks WHERE id = p_task_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;
  IF v_task.claimed_by IS NULL THEN
    RETURN jsonb_build_object('outcome', 'not_held');
  END IF;
  IF v_task.claimed_by <> p_member_id THEN
    IF v_task.claim_expires_at > now() THEN
      RETURN jsonb_build_object('outcome', 'held', 'holder', pm.task_claim_holder(v_task));
    END IF;
    RETURN jsonb_build_object('outcome', 'not_held');
  END IF;
  -- Still theirs (nobody took it since it ran out, if it did): renew it.
  UPDATE pm.tasks SET claim_expires_at = now() + make_interval(mins => p_lease_minutes)
  WHERE id = p_task_id
  RETURNING * INTO v_task;
  RETURN jsonb_build_object('outcome', 'extended', 'task', to_jsonb(v_task));
END;
$$;

REVOKE ALL ON FUNCTION pm.extend_task_claim(uuid, uuid, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.extend_task_claim(uuid, uuid, integer) TO service_role;

-- Ends a claim. The holder may; p_force lets a manager end anyone's. An
-- assignment the claim made (claim_assigned) is removed with it, so the task
-- goes back unassigned; a person's assignment stays. Outcomes: released
-- (holder says whose it was), not_claimed (no live claim, though one that ran
-- out is cleared the same way for its holder or a manager), held (someone
-- else's live claim and no p_force), not_found. unassigned says whether the
-- holder's assignment went.
CREATE OR REPLACE FUNCTION pm.release_task_claim(
  p_task_id uuid,
  p_member_id uuid,
  p_force boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_task pm.tasks;
  v_holder jsonb;
  v_live boolean;
  v_unassigned boolean := false;
BEGIN
  SELECT * INTO v_task FROM pm.tasks WHERE id = p_task_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;
  IF v_task.claimed_by IS NULL THEN
    RETURN jsonb_build_object('outcome', 'not_claimed', 'unassigned', false, 'task', to_jsonb(v_task));
  END IF;
  v_live := v_task.claim_expires_at > now();
  IF v_task.claimed_by <> p_member_id AND NOT coalesce(p_force, false) THEN
    IF v_live THEN
      RETURN jsonb_build_object('outcome', 'held', 'holder', pm.task_claim_holder(v_task));
    END IF;
    -- Someone else's claim that ran out: left for them, a manager or the next claim.
    RETURN jsonb_build_object('outcome', 'not_claimed', 'unassigned', false, 'task', to_jsonb(v_task));
  END IF;
  v_holder := pm.task_claim_holder(v_task);
  IF v_task.claim_assigned THEN
    DELETE FROM pm.task_assignees WHERE task_id = p_task_id AND member_id = v_task.claimed_by;
    v_unassigned := true;
  END IF;
  UPDATE pm.tasks SET claimed_by = NULL, claimed_at = NULL, claim_expires_at = NULL, claim_assigned = false
  WHERE id = p_task_id
  RETURNING * INTO v_task;
  RETURN jsonb_build_object('outcome', CASE WHEN v_live THEN 'released' ELSE 'not_claimed' END,
    'holder', v_holder, 'unassigned', v_unassigned, 'task', to_jsonb(v_task));
END;
$$;

REVOKE ALL ON FUNCTION pm.release_task_claim(uuid, uuid, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.release_task_claim(uuid, uuid, boolean) TO service_role;

-- The best task for a member to work on next, or no row. Tasks assigned to
-- them first; then, with p_include_unassigned, unassigned tasks meant for them
-- (an agent: ai_readiness ai_ready only; a person: not meant for an agent).
-- A task whose only assignee came from someone else's claim that ran out
-- counts as unassigned: it is back in the pool.
-- Left out: backlog, in review and done; Trash (the task, its parent, its
-- project); projects that are not active; unmet blockers (a blocker that is
-- not done and not in Trash); a live claim by someone else. Then by priority,
-- due date (none last) and age. p_project_ids is the projects the member may
-- open (NULL: every project); p_project_id narrows it to one.
CREATE OR REPLACE FUNCTION pm.next_task_for_member(
  p_member_id uuid,
  p_project_ids uuid[] DEFAULT NULL,
  p_project_id uuid DEFAULT NULL,
  p_include_unassigned boolean DEFAULT false,
  p_as_agent boolean DEFAULT true
)
RETURNS TABLE (task_id uuid, assigned boolean)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT t.id, mine.assigned
  FROM pm.tasks t
  JOIN pm.projects p ON p.id = t.project_id
  CROSS JOIN LATERAL (
    SELECT EXISTS (SELECT 1 FROM pm.task_assignees a WHERE a.task_id = t.id AND a.member_id = p_member_id) AS assigned,
           EXISTS (SELECT 1 FROM pm.task_assignees a WHERE a.task_id = t.id) AS anyone
  ) mine
  WHERE t.deleted_at IS NULL
    AND t.status IN ('todo', 'in_progress')
    AND p.deleted_at IS NULL
    AND p.status = 'active'
    AND p.archived_at IS NULL
    AND (p_project_ids IS NULL OR t.project_id = ANY (p_project_ids))
    AND (p_project_id IS NULL OR t.project_id = p_project_id)
    AND (t.parent_task_id IS NULL OR EXISTS (
      SELECT 1 FROM pm.tasks parent WHERE parent.id = t.parent_task_id AND parent.deleted_at IS NULL))
    AND NOT EXISTS (
      SELECT 1 FROM pm.task_dependencies d JOIN pm.tasks b ON b.id = d.blocked_by_task_id
      WHERE d.task_id = t.id AND b.deleted_at IS NULL AND b.status <> 'done')
    AND (t.claimed_by IS NULL OR t.claimed_by = p_member_id OR t.claim_expires_at IS NULL OR t.claim_expires_at <= now())
    AND (
      mine.assigned
      OR (p_include_unassigned AND (NOT mine.anyone OR (
            t.claim_assigned AND t.claimed_by <> p_member_id AND t.claim_expires_at <= now()
            AND NOT EXISTS (SELECT 1 FROM pm.task_assignees a WHERE a.task_id = t.id AND a.member_id <> t.claimed_by)
          )) AND CASE
            WHEN p_as_agent THEN t.ai_readiness IS NOT DISTINCT FROM 'ai_ready'
            ELSE t.ai_readiness IS NULL OR t.ai_readiness = 'human_only'
          END)
    )
  ORDER BY mine.assigned DESC,
    CASE t.priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,
    t.due_date ASC NULLS LAST,
    t.created_at ASC,
    t.id
  LIMIT 1
$$;

REVOKE ALL ON FUNCTION pm.next_task_for_member(uuid, uuid[], uuid, boolean, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.next_task_for_member(uuid, uuid[], uuid, boolean, boolean) TO service_role;

-- ---------------------------------------------------------------------------
-- Incident keys
-- ---------------------------------------------------------------------------

-- Counts a repeat on the open task holding p_dedupe_key in the project and
-- returns it, or NULL when no open task holds the key.
CREATE OR REPLACE FUNCTION pm.record_task_occurrence(p_project_id uuid, p_dedupe_key text)
RETURNS jsonb
LANGUAGE sql
SECURITY DEFINER
SET search_path = ''
AS $$
  WITH repeated AS (
    UPDATE pm.tasks
    SET occurrences = occurrences + 1, last_occurred_at = now()
    WHERE project_id = p_project_id
      AND dedupe_key = p_dedupe_key
      AND status <> 'done'
      AND deleted_at IS NULL
    RETURNING *
  )
  SELECT to_jsonb(repeated) FROM repeated
$$;

REVOKE ALL ON FUNCTION pm.record_task_occurrence(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.record_task_occurrence(uuid, text) TO service_role;

-- ============================================================
-- QUESTIONS (20261124000100_questions.sql)
-- One member asks another a question (on a task, a project or nothing), with
-- optional choices, and gets the answer back. Asking rings asked_to's bell;
-- answering, cancelling, expiring or Trash clears it. An open question past
-- expires_at reads as expired. Members read; only the server writes.
-- ============================================================

CREATE TABLE IF NOT EXISTS pm.questions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- A task's question always carries its task's project (set by the trigger).
  project_id uuid REFERENCES pm.projects(id) ON DELETE CASCADE,
  task_id uuid REFERENCES pm.tasks(id) ON DELETE CASCADE,
  asked_by uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  asked_to uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  question text NOT NULL,
  choices jsonb,
  allow_other boolean NOT NULL DEFAULT true,
  status text NOT NULL DEFAULT 'open',
  answer_choice text,
  answer_text text,
  answered_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  answered_at timestamptz,
  cancelled_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  cancelled_at timestamptz,
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- Trash: when it was deleted and by whom (null = live). Rows are never removed.
  deleted_at timestamptz,
  deleted_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL
);

ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_question_length;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_question_length CHECK (length(btrim(question)) BETWEEN 1 AND 2000);
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_status_check;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_status_check CHECK (status IN ('open', 'answered', 'cancelled', 'expired'));
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_choices_shape;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_choices_shape CHECK (
    choices IS NULL OR (jsonb_typeof(choices) = 'array' AND jsonb_array_length(choices) BETWEEN 1 AND 10));
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_answer_choice_listed;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_answer_choice_listed CHECK (
    answer_choice IS NULL OR (choices IS NOT NULL AND choices ? answer_choice));
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_answer_text_length;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_answer_text_length CHECK (answer_text IS NULL OR length(answer_text) BETWEEN 1 AND 5000);
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_answered_has_answer;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_answered_has_answer CHECK (
    status <> 'answered' OR (answered_at IS NOT NULL AND (answer_choice IS NOT NULL OR answer_text IS NOT NULL)));
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_task_has_project;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_task_has_project CHECK (task_id IS NULL OR project_id IS NOT NULL);

COMMENT ON TABLE pm.questions IS
  'A question one member asks another, on a task, a project or nothing, with optional choices. Written by the server only.';
COMMENT ON COLUMN pm.questions.allow_other IS
  'With choices: whether a free-text answer is allowed beside them. Without choices the answer is free text.';
COMMENT ON COLUMN pm.questions.expires_at IS
  'An open question past this time reads as expired; the server stores expired when it next reads questions.';

-- "Open questions to member X", and a task's or project's questions.
CREATE INDEX IF NOT EXISTS idx_questions_asked_to_open
  ON pm.questions (asked_to, created_at) WHERE status = 'open' AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_questions_asked_by ON pm.questions (asked_by, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_questions_task ON pm.questions (task_id, created_at) WHERE task_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_questions_project ON pm.questions (project_id) WHERE project_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_questions_expiring
  ON pm.questions (expires_at) WHERE status = 'open' AND expires_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_questions_deleted_at ON pm.questions (deleted_at DESC) WHERE deleted_at IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Normalise every write: the task's project, and the fields a later write may
-- not change.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.handle_question_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  task_project uuid;
BEGIN
  NEW.question := btrim(NEW.question);
  IF NEW.task_id IS NOT NULL THEN
    SELECT project_id INTO task_project FROM pm.tasks WHERE id = NEW.task_id;
    IF task_project IS NOT NULL THEN
      NEW.project_id := task_project;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.asked_by := OLD.asked_by;
    NEW.created_at := OLD.created_at;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_question_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS questions_before_write ON pm.questions;
CREATE TRIGGER questions_before_write
  BEFORE INSERT OR UPDATE ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.handle_question_before_write();

DROP TRIGGER IF EXISTS set_questions_updated_at ON pm.questions;
CREATE TRIGGER set_questions_updated_at
  BEFORE UPDATE ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

-- ---------------------------------------------------------------------------
-- Signals: asking rings asked_to's bell; a question that is no longer open
-- (answered, cancelled, expired, in Trash) takes its bell away, and one that
-- opens again brings it back.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.notify_question_asked()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  asker text;
BEGIN
  IF NEW.status <> 'open' OR NEW.deleted_at IS NOT NULL OR NEW.asked_to = NEW.asked_by THEN
    RETURN NULL;
  END IF;
  SELECT name INTO asker FROM pm.team_members WHERE id = NEW.asked_by;
  PERFORM pm.upsert_notification(
    NEW.asked_to,
    'Question from ' || COALESCE(NULLIF(btrim(asker), ''), 'a teammate'),
    left(NEW.question, 500),
    -- My Tasks, where the asked member answers it: they may not be able to
    -- open the task or project it is on.
    '/my-tasks',
    'question',
    NEW.id::text
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.notify_question_asked() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS notify_question_asked ON pm.questions;
CREATE TRIGGER notify_question_asked
  AFTER INSERT ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.notify_question_asked();

CREATE OR REPLACE FUNCTION pm.sync_question_notification()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF NEW.status <> 'open' OR NEW.deleted_at IS NOT NULL THEN
    PERFORM pm.set_notifications_cleared('question', NEW.id::text, true);
  ELSIF OLD.status <> 'open' OR OLD.deleted_at IS NOT NULL THEN
    PERFORM pm.set_notifications_cleared('question', NEW.id::text, false);
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.sync_question_notification() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS sync_question_notification ON pm.questions;
CREATE TRIGGER sync_question_notification
  AFTER UPDATE ON pm.questions
  FOR EACH ROW
  WHEN (NEW.status IS DISTINCT FROM OLD.status OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at)
  EXECUTE FUNCTION pm.sync_question_notification();

-- A task moved to another project takes its questions along.
CREATE OR REPLACE FUNCTION pm.sync_task_questions_project()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  UPDATE pm.questions SET project_id = NEW.project_id WHERE task_id = NEW.id;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.sync_task_questions_project() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS tasks_sync_questions_project ON pm.tasks;
CREATE TRIGGER tasks_sync_questions_project
  AFTER UPDATE OF project_id ON pm.tasks
  FOR EACH ROW
  WHEN (NEW.project_id IS DISTINCT FROM OLD.project_id)
  EXECUTE FUNCTION pm.sync_task_questions_project();

-- Never permanently deleted.
DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.questions;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.questions;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.questions
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

-- ---------------------------------------------------------------------------
-- Row level security: members read; only the server writes.
-- ---------------------------------------------------------------------------
ALTER TABLE pm.questions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS questions_select ON pm.questions;
CREATE POLICY questions_select ON pm.questions FOR SELECT TO authenticated
  USING (
    asked_by = pm.current_team_member_id()
    OR asked_to = pm.current_team_member_id()
    OR (task_id IS NOT NULL AND pm.can_access_task(task_id))
    OR (task_id IS NULL AND project_id IS NOT NULL AND pm.can_access_project(project_id))
  );

DROP POLICY IF EXISTS questions_not_deleted ON pm.questions;
CREATE POLICY questions_not_deleted ON pm.questions AS RESTRICTIVE FOR ALL TO authenticated
  USING (deleted_at IS NULL) WITH CHECK (deleted_at IS NULL);

DROP POLICY IF EXISTS questions_parent_live ON pm.questions;
CREATE POLICY questions_parent_live ON pm.questions AS RESTRICTIVE FOR ALL TO authenticated
  USING ((task_id IS NULL OR pm.task_is_live(task_id)) AND (project_id IS NULL OR pm.project_is_live(project_id)));

REVOKE ALL ON pm.questions FROM anon, authenticated;
GRANT SELECT ON pm.questions TO authenticated;
GRANT ALL ON pm.questions TO service_role;

-- Live sync: open screens see questions asked and answered as it happens.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime')
     AND NOT EXISTS (SELECT 1 FROM pg_publication_tables
                     WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'questions') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE pm.questions;
  END IF;
END $$;

-- ============================================================
-- AGENT WEBHOOKS (20261124000200_agent_webhooks.sql)
-- Task, comment, question, suggestion and review events on the webhook
-- outbox, ordered per subject. Endpoint filters: project_ids and member_id
-- (events that concern the member, pm.webhook_event_members). One
-- task.created or task.updated per task per transaction. Only invoice events
-- need Client invoicing.
-- ============================================================

-- ---------------------------------------------------------------------------
-- Endpoint filters
-- ---------------------------------------------------------------------------
ALTER TABLE pm.webhook_endpoints
  ADD COLUMN IF NOT EXISTS project_ids uuid[],
  ADD COLUMN IF NOT EXISTS member_id uuid REFERENCES pm.team_members(id) ON DELETE CASCADE;

ALTER TABLE pm.webhook_endpoints DROP CONSTRAINT IF EXISTS webhook_endpoints_project_ids_not_empty;
ALTER TABLE pm.webhook_endpoints
  ADD CONSTRAINT webhook_endpoints_project_ids_not_empty CHECK (project_ids IS NULL OR cardinality(project_ids) > 0);

COMMENT ON COLUMN pm.webhook_endpoints.project_ids IS
  'Only events on these projects (null: every project). An event with no project never matches a list.';
COMMENT ON COLUMN pm.webhook_endpoints.member_id IS
  'Only events that concern this member, as pm.webhook_event_members defines it (null: everyone). Goes with the member.';

-- ---------------------------------------------------------------------------
-- Who and whom
-- ---------------------------------------------------------------------------
-- The member behind the current write, person or agent: the signed-in
-- member, or for service-role writes the x-actor-member-id header the server
-- sends. NULL for SQL run directly, cron jobs and keys with no member.
CREATE OR REPLACE FUNCTION pm.webhook_actor_id()
RETURNS uuid
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_header text;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    RETURN pm.current_team_member_id();
  END IF;
  IF coalesce(auth.role(), '') = 'service_role' THEN
    BEGIN
      v_header := nullif(current_setting('request.headers', true), '')::json ->> 'x-actor-member-id';
    EXCEPTION WHEN others THEN
      v_header := NULL;
    END;
    IF v_header ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RETURN (SELECT m.id FROM pm.team_members m WHERE m.id = v_header::uuid);
    END IF;
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.webhook_actor_id() FROM PUBLIC, anon, authenticated;

-- Who an event concerns: the one definition behind an endpoint's member
-- filter and every payload's member_ids.
-- - A task (task.*, and comment.created and review.submitted, whose subject
--   is the task): its assignees and the holder of a live claim on it.
-- - A question: the member asked (asked_to) and the asker (asked_by).
-- - A suggestion: who proposed it and who it would be assigned to.
-- p_also adds the members a change took off the subject (an assignee who was
-- removed), so they hear about it too.
CREATE OR REPLACE FUNCTION pm.webhook_event_members(p_subject_type text, p_subject_id uuid, p_also uuid[] DEFAULT '{}')
RETURNS uuid[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT coalesce(array_agg(DISTINCT m ORDER BY m) FILTER (WHERE m IS NOT NULL), '{}')
  FROM (
    SELECT a.member_id AS m FROM pm.task_assignees a
    WHERE p_subject_type = 'task' AND a.task_id = p_subject_id
    UNION ALL
    SELECT t.claimed_by FROM pm.tasks t
    WHERE p_subject_type = 'task' AND t.id = p_subject_id
      AND (t.claim_expires_at IS NULL OR t.claim_expires_at > now())
    UNION ALL
    SELECT unnest(ARRAY[q.asked_to, q.asked_by]) FROM pm.questions q
    WHERE p_subject_type = 'question' AND q.id = p_subject_id
    UNION ALL
    SELECT unnest(ARRAY[s.proposed_by, s.assigned_to]) FROM pm.task_suggestions s
    WHERE p_subject_type = 'suggestion' AND s.id = p_subject_id
    UNION ALL
    SELECT unnest(coalesce(p_also, '{}'))
  ) members
$$;

REVOKE ALL ON FUNCTION pm.webhook_event_members(text, uuid, uuid[]) FROM PUBLIC, anon, authenticated;

-- Whether an endpoint receives an event: active, subscribed to its type, and
-- inside its filters. p_project_ids holds every project the event touches (a
-- task moved between projects touches both); p_member_ids is who it
-- concerns.
CREATE OR REPLACE FUNCTION pm.webhook_endpoint_matches(
  p_endpoint pm.webhook_endpoints,
  p_event_type text,
  p_project_ids uuid[],
  p_member_ids uuid[]
)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = pm
AS $$
  SELECT p_endpoint.is_active
    AND p_event_type = ANY (p_endpoint.events)
    AND (p_endpoint.project_ids IS NULL OR p_endpoint.project_ids && coalesce(p_project_ids, '{}'))
    AND (p_endpoint.member_id IS NULL OR p_endpoint.member_id = ANY (coalesce(p_member_ids, '{}')))
$$;

REVOKE ALL ON FUNCTION pm.webhook_endpoint_matches(pm.webhook_endpoints, text, uuid[], uuid[]) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- The event writer for everything but invoices
-- ---------------------------------------------------------------------------
-- Records one event and fans out one delivery per matching endpoint; writes
-- nothing when no endpoint matches. p_data becomes the payload's data, with
-- member_ids added.
--
-- p_folds_into: when the subject's latest event in this transaction is one of
-- these types (and nothing has been tried yet), it is refreshed instead: its
-- data becomes p_data, member_ids and changes become the union of both, and
-- endpoints that match now get a delivery too. Nothing else sees an event
-- before its transaction commits, so a refresh is never a change to
-- something sent.
CREATE OR REPLACE FUNCTION pm.emit_webhook_event(
  p_event_type text,
  p_subject_type text,
  p_subject_id uuid,
  p_project_ids uuid[],
  p_member_ids uuid[],
  p_data jsonb,
  p_folds_into text[] DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_latest pm.webhook_events;
  v_members uuid[] := coalesce(p_member_ids, '{}');
  v_data jsonb := coalesce(p_data, '{}'::jsonb);
  v_changes jsonb;
  v_seq bigint;
  v_public_id text;
  v_event_uuid uuid;
BEGIN
  IF p_folds_into IS NOT NULL THEN
    SELECT * INTO v_latest
    FROM pm.webhook_events ev
    WHERE ev.resource_type = p_subject_type AND ev.resource_id = p_subject_id AND ev.created_at = now()
    ORDER BY ev.sequence DESC
    LIMIT 1;
    IF FOUND AND v_latest.event_type = ANY (p_folds_into) AND NOT EXISTS (
      SELECT 1 FROM pm.webhook_deliveries d
      WHERE d.webhook_event_id = v_latest.id AND (d.status <> 'pending' OR d.attempts > 0)
    ) THEN
      SELECT coalesce(array_agg(DISTINCT m ORDER BY m), '{}') INTO v_members
      FROM (
        SELECT unnest(v_members) AS m
        UNION ALL
        SELECT value::uuid FROM jsonb_array_elements_text(coalesce(v_latest.payload -> 'data' -> 'member_ids', '[]'::jsonb))
      ) folded;
      IF (v_latest.payload -> 'data') ? 'changes' THEN
        SELECT coalesce(jsonb_agg(DISTINCT c ORDER BY c), '[]'::jsonb) INTO v_changes
        FROM (
          SELECT jsonb_array_elements_text(v_latest.payload -> 'data' -> 'changes') AS c
          UNION ALL
          SELECT jsonb_array_elements_text(coalesce(v_data -> 'changes', '[]'::jsonb))
        ) folded;
        v_data := v_data || jsonb_build_object('changes', v_changes);
      ELSE
        v_data := v_data - 'changes';
      END IF;

      UPDATE pm.webhook_events
      SET payload = jsonb_set(payload, '{data}', v_data || jsonb_build_object('member_ids', to_jsonb(v_members)))
      WHERE id = v_latest.id;

      INSERT INTO pm.webhook_deliveries (webhook_event_id, endpoint_id)
      SELECT v_latest.id, e.id
      FROM pm.webhook_endpoints e
      WHERE pm.webhook_endpoint_matches(e, v_latest.event_type, p_project_ids, v_members)
        AND NOT EXISTS (
          SELECT 1 FROM pm.webhook_deliveries d WHERE d.webhook_event_id = v_latest.id AND d.endpoint_id = e.id
        );
      RETURN;
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE pm.webhook_endpoint_matches(e, p_event_type, p_project_ids, v_members)
  ) THEN
    RETURN;
  END IF;

  v_seq := nextval('pm.webhook_event_seq');
  v_public_id := 'evt_' || replace(gen_random_uuid()::text, '-', '');

  INSERT INTO pm.webhook_events (event_id, sequence, event_type, resource_type, resource_id, payload)
  VALUES (
    v_public_id, v_seq, p_event_type, p_subject_type, p_subject_id,
    jsonb_build_object(
      'id', v_public_id,
      'type', p_event_type,
      'sequence', v_seq,
      'created_at', now(),
      'data', v_data || jsonb_build_object('member_ids', to_jsonb(v_members))
    )
  )
  RETURNING id INTO v_event_uuid;

  INSERT INTO pm.webhook_deliveries (webhook_event_id, endpoint_id)
  SELECT v_event_uuid, e.id
  FROM pm.webhook_endpoints e
  WHERE pm.webhook_endpoint_matches(e, p_event_type, p_project_ids, v_members);
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_webhook_event(text, text, uuid, uuid[], uuid[], jsonb, text[]) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Payload pieces
-- ---------------------------------------------------------------------------
-- What every event about a task carries: the task as it is now (assignees
-- and a live claim included), its project, and the ids a harness keys on.
CREATE OR REPLACE FUNCTION pm.webhook_task_data(p_task pm.tasks)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT jsonb_build_object(
    'task', jsonb_build_object(
      'id', p_task.id,
      'project_id', p_task.project_id,
      'parent_task_id', p_task.parent_task_id,
      'title', p_task.title,
      'description', p_task.description,
      'status', p_task.status,
      'priority', p_task.priority,
      'due_date', p_task.due_date,
      'tags', to_jsonb(p_task.tags),
      'ai_readiness', p_task.ai_readiness,
      'assignee_ids', coalesce((
        SELECT jsonb_agg(a.member_id ORDER BY a.member_id) FROM pm.task_assignees a WHERE a.task_id = p_task.id
      ), '[]'::jsonb),
      'claimed_by', CASE WHEN p_task.claim_expires_at IS NULL OR p_task.claim_expires_at > now() THEN p_task.claimed_by END,
      'claim_expires_at', CASE WHEN p_task.claimed_by IS NOT NULL AND p_task.claim_expires_at > now() THEN p_task.claim_expires_at END,
      'created_by', p_task.created_by,
      'created_via', p_task.created_via,
      'source_task_suggestion_id', p_task.source_task_suggestion_id,
      'completed_at', p_task.completed_at,
      'created_at', p_task.created_at,
      'updated_at', p_task.updated_at,
      'deleted_at', p_task.deleted_at
    ),
    'project', jsonb_build_object('id', p_task.project_id, 'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = p_task.project_id), '')),
    'project_id', p_task.project_id,
    'task_id', p_task.id,
    'actor_id', pm.webhook_actor_id()
  )
$$;

REVOKE ALL ON FUNCTION pm.webhook_task_data(pm.tasks) FROM PUBLIC, anon, authenticated;

-- A task event. Any change in the transaction that created the task is part
-- of its creation: it refreshes that task.created (or sends it, when it is
-- the change that brings an endpoint in, such as the assignee a member
-- filter waits for). task.updated carries the names of the changed fields.
CREATE OR REPLACE FUNCTION pm.emit_task_event(
  p_task pm.tasks,
  p_event_type text,
  p_changes text[] DEFAULT '{}',
  p_also_members uuid[] DEFAULT '{}',
  p_also_projects uuid[] DEFAULT '{}'
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text := p_event_type;
  v_data jsonb := pm.webhook_task_data(p_task);
BEGIN
  IF v_type = 'task.updated' AND p_task.created_at = now() THEN
    v_type := 'task.created';
  END IF;
  IF v_type = 'task.updated' THEN
    v_data := v_data || jsonb_build_object('changes', to_jsonb(coalesce(p_changes, '{}')));
  END IF;
  PERFORM pm.emit_webhook_event(
    v_type,
    'task',
    p_task.id,
    ARRAY[p_task.project_id] || coalesce(p_also_projects, '{}'),
    pm.webhook_event_members('task', p_task.id, p_also_members),
    v_data,
    CASE
      WHEN v_type = 'task.updated' THEN ARRAY['task.updated']
      WHEN v_type = 'task.created' AND p_event_type = 'task.updated' THEN ARRAY['task.created']
    END
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_task_event(pm.tasks, text, text[], uuid[], uuid[]) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------------
-- Tasks: created, the fields people act on changed (status, title,
-- description, priority, due date, project, who may work it), moved to Trash
-- (task.deleted) or restored (task.created again, as creating it would
-- send). Reordering, claims and edits in Trash send nothing.
CREATE OR REPLACE FUNCTION pm.emit_task_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_changes text[] := '{}';
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['task.created', 'task.updated', 'task.deleted']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.deleted_at IS NULL THEN
      PERFORM pm.emit_task_event(NEW, 'task.created');
    END IF;
    RETURN NULL;
  END IF;

  IF NEW.deleted_at IS NOT NULL THEN
    IF OLD.deleted_at IS NULL THEN
      PERFORM pm.emit_task_event(NEW, 'task.deleted');
    END IF;
    RETURN NULL;
  END IF;
  IF OLD.deleted_at IS NOT NULL THEN
    PERFORM pm.emit_task_event(NEW, 'task.created');
    RETURN NULL;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN v_changes := v_changes || 'status'::text; END IF;
  IF NEW.title IS DISTINCT FROM OLD.title THEN v_changes := v_changes || 'title'::text; END IF;
  IF NEW.description IS DISTINCT FROM OLD.description THEN v_changes := v_changes || 'description'::text; END IF;
  IF NEW.priority IS DISTINCT FROM OLD.priority THEN v_changes := v_changes || 'priority'::text; END IF;
  IF NEW.due_date IS DISTINCT FROM OLD.due_date THEN v_changes := v_changes || 'due_date'::text; END IF;
  IF NEW.project_id IS DISTINCT FROM OLD.project_id THEN v_changes := v_changes || 'project_id'::text; END IF;
  IF NEW.ai_readiness IS DISTINCT FROM OLD.ai_readiness THEN v_changes := v_changes || 'ai_readiness'::text; END IF;
  IF cardinality(v_changes) = 0 THEN
    RETURN NULL;
  END IF;
  PERFORM pm.emit_task_event(NEW, 'task.updated', v_changes, '{}', ARRAY[OLD.project_id]);
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_task_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_task_webhook_insert ON pm.tasks;
CREATE TRIGGER emit_task_webhook_insert
  AFTER INSERT ON pm.tasks
  FOR EACH ROW EXECUTE FUNCTION pm.emit_task_webhook();

DROP TRIGGER IF EXISTS emit_task_webhook_update ON pm.tasks;
CREATE TRIGGER emit_task_webhook_update
  AFTER UPDATE ON pm.tasks
  FOR EACH ROW
  WHEN (NEW.status IS DISTINCT FROM OLD.status
    OR NEW.title IS DISTINCT FROM OLD.title
    OR NEW.description IS DISTINCT FROM OLD.description
    OR NEW.priority IS DISTINCT FROM OLD.priority
    OR NEW.due_date IS DISTINCT FROM OLD.due_date
    OR NEW.project_id IS DISTINCT FROM OLD.project_id
    OR NEW.ai_readiness IS DISTINCT FROM OLD.ai_readiness
    OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at)
  EXECUTE FUNCTION pm.emit_task_webhook();

-- Assignees: a task.updated with changes ["assignee_ids"]. A removed
-- assignee is among the members it concerns, so they hear they are off it.
CREATE OR REPLACE FUNCTION pm.emit_task_assignee_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_task pm.tasks;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['task.created', 'task.updated']
  ) THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_task FROM pm.tasks
  WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.task_id ELSE NEW.task_id END;
  IF NOT FOUND OR v_task.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  PERFORM pm.emit_task_event(
    v_task,
    'task.updated',
    ARRAY['assignee_ids'],
    CASE WHEN TG_OP = 'DELETE' THEN ARRAY[OLD.member_id] ELSE '{}'::uuid[] END
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_task_assignee_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_task_assignee_webhook ON pm.task_assignees;
CREATE TRIGGER emit_task_assignee_webhook
  AFTER INSERT OR DELETE ON pm.task_assignees
  FOR EACH ROW EXECUTE FUNCTION pm.emit_task_assignee_webhook();

-- Comments on a live task: comment.created, in the task's line.
CREATE OR REPLACE FUNCTION pm.emit_comment_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_task pm.tasks;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e WHERE e.is_active AND 'comment.created' = ANY (e.events)
  ) THEN
    RETURN NULL;
  END IF;
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_task FROM pm.tasks WHERE id = NEW.task_id;
  IF NOT FOUND OR v_task.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  PERFORM pm.emit_webhook_event(
    'comment.created',
    'task',
    v_task.id,
    ARRAY[v_task.project_id],
    pm.webhook_event_members('task', v_task.id),
    pm.webhook_task_data(v_task) || jsonb_build_object('comment', jsonb_build_object(
      'id', NEW.id,
      'task_id', NEW.task_id,
      'author_id', NEW.user_id,
      'text', NEW.text,
      'created_at', NEW.created_at
    ))
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_comment_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_comment_webhook ON pm.task_comments;
CREATE TRIGGER emit_comment_webhook
  AFTER INSERT ON pm.task_comments
  FOR EACH ROW EXECUTE FUNCTION pm.emit_comment_webhook();

-- Reviews on a live task: review.submitted, in the task's line.
CREATE OR REPLACE FUNCTION pm.emit_review_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_task pm.tasks;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e WHERE e.is_active AND 'review.submitted' = ANY (e.events)
  ) THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_task FROM pm.tasks WHERE id = NEW.task_id;
  IF NOT FOUND OR v_task.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  PERFORM pm.emit_webhook_event(
    'review.submitted',
    'task',
    v_task.id,
    ARRAY[v_task.project_id],
    pm.webhook_event_members('task', v_task.id),
    pm.webhook_task_data(v_task) || jsonb_build_object('review', jsonb_build_object(
      'id', NEW.id,
      'task_id', NEW.task_id,
      'round', NEW.round,
      'verdict', NEW.verdict,
      'summary', NEW.summary,
      'pr_url', NEW.pr_url,
      'head_sha', NEW.head_sha,
      'reviewer_id', NEW.reviewer_member_id,
      'created_at', NEW.created_at
    ))
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_review_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_review_webhook ON pm.task_reviews;
CREATE TRIGGER emit_review_webhook
  AFTER INSERT ON pm.task_reviews
  FOR EACH ROW EXECUTE FUNCTION pm.emit_review_webhook();

-- Questions: asked (also when one opens again or comes back from Trash
-- open), answered, cancelled (also when an open one goes to Trash). Expiry
-- sends nothing: an open question past expires_at reads as expired.
CREATE OR REPLACE FUNCTION pm.emit_question_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['question.asked', 'question.answered', 'question.cancelled']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'open' AND NEW.deleted_at IS NULL THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.deleted_at IS NOT NULL THEN
    IF OLD.deleted_at IS NULL AND OLD.status = 'open' THEN
      v_type := 'question.cancelled';
    END IF;
  ELSIF OLD.deleted_at IS NOT NULL THEN
    IF NEW.status = 'open' THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_type := CASE NEW.status
      WHEN 'open' THEN 'question.asked'
      WHEN 'answered' THEN 'question.answered'
      WHEN 'cancelled' THEN 'question.cancelled'
    END;
  END IF;
  IF v_type IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'question',
    NEW.id,
    ARRAY[NEW.project_id],
    pm.webhook_event_members('question', NEW.id),
    jsonb_build_object(
      'question', jsonb_build_object(
        'id', NEW.id,
        'project_id', NEW.project_id,
        'task_id', NEW.task_id,
        'asked_by', NEW.asked_by,
        'asked_to', NEW.asked_to,
        'question', NEW.question,
        'choices', NEW.choices,
        'allow_other', NEW.allow_other,
        'status', NEW.status,
        'answer_choice', NEW.answer_choice,
        'answer_text', NEW.answer_text,
        'answered_by', NEW.answered_by,
        'answered_at', NEW.answered_at,
        'cancelled_by', NEW.cancelled_by,
        'cancelled_at', NEW.cancelled_at,
        'expires_at', NEW.expires_at,
        'created_at', NEW.created_at,
        'updated_at', NEW.updated_at,
        'deleted_at', NEW.deleted_at
      ),
      'project', CASE WHEN NEW.project_id IS NOT NULL THEN jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ) END,
      'project_id', NEW.project_id,
      'task_id', NEW.task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_question_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_question_webhook_insert ON pm.questions;
CREATE TRIGGER emit_question_webhook_insert
  AFTER INSERT ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.emit_question_webhook();

DROP TRIGGER IF EXISTS emit_question_webhook_update ON pm.questions;
CREATE TRIGGER emit_question_webhook_update
  AFTER UPDATE ON pm.questions
  FOR EACH ROW
  WHEN (NEW.status IS DISTINCT FROM OLD.status OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at)
  EXECUTE FUNCTION pm.emit_question_webhook();

-- Suggestions: created, and decided (approved, rejected or declined). The
-- task an approval makes arrives as its own task.created, which names the
-- suggestion in source_task_suggestion_id.
CREATE OR REPLACE FUNCTION pm.emit_suggestion_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['suggestion.created', 'suggestion.decided']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_type := 'suggestion.created';
  ELSIF NEW.status IN ('approved', 'rejected', 'declined') AND OLD.status NOT IN ('approved', 'rejected', 'declined') THEN
    v_type := 'suggestion.decided';
  ELSE
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'suggestion',
    NEW.id,
    ARRAY[NEW.project_id],
    pm.webhook_event_members('suggestion', NEW.id),
    jsonb_build_object(
      'suggestion', jsonb_build_object(
        'id', NEW.id,
        'project_id', NEW.project_id,
        'goal_id', NEW.goal_id,
        'proposed_by', NEW.proposed_by,
        'assigned_to', NEW.assigned_to,
        'title', NEW.title,
        'description', NEW.description,
        'reasoning', NEW.reasoning,
        'priority', NEW.priority,
        'effort_estimate', NEW.effort_estimate,
        'status', NEW.status,
        'reviewed_by', NEW.reviewed_by,
        'reviewed_at', NEW.reviewed_at,
        'rejection_reason', NEW.rejection_reason,
        'info_request', NEW.info_request,
        'converted_task_id', NEW.converted_task_id,
        'bundle_key', NEW.bundle_key,
        'created_at', NEW.created_at,
        'updated_at', NEW.updated_at
      ),
      'project', jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ),
      'project_id', NEW.project_id,
      'task_id', NEW.converted_task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_suggestion_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_suggestion_webhook_insert ON pm.task_suggestions;
CREATE TRIGGER emit_suggestion_webhook_insert
  AFTER INSERT ON pm.task_suggestions
  FOR EACH ROW EXECUTE FUNCTION pm.emit_suggestion_webhook();

DROP TRIGGER IF EXISTS emit_suggestion_webhook_update ON pm.task_suggestions;
CREATE TRIGGER emit_suggestion_webhook_update
  AFTER UPDATE OF status ON pm.task_suggestions
  FOR EACH ROW
  WHEN (NEW.status IS DISTINCT FROM OLD.status)
  EXECUTE FUNCTION pm.emit_suggestion_webhook();

-- ============================================================
-- AGENT PLUMBING (20261124000300_agent_plumbing.sql)
-- Self-reported heartbeats (container optional, expected_interval_seconds,
-- status_note; a self-report means the agent is up) and idempotency keys for
-- API POSTs (one run per API key, path and Idempotency-Key for 24 hours;
-- 2xx answers replayed; service role only; pm-api-idempotency-cleanup
-- removes expired keys hourly).
-- ============================================================

ALTER TABLE pm.agent_health ALTER COLUMN container DROP NOT NULL;
ALTER TABLE pm.agent_health
  ADD COLUMN IF NOT EXISTS expected_interval_seconds integer NOT NULL DEFAULT 60,
  ADD COLUMN IF NOT EXISTS status_note text;

ALTER TABLE pm.agent_health DROP CONSTRAINT IF EXISTS agent_health_expected_interval_range;
ALTER TABLE pm.agent_health
  ADD CONSTRAINT agent_health_expected_interval_range CHECK (expected_interval_seconds BETWEEN 30 AND 86400);
ALTER TABLE pm.agent_health DROP CONSTRAINT IF EXISTS agent_health_status_note_length;
ALTER TABLE pm.agent_health
  ADD CONSTRAINT agent_health_status_note_length CHECK (status_note IS NULL OR length(status_note) BETWEEN 1 AND 280);

COMMENT ON COLUMN pm.agent_health.container IS
  'The container the fleet publisher watches, when there is one. Null for an agent that reports itself without one.';
COMMENT ON COLUMN pm.agent_health.expected_interval_seconds IS
  'How often this agent promises a beat (30 to 86400 seconds). Readers call the row stale after two missed beats plus a minute.';
COMMENT ON COLUMN pm.agent_health.status_note IS
  'What the agent last said it is doing, from its own heartbeat. Each self-report replaces it.';

-- ---------------------------------------------------------------------------
-- Idempotency keys
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.api_idempotency_keys (
  api_key_id uuid NOT NULL REFERENCES pm.api_keys(id) ON DELETE CASCADE,
  path text NOT NULL,
  idempotency_key text NOT NULL,
  -- sha256 of the request's query string and body.
  request_hash text NOT NULL,
  state text NOT NULL DEFAULT 'in_flight',
  response_status integer,
  response_body text,
  started_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  expires_at timestamptz NOT NULL DEFAULT (now() + interval '24 hours'),
  PRIMARY KEY (api_key_id, path, idempotency_key)
);

ALTER TABLE pm.api_idempotency_keys DROP CONSTRAINT IF EXISTS api_idempotency_keys_state_check;
ALTER TABLE pm.api_idempotency_keys
  ADD CONSTRAINT api_idempotency_keys_state_check CHECK (state IN ('in_flight', 'completed'));
ALTER TABLE pm.api_idempotency_keys DROP CONSTRAINT IF EXISTS api_idempotency_keys_key_length;
ALTER TABLE pm.api_idempotency_keys
  ADD CONSTRAINT api_idempotency_keys_key_length CHECK (length(idempotency_key) BETWEEN 1 AND 255);
ALTER TABLE pm.api_idempotency_keys DROP CONSTRAINT IF EXISTS api_idempotency_keys_completed_has_response;
ALTER TABLE pm.api_idempotency_keys
  ADD CONSTRAINT api_idempotency_keys_completed_has_response CHECK (
    state <> 'completed' OR (response_status BETWEEN 200 AND 299 AND response_body IS NOT NULL AND completed_at IS NOT NULL));

CREATE INDEX IF NOT EXISTS idx_api_idempotency_keys_expires ON pm.api_idempotency_keys (expires_at);

COMMENT ON TABLE pm.api_idempotency_keys IS
  'One row per API key, path and Idempotency-Key for 24 hours: the claim, then the 2xx answer a retry gets back. Service role only.';

ALTER TABLE pm.api_idempotency_keys ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.api_idempotency_keys FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.api_idempotency_keys TO service_role;

-- Claims a key for one request. state: claimed (run the handler), replay
-- (answer with status and body), mismatch (another body under this key) or
-- in_flight (the first request is still running). An expired row, or a claim
-- left running for 10 minutes, is taken over as a new claim.
CREATE OR REPLACE FUNCTION pm.claim_api_idempotency_key(
  p_api_key_id uuid,
  p_path text,
  p_idempotency_key text,
  p_request_hash text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_row pm.api_idempotency_keys%ROWTYPE;
BEGIN
  FOR attempt IN 1..3 LOOP
    INSERT INTO pm.api_idempotency_keys (api_key_id, path, idempotency_key, request_hash)
    VALUES (p_api_key_id, p_path, p_idempotency_key, p_request_hash)
    ON CONFLICT (api_key_id, path, idempotency_key) DO NOTHING;
    IF FOUND THEN
      RETURN jsonb_build_object('state', 'claimed');
    END IF;

    SELECT * INTO v_row FROM pm.api_idempotency_keys
    WHERE api_key_id = p_api_key_id AND path = p_path AND idempotency_key = p_idempotency_key
    FOR UPDATE;
    -- Released between the insert and the read: try the insert again.
    CONTINUE WHEN NOT FOUND;

    IF v_row.expires_at <= now()
       OR (v_row.state = 'in_flight' AND v_row.started_at <= now() - interval '10 minutes') THEN
      UPDATE pm.api_idempotency_keys
      SET request_hash = p_request_hash, state = 'in_flight', response_status = NULL, response_body = NULL,
          started_at = now(), completed_at = NULL, expires_at = now() + interval '24 hours'
      WHERE api_key_id = p_api_key_id AND path = p_path AND idempotency_key = p_idempotency_key;
      RETURN jsonb_build_object('state', 'claimed');
    END IF;
    IF v_row.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('state', 'mismatch');
    END IF;
    IF v_row.state = 'in_flight' THEN
      RETURN jsonb_build_object('state', 'in_flight', 'started_at', v_row.started_at);
    END IF;
    RETURN jsonb_build_object('state', 'replay', 'status', v_row.response_status, 'body', v_row.response_body);
  END LOOP;
  RETURN jsonb_build_object('state', 'in_flight');
END;
$$;

-- Removes expired keys; answers how many.
CREATE OR REPLACE FUNCTION pm.cleanup_api_idempotency_keys()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_count integer;
BEGIN
  DELETE FROM pm.api_idempotency_keys WHERE expires_at <= now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION pm.claim_api_idempotency_key(uuid, text, text, text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION pm.cleanup_api_idempotency_keys() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.claim_api_idempotency_key(uuid, text, text, text) TO service_role;
GRANT EXECUTE ON FUNCTION pm.cleanup_api_idempotency_keys() TO service_role;

-- Expired keys go hourly. Skipped where pg_cron is unavailable (PGlite).
-- Re-running cron.schedule updates the job in place.
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron') THEN
    RAISE NOTICE 'pg_cron is unavailable here; expired idempotency keys will not be cleaned up on a schedule';
    RETURN;
  END IF;
  CREATE EXTENSION IF NOT EXISTS pg_cron;
  PERFORM cron.schedule('pm-api-idempotency-cleanup', '23 * * * *', $job$SELECT pm.cleanup_api_idempotency_keys();$job$);
END;
$do$;

-- ============================================================
-- API KEY LINEAGE (20261124000400_agent_setup_api.sql)
-- A key made by another key over the API records it
-- (created_by_key_id, null for Settings keys and older ones; the lineage
-- never changes), and pm.revoke_api_key_tree revokes a key with every live
-- descendant in one statement (service role only).
-- ============================================================

ALTER TABLE pm.api_keys
  ADD COLUMN IF NOT EXISTS created_by_key_id uuid REFERENCES pm.api_keys(id);

COMMENT ON COLUMN pm.api_keys.created_by_key_id IS
  'The key that made this one over the API (null: made in Settings, or before 2.0.16). Revoking a key revokes its descendants.';

CREATE INDEX IF NOT EXISTS idx_api_keys_created_by_key ON pm.api_keys (created_by_key_id)
  WHERE created_by_key_id IS NOT NULL;

CREATE OR REPLACE FUNCTION pm.api_keys_guard()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
    RAISE EXCEPTION 'API key % is revoked; a revoke cannot be changed', OLD.id
      USING ERRCODE = '42501';
  END IF;
  IF NEW.key_hash IS DISTINCT FROM OLD.key_hash
    OR NEW.key_prefix IS DISTINCT FROM OLD.key_prefix
    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'API key % secret and creation time cannot change', OLD.id
      USING ERRCODE = '42501';
  END IF;
  IF (NEW.team_member_id IS DISTINCT FROM OLD.team_member_id AND NEW.team_member_id IS NOT NULL)
    OR (NEW.created_by IS DISTINCT FROM OLD.created_by AND NEW.created_by IS NOT NULL) THEN
    RAISE EXCEPTION 'API key % cannot move to another member', OLD.id
      USING ERRCODE = '42501';
  END IF;
  IF NEW.created_by_key_id IS DISTINCT FROM OLD.created_by_key_id THEN
    RAISE EXCEPTION 'API key % lineage cannot change', OLD.id
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.api_keys_guard() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION pm.revoke_api_key_tree(p_key_id uuid)
RETURNS TABLE (id uuid, depth integer)
LANGUAGE sql
SET search_path = ''
AS $$
  WITH RECURSIVE tree AS (
    SELECT k.id, 0 AS depth, ARRAY[k.id] AS path FROM pm.api_keys k WHERE k.id = p_key_id
    UNION ALL
    SELECT c.id, t.depth + 1, t.path || c.id FROM pm.api_keys c JOIN tree t ON c.created_by_key_id = t.id
    -- No depth cap: every descendant is revoked however deep the chain. The
    -- path only guards a key that names itself as its parent.
    WHERE NOT c.id = ANY(t.path)
  )
  UPDATE pm.api_keys k SET revoked_at = now()
  FROM tree
  WHERE k.id = tree.id AND k.revoked_at IS NULL
  RETURNING k.id, tree.depth;
$$;

REVOKE ALL ON FUNCTION pm.revoke_api_key_tree(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.revoke_api_key_tree(uuid) TO service_role;

-- ============================================================
-- RUNS (20261124000500_agent_runs.sql)
-- One run of an agent (pm.agent_runs): status, plan, notes, tokens and
-- cost, on a task or not, with the harness's run id (unique per agent) and
-- trace link. A run running two hours past its last update reads as
-- timed_out. run.started and run.finished on the webhook outbox, ordered per
-- run. pm.agent_run_feed reads stored runs plus turn.completed rows that name
-- no run, copying nothing. Members read their own (agents.manage: all);
-- only the server writes.
-- ============================================================

CREATE TABLE IF NOT EXISTS pm.agent_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  -- A task's run always carries its task's project (set by the trigger).
  task_id uuid REFERENCES pm.tasks(id) ON DELETE SET NULL,
  project_id uuid REFERENCES pm.projects(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'running',
  title text,
  summary text,
  plan jsonb NOT NULL DEFAULT '[]'::jsonb,
  notes jsonb NOT NULL DEFAULT '[]'::jsonb,
  tokens_in bigint,
  tokens_out bigint,
  cost_usd numeric(14, 6),
  model text,
  trigger text,
  external_id text,
  external_url text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_status_check;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_status_check CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled', 'timed_out'));
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_finished_when_done;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_finished_when_done CHECK ((status = 'running') = (finished_at IS NULL));
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_finished_after_start;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_finished_after_start CHECK (finished_at IS NULL OR finished_at >= started_at);
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_title_length;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_title_length CHECK (title IS NULL OR length(title) BETWEEN 1 AND 300);
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_summary_length;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_summary_length CHECK (summary IS NULL OR length(summary) BETWEEN 1 AND 4000);
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_plan_shape;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_plan_shape CHECK (jsonb_typeof(plan) = 'array' AND jsonb_array_length(plan) <= 50);
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_notes_shape;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_notes_shape CHECK (jsonb_typeof(notes) = 'array' AND jsonb_array_length(notes) <= 50);
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_metadata_shape;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_metadata_shape CHECK (jsonb_typeof(metadata) = 'object' AND length(metadata::text) <= 16000);
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_amounts_not_negative;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_amounts_not_negative CHECK (
    (tokens_in IS NULL OR tokens_in >= 0) AND (tokens_out IS NULL OR tokens_out >= 0) AND (cost_usd IS NULL OR cost_usd >= 0));
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_model_length;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_model_length CHECK (model IS NULL OR length(model) BETWEEN 1 AND 200);
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_trigger_shape;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_trigger_shape CHECK (trigger IS NULL OR trigger ~ '^[a-z][a-z0-9_.-]{0,39}$');
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_external_id_length;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_external_id_length CHECK (external_id IS NULL OR length(external_id) BETWEEN 1 AND 300);
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_external_url_shape;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_external_url_shape CHECK (external_url IS NULL OR (length(external_url) <= 2000 AND external_url ~* '^https?://'));
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_task_has_project;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_task_has_project CHECK (task_id IS NULL OR project_id IS NOT NULL);
-- One run per harness run id, per agent (nulls never collide).
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_agent_external_id_key;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_agent_external_id_key UNIQUE (agent_id, external_id);

COMMENT ON TABLE pm.agent_runs IS
  'One run of an agent: status, plan, notes, tokens and cost, on a task or not, with the harness''s trace link. Written by the server only.';
COMMENT ON COLUMN pm.agent_runs.status IS
  'running, succeeded, failed, cancelled or timed_out. A run running two hours past updated_at reads as timed_out; the row stays running.';
COMMENT ON COLUMN pm.agent_runs.cost_usd IS
  'The run''s own cost so far in US dollars, as the harness reports it (null: not reported). Never summed with usage.recorded.';
COMMENT ON COLUMN pm.agent_runs.external_id IS
  'The harness''s own run id, unique per agent: starting a run with it again returns the same run.';

-- An agent's runs, newest first; a task's latest run; the still running.
CREATE INDEX IF NOT EXISTS idx_agent_runs_agent_started ON pm.agent_runs (agent_id, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_runs_task_started ON pm.agent_runs (task_id, started_at DESC) WHERE task_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_agent_runs_project ON pm.agent_runs (project_id) WHERE project_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_agent_runs_started ON pm.agent_runs (started_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_runs_running ON pm.agent_runs (updated_at) WHERE status = 'running';

-- A run's turns: turn.completed rows the server attached to it.
CREATE INDEX IF NOT EXISTS idx_agent_activities_turn_run ON pm.agent_activities ((metadata->>'run_id'))
  WHERE activity_type = 'turn.completed' AND metadata->>'run_id' IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Normalise every write: the task's project, the finish time, and the fields
-- a later write may not change (a finished run's status and finish time
-- among them).
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.handle_agent_run_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  task_project uuid;
BEGIN
  IF NEW.task_id IS NOT NULL THEN
    SELECT project_id INTO task_project FROM pm.tasks WHERE id = NEW.task_id;
    IF task_project IS NOT NULL THEN
      NEW.project_id := task_project;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.agent_id := OLD.agent_id;
    NEW.created_at := OLD.created_at;
    NEW.external_id := coalesce(OLD.external_id, NEW.external_id);
    -- A finished run stays as it finished, whoever writes: two finishes at
    -- once cannot both land. Its other details may still change.
    IF OLD.status <> 'running' THEN
      NEW.status := OLD.status;
      NEW.finished_at := OLD.finished_at;
    END IF;
  END IF;
  IF NEW.status <> 'running' AND NEW.finished_at IS NULL THEN
    NEW.finished_at := greatest(now(), NEW.started_at);
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_agent_run_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS agent_runs_before_write ON pm.agent_runs;
CREATE TRIGGER agent_runs_before_write
  BEFORE INSERT OR UPDATE ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.handle_agent_run_before_write();

DROP TRIGGER IF EXISTS set_agent_runs_updated_at ON pm.agent_runs;
CREATE TRIGGER set_agent_runs_updated_at
  BEFORE UPDATE ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

-- A task moved to another project takes its runs along.
CREATE OR REPLACE FUNCTION pm.sync_task_agent_runs_project()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  UPDATE pm.agent_runs SET project_id = NEW.project_id WHERE task_id = NEW.id;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.sync_task_agent_runs_project() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS tasks_sync_agent_runs_project ON pm.tasks;
CREATE TRIGGER tasks_sync_agent_runs_project
  AFTER UPDATE OF project_id ON pm.tasks
  FOR EACH ROW
  WHEN (NEW.project_id IS DISTINCT FROM OLD.project_id)
  EXECUTE FUNCTION pm.sync_task_agent_runs_project();

-- Never permanently deleted.
DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.agent_runs;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.agent_runs;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.agent_runs
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

-- ---------------------------------------------------------------------------
-- Webhooks: run.started and run.finished, concerning the run's agent, in the
-- run's own line. One look at webhook_endpoints when nobody subscribes.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.emit_agent_run_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['run.started', 'run.finished']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_type := CASE WHEN NEW.status = 'running' THEN 'run.started' ELSE 'run.finished' END;
  ELSIF OLD.status = 'running' AND NEW.status <> 'running' THEN
    v_type := 'run.finished';
  END IF;
  IF v_type IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'run',
    NEW.id,
    ARRAY[NEW.project_id],
    ARRAY[NEW.agent_id],
    jsonb_build_object(
      'run', jsonb_build_object(
        'id', NEW.id,
        'agent_id', NEW.agent_id,
        'task_id', NEW.task_id,
        'project_id', NEW.project_id,
        'status', NEW.status,
        'title', NEW.title,
        'summary', NEW.summary,
        'model', NEW.model,
        'trigger', NEW.trigger,
        'tokens_in', NEW.tokens_in,
        'tokens_out', NEW.tokens_out,
        'cost_usd', NEW.cost_usd,
        'external_id', NEW.external_id,
        'external_url', NEW.external_url,
        'started_at', NEW.started_at,
        'finished_at', NEW.finished_at,
        'updated_at', NEW.updated_at
      ),
      'project', CASE WHEN NEW.project_id IS NOT NULL THEN jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ) END,
      'project_id', NEW.project_id,
      'task_id', NEW.task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_agent_run_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_agent_run_webhook_insert ON pm.agent_runs;
CREATE TRIGGER emit_agent_run_webhook_insert
  AFTER INSERT ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.emit_agent_run_webhook();

DROP TRIGGER IF EXISTS emit_agent_run_webhook_update ON pm.agent_runs;
CREATE TRIGGER emit_agent_run_webhook_update
  AFTER UPDATE ON pm.agent_runs
  FOR EACH ROW
  WHEN (NEW.status IS DISTINCT FROM OLD.status)
  EXECUTE FUNCTION pm.emit_agent_run_webhook();

-- ---------------------------------------------------------------------------
-- Row level security: a member reads their own runs, or every run with
-- agents.manage (as agent_activities), while the AI agents module is on.
-- Only the server writes.
-- ---------------------------------------------------------------------------
ALTER TABLE pm.agent_runs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS agent_runs_select ON pm.agent_runs;
CREATE POLICY agent_runs_select ON pm.agent_runs FOR SELECT TO authenticated
  USING (pm.has_permission('agents.manage') OR agent_id = pm.current_team_member_id());

DROP POLICY IF EXISTS agent_runs_module_on ON pm.agent_runs;
CREATE POLICY agent_runs_module_on ON pm.agent_runs AS RESTRICTIVE FOR ALL TO authenticated
  USING ((select pm.module_enabled('agents')));

DROP POLICY IF EXISTS agent_runs_parent_live ON pm.agent_runs;
CREATE POLICY agent_runs_parent_live ON pm.agent_runs AS RESTRICTIVE FOR ALL TO authenticated
  USING ((task_id IS NULL OR pm.task_is_live(task_id)) AND (project_id IS NULL OR pm.project_is_live(project_id)));

REVOKE ALL ON pm.agent_runs FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.agent_runs TO authenticated;
GRANT ALL ON pm.agent_runs TO service_role;

-- ---------------------------------------------------------------------------
-- The read model: stored runs, plus each turn.completed that names no run.
-- Security invoker, so a member reads it through both tables' row security.
-- sort_at orders it: a run's start, a turn's arrival.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW pm.agent_run_feed
WITH (security_invoker = true) AS
SELECT
  r.id,
  'run'::text AS source,
  r.agent_id,
  r.task_id,
  r.project_id,
  CASE WHEN r.status = 'running' AND r.updated_at < now() - interval '2 hours' THEN 'timed_out' ELSE r.status END AS status,
  NULL::text AS outcome,
  r.title,
  r.summary,
  r.model,
  r.trigger,
  r.started_at,
  r.finished_at,
  CASE WHEN r.finished_at IS NOT NULL THEN (extract(epoch FROM r.finished_at - r.started_at) * 1000)::bigint END AS duration_ms,
  r.tokens_in,
  r.tokens_out,
  r.cost_usd,
  r.external_id,
  r.external_url,
  r.started_at AS sort_at,
  r.updated_at
FROM pm.agent_runs r
UNION ALL
SELECT
  a.id,
  'turn'::text AS source,
  a.agent_id,
  NULL::uuid AS task_id,
  a.project_id,
  'succeeded'::text AS status,
  a.metadata->>'outcome' AS outcome,
  a.title,
  NULL::text AS summary,
  a.metadata->>'model' AS model,
  CASE WHEN a.metadata->>'origin' = 'directed' THEN 'chat' ELSE 'scheduled' END AS trigger,
  coalesce(pm.agent_analytics_ts(a.metadata->>'started_at'), a.created_at) AS started_at,
  coalesce(pm.agent_analytics_ts(a.metadata->>'finished_at'), a.created_at) AS finished_at,
  pm.agent_analytics_int(a.metadata->>'duration_ms') AS duration_ms,
  CASE WHEN a.metadata->>'tokens_scope' = 'turn' AND a.metadata->'tokens' ? 'input'
    THEN pm.agent_analytics_int(a.metadata->'tokens'->>'input') END AS tokens_in,
  CASE WHEN a.metadata->>'tokens_scope' = 'turn' AND a.metadata->'tokens' ? 'output'
    THEN pm.agent_analytics_int(a.metadata->'tokens'->>'output') END AS tokens_out,
  NULL::numeric AS cost_usd,
  a.metadata->>'source_turn_id' AS external_id,
  NULL::text AS external_url,
  a.created_at AS sort_at,
  a.created_at AS updated_at
FROM pm.agent_activities a
WHERE a.activity_type = 'turn.completed'
  AND a.agent_id IS NOT NULL
  AND a.metadata->>'run_id' IS NULL
  AND NOT (a.metadata->>'origin' = 'scheduled' AND coalesce(a.metadata->>'outcome', '') IN ('idle', 'skipped', 'waiting'));

COMMENT ON VIEW pm.agent_run_feed IS
  'Every run: stored runs, plus each turn.completed that names no run read as a finished run. Copies nothing; turns stay the record of runtime and tokens.';

REVOKE ALL ON pm.agent_run_feed FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.agent_run_feed TO authenticated;
GRANT SELECT ON pm.agent_run_feed TO service_role;

-- Live sync: open screens see runs start, move and finish as it happens.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime')
     AND NOT EXISTS (SELECT 1 FROM pg_publication_tables
                     WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'agent_runs') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE pm.agent_runs;
  END IF;
END $$;

-- ============================================================
-- OPEN AGENT VOCABULARY (20261124000600_open_agent_vocabulary.sql)
-- Approvals are questions of kind approval (choices approve and reject, an
-- action { type, summary, details? }, the bell and webhooks of a question);
-- agent_activities.activity_type and team_members.agent_profile are checked
-- by shape, with the vocabulary and the profile registry in code.
-- ============================================================

ALTER TABLE pm.questions
  ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'question',
  ADD COLUMN IF NOT EXISTS action jsonb;

ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_kind_check;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_kind_check CHECK (kind IN ('question', 'approval'));
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_approval_shape;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_approval_shape CHECK (
    (kind = 'question' AND action IS NULL)
    OR (
      kind = 'approval'
      -- coalesce: a missing action, type, summary or choices is a refusal, never unknown.
      AND coalesce(
        jsonb_typeof(action) = 'object'
        AND jsonb_typeof(action->'type') = 'string'
        AND jsonb_typeof(action->'summary') = 'string'
        AND length(action::text) <= 8000
        AND choices = '["approve", "reject"]'::jsonb,
        false)
      AND NOT allow_other
    ));

COMMENT ON COLUMN pm.questions.kind IS
  'question, or approval: a person approves or rejects an action before an agent does it (choices approve and reject, answer_text a note).';
COMMENT ON COLUMN pm.questions.action IS
  'An approval''s action: { type, summary, details? }. Null on a plain question.';

-- kind and action are fixed once written, like asked_by.
CREATE OR REPLACE FUNCTION pm.handle_question_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  task_project uuid;
BEGIN
  NEW.question := btrim(NEW.question);
  IF NEW.task_id IS NOT NULL THEN
    SELECT project_id INTO task_project FROM pm.tasks WHERE id = NEW.task_id;
    IF task_project IS NOT NULL THEN
      NEW.project_id := task_project;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.asked_by := OLD.asked_by;
    NEW.created_at := OLD.created_at;
    NEW.kind := OLD.kind;
    NEW.action := OLD.action;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_question_before_write() FROM PUBLIC, anon, authenticated;

-- The bell: an approval says so; a plain question reads as before.
CREATE OR REPLACE FUNCTION pm.notify_question_asked()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  asker text;
BEGIN
  IF NEW.status <> 'open' OR NEW.deleted_at IS NOT NULL OR NEW.asked_to = NEW.asked_by THEN
    RETURN NULL;
  END IF;
  SELECT name INTO asker FROM pm.team_members WHERE id = NEW.asked_by;
  PERFORM pm.upsert_notification(
    NEW.asked_to,
    CASE WHEN NEW.kind = 'approval' THEN 'Approval request from ' ELSE 'Question from ' END
      || COALESCE(NULLIF(btrim(asker), ''), 'a teammate'),
    left(NEW.question, 500),
    -- My Tasks, where the asked member answers it: they may not be able to
    -- open the task or project it is on.
    '/my-tasks',
    'question',
    NEW.id::text
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.notify_question_asked() FROM PUBLIC, anon, authenticated;

-- Webhooks: an approval's question also carries kind, action, decision and
-- decided_by. A plain question's payload is byte for byte what it was.
CREATE OR REPLACE FUNCTION pm.emit_question_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['question.asked', 'question.answered', 'question.cancelled']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'open' AND NEW.deleted_at IS NULL THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.deleted_at IS NOT NULL THEN
    IF OLD.deleted_at IS NULL AND OLD.status = 'open' THEN
      v_type := 'question.cancelled';
    END IF;
  ELSIF OLD.deleted_at IS NOT NULL THEN
    IF NEW.status = 'open' THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_type := CASE NEW.status
      WHEN 'open' THEN 'question.asked'
      WHEN 'answered' THEN 'question.answered'
      WHEN 'cancelled' THEN 'question.cancelled'
    END;
  END IF;
  IF v_type IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'question',
    NEW.id,
    ARRAY[NEW.project_id],
    pm.webhook_event_members('question', NEW.id),
    jsonb_build_object(
      'question', jsonb_build_object(
        'id', NEW.id,
        'project_id', NEW.project_id,
        'task_id', NEW.task_id,
        'asked_by', NEW.asked_by,
        'asked_to', NEW.asked_to,
        'question', NEW.question,
        'choices', NEW.choices,
        'allow_other', NEW.allow_other,
        'status', NEW.status,
        'answer_choice', NEW.answer_choice,
        'answer_text', NEW.answer_text,
        'answered_by', NEW.answered_by,
        'answered_at', NEW.answered_at,
        'cancelled_by', NEW.cancelled_by,
        'cancelled_at', NEW.cancelled_at,
        'expires_at', NEW.expires_at,
        'created_at', NEW.created_at,
        'updated_at', NEW.updated_at,
        'deleted_at', NEW.deleted_at
      ) || CASE WHEN NEW.kind = 'approval' THEN jsonb_build_object(
        'kind', NEW.kind,
        'action', NEW.action,
        'decision', CASE NEW.answer_choice WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' END,
        'decided_by', CASE WHEN NEW.status = 'answered' THEN NEW.answered_by END
      ) ELSE '{}'::jsonb END,
      'project', CASE WHEN NEW.project_id IS NOT NULL THEN jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ) END,
      'project_id', NEW.project_id,
      'task_id', NEW.task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_question_webhook() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Agent events: checked by shape here, by vocabulary in code
-- ---------------------------------------------------------------------------
ALTER TABLE pm.agent_activities DROP CONSTRAINT IF EXISTS agent_activities_activity_type_check;
ALTER TABLE pm.agent_activities
  ADD CONSTRAINT agent_activities_activity_type_check CHECK (
    activity_type ~ '^[a-z][a-z0-9_]{0,39}(\.[a-z][a-z0-9_]{0,39}){0,2}$');

COMMENT ON COLUMN pm.agent_activities.activity_type IS
  'A typed event, note, custom.<namespace>.<name>, or a grandfathered legacy type. The vocabulary and each payload are checked in src/lib/agent-events.ts.';

-- ---------------------------------------------------------------------------
-- Agent profiles: checked by shape here, by the registry in code
-- ---------------------------------------------------------------------------
ALTER TABLE pm.team_members DROP CONSTRAINT IF EXISTS team_members_agent_profile_check;
ALTER TABLE pm.team_members
  ADD CONSTRAINT team_members_agent_profile_check CHECK (agent_profile ~ '^[a-z][a-z0-9-]{0,39}$');

COMMENT ON COLUMN pm.team_members.agent_profile IS
  'Which MCP tools an agent sees: a core profile or one of the install''s (src/custom/agent-profiles.ts). Checked in code.';

-- ============================================================
-- WORKSPACES: PROJECT AGENTS, OWNERS AND BRIEF (20261124000800_agent_workspaces.sql)
-- Agents on projects (pm.project_agents: status, template, settings for
-- the template's fields, instructions), the people who own each agent
-- (pm.agent_owners), a role label and description on team_members, and
-- project context read as a brief: section (set from category when a write
-- names none), pinned, and full-text search (pm.search_project_context,
-- service role only).
-- ============================================================

-- ---------------------------------------------------------------------------
-- Role label and description
-- ---------------------------------------------------------------------------
ALTER TABLE pm.team_members
  ADD COLUMN IF NOT EXISTS agent_role text,
  ADD COLUMN IF NOT EXISTS description text;

ALTER TABLE pm.team_members DROP CONSTRAINT IF EXISTS team_members_agent_role_check;
ALTER TABLE pm.team_members
  ADD CONSTRAINT team_members_agent_role_check CHECK (agent_role IS NULL OR agent_role ~ '^[a-z][a-z0-9-]{0,39}$');
ALTER TABLE pm.team_members DROP CONSTRAINT IF EXISTS team_members_description_length;
ALTER TABLE pm.team_members
  ADD CONSTRAINT team_members_description_length CHECK (description IS NULL OR length(description) <= 2000);

COMMENT ON COLUMN pm.team_members.agent_role IS
  'An agent''s role label for people (builder, code-reviewer): finding, grouping, routing at a glance. Drives no behaviour.';
COMMENT ON COLUMN pm.team_members.description IS
  'What this member (usually an agent) is for, in plain words.';

-- The distinct roles in use, and agents by role.
CREATE INDEX IF NOT EXISTS idx_team_members_agent_role ON pm.team_members (agent_role) WHERE agent_role IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Agents on projects
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.project_agents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES pm.projects(id) ON DELETE CASCADE,
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'active',
  template_key text,
  settings jsonb NOT NULL DEFAULT '{}'::jsonb,
  instructions text NOT NULL DEFAULT '',
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.project_agents DROP CONSTRAINT IF EXISTS project_agents_project_agent_key;
ALTER TABLE pm.project_agents
  ADD CONSTRAINT project_agents_project_agent_key UNIQUE (project_id, agent_id);
ALTER TABLE pm.project_agents DROP CONSTRAINT IF EXISTS project_agents_status_check;
ALTER TABLE pm.project_agents
  ADD CONSTRAINT project_agents_status_check CHECK (status IN ('active', 'paused'));
ALTER TABLE pm.project_agents DROP CONSTRAINT IF EXISTS project_agents_template_key_shape;
ALTER TABLE pm.project_agents
  ADD CONSTRAINT project_agents_template_key_shape CHECK (template_key IS NULL OR template_key ~ '^[a-z0-9][a-z0-9-]{0,99}$');
ALTER TABLE pm.project_agents DROP CONSTRAINT IF EXISTS project_agents_settings_shape;
ALTER TABLE pm.project_agents
  ADD CONSTRAINT project_agents_settings_shape CHECK (jsonb_typeof(settings) = 'object' AND length(settings::text) <= 16000);
ALTER TABLE pm.project_agents DROP CONSTRAINT IF EXISTS project_agents_instructions_length;
ALTER TABLE pm.project_agents
  ADD CONSTRAINT project_agents_instructions_length CHECK (length(instructions) <= 8000);

COMMENT ON TABLE pm.project_agents IS
  'One agent on one project: active or paused, its template, settings for that template''s fields and instructions for this project. Written by the server only.';
COMMENT ON COLUMN pm.project_agents.settings IS
  'Values for the fields its template declares; checked in code against the template (src/lib/project-agents.ts).';

-- An agent's assignments; a template's agents. A project's come from the unique key.
CREATE INDEX IF NOT EXISTS idx_project_agents_agent ON pm.project_agents (agent_id, status);
CREATE INDEX IF NOT EXISTS idx_project_agents_template ON pm.project_agents (template_key) WHERE template_key IS NOT NULL;

-- Only an agent is assigned; who and where never change after the row is written.
CREATE OR REPLACE FUNCTION pm.handle_project_agent_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.project_id := OLD.project_id;
    NEW.agent_id := OLD.agent_id;
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
  ELSIF NOT EXISTS (SELECT 1 FROM pm.team_members m WHERE m.id = NEW.agent_id AND m.role = 'agent') THEN
    RAISE EXCEPTION 'Only an agent member is assigned to a project as an agent'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_project_agent_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS project_agents_before_write ON pm.project_agents;
CREATE TRIGGER project_agents_before_write
  BEFORE INSERT OR UPDATE ON pm.project_agents
  FOR EACH ROW EXECUTE FUNCTION pm.handle_project_agent_before_write();

DROP TRIGGER IF EXISTS set_project_agents_updated_at ON pm.project_agents;
CREATE TRIGGER set_project_agents_updated_at
  BEFORE UPDATE ON pm.project_agents
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

ALTER TABLE pm.project_agents ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS project_agents_select ON pm.project_agents;
CREATE POLICY project_agents_select ON pm.project_agents FOR SELECT TO authenticated
  USING (pm.can_access_project(project_id) OR agent_id = pm.current_team_member_id());

DROP POLICY IF EXISTS project_agents_module_on ON pm.project_agents;
CREATE POLICY project_agents_module_on ON pm.project_agents AS RESTRICTIVE FOR ALL TO authenticated
  USING ((select pm.module_enabled('agents')));

DROP POLICY IF EXISTS project_agents_parent_live ON pm.project_agents;
CREATE POLICY project_agents_parent_live ON pm.project_agents AS RESTRICTIVE FOR ALL TO authenticated
  USING (pm.project_is_live(project_id));

REVOKE ALL ON pm.project_agents FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.project_agents TO authenticated;
GRANT ALL ON pm.project_agents TO service_role;

-- Each agent's assignments counted, with up to 50 project ids, in one row.
CREATE OR REPLACE VIEW pm.project_agent_counts WITH (security_invoker = true) AS
  SELECT
    agent_id,
    (count(*) FILTER (WHERE status = 'active'))::integer AS active,
    count(*)::integer AS total,
    (array_agg(project_id ORDER BY created_at))[1:50] AS project_ids
  FROM pm.project_agents
  GROUP BY agent_id;

REVOKE ALL ON pm.project_agent_counts FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.project_agent_counts TO authenticated;
GRANT SELECT ON pm.project_agent_counts TO service_role;

-- ---------------------------------------------------------------------------
-- Agent owners
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.agent_owners (
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  member_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (agent_id, member_id)
);

COMMENT ON TABLE pm.agent_owners IS
  'The people responsible for an agent. No row: the workspace Owners. Written by the server only.';

-- The agents a person owns.
CREATE INDEX IF NOT EXISTS idx_agent_owners_member ON pm.agent_owners (member_id);

-- An agent is owned by people: never by itself or another agent.
CREATE OR REPLACE FUNCTION pm.handle_agent_owner_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF NEW.agent_id = NEW.member_id THEN
    RAISE EXCEPTION 'An agent cannot own itself' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pm.team_members m WHERE m.id = NEW.agent_id AND m.role = 'agent') THEN
    RAISE EXCEPTION 'Only an agent has owners' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM pm.team_members m WHERE m.id = NEW.member_id AND m.role = 'agent') THEN
    RAISE EXCEPTION 'An agent is owned by people, never by another agent' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_agent_owner_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS agent_owners_before_write ON pm.agent_owners;
CREATE TRIGGER agent_owners_before_write
  BEFORE INSERT OR UPDATE ON pm.agent_owners
  FOR EACH ROW EXECUTE FUNCTION pm.handle_agent_owner_before_write();

ALTER TABLE pm.agent_owners ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS agent_owners_select ON pm.agent_owners;
CREATE POLICY agent_owners_select ON pm.agent_owners FOR SELECT TO authenticated
  USING (pm.has_permission('team.read') OR member_id = pm.current_team_member_id() OR agent_id = pm.current_team_member_id());

DROP POLICY IF EXISTS agent_owners_module_on ON pm.agent_owners;
CREATE POLICY agent_owners_module_on ON pm.agent_owners AS RESTRICTIVE FOR ALL TO authenticated
  USING ((select pm.module_enabled('agents')));

REVOKE ALL ON pm.agent_owners FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.agent_owners TO authenticated;
GRANT ALL ON pm.agent_owners TO service_role;

-- ---------------------------------------------------------------------------
-- Project brief: sections, pins and search over project context
-- ---------------------------------------------------------------------------
ALTER TABLE pm.project_context
  ADD COLUMN IF NOT EXISTS section text,
  ADD COLUMN IF NOT EXISTS pinned boolean NOT NULL DEFAULT false;

-- A row written with only a category (or whose category changes while its
-- section does not) gets the section its category maps to.
CREATE OR REPLACE FUNCTION pm.handle_project_context_section()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF NEW.section IS NULL
    OR (TG_OP = 'UPDATE' AND NEW.category IS DISTINCT FROM OLD.category AND NEW.section IS NOT DISTINCT FROM OLD.section) THEN
    NEW.section := CASE NEW.category
      WHEN 'business_context' THEN 'overview'
      WHEN 'constraint' THEN 'rules'
      WHEN 'technical_decision' THEN 'decisions'
      ELSE 'history'
    END;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_project_context_section() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS project_context_section ON pm.project_context;
CREATE TRIGGER project_context_section
  BEFORE INSERT OR UPDATE ON pm.project_context
  FOR EACH ROW EXECUTE FUNCTION pm.handle_project_context_section();

-- Existing rows, once: their freshness (updated_at) stays as it was.
ALTER TABLE pm.project_context DISABLE TRIGGER set_project_context_updated_at;
UPDATE pm.project_context
SET section = CASE category
  WHEN 'business_context' THEN 'overview'
  WHEN 'constraint' THEN 'rules'
  WHEN 'technical_decision' THEN 'decisions'
  ELSE 'history'
END
WHERE section IS NULL;
ALTER TABLE pm.project_context ENABLE TRIGGER set_project_context_updated_at;

ALTER TABLE pm.project_context ALTER COLUMN section SET NOT NULL;
ALTER TABLE pm.project_context DROP CONSTRAINT IF EXISTS project_context_section_check;
ALTER TABLE pm.project_context
  ADD CONSTRAINT project_context_section_check CHECK (section IN ('overview', 'rules', 'decisions', 'links', 'glossary', 'history'));

COMMENT ON COLUMN pm.project_context.section IS
  'Where the entry reads in the project brief. Set from category when a write names none.';
COMMENT ON COLUMN pm.project_context.pinned IS
  'Pinned entries go into every agent''s context for the project; the rest are found by search.';

-- A brief's sections, pinned first then newest; the pinned entries; full-text search.
CREATE INDEX IF NOT EXISTS idx_project_context_brief ON pm.project_context (project_id, section, pinned DESC, updated_at DESC) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_project_context_pinned ON pm.project_context (project_id, updated_at DESC) WHERE pinned AND is_active;
CREATE INDEX IF NOT EXISTS idx_project_context_search ON pm.project_context USING gin (to_tsvector('english', content)) WHERE is_active;

-- A project's active entries matching a query, best first (web search
-- syntax: words, "phrases", -not). At most 50.
CREATE OR REPLACE FUNCTION pm.search_project_context(p_project_id uuid, p_query text, p_limit integer DEFAULT 20)
RETURNS TABLE (
  id uuid,
  project_id uuid,
  category text,
  section text,
  content text,
  source text,
  file_path text,
  pinned boolean,
  is_active boolean,
  created_at timestamptz,
  updated_at timestamptz,
  rank real
)
LANGUAGE sql
STABLE
SET search_path = ''
AS $$
  SELECT c.id, c.project_id, c.category, c.section, c.content, c.source, c.file_path, c.pinned, c.is_active,
    c.created_at, c.updated_at, ts_rank(to_tsvector('english'::regconfig, c.content), q.query)
  FROM pm.project_context c
  CROSS JOIN websearch_to_tsquery('english'::regconfig, coalesce(p_query, '')) AS q(query)
  WHERE c.project_id = p_project_id
    AND c.is_active
    AND to_tsvector('english'::regconfig, c.content) @@ q.query
  ORDER BY ts_rank(to_tsvector('english'::regconfig, c.content), q.query) DESC, c.pinned DESC, c.updated_at DESC
  LIMIT least(greatest(coalesce(p_limit, 20), 1), 50)
$$;

REVOKE ALL ON FUNCTION pm.search_project_context(uuid, text, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.search_project_context(uuid, text, integer) TO service_role;

-- ---------------------------------------------------------------------------
-- Live sync: open screens see assignments and owners change as it happens.
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables
                   WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'project_agents') THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE pm.project_agents;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables
                   WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'agent_owners') THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE pm.agent_owners;
    END IF;
  END IF;
END $$;

-- ============================================================
-- IDENTITY, GROUPS AND ON BEHALF OF (20261124000900_identity_groups_principal.sql)
-- Groups and their members (pm.groups, pm.group_members) as targets for
-- questions, approvals, escalation and agent ownership; linked identities
-- (pm.member_identities) with one-time link requests; delegation tokens
-- (X-Act-For) and principal_id on what an agent makes for someone.
-- ============================================================

-- ---------------------------------------------------------------------------
-- Groups
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.groups (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  slug text NOT NULL,
  description text NOT NULL DEFAULT '',
  external_id text,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- Trash: when it was deleted and by whom (null = live). Rows are never removed.
  deleted_at timestamptz,
  deleted_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL
);

ALTER TABLE pm.groups DROP CONSTRAINT IF EXISTS groups_name_length;
ALTER TABLE pm.groups
  ADD CONSTRAINT groups_name_length CHECK (length(btrim(name)) BETWEEN 1 AND 100);
ALTER TABLE pm.groups DROP CONSTRAINT IF EXISTS groups_slug_shape;
ALTER TABLE pm.groups
  ADD CONSTRAINT groups_slug_shape CHECK (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$');
ALTER TABLE pm.groups DROP CONSTRAINT IF EXISTS groups_description_length;
ALTER TABLE pm.groups
  ADD CONSTRAINT groups_description_length CHECK (length(description) <= 2000);
ALTER TABLE pm.groups DROP CONSTRAINT IF EXISTS groups_external_id_length;
ALTER TABLE pm.groups
  ADD CONSTRAINT groups_external_id_length CHECK (external_id IS NULL OR length(external_id) BETWEEN 1 AND 255);

COMMENT ON TABLE pm.groups IS
  'A named group of people and agents: a target for questions, approvals, escalation and agent ownership. Written by the server only.';
COMMENT ON COLUMN pm.groups.external_id IS
  'The group''s id in a directory (SCIM, Google, Entra), for a sync later. Unique among live groups.';

-- One live group per slug and per directory id; the list by name.
CREATE UNIQUE INDEX IF NOT EXISTS groups_slug_live ON pm.groups (slug) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS groups_external_id_live ON pm.groups (external_id) WHERE external_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_groups_name ON pm.groups (lower(name), id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_groups_deleted_at ON pm.groups (deleted_at DESC) WHERE deleted_at IS NOT NULL;

-- Who made it, and when, never change.
CREATE OR REPLACE FUNCTION pm.handle_group_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  NEW.name := btrim(NEW.name);
  IF TG_OP = 'UPDATE' THEN
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_group_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS groups_before_write ON pm.groups;
CREATE TRIGGER groups_before_write
  BEFORE INSERT OR UPDATE ON pm.groups
  FOR EACH ROW EXECUTE FUNCTION pm.handle_group_before_write();

DROP TRIGGER IF EXISTS set_groups_updated_at ON pm.groups;
CREATE TRIGGER set_groups_updated_at
  BEFORE UPDATE ON pm.groups
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

-- Never permanently deleted.
DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.groups;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.groups
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.groups;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.groups
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

CREATE TABLE IF NOT EXISTS pm.group_members (
  group_id uuid NOT NULL REFERENCES pm.groups(id) ON DELETE CASCADE,
  member_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  role text NOT NULL DEFAULT 'member',
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (group_id, member_id)
);

ALTER TABLE pm.group_members DROP CONSTRAINT IF EXISTS group_members_role_check;
ALTER TABLE pm.group_members
  ADD CONSTRAINT group_members_role_check CHECK (role IN ('member', 'lead'));

COMMENT ON TABLE pm.group_members IS
  'Who is in a group (a person or an agent), as member or lead. Removed outright. Written by the server only.';

-- The groups a member is in; a group's leads.
CREATE INDEX IF NOT EXISTS idx_group_members_member ON pm.group_members (member_id);
CREATE INDEX IF NOT EXISTS idx_group_members_role ON pm.group_members (group_id, role, created_at);

ALTER TABLE pm.groups ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS groups_select ON pm.groups;
CREATE POLICY groups_select ON pm.groups FOR SELECT TO authenticated
  USING (pm.has_permission('team.read') OR pm.has_permission('team.manage') OR EXISTS (SELECT 1 FROM pm.group_members gm WHERE gm.group_id = groups.id AND gm.member_id = pm.current_team_member_id()));

DROP POLICY IF EXISTS groups_not_deleted ON pm.groups;
CREATE POLICY groups_not_deleted ON pm.groups AS RESTRICTIVE FOR ALL TO authenticated
  USING (deleted_at IS NULL) WITH CHECK (deleted_at IS NULL);

REVOKE ALL ON pm.groups FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.groups TO authenticated;
GRANT ALL ON pm.groups TO service_role;

ALTER TABLE pm.group_members ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS group_members_select ON pm.group_members;
CREATE POLICY group_members_select ON pm.group_members FOR SELECT TO authenticated
  USING (pm.has_permission('team.read') OR pm.has_permission('team.manage') OR member_id = pm.current_team_member_id());

REVOKE ALL ON pm.group_members FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.group_members TO authenticated;
GRANT ALL ON pm.group_members TO service_role;

-- Each group's members and leads counted, so a list of groups reads them in one query.
CREATE OR REPLACE VIEW pm.group_member_counts WITH (security_invoker = true) AS
  SELECT
    group_id,
    count(*)::integer AS members,
    (count(*) FILTER (WHERE role = 'lead'))::integer AS leads
  FROM pm.group_members
  GROUP BY group_id;

REVOKE ALL ON pm.group_member_counts FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.group_member_counts TO authenticated;
GRANT SELECT ON pm.group_member_counts TO service_role;

-- ---------------------------------------------------------------------------
-- Questions and approvals asked to a group
-- ---------------------------------------------------------------------------
ALTER TABLE pm.questions
  ADD COLUMN IF NOT EXISTS asked_to_group uuid REFERENCES pm.groups(id),
  ADD COLUMN IF NOT EXISTS principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL;

ALTER TABLE pm.questions ALTER COLUMN asked_to DROP NOT NULL;
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_one_addressee;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_one_addressee CHECK (num_nonnulls(asked_to, asked_to_group) = 1);

COMMENT ON COLUMN pm.questions.asked_to_group IS
  'Asked to a group instead of one member: any member answers (answered_by says who). Exactly one of asked_to and asked_to_group is set.';
COMMENT ON COLUMN pm.questions.principal_id IS
  'The person an agent asked this for (X-Act-For). Stamped by the server, never from the row.';

CREATE INDEX IF NOT EXISTS idx_questions_asked_to_group_open
  ON pm.questions (asked_to_group, created_at) WHERE asked_to_group IS NOT NULL AND status = 'open' AND deleted_at IS NULL;

-- The bell: the member asked, or every active member of the group asked
-- (never the asker). An approval says so; a plain question reads as before.
CREATE OR REPLACE FUNCTION pm.notify_question_asked()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  asker text;
  title text;
  group_name text;
  recipient uuid;
BEGIN
  IF NEW.status <> 'open' OR NEW.deleted_at IS NOT NULL OR NEW.asked_to = NEW.asked_by THEN
    RETURN NULL;
  END IF;
  SELECT name INTO asker FROM pm.team_members WHERE id = NEW.asked_by;
  title := CASE WHEN NEW.kind = 'approval' THEN 'Approval request from ' ELSE 'Question from ' END
    || COALESCE(NULLIF(btrim(asker), ''), 'a teammate');
  IF NEW.asked_to IS NOT NULL THEN
    PERFORM pm.upsert_notification(
      NEW.asked_to,
      title,
      left(NEW.question, 500),
      -- My Tasks, where the asked member answers it: they may not be able to
      -- open the task or project it is on.
      '/my-tasks',
      'question',
      NEW.id::text
    );
    RETURN NULL;
  END IF;
  SELECT g.name INTO group_name FROM pm.groups g WHERE g.id = NEW.asked_to_group;
  title := title || ' to ' || COALESCE(NULLIF(btrim(group_name), ''), 'your group');
  FOR recipient IN
    SELECT gm.member_id
    FROM pm.group_members gm
    JOIN pm.team_members m ON m.id = gm.member_id
    WHERE gm.group_id = NEW.asked_to_group
      AND gm.member_id <> NEW.asked_by
      AND coalesce(m.status, 'active') = 'active'
  LOOP
    PERFORM pm.upsert_notification(recipient, title, left(NEW.question, 500), '/my-tasks', 'question', NEW.id::text);
  END LOOP;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.notify_question_asked() FROM PUBLIC, anon, authenticated;

-- Who a question event concerns adds the group's members and the person an
-- agent acted for.
CREATE OR REPLACE FUNCTION pm.webhook_event_members(p_subject_type text, p_subject_id uuid, p_also uuid[] DEFAULT '{}')
RETURNS uuid[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT coalesce(array_agg(DISTINCT m ORDER BY m) FILTER (WHERE m IS NOT NULL), '{}')
  FROM (
    SELECT a.member_id AS m FROM pm.task_assignees a
    WHERE p_subject_type = 'task' AND a.task_id = p_subject_id
    UNION ALL
    SELECT t.claimed_by FROM pm.tasks t
    WHERE p_subject_type = 'task' AND t.id = p_subject_id
      AND (t.claim_expires_at IS NULL OR t.claim_expires_at > now())
    UNION ALL
    SELECT unnest(ARRAY[q.asked_to, q.asked_by, q.principal_id]) FROM pm.questions q
    WHERE p_subject_type = 'question' AND q.id = p_subject_id
    UNION ALL
    SELECT gm.member_id FROM pm.questions q
    JOIN pm.group_members gm ON gm.group_id = q.asked_to_group
    WHERE p_subject_type = 'question' AND q.id = p_subject_id
    UNION ALL
    SELECT unnest(ARRAY[s.proposed_by, s.assigned_to]) FROM pm.task_suggestions s
    WHERE p_subject_type = 'suggestion' AND s.id = p_subject_id
    UNION ALL
    SELECT unnest(coalesce(p_also, '{}'))
  ) members
$$;

REVOKE ALL ON FUNCTION pm.webhook_event_members(text, uuid, uuid[]) FROM PUBLIC, anon, authenticated;

-- Webhooks: asked_to_group and principal_id join the question object when
-- set. A plain question's payload is byte for byte what it was.
CREATE OR REPLACE FUNCTION pm.emit_question_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['question.asked', 'question.answered', 'question.cancelled']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'open' AND NEW.deleted_at IS NULL THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.deleted_at IS NOT NULL THEN
    IF OLD.deleted_at IS NULL AND OLD.status = 'open' THEN
      v_type := 'question.cancelled';
    END IF;
  ELSIF OLD.deleted_at IS NOT NULL THEN
    IF NEW.status = 'open' THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_type := CASE NEW.status
      WHEN 'open' THEN 'question.asked'
      WHEN 'answered' THEN 'question.answered'
      WHEN 'cancelled' THEN 'question.cancelled'
    END;
  END IF;
  IF v_type IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'question',
    NEW.id,
    ARRAY[NEW.project_id],
    pm.webhook_event_members('question', NEW.id),
    jsonb_build_object(
      'question', jsonb_build_object(
        'id', NEW.id,
        'project_id', NEW.project_id,
        'task_id', NEW.task_id,
        'asked_by', NEW.asked_by,
        'asked_to', NEW.asked_to,
        'question', NEW.question,
        'choices', NEW.choices,
        'allow_other', NEW.allow_other,
        'status', NEW.status,
        'answer_choice', NEW.answer_choice,
        'answer_text', NEW.answer_text,
        'answered_by', NEW.answered_by,
        'answered_at', NEW.answered_at,
        'cancelled_by', NEW.cancelled_by,
        'cancelled_at', NEW.cancelled_at,
        'expires_at', NEW.expires_at,
        'created_at', NEW.created_at,
        'updated_at', NEW.updated_at,
        'deleted_at', NEW.deleted_at
      ) || CASE WHEN NEW.kind = 'approval' THEN jsonb_build_object(
        'kind', NEW.kind,
        'action', NEW.action,
        'decision', CASE NEW.answer_choice WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' END,
        'decided_by', CASE WHEN NEW.status = 'answered' THEN NEW.answered_by END
      ) ELSE '{}'::jsonb END
        || CASE WHEN NEW.asked_to_group IS NOT NULL THEN jsonb_build_object('asked_to_group', NEW.asked_to_group) ELSE '{}'::jsonb END
        || CASE WHEN NEW.principal_id IS NOT NULL THEN jsonb_build_object('principal_id', NEW.principal_id) ELSE '{}'::jsonb END,
      'project', CASE WHEN NEW.project_id IS NOT NULL THEN jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ) END,
      'project_id', NEW.project_id,
      'task_id', NEW.task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_question_webhook() FROM PUBLIC, anon, authenticated;

-- A member of the group asked is a party to the question.
DROP POLICY IF EXISTS questions_select ON pm.questions;
CREATE POLICY questions_select ON pm.questions FOR SELECT TO authenticated
  USING (
    asked_by = pm.current_team_member_id()
    OR asked_to = pm.current_team_member_id()
    OR (asked_to_group IS NOT NULL AND EXISTS (SELECT 1 FROM pm.group_members gm WHERE gm.group_id = questions.asked_to_group AND gm.member_id = pm.current_team_member_id()))
    OR (task_id IS NOT NULL AND pm.can_access_task(task_id))
    OR (task_id IS NULL AND project_id IS NOT NULL AND pm.can_access_project(project_id))
  );

-- ---------------------------------------------------------------------------
-- Escalation to a group, and groups that own agents
-- ---------------------------------------------------------------------------
ALTER TABLE pm.team_members
  ADD COLUMN IF NOT EXISTS agent_escalate_to_group uuid REFERENCES pm.groups(id) ON DELETE SET NULL;

COMMENT ON COLUMN pm.team_members.agent_escalate_to_group IS
  'An agent''s escalation group: any member answers its questions. agent_escalate_to (a person) comes first when both are set.';

CREATE TABLE IF NOT EXISTS pm.agent_owner_groups (
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  group_id uuid NOT NULL REFERENCES pm.groups(id) ON DELETE CASCADE,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (agent_id, group_id)
);

COMMENT ON TABLE pm.agent_owner_groups IS
  'Groups responsible for an agent, beside its people (pm.agent_owners): any member manages it as an owner. Written by the server only.';

-- The agents a group owns.
CREATE INDEX IF NOT EXISTS idx_agent_owner_groups_group ON pm.agent_owner_groups (group_id);

CREATE OR REPLACE FUNCTION pm.handle_agent_owner_group_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pm.team_members m WHERE m.id = NEW.agent_id AND m.role = 'agent') THEN
    RAISE EXCEPTION 'Only an agent has owners' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_agent_owner_group_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS agent_owner_groups_before_write ON pm.agent_owner_groups;
CREATE TRIGGER agent_owner_groups_before_write
  BEFORE INSERT OR UPDATE ON pm.agent_owner_groups
  FOR EACH ROW EXECUTE FUNCTION pm.handle_agent_owner_group_before_write();

ALTER TABLE pm.agent_owner_groups ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS agent_owner_groups_select ON pm.agent_owner_groups;
CREATE POLICY agent_owner_groups_select ON pm.agent_owner_groups FOR SELECT TO authenticated
  USING (pm.has_permission('team.read') OR agent_id = pm.current_team_member_id() OR EXISTS (SELECT 1 FROM pm.group_members gm WHERE gm.group_id = agent_owner_groups.group_id AND gm.member_id = pm.current_team_member_id()));

DROP POLICY IF EXISTS agent_owner_groups_module_on ON pm.agent_owner_groups;
CREATE POLICY agent_owner_groups_module_on ON pm.agent_owner_groups AS RESTRICTIVE FOR ALL TO authenticated
  USING ((select pm.module_enabled('agents')));

REVOKE ALL ON pm.agent_owner_groups FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.agent_owner_groups TO authenticated;
GRANT ALL ON pm.agent_owner_groups TO service_role;

-- ---------------------------------------------------------------------------
-- Linked identities
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.member_identities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  member_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  provider text NOT NULL,
  external_id text NOT NULL,
  workspace_id text,
  handle text,
  verified_at timestamptz,
  verified_method text,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.member_identities DROP CONSTRAINT IF EXISTS member_identities_provider_shape;
ALTER TABLE pm.member_identities
  ADD CONSTRAINT member_identities_provider_shape CHECK (provider ~ '^(slack|teams|telegram|discord|github|email|custom\.[a-z0-9][a-z0-9_-]{0,39})$');
ALTER TABLE pm.member_identities DROP CONSTRAINT IF EXISTS member_identities_external_id_shape;
ALTER TABLE pm.member_identities
  ADD CONSTRAINT member_identities_external_id_shape CHECK (length(external_id) BETWEEN 1 AND 255 AND external_id = btrim(external_id));
ALTER TABLE pm.member_identities DROP CONSTRAINT IF EXISTS member_identities_workspace_id_length;
ALTER TABLE pm.member_identities
  ADD CONSTRAINT member_identities_workspace_id_length CHECK (workspace_id IS NULL OR length(workspace_id) BETWEEN 1 AND 255);
ALTER TABLE pm.member_identities DROP CONSTRAINT IF EXISTS member_identities_handle_length;
ALTER TABLE pm.member_identities
  ADD CONSTRAINT member_identities_handle_length CHECK (handle IS NULL OR length(handle) BETWEEN 1 AND 255);
ALTER TABLE pm.member_identities DROP CONSTRAINT IF EXISTS member_identities_verified_method_check;
ALTER TABLE pm.member_identities
  ADD CONSTRAINT member_identities_verified_method_check CHECK (verified_method IS NULL OR verified_method IN ('link', 'admin', 'directory'));
ALTER TABLE pm.member_identities DROP CONSTRAINT IF EXISTS member_identities_verified_together;
ALTER TABLE pm.member_identities
  ADD CONSTRAINT member_identities_verified_together CHECK ((verified_at IS NULL) = (verified_method IS NULL));

COMMENT ON TABLE pm.member_identities IS
  'A member''s identities in other systems (Slack, Teams, Telegram, email, ...). Only verified ones resolve. Written by the server only.';
COMMENT ON COLUMN pm.member_identities.verified_method IS
  'How it was proven: link (the person confirmed it signed in), admin (an Owner or team manager linked it) or directory (a sync).';

-- One owner per identity (a null workspace counts as one workspace); a member's identities by provider.
CREATE UNIQUE INDEX IF NOT EXISTS member_identities_key
  ON pm.member_identities (provider, coalesce(workspace_id, ''), external_id);
CREATE INDEX IF NOT EXISTS idx_member_identities_member ON pm.member_identities (member_id, provider);

DROP TRIGGER IF EXISTS set_member_identities_updated_at ON pm.member_identities;
CREATE TRIGGER set_member_identities_updated_at
  BEFORE UPDATE ON pm.member_identities
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

ALTER TABLE pm.member_identities ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS member_identities_select ON pm.member_identities;
CREATE POLICY member_identities_select ON pm.member_identities FOR SELECT TO authenticated
  USING (member_id = pm.current_team_member_id() OR pm.has_permission('team.manage'));

REVOKE ALL ON pm.member_identities FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.member_identities TO authenticated;
GRANT ALL ON pm.member_identities TO service_role;

CREATE TABLE IF NOT EXISTS pm.identity_link_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  token_hash text NOT NULL,
  provider text NOT NULL,
  external_id text NOT NULL,
  workspace_id text,
  handle text,
  -- When set, only this member may confirm it.
  expected_member_id uuid REFERENCES pm.team_members(id) ON DELETE CASCADE,
  requested_by uuid REFERENCES pm.team_members(id) ON DELETE CASCADE,
  requested_by_key_id uuid REFERENCES pm.api_keys(id) ON DELETE SET NULL,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  consumed_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.identity_link_requests DROP CONSTRAINT IF EXISTS identity_link_requests_token_hash_key;
ALTER TABLE pm.identity_link_requests
  ADD CONSTRAINT identity_link_requests_token_hash_key UNIQUE (token_hash);
ALTER TABLE pm.identity_link_requests DROP CONSTRAINT IF EXISTS identity_link_requests_provider_shape;
ALTER TABLE pm.identity_link_requests
  ADD CONSTRAINT identity_link_requests_provider_shape CHECK (provider ~ '^(slack|teams|telegram|discord|github|email|custom\.[a-z0-9][a-z0-9_-]{0,39})$');
ALTER TABLE pm.identity_link_requests DROP CONSTRAINT IF EXISTS identity_link_requests_external_id_length;
ALTER TABLE pm.identity_link_requests
  ADD CONSTRAINT identity_link_requests_external_id_length CHECK (length(external_id) BETWEEN 1 AND 255);

COMMENT ON TABLE pm.identity_link_requests IS
  'One-time links a harness asks for so a person proves an identity is theirs. Only the token''s hash is stored. Service role only.';

ALTER TABLE pm.identity_link_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.identity_link_requests FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.identity_link_requests TO service_role;

-- ---------------------------------------------------------------------------
-- Delegation tokens
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.delegation_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  token_hash text NOT NULL,
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  principal_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  -- The identity it was minted for; unlinking it revokes the token.
  identity_id uuid REFERENCES pm.member_identities(id) ON DELETE CASCADE,
  minted_via text NOT NULL,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_by_key_id uuid REFERENCES pm.api_keys(id) ON DELETE SET NULL,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  last_used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.delegation_tokens DROP CONSTRAINT IF EXISTS delegation_tokens_token_hash_key;
ALTER TABLE pm.delegation_tokens
  ADD CONSTRAINT delegation_tokens_token_hash_key UNIQUE (token_hash);
ALTER TABLE pm.delegation_tokens DROP CONSTRAINT IF EXISTS delegation_tokens_minted_via_check;
ALTER TABLE pm.delegation_tokens
  ADD CONSTRAINT delegation_tokens_minted_via_check CHECK (minted_via IN ('identity', 'session'));
ALTER TABLE pm.delegation_tokens DROP CONSTRAINT IF EXISTS delegation_tokens_not_self;
ALTER TABLE pm.delegation_tokens
  ADD CONSTRAINT delegation_tokens_not_self CHECK (agent_id <> principal_id);

COMMENT ON TABLE pm.delegation_tokens IS
  'Short-lived tokens that let one agent act for one person (X-Act-For). Only the hash is stored, so each can be revoked. Service role only.';

CREATE INDEX IF NOT EXISTS idx_delegation_tokens_agent ON pm.delegation_tokens (agent_id, principal_id);
CREATE INDEX IF NOT EXISTS idx_delegation_tokens_principal ON pm.delegation_tokens (principal_id);

ALTER TABLE pm.delegation_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.delegation_tokens FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.delegation_tokens TO service_role;

-- ---------------------------------------------------------------------------
-- On behalf of: principal_id on what an agent makes for someone
-- ---------------------------------------------------------------------------
ALTER TABLE pm.agent_runs ADD COLUMN IF NOT EXISTS principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL;
ALTER TABLE pm.tasks ADD COLUMN IF NOT EXISTS principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL;
ALTER TABLE pm.agent_activities ADD COLUMN IF NOT EXISTS principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL;
ALTER TABLE pm.task_comments ADD COLUMN IF NOT EXISTS principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL;
ALTER TABLE pm.api_audit_log ADD COLUMN IF NOT EXISTS principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL;

COMMENT ON COLUMN pm.agent_runs.principal_id IS 'The person the agent acted for (X-Act-For); null when it acted as itself.';
COMMENT ON COLUMN pm.tasks.principal_id IS 'The person the agent that created it acted for (X-Act-For); null otherwise.';
COMMENT ON COLUMN pm.agent_activities.principal_id IS 'The person the agent acted for (X-Act-For); null when it acted as itself.';
COMMENT ON COLUMN pm.task_comments.principal_id IS 'The person the agent that wrote it acted for (X-Act-For); null otherwise.';
COMMENT ON COLUMN pm.api_audit_log.principal_id IS 'The person the API key''s agent acted for (X-Act-For); null when it acted as itself.';

-- What an agent did for one person.
CREATE INDEX IF NOT EXISTS idx_agent_runs_principal ON pm.agent_runs (principal_id, started_at DESC) WHERE principal_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_api_audit_log_principal ON pm.api_audit_log (principal_id) WHERE principal_id IS NOT NULL;

-- The person the current write acts for: the x-actor-principal-id header the
-- server sends with an agent's write (service role only), else what the
-- server set on the row. A signed-in member's own write acts for no one.
-- Fixed once written.
CREATE OR REPLACE FUNCTION pm.stamp_principal()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_header text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.principal_id := OLD.principal_id;
    RETURN NEW;
  END IF;
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    NEW.principal_id := NULL;
    RETURN NEW;
  END IF;
  BEGIN
    v_header := nullif(current_setting('request.headers', true), '')::json ->> 'x-actor-principal-id';
  EXCEPTION WHEN others THEN
    v_header := NULL;
  END;
  IF v_header ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND EXISTS (SELECT 1 FROM pm.team_members m WHERE m.id = v_header::uuid) THEN
    NEW.principal_id := v_header::uuid;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.stamp_principal() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS stamp_principal ON pm.agent_runs;
CREATE TRIGGER stamp_principal BEFORE INSERT OR UPDATE OF principal_id ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.stamp_principal();
DROP TRIGGER IF EXISTS stamp_principal ON pm.questions;
CREATE TRIGGER stamp_principal BEFORE INSERT OR UPDATE OF principal_id ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.stamp_principal();
DROP TRIGGER IF EXISTS stamp_principal ON pm.tasks;
CREATE TRIGGER stamp_principal BEFORE INSERT OR UPDATE OF principal_id ON pm.tasks
  FOR EACH ROW EXECUTE FUNCTION pm.stamp_principal();
DROP TRIGGER IF EXISTS stamp_principal ON pm.agent_activities;
CREATE TRIGGER stamp_principal BEFORE INSERT OR UPDATE OF principal_id ON pm.agent_activities
  FOR EACH ROW EXECUTE FUNCTION pm.stamp_principal();
DROP TRIGGER IF EXISTS stamp_principal ON pm.task_comments;
CREATE TRIGGER stamp_principal BEFORE INSERT OR UPDATE OF principal_id ON pm.task_comments
  FOR EACH ROW EXECUTE FUNCTION pm.stamp_principal();
DROP TRIGGER IF EXISTS stamp_principal ON pm.api_audit_log;
CREATE TRIGGER stamp_principal BEFORE INSERT OR UPDATE OF principal_id ON pm.api_audit_log
  FOR EACH ROW EXECUTE FUNCTION pm.stamp_principal();

