ALTER TABLE pm.mcp_profile_rows ENABLE ROW LEVEL SECURITY;
ALTER TABLE pm.agent_template_rows ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.mcp_profile_rows FROM PUBLIC, anon, authenticated;
REVOKE ALL ON pm.agent_template_rows FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.mcp_profile_rows TO service_role;
GRANT ALL ON pm.agent_template_rows TO service_role;

-- The four fleet profiles leave core. Only where a member still uses one does
-- it become a row, with the tool set it had (every tool its keys allow): an
-- install that never used them gets nothing.
INSERT INTO pm.mcp_profile_rows (value, label, description, tools)
SELECT v.value, v.label, v.description, NULL
FROM (VALUES
  ('coordinator', 'Coordinator', 'Plans and assigns work, keeps projects and leads current'),
  ('builder', 'Builder', 'Works assigned tasks, tracks time and raises blockers'),
  ('auditor', 'Auditor', 'Audits projects against their goals and proposes tasks'),
  ('reviewer', 'Reviewer', 'Reviews finished work and records verdicts')
) AS v(value, label, description)
WHERE EXISTS (SELECT 1 FROM pm.team_members m WHERE m.agent_profile = v.value)
ON CONFLICT (value) DO NOTHING;

-- ---------------------------------------------------------------------------
-- The template an agent was set up from, on the agent
-- ---------------------------------------------------------------------------
ALTER TABLE pm.team_members ADD COLUMN IF NOT EXISTS agent_template_key text;
ALTER TABLE pm.team_members DROP CONSTRAINT IF EXISTS team_members_agent_template_key_check;
ALTER TABLE pm.team_members
  ADD CONSTRAINT team_members_agent_template_key_check CHECK (agent_template_key IS NULL OR length(agent_template_key) BETWEEN 1 AND 100);

COMMENT ON COLUMN pm.team_members.agent_template_key IS
  'The template an agent was last set up from (hire, apply or import); null when none was. Kept on the agent, so audit retention cannot lose it.';

-- Once: the newest successful hire, apply or import that named a template.
UPDATE pm.team_members m
SET agent_template_key = t.template_key
FROM (
  SELECT DISTINCT ON (l.entity_id) l.entity_id, l.request_body->>'template' AS template_key
  FROM pm.api_audit_log l
  WHERE l.entity_type = 'team_member'
    AND l.status_code < 300
    AND jsonb_typeof(l.request_body->'template') = 'string'
    AND (l.endpoint IN ('/api/v1/agents/import', '/api/workspace/agents') OR l.endpoint = '/api/v1/agents/' || l.entity_id::text || '/template')
  ORDER BY l.entity_id, l.timestamp DESC, l.id DESC
) t
WHERE m.id = t.entity_id
  AND m.role = 'agent'
  AND m.agent_template_key IS NULL
  AND length(t.template_key) BETWEEN 1 AND 100;

-- Older code records the template only in the audit log: each such row sets it on the agent too,
-- unless a newer one already named another.
CREATE OR REPLACE FUNCTION pm.record_agent_template_key()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF NEW.endpoint IN ('/api/v1/agents/import', '/api/workspace/agents') OR NEW.endpoint = '/api/v1/agents/' || NEW.entity_id::text || '/template' THEN
    UPDATE pm.team_members
    SET agent_template_key = NEW.request_body->>'template'
    WHERE id = NEW.entity_id
      AND role = 'agent'
      AND length(NEW.request_body->>'template') BETWEEN 1 AND 100
      AND agent_template_key IS DISTINCT FROM NEW.request_body->>'template'
      AND NOT EXISTS (
        SELECT 1 FROM pm.api_audit_log l
        WHERE l.entity_type = 'team_member'
          AND l.entity_id = NEW.entity_id
          AND l.id <> NEW.id
          AND l.status_code < 300
          AND l.timestamp > NEW.timestamp
          AND jsonb_typeof(l.request_body->'template') = 'string'
          AND (l.endpoint IN ('/api/v1/agents/import', '/api/workspace/agents') OR l.endpoint = '/api/v1/agents/' || l.entity_id::text || '/template')
      );
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.record_agent_template_key() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS record_agent_template_key ON pm.api_audit_log;
CREATE TRIGGER record_agent_template_key AFTER INSERT ON pm.api_audit_log
  FOR EACH ROW
  WHEN (NEW.entity_type = 'team_member' AND NEW.status_code < 300 AND jsonb_typeof(NEW.request_body->'template') = 'string')
  EXECUTE FUNCTION pm.record_agent_template_key();

-- Retention keeps what the app still reads from the log: the agents a
-- deprovision took ownership of and, for one more release, the template an
-- agent was set up from (2.0.29 reads it there; it now lives on the agent).
-- The next release drops the template exception.
CREATE OR REPLACE FUNCTION pm.purge_audit_log()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_days integer;
  v_count integer := 0;
BEGIN
  SELECT audit_retention_days INTO v_days FROM pm.business_settings LIMIT 1;
  IF v_days IS NULL THEN
    RETURN 0;
  END IF;
  PERFORM set_config('pm.audit_retention', 'on', true);
  DELETE FROM pm.api_audit_log l
  WHERE l.timestamp < now() - make_interval(days => v_days)
    -- The template an agent was set up from (2.0.29 reads it here). Dropped next release.
    AND NOT coalesce(l.entity_type = 'team_member' AND l.request_body ? 'template', false)
    -- The agents a deprovision took ownership of (read on reactivation).
    AND NOT coalesce(l.endpoint LIKE '/app/team-members/%/deprovision' AND l.request_body->>'step' = 'owner_removed', false);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  PERFORM set_config('pm.audit_retention', 'off', true);
  IF v_count > 0 THEN
    INSERT INTO pm.api_audit_log (method, endpoint, entity_type, request_body, status_code, via)
    VALUES ('DELETE', '/app/audit/retention', 'api_audit_log',
      jsonb_build_object('deleted', v_count, 'retention_days', v_days), 200, 'app');
  END IF;
  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION pm.purge_audit_log() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.purge_audit_log() TO service_role;

-- ============================================================
-- FOLLOW-UPS (20261125000200_followups.sql)
-- A wake signal for re-queued mail (messages.requeued_at, stamped by a
-- trigger); a default lifetime for personal API keys (Owner only); group
-- handlers' inbox access derived when it is read, the copying stopped and
-- the rows it made removed where they can be told apart.
-- ============================================================

-- ---------------------------------------------------------------------------
-- Re-queued mail: messages.requeued_at
-- ---------------------------------------------------------------------------
ALTER TABLE pm.messages
  ADD COLUMN IF NOT EXISTS requeued_at timestamptz;

COMMENT ON COLUMN pm.messages.requeued_at IS
  'When the message last went back to New for the agent after leaving it (sent back, answered, moved out of Filtered). Stamped by a trigger; null until then.';

CREATE OR REPLACE FUNCTION pm.messages_stamp_requeued()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.requeued_at := NULL;
  ELSIF NEW.status = 'new' AND OLD.status NOT IN ('new', 'receiving') THEN
    NEW.requeued_at := now();
  ELSE
    NEW.requeued_at := OLD.requeued_at;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.messages_stamp_requeued() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS messages_stamp_requeued ON pm.messages;
CREATE TRIGGER messages_stamp_requeued
  BEFORE INSERT OR UPDATE ON pm.messages
  FOR EACH ROW EXECUTE FUNCTION pm.messages_stamp_requeued();

-- ---------------------------------------------------------------------------
-- A default lifetime for personal API keys
-- ---------------------------------------------------------------------------
ALTER TABLE pm.business_settings
  ADD COLUMN IF NOT EXISTS personal_key_lifetime_days integer;

ALTER TABLE pm.business_settings DROP CONSTRAINT IF EXISTS business_settings_personal_key_lifetime_days_check;
ALTER TABLE pm.business_settings
  ADD CONSTRAINT business_settings_personal_key_lifetime_days_check CHECK (personal_key_lifetime_days IS NULL OR personal_key_lifetime_days BETWEEN 1 AND 3650);

COMMENT ON COLUMN pm.business_settings.personal_key_lifetime_days IS
  'How many days a person''s new key lasts unless they choose otherwise, and the longest anyone but an Owner may choose (null: until revoked, no limit). Keys made before keep their own expiry. An Owner sets it.';

-- Owner-only settings on the business row, now with the personal key lifetime.
CREATE OR REPLACE FUNCTION pm.business_settings_owner_columns()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF auth.role() = 'service_role' OR auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  IF (TG_OP = 'INSERT' AND (NEW.auto_migrate IS DISTINCT FROM true OR NEW.owners_read_personal_inboxes IS DISTINCT FROM false
       OR NEW.agents_paused_at IS NOT NULL OR NEW.audit_retention_days IS NOT NULL OR NEW.audit_redact_keys <> '{}'
       OR NEW.connect_ai_enabled IS DISTINCT FROM true OR NEW.personal_key_lifetime_days IS NOT NULL))
     OR (TG_OP = 'UPDATE' AND (NEW.auto_migrate IS DISTINCT FROM OLD.auto_migrate
       OR NEW.owners_read_personal_inboxes IS DISTINCT FROM OLD.owners_read_personal_inboxes
       OR NEW.agents_paused_at IS DISTINCT FROM OLD.agents_paused_at
       OR NEW.agents_paused_by IS DISTINCT FROM OLD.agents_paused_by
       OR NEW.audit_retention_days IS DISTINCT FROM OLD.audit_retention_days
       OR NEW.audit_redact_keys IS DISTINCT FROM OLD.audit_redact_keys
       OR NEW.connect_ai_enabled IS DISTINCT FROM OLD.connect_ai_enabled
       OR NEW.personal_key_lifetime_days IS DISTINCT FROM OLD.personal_key_lifetime_days)) THEN
    IF COALESCE(pm.current_team_member_role(), '') <> 'owner' THEN
      RAISE EXCEPTION 'Only an Owner can change this setting' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.business_settings_owner_columns() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Group handlers: inbox access derived when it is read
-- ---------------------------------------------------------------------------
-- Who reads an inbox, as before, plus the members of a live group that
-- handles it, for as long as all three hold.
CREATE OR REPLACE FUNCTION pm.can_read_inbox(p_inbox_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT EXISTS (
    SELECT 1 FROM pm.inboxes i
    WHERE i.id = p_inbox_id
      AND CASE
        -- Shared: inbound_email.manage reads every one; inbound_email.read the granted ones.
        WHEN i.owner_member_id IS NULL THEN
          pm.has_permission('inbound_email.manage', 'app')
          OR (
            pm.has_permission('inbound_email.read', 'app')
            AND (
              EXISTS (
                SELECT 1 FROM pm.inbox_access a
                WHERE a.inbox_id = i.id AND a.member_id = pm.current_team_member_id()
              )
              OR EXISTS (
                SELECT 1 FROM pm.inbox_handlers h
                JOIN pm.group_members gm ON gm.group_id = h.handler_group_id
                JOIN pm.groups g ON g.id = h.handler_group_id AND g.deleted_at IS NULL
                WHERE h.inbox_id = i.id AND gm.member_id = pm.current_team_member_id()
              )
            )
          )
        -- Personal: its owner and the people it was shared with, while the
        -- Inbox is on; managing inboxes only while the workspace allows it.
        ELSE
          (
            pm.module_enabled('inbox')
            AND (
              i.owner_member_id = pm.current_team_member_id()
              OR EXISTS (
                SELECT 1 FROM pm.inbox_access a
                WHERE a.inbox_id = i.id AND a.member_id = pm.current_team_member_id()
              )
              OR EXISTS (
                SELECT 1 FROM pm.inbox_handlers h
                JOIN pm.group_members gm ON gm.group_id = h.handler_group_id
                JOIN pm.groups g ON g.id = h.handler_group_id AND g.deleted_at IS NULL
                WHERE h.inbox_id = i.id AND gm.member_id = pm.current_team_member_id()
              )
            )
          )
          OR (
            pm.has_permission('inbound_email.manage', 'app')
            AND COALESCE((SELECT s.owners_read_personal_inboxes FROM pm.business_settings s LIMIT 1), false)
          )
      END
  )
$$;

REVOKE ALL ON FUNCTION pm.can_read_inbox(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION pm.can_read_inbox(uuid) TO authenticated, service_role;

-- Changing the rows: a member handler reads its inbox (a group's members read
-- it through the group, above), and the column follows the primary member.
CREATE OR REPLACE FUNCTION pm.inbox_handlers_after_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_inbox uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.inbox_id ELSE NEW.inbox_id END;
  v_primary uuid;
BEGIN
  IF TG_OP <> 'DELETE' AND NEW.handler_member_id IS NOT NULL THEN
    INSERT INTO pm.inbox_access (inbox_id, member_id) VALUES (NEW.inbox_id, NEW.handler_member_id)
    ON CONFLICT DO NOTHING;
  END IF;
  IF coalesce(current_setting('pm.inbox_handler_sync', true), '') = 'on' THEN
    RETURN NULL;
  END IF;
  SELECT h.handler_member_id INTO v_primary FROM pm.inbox_handlers h WHERE h.inbox_id = v_inbox AND h.is_primary;
  PERFORM set_config('pm.inbox_handler_sync', 'on', true);
  UPDATE pm.inboxes SET handler_member_id = v_primary
  WHERE id = v_inbox AND handler_member_id IS DISTINCT FROM v_primary;
  PERFORM set_config('pm.inbox_handler_sync', '', true);
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.inbox_handlers_after_write() FROM PUBLIC, anon, authenticated;

-- Joining a group no longer copies its inboxes' access.
DROP TRIGGER IF EXISTS group_members_grant_handled_inboxes ON pm.group_members;
DROP FUNCTION IF EXISTS pm.group_members_grant_handled_inboxes();

-- The rows the copying made, where they can be told apart (see the header).
DELETE FROM pm.inbox_access a
USING pm.inbox_handlers h, pm.group_members gm, pm.inboxes i
WHERE h.inbox_id = a.inbox_id
  AND h.handler_group_id IS NOT NULL
  AND gm.group_id = h.handler_group_id
  AND gm.member_id = a.member_id
  AND i.id = a.inbox_id
  AND a.created_by IS NULL
  AND a.created_at >= h.created_at
  AND a.member_id IS DISTINCT FROM i.owner_member_id
  AND a.member_id IS DISTINCT FROM i.handler_member_id
  AND NOT EXISTS (
    SELECT 1 FROM pm.inbox_handlers mh
    WHERE mh.inbox_id = a.inbox_id AND mh.handler_member_id = a.member_id
  );

-- ============================================================
-- TASK TEMPLATES (20261125000300_task_templates.sql)
-- One task or a playbook of tasks used again and again: the library
-- (task_templates, versioned, lockable to a project, in Trash never
-- removed), every use recorded as a run with its snapshot and the tasks it
-- made (task_template_runs), templates.manage for Admins, and template.run
-- on the webhook outbox.
-- ============================================================

-- ---------------------------------------------------------------------------
-- Templates
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.task_templates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  -- Locked to one project: shown only there, and it always creates there.
  project_id uuid REFERENCES pm.projects(id),
  -- [{ "key": "product", "label": "Product" }]
  fields jsonb NOT NULL DEFAULT '[]'::jsonb,
  -- [{ "title", "description", "priority", "tags", "assignee", "due_in_days", "subtasks": [...] }]
  items jsonb NOT NULL DEFAULT '[]'::jsonb,
  version integer NOT NULL DEFAULT 1,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- Trash: when it was deleted and by whom (null = live). Rows are never removed.
  deleted_at timestamptz,
  deleted_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL
);

ALTER TABLE pm.task_templates DROP CONSTRAINT IF EXISTS task_templates_name_length;
ALTER TABLE pm.task_templates
  ADD CONSTRAINT task_templates_name_length CHECK (length(btrim(name)) BETWEEN 1 AND 120);
ALTER TABLE pm.task_templates DROP CONSTRAINT IF EXISTS task_templates_description_length;
ALTER TABLE pm.task_templates
  ADD CONSTRAINT task_templates_description_length CHECK (length(description) <= 2000);
ALTER TABLE pm.task_templates DROP CONSTRAINT IF EXISTS task_templates_fields_shape;
ALTER TABLE pm.task_templates
  ADD CONSTRAINT task_templates_fields_shape CHECK (jsonb_typeof(fields) = 'array' AND jsonb_array_length(fields) <= 10);
ALTER TABLE pm.task_templates DROP CONSTRAINT IF EXISTS task_templates_items_shape;
ALTER TABLE pm.task_templates
  ADD CONSTRAINT task_templates_items_shape CHECK (jsonb_typeof(items) = 'array' AND jsonb_array_length(items) <= 50);
ALTER TABLE pm.task_templates DROP CONSTRAINT IF EXISTS task_templates_version_positive;
ALTER TABLE pm.task_templates
  ADD CONSTRAINT task_templates_version_positive CHECK (version >= 1);

COMMENT ON TABLE pm.task_templates IS
  'Task templates: one task or a playbook of tasks with subtasks, fill-in fields and due dates counted from a start date. Written by the server only.';
COMMENT ON COLUMN pm.task_templates.project_id IS
  'Locked to this project: the template shows only there and always creates there. Null: any project.';
COMMENT ON COLUMN pm.task_templates.version IS
  'Goes up by one whenever what the template makes changes (name, description, project, fields, items).';

-- The library by name; a project's templates; Trash.
CREATE INDEX IF NOT EXISTS idx_task_templates_name ON pm.task_templates (lower(name), id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_task_templates_project ON pm.task_templates (project_id) WHERE deleted_at IS NULL AND project_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_task_templates_deleted_at ON pm.task_templates (deleted_at DESC) WHERE deleted_at IS NOT NULL;

-- Who made it, and when, never change; the version follows what it makes.
CREATE OR REPLACE FUNCTION pm.handle_task_template_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  NEW.name := btrim(NEW.name);
  IF TG_OP = 'INSERT' THEN
    NEW.version := 1;
  ELSE
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
    IF (NEW.name, NEW.description, NEW.project_id, NEW.fields, NEW.items)
       IS DISTINCT FROM (OLD.name, OLD.description, OLD.project_id, OLD.fields, OLD.items) THEN
      NEW.version := OLD.version + 1;
    ELSE
      NEW.version := OLD.version;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_task_template_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS task_templates_before_write ON pm.task_templates;
CREATE TRIGGER task_templates_before_write
  BEFORE INSERT OR UPDATE ON pm.task_templates
  FOR EACH ROW EXECUTE FUNCTION pm.handle_task_template_before_write();

DROP TRIGGER IF EXISTS set_task_templates_updated_at ON pm.task_templates;
CREATE TRIGGER set_task_templates_updated_at
  BEFORE UPDATE ON pm.task_templates
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

-- Never permanently deleted.
DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.task_templates;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.task_templates
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.task_templates;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.task_templates
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

ALTER TABLE pm.task_templates ENABLE ROW LEVEL SECURITY;

-- Whoever may create tasks or manage templates reads the library; a template
-- locked to a project only while they can open that project.
DROP POLICY IF EXISTS task_templates_select ON pm.task_templates;
CREATE POLICY task_templates_select ON pm.task_templates FOR SELECT TO authenticated
  USING (
    (pm.has_permission('templates.manage') OR pm.has_permission('tasks.create'))
    AND (task_templates.project_id IS NULL OR pm.can_access_project(task_templates.project_id))
  );

DROP POLICY IF EXISTS task_templates_not_deleted ON pm.task_templates;
CREATE POLICY task_templates_not_deleted ON pm.task_templates AS RESTRICTIVE FOR ALL TO authenticated
  USING (deleted_at IS NULL) WITH CHECK (deleted_at IS NULL);

REVOKE ALL ON pm.task_templates FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.task_templates TO authenticated;
GRANT ALL ON pm.task_templates TO service_role;

-- ---------------------------------------------------------------------------
-- Runs: every use of a template
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.task_template_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  template_id uuid NOT NULL REFERENCES pm.task_templates(id),
  template_version integer NOT NULL,
  -- What the template held when it ran: { name, fields, items }.
  snapshot jsonb NOT NULL,
  project_id uuid NOT NULL REFERENCES pm.projects(id),
  run_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  via text NOT NULL DEFAULT 'app',
  -- The schedule that ran it (schedules come later and add the reference).
  schedule_id uuid,
  start_date date NOT NULL,
  field_values jsonb NOT NULL DEFAULT '{}'::jsonb,
  -- Every task it made, subtasks included, in the order they were made.
  task_ids uuid[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.task_template_runs DROP CONSTRAINT IF EXISTS task_template_runs_via_check;
ALTER TABLE pm.task_template_runs
  ADD CONSTRAINT task_template_runs_via_check CHECK (via IN ('app', 'api', 'mcp', 'schedule'));
ALTER TABLE pm.task_template_runs DROP CONSTRAINT IF EXISTS task_template_runs_snapshot_shape;
ALTER TABLE pm.task_template_runs
  ADD CONSTRAINT task_template_runs_snapshot_shape CHECK (jsonb_typeof(snapshot) = 'object' AND jsonb_typeof(field_values) = 'object');

COMMENT ON TABLE pm.task_template_runs IS
  'One row per use of a task template: its version and snapshot, who ran it and how, the project, start date, fill-in values and the tasks it made. Never changed or removed. Written by the server only.';
COMMENT ON COLUMN pm.task_template_runs.schedule_id IS
  'The schedule that ran it, once schedules exist. Null for a run made by hand, over the API or MCP.';

-- A template's runs, newest first; a schedule's last run.
CREATE INDEX IF NOT EXISTS idx_task_template_runs_template ON pm.task_template_runs (template_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_task_template_runs_schedule ON pm.task_template_runs (schedule_id, created_at DESC) WHERE schedule_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_task_template_runs_project ON pm.task_template_runs (project_id, created_at DESC);

-- Never permanently deleted.
DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.task_template_runs;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.task_template_runs
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.task_template_runs;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.task_template_runs
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

ALTER TABLE pm.task_template_runs ENABLE ROW LEVEL SECURITY;

-- Your own runs, and the runs on projects you can open while you may use templates.
DROP POLICY IF EXISTS task_template_runs_select ON pm.task_template_runs;
CREATE POLICY task_template_runs_select ON pm.task_template_runs FOR SELECT TO authenticated
  USING (
    task_template_runs.run_by = pm.current_team_member_id()
    OR (
      (pm.has_permission('templates.manage') OR pm.has_permission('tasks.create'))
      AND pm.can_access_project(task_template_runs.project_id)
    )
  );

REVOKE ALL ON pm.task_template_runs FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.task_template_runs TO authenticated;
GRANT ALL ON pm.task_template_runs TO service_role;

-- Each template's runs counted, and its last, so the library reads them in one query.
CREATE OR REPLACE VIEW pm.task_template_run_stats WITH (security_invoker = true) AS
  SELECT
    template_id,
    count(*)::integer AS runs,
    max(created_at) AS last_run_at
  FROM pm.task_template_runs
  GROUP BY template_id;

REVOKE ALL ON pm.task_template_run_stats FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.task_template_run_stats TO authenticated;
GRANT SELECT ON pm.task_template_run_stats TO service_role;

-- ---------------------------------------------------------------------------
-- Webhooks: template.run, concerning who ran it and everyone its tasks are
-- assigned to. One look at webhook_endpoints when nobody subscribes.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.emit_task_template_run_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_members uuid[];
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['template.run']
  ) THEN
    RETURN NULL;
  END IF;

  SELECT coalesce(array_agg(DISTINCT m ORDER BY m) FILTER (WHERE m IS NOT NULL), '{}') INTO v_members
  FROM (
    SELECT NEW.run_by AS m
    UNION ALL
    SELECT a.member_id FROM pm.task_assignees a WHERE a.task_id = ANY (NEW.task_ids)
  ) members;

  PERFORM pm.emit_webhook_event(
    'template.run',
    'template_run',
    NEW.id,
    ARRAY[NEW.project_id],
    v_members,
    jsonb_build_object(
      'run', jsonb_build_object(
        'id', NEW.id,
        'template_id', NEW.template_id,
        'template_version', NEW.template_version,
        'template_name', coalesce(NEW.snapshot ->> 'name', ''),
        'project_id', NEW.project_id,
        'run_by', NEW.run_by,
        'via', NEW.via,
        'schedule_id', NEW.schedule_id,
        'start_date', NEW.start_date,
        'field_values', NEW.field_values,
        'task_ids', to_jsonb(NEW.task_ids),
        'created_at', NEW.created_at
      ),
      'project', jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ),
      'project_id', NEW.project_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_task_template_run_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_task_template_run_webhook ON pm.task_template_runs;
CREATE TRIGGER emit_task_template_run_webhook
  AFTER INSERT ON pm.task_template_runs
  FOR EACH ROW EXECUTE FUNCTION pm.emit_task_template_run_webhook();

-- ---------------------------------------------------------------------------
-- Permissions: managing templates is core; Admins hold it by default
-- ---------------------------------------------------------------------------
-- templates.manage is core (no module), so it has no permission_modules row.
INSERT INTO pm.role_permissions (role, permission_key, access_channel) VALUES
  ('admin', 'templates.manage', 'app'),
  ('admin', 'templates.manage', 'api')
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- Live sync: open screens see the library and its runs change.
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables
                   WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'task_templates') THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE pm.task_templates;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables
                   WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'task_template_runs') THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE pm.task_template_runs;
    END IF;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Trash: templates join Settings > Trash like every other record
-- ---------------------------------------------------------------------------
-- (The functions above are edited in place where Trash is defined.)
DROP TRIGGER IF EXISTS record_trash_event ON pm.task_templates;
CREATE TRIGGER record_trash_event AFTER UPDATE OF deleted_at ON pm.task_templates
  FOR EACH ROW WHEN (OLD.deleted_at IS DISTINCT FROM NEW.deleted_at)
  EXECUTE FUNCTION pm.record_trash_event();

-- ============================================================
-- GOOGLE SIGN-IN (20261125000400_google_sign_in.sql)
-- Sign in with Google beside email and password: the workspace setting
-- (business_settings.sign_in_methods, both by default, Owner only), and
-- service-only facts about logins (whether one has a password, whether the
-- project has other logins, who could sign in each way) for unlinking Google,
-- the first-owner claim and changing the methods.
-- ============================================================

-- ---------------------------------------------------------------------------
-- The workspace setting: which ways people sign in
-- ---------------------------------------------------------------------------
-- Last of the table changes: these lock business_settings, briefly.
ALTER TABLE pm.business_settings
  ADD COLUMN IF NOT EXISTS sign_in_methods text NOT NULL DEFAULT 'both';
ALTER TABLE pm.business_settings ALTER COLUMN sign_in_methods SET DEFAULT 'both';

ALTER TABLE pm.business_settings DROP CONSTRAINT IF EXISTS business_settings_sign_in_methods_check;
ALTER TABLE pm.business_settings
  ADD CONSTRAINT business_settings_sign_in_methods_check CHECK (sign_in_methods IN ('password', 'google', 'both'));

COMMENT ON COLUMN pm.business_settings.sign_in_methods IS
  'How people sign in: both (email and password, or Google: the default), password (email and password only) or google (Google only). The sign-in page shows Google only while the provider is on in Supabase. Only an active team member gets in either way. An Owner sets it.';

-- Owner-only settings on the business row, now with the sign-in methods.
CREATE OR REPLACE FUNCTION pm.business_settings_owner_columns()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF auth.role() = 'service_role' OR auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  IF (TG_OP = 'INSERT' AND (NEW.auto_migrate IS DISTINCT FROM true OR NEW.owners_read_personal_inboxes IS DISTINCT FROM false
       OR NEW.agents_paused_at IS NOT NULL OR NEW.audit_retention_days IS NOT NULL OR NEW.audit_redact_keys <> '{}'
       OR NEW.connect_ai_enabled IS DISTINCT FROM true OR NEW.personal_key_lifetime_days IS NOT NULL
       OR NEW.sign_in_methods IS DISTINCT FROM 'both'))
     OR (TG_OP = 'UPDATE' AND (NEW.auto_migrate IS DISTINCT FROM OLD.auto_migrate
       OR NEW.owners_read_personal_inboxes IS DISTINCT FROM OLD.owners_read_personal_inboxes
       OR NEW.agents_paused_at IS DISTINCT FROM OLD.agents_paused_at
       OR NEW.agents_paused_by IS DISTINCT FROM OLD.agents_paused_by
       OR NEW.audit_retention_days IS DISTINCT FROM OLD.audit_retention_days
       OR NEW.audit_redact_keys IS DISTINCT FROM OLD.audit_redact_keys
       OR NEW.connect_ai_enabled IS DISTINCT FROM OLD.connect_ai_enabled
       OR NEW.personal_key_lifetime_days IS DISTINCT FROM OLD.personal_key_lifetime_days
       OR NEW.sign_in_methods IS DISTINCT FROM OLD.sign_in_methods)) THEN
    IF COALESCE(pm.current_team_member_role(), '') <> 'owner' THEN
      RAISE EXCEPTION 'Only an Owner can change this setting' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.business_settings_owner_columns() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- What the server needs to know about a login (service role only)
-- ---------------------------------------------------------------------------
-- Whether a login has a password: an invited person who joined with Google
-- has none, so unlinking Google would leave them no way in.
CREATE OR REPLACE FUNCTION pm.login_has_password(p_user uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = p_user AND coalesce(u.encrypted_password, '') <> '')
$$;

REVOKE ALL ON FUNCTION pm.login_has_password(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.login_has_password(uuid) TO service_role;

-- Whether the project has logins besides this one (another app's users).
-- Signing in with Google makes a login before the first Owner is claimed, so
-- the claim asks about the others, not about any login at all.
CREATE OR REPLACE FUNCTION pm.other_logins_exist(p_user uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT EXISTS (SELECT 1 FROM auth.users u WHERE u.id IS DISTINCT FROM p_user)
$$;

REVOKE ALL ON FUNCTION pm.other_logins_exist(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.other_logins_exist(uuid) TO service_role;

-- Who could sign in each way, for an Owner changing the sign-in methods:
-- every active person on the team (agents work through keys) whose login has
-- signed in at least once (an invite still waiting can be accepted either
-- way), with whether it has a password and whether Google is linked.
CREATE OR REPLACE FUNCTION pm.member_sign_in_reach()
RETURNS TABLE (member_id uuid, name text, has_password boolean, has_google boolean)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT m.id, m.name,
         coalesce(u.encrypted_password, '') <> '',
         EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = u.id AND i.provider = 'google')
  FROM pm.team_members m
  JOIN auth.users u ON u.id = m.auth_user_id
  WHERE m.status = 'active' AND m.role <> 'agent' AND u.last_sign_in_at IS NOT NULL
  ORDER BY m.name, m.id
$$;

REVOKE ALL ON FUNCTION pm.member_sign_in_reach() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.member_sign_in_reach() TO service_role;

-- ============================================================
-- TABLE GRANTS (20261125000600_table_grants.sql)
-- The anon key reads nothing in pm but the workspace brand; members
-- (authenticated) hold only what a row policy can let through.
-- ============================================================
-- Table grants: the public anon key reads nothing in pm but the workspace
-- brand, and a signed-in member (authenticated) holds only the table
-- privileges a row policy can let through.
--
-- Why: tables made before 2.0 kept Supabase's default grants (ALL to anon and
-- authenticated), so the anon key that ships to every browser held INSERT,
-- UPDATE, DELETE and even TRUNCATE on most pm tables. Row security is what
-- stops it today: every pm table has it on, and no policy but the workspace
-- brand's names anon. This makes the grants a second wall, so a missing or
-- wrong policy cannot become a hole, and TRUNCATE (which row security does
-- not check) is gone.
--
-- What changes, per relation in pm (tables and views):
-- - anon: every privilege goes, except SELECT on pm.workspace_brand (its row
--   policy is the one that names anon: the sign-in page shows the brand).
-- - authenticated: TRUNCATE, REFERENCES, TRIGGER and MAINTAIN go everywhere.
--   SELECT, INSERT, UPDATE and DELETE stay only where a permissive row policy
--   for authenticated allows that command (so nothing that works today stops
--   working), less DELETE on the tables whose forbid_hard_delete trigger
--   refuses every delete (they go to Trash through pm.soft_delete_record).
--   Views keep SELECT only: they run as the caller, and no view's base table
--   lets a member write through it.
-- - Column grants (pm.projects, pm.project_time_entries) are left as they are:
--   only privileges held on the whole table are revoked.
-- - Sequences: anon loses all; authenticated keeps USAGE and SELECT, not
--   UPDATE (setval).
-- - The pm-2.0 bridge views (installs moved from 1.x) keep no more than
--   their pm table, as they always matched it.
-- - service_role, and other apps' objects in a shared database, are not
--   touched.
--
-- New tables: default privileges in pm no longer grant anything to anon, nor
-- TRUNCATE, REFERENCES, TRIGGER or MAINTAIN to authenticated, nor UPDATE on
-- new sequences. A new table still gets SELECT, INSERT, UPDATE and DELETE for
-- authenticated by default (row security decides), and test:table-grants
-- fails until it is on that test's list or revokes what it does not need.
--
-- Additive in spirit and safe to run twice: it only revokes, never grants, and
-- revokes only what is held, so a second run changes nothing. The previous
-- release's code keeps working: everything it reads or writes as a member
-- goes through a row policy, and every privilege such a policy allows stays.
--
-- Also here (one migration per release branch): audit retention drops the
-- template exception it kept for 2.0.29 (see the section at the end).

DO $grants$
DECLARE
  -- What authenticated keeps, per relation: 'name:PRIVILEGES'. A relation not
  -- listed keeps nothing. Never grants: only privileges already held stay.
  member_keeps text[] := ARRAY[
    -- Read only: the row policy is SELECT, writes go through the server.
    'activities:SELECT', 'agent_health:SELECT', 'agent_health_history:SELECT',
    'agent_owner_groups:SELECT', 'agent_owners:SELECT', 'agent_runs:SELECT',
    'analytics_tracking_starts:SELECT', 'answers:SELECT', 'api_audit_log:SELECT',
    'api_keys:SELECT', 'attachments:SELECT', 'conversation_projects:SELECT',
    'conversations:SELECT', 'group_members:SELECT', 'groups:SELECT',
    'ignored_addresses:SELECT', 'inbox_handlers:SELECT', 'invoice_payments:SELECT',
    'maintenance_runs:SELECT', 'meetings:SELECT', 'member_identities:SELECT',
    'message_candidates:SELECT', 'message_endpoints:SELECT', 'messages:SELECT',
    'own_domains:SELECT', 'participants:SELECT', 'permission_modules:SELECT',
    'plan_items:SELECT', 'plans:SELECT', 'portal_events:SELECT',
    'project_agents:SELECT', 'project_billing_plans:SELECT',
    'project_billing_runs:SELECT', 'project_budget_history:SELECT',
    'questions:SELECT', 'reply_drafts:SELECT', 'reply_points:SELECT',
    'sender_rules:SELECT', 'task_events:SELECT', 'task_files:SELECT',
    'task_links:SELECT', 'task_reopens:SELECT', 'task_reviews:SELECT',
    'task_template_runs:SELECT', 'task_templates:SELECT',
    'team_member_share_earnings:SELECT', 'trash_events:SELECT', 'triage:SELECT',
    'webhook_events:SELECT', 'workspace_brand:SELECT', 'workspace_modules:SELECT',
    -- Views (security_invoker): read only.
    'agent_run_feed:SELECT', 'conversation_participants:SELECT',
    'group_member_counts:SELECT', 'project_agent_counts:SELECT',
    'task_template_run_stats:SELECT',
    -- Full row policy (ALL or all four commands), no delete guard.
    'agent_activities:SELECT,INSERT,UPDATE,DELETE',
    'agent_billing_gap_reviews:SELECT,INSERT,UPDATE,DELETE',
    'business_settings:SELECT,INSERT,UPDATE,DELETE',
    'client_addresses:SELECT,INSERT,UPDATE,DELETE',
    'client_domains:SELECT,INSERT,UPDATE,DELETE',
    'contact_emails:SELECT,INSERT,UPDATE,DELETE',
    'endpoints:SELECT,INSERT,UPDATE,DELETE',
    'inbox_access:SELECT,INSERT,UPDATE,DELETE',
    'inboxes:SELECT,INSERT,UPDATE,DELETE',
    'invoice_line_shares:SELECT,INSERT,UPDATE,DELETE',
    'invoice_time_entry_allocations:SELECT,INSERT,UPDATE,DELETE',
    'lead_contacts:SELECT,INSERT,UPDATE,DELETE',
    'lead_members:SELECT,INSERT,UPDATE,DELETE',
    'portal_settings:SELECT,INSERT,UPDATE,DELETE',
    'project_contacts:SELECT,INSERT,UPDATE,DELETE',
    'project_context:SELECT,INSERT,UPDATE,DELETE',
    'project_credential_members:SELECT,INSERT,UPDATE,DELETE',
    'project_goals:SELECT,INSERT,UPDATE,DELETE',
    'project_members:SELECT,INSERT,UPDATE,DELETE',
    'project_retainer_periods:SELECT,INSERT,UPDATE,DELETE',
    'project_retainer_shares:SELECT,INSERT,UPDATE,DELETE',
    'provider_plans:SELECT,INSERT,UPDATE,DELETE',
    'role_permissions:SELECT,INSERT,UPDATE,DELETE',
    'smtp_accounts:SELECT,INSERT,UPDATE,DELETE',
    'task_acceptance_criteria:SELECT,INSERT,UPDATE,DELETE',
    'task_assignees:SELECT,INSERT,UPDATE,DELETE',
    'task_dependencies:SELECT,INSERT,UPDATE,DELETE',
    'task_suggestions:SELECT,INSERT,UPDATE,DELETE',
    'team_member_earning_adjustments:SELECT,INSERT,UPDATE,DELETE',
    'team_member_hourly_rates:SELECT,INSERT,UPDATE,DELETE',
    'team_member_payout_allocations:SELECT,INSERT,UPDATE,DELETE',
    'team_member_payouts:SELECT,INSERT,UPDATE,DELETE',
    'team_member_permissions:SELECT,INSERT,UPDATE,DELETE',
    'time_entry_tasks:SELECT,INSERT,UPDATE,DELETE',
    'webhook_endpoints:SELECT,INSERT,UPDATE,DELETE',
    -- Full row policy, but forbid_hard_delete refuses every DELETE (Trash).
    'client_communications:SELECT,INSERT,UPDATE', 'contacts:SELECT,INSERT,UPDATE',
    'entity_files:SELECT,INSERT,UPDATE', 'lead_fields:SELECT,INSERT,UPDATE',
    'lead_interactions:SELECT,INSERT,UPDATE', 'lead_proposals:SELECT,INSERT,UPDATE',
    'leads:SELECT,INSERT,UPDATE', 'portal_update_attachments:SELECT,INSERT,UPDATE',
    'portal_updates:SELECT,INSERT,UPDATE', 'project_credentials:SELECT,INSERT,UPDATE',
    'project_hourly_rates:SELECT,INSERT,UPDATE', 'project_invoices:SELECT,INSERT,UPDATE',
    'project_retainer_amounts:SELECT,INSERT,UPDATE', 'project_retainers:SELECT,INSERT,UPDATE',
    'reminders:SELECT,INSERT,UPDATE', 'task_comments:SELECT,INSERT,UPDATE',
    'task_subtasks:SELECT,INSERT,UPDATE', 'tasks:SELECT,INSERT,UPDATE',
    'team_members:SELECT,INSERT,UPDATE',
    -- Partial row policies.
    'task_views:SELECT,INSERT,UPDATE',               -- pm.mark_task_seen(s) upsert
    'team_member_notifications:SELECT,UPDATE,DELETE', -- read, mark read, dismiss
    'webhook_deliveries:SELECT,UPDATE',              -- pm.requeue_webhook_delivery
    'workspace_region:SELECT,INSERT,UPDATE'          -- Owner sets the region
    -- Not listed, so nothing at table level: api_rate_limit_windows and
    -- billing_draft_notices (no member policy), projects and
    -- project_time_entries (column grants only, left as they are).
  ];
  anon_keeps text[] := ARRAY['workspace_brand:SELECT'];
  rel record;
  bridge record;
  role_name text;
  keeps text[];
  keep text[];
  priv text;
BEGIN
  FOR rel IN
    SELECT c.oid, c.relname, c.relkind, c.relacl
    FROM pg_class c
    WHERE c.relnamespace = 'pm'::regnamespace
      AND c.relkind IN ('r', 'p', 'v', 'm', 'f', 'S')
      AND NOT EXISTS (
        SELECT 1 FROM pg_depend d
        WHERE d.classid = 'pg_class'::regclass AND d.objid = c.oid AND d.deptype = 'e'
      )
  LOOP
    FOREACH role_name IN ARRAY ARRAY['anon', 'authenticated'] LOOP
      IF rel.relkind = 'S' THEN
        keep := CASE WHEN role_name = 'authenticated' THEN ARRAY['USAGE', 'SELECT'] ELSE ARRAY[]::text[] END;
      ELSE
        keeps := CASE WHEN role_name = 'anon' THEN anon_keeps ELSE member_keeps END;
        SELECT coalesce(string_to_array(split_part(k, ':', 2), ','), ARRAY[]::text[]) INTO keep
        FROM unnest(keeps) k WHERE split_part(k, ':', 1) = rel.relname;
        keep := coalesce(keep, ARRAY[]::text[]);
      END IF;
      -- Privileges held on the whole relation (column grants are not in relacl).
      FOR priv IN
        SELECT a.privilege_type FROM aclexplode(rel.relacl) a
        WHERE a.grantee = role_name::regrole
      LOOP
        IF NOT priv = ANY (keep) THEN
          EXECUTE format('REVOKE %s ON %s %s FROM %I',
            priv, CASE WHEN rel.relkind = 'S' THEN 'SEQUENCE' ELSE 'TABLE' END, rel.oid::regclass, role_name);
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;

  -- The pm-2.0 bridge views (public and communications names, on installs
  -- moved from 1.x, removed in 2.1) run as the caller, so a grant beyond
  -- their pm table reaches nothing: each keeps no more than its table holds.
  FOR bridge IN
    SELECT v.oid, v.relacl, t.relacl AS table_acl
    FROM pg_class v
    JOIN pg_namespace n ON n.oid = v.relnamespace AND n.nspname IN ('public', 'communications')
    JOIN pg_class t ON t.relname = v.relname AND t.relnamespace = 'pm'::regnamespace
    WHERE v.relkind = 'v' AND obj_description(v.oid, 'pg_class') = 'pm-2.0 bridge'
  LOOP
    FOREACH role_name IN ARRAY ARRAY['anon', 'authenticated'] LOOP
      FOR priv IN
        SELECT a.privilege_type FROM aclexplode(bridge.relacl) a
        WHERE a.grantee = role_name::regrole
          AND NOT EXISTS (
            SELECT 1 FROM aclexplode(bridge.table_acl) ta
            WHERE ta.grantee = a.grantee AND ta.privilege_type = a.privilege_type
          )
      LOOP
        EXECUTE format('REVOKE %s ON TABLE %s FROM %I', priv, bridge.oid::regclass, role_name);
      END LOOP;
    END LOOP;
  END LOOP;

  -- New tables and sequences in pm (the defaults of the role that runs the
  -- migrations, as schema.sql set them).
  ALTER DEFAULT PRIVILEGES IN SCHEMA pm REVOKE ALL ON TABLES FROM anon;
  ALTER DEFAULT PRIVILEGES IN SCHEMA pm REVOKE ALL ON SEQUENCES FROM anon;
  ALTER DEFAULT PRIVILEGES IN SCHEMA pm REVOKE TRUNCATE, REFERENCES, TRIGGER ON TABLES FROM authenticated;
  ALTER DEFAULT PRIVILEGES IN SCHEMA pm REVOKE UPDATE ON SEQUENCES FROM authenticated;
  -- MAINTAIN exists from Postgres 17.
  IF current_setting('server_version_num')::int >= 170000 THEN
    EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA pm REVOKE MAINTAIN ON TABLES FROM authenticated';
  END IF;
END
$grants$;

-- ---------------------------------------------------------------------------
-- Audit retention: the template exception goes.
-- pm.purge_audit_log kept every audit row naming the template an agent was
-- set up from, because 2.0.29 read the template there. Since 2.0.30 it lives
-- on the agent (team_members.agent_template_key, set from the audit row by
-- record_agent_template_key as it is written), and the previous release reads
-- the audit log only on a database without that column. Retention now keeps
-- only the deprovision rows reactivation reads.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.purge_audit_log()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_days integer;
  v_count integer := 0;
BEGIN
  SELECT audit_retention_days INTO v_days FROM pm.business_settings LIMIT 1;
  IF v_days IS NULL THEN
    RETURN 0;
  END IF;
  PERFORM set_config('pm.audit_retention', 'on', true);
  DELETE FROM pm.api_audit_log l
  WHERE l.timestamp < now() - make_interval(days => v_days)
    -- The agents a deprovision took ownership of (read on reactivation).
    AND NOT coalesce(l.endpoint LIKE '/app/team-members/%/deprovision' AND l.request_body->>'step' = 'owner_removed', false);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  PERFORM set_config('pm.audit_retention', 'off', true);
  IF v_count > 0 THEN
    INSERT INTO pm.api_audit_log (method, endpoint, entity_type, request_body, status_code, via)
    VALUES ('DELETE', '/app/audit/retention', 'api_audit_log',
      jsonb_build_object('deleted', v_count, 'retention_days', v_days), 200, 'app');
  END IF;
  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION pm.purge_audit_log() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.purge_audit_log() TO service_role;

-- ============================================================
-- APPROVAL DECISIONS (20261125000700_approval_decisions.sql)
-- Whoever an approval names decides it, and how it was decided
-- (decided_via) is kept and carried by the question.* events.
-- ============================================================
ALTER TABLE pm.questions ADD COLUMN IF NOT EXISTS decided_via text;

ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_decided_via_check;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_decided_via_check CHECK (
    decided_via IS NULL OR (decided_via IN ('app', 'api_key', 'agent', 'act_for') AND kind = 'approval')
  );

COMMENT ON COLUMN pm.questions.decided_via IS
  'How an approval was decided: app (signed in), api_key (the person''s own key with approvals.decide), agent (the agent asked, with its own key) or act_for (an agent acting for the person, with approvals.decide on its key and held by the person). Null on a plain question, an open approval, or one decided before this was recorded.';

-- approvals.decide: people hold it on the API (Owners hold every
-- permission), so each can add it to their own key on purpose. No agent
-- holds it by default, and no key carries it until its person adds it.
INSERT INTO pm.role_permissions (role, permission_key, access_channel) VALUES
  ('admin', 'approvals.decide', 'api'),
  ('member', 'approvals.decide', 'api')
ON CONFLICT DO NOTHING;

-- The question.* events carry decided_via on an approval.
CREATE OR REPLACE FUNCTION pm.emit_question_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['question.asked', 'question.answered', 'question.cancelled']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'open' AND NEW.deleted_at IS NULL THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.deleted_at IS NOT NULL THEN
    IF OLD.deleted_at IS NULL AND OLD.status = 'open' THEN
      v_type := 'question.cancelled';
    END IF;
  ELSIF OLD.deleted_at IS NOT NULL THEN
    IF NEW.status = 'open' THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_type := CASE NEW.status
      WHEN 'open' THEN 'question.asked'
      WHEN 'answered' THEN 'question.answered'
      WHEN 'cancelled' THEN 'question.cancelled'
    END;
  END IF;
  IF v_type IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'question',
    NEW.id,
    ARRAY[NEW.project_id],
    pm.webhook_event_members('question', NEW.id),
    jsonb_build_object(
      'question', jsonb_build_object(
        'id', NEW.id,
        'project_id', NEW.project_id,
        'task_id', NEW.task_id,
        'asked_by', NEW.asked_by,
        'asked_to', NEW.asked_to,
        'question', NEW.question,
        'choices', NEW.choices,
        'allow_other', NEW.allow_other,
        'status', NEW.status,
        'answer_choice', NEW.answer_choice,
        'answer_text', NEW.answer_text,
        'answered_by', NEW.answered_by,
        'answered_at', NEW.answered_at,
        'cancelled_by', NEW.cancelled_by,
        'cancelled_at', NEW.cancelled_at,
        'expires_at', NEW.expires_at,
        'created_at', NEW.created_at,
        'updated_at', NEW.updated_at,
        'deleted_at', NEW.deleted_at
      ) || CASE WHEN NEW.kind = 'approval' THEN jsonb_build_object(
        'kind', NEW.kind,
        'action', NEW.action,
        'decision', CASE NEW.answer_choice WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' END,
        'decided_by', CASE WHEN NEW.status = 'answered' THEN NEW.answered_by END,
        'decided_via', CASE WHEN NEW.status = 'answered' THEN NEW.decided_via END
      ) ELSE '{}'::jsonb END
        || CASE WHEN NEW.asked_to_group IS NOT NULL THEN jsonb_build_object('asked_to_group', NEW.asked_to_group) ELSE '{}'::jsonb END
        || CASE WHEN NEW.principal_id IS NOT NULL THEN jsonb_build_object('principal_id', NEW.principal_id) ELSE '{}'::jsonb END,
      'project', CASE WHEN NEW.project_id IS NOT NULL THEN jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ) END,
      'project_id', NEW.project_id,
      'task_id', NEW.task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_question_webhook() FROM PUBLIC, anon, authenticated;

-- ============================================================
-- SPEND, COUNTED ONCE (20261125000800_agent_spend.sql)
-- What an agent spent, counted once and the same way everywhere: the
-- budget (pm.agent_limit_state) and Analytics (pm.agent_run_stats) both
-- read pm.agent_spend_facts. Work under a run counts as the run's own
-- totals; usage.recorded and turn.completed rows that name a run are
-- never added again; usage and turns that name no run add on top.
-- ============================================================

-- ---------------------------------------------------------------------------
-- Usage by run and by agent and time
-- ---------------------------------------------------------------------------
-- A run's usage: usage.recorded rows the server attached to it (run_id).
CREATE INDEX IF NOT EXISTS idx_agent_activities_usage_run ON pm.agent_activities ((metadata->>'run_id'))
  WHERE activity_type = 'usage.recorded' AND metadata->>'run_id' IS NOT NULL;
-- The budget reads one agent's usage over its period.
CREATE INDEX IF NOT EXISTS idx_agent_activities_usage_created ON pm.agent_activities (agent_id, created_at DESC)
  WHERE activity_type = 'usage.recorded';

-- ---------------------------------------------------------------------------
-- Spend facts: one row per thing that counts, in a window [p_from, p_to)
-- ---------------------------------------------------------------------------
-- The only place the counting rule lives:
-- - A stored run counts where it started (started_at). Its cost is its own
--   cost_usd when above 0, else the cost of the usage rows attached to it.
--   Its tokens are its own tokens_in and tokens_out when they add up to
--   more than 0, else its attached usage's tokens, else (for an agent
--   without a usage ledger in the window) its attached turns' own tokens.
--   A run stored with 0 never hides what is attached to it.
-- - usage.recorded that names a run (metadata.run_id, kept by the server
--   only when it names one of the agent's runs) is part of that run and
--   never adds again. Usage that names no run adds on its own, at
--   recorded_at (else created_at). Rows written before usage could name a
--   run carry none, so they add on their own.
-- - turn.completed that names a run is part of that run. A turn that names
--   no run adds its own tokens (tokens_scope turn), at its started_at, only
--   for an agent with no usage.recorded in the window: the host publisher
--   reports the same turns as usage, and the ledger is the measure.
-- - Cost above 0 is priced; cost 0 or none is unpriced (cost_usd null),
--   never a real zero spend.
-- - principal_id is the person the work was for: a run's own, a usage or
--   turn row's own (X-Act-For); null when the agent worked as itself.
-- Security invoker: Analytics reads it as the caller (row policies apply);
-- the budget reads it inside pm.agent_limit_state.
CREATE OR REPLACE FUNCTION pm.agent_spend_facts(p_from timestamptz, p_to timestamptz, p_agent_ids uuid[] DEFAULT NULL)
RETURNS TABLE (
  source text,
  source_id text,
  agent_id uuid,
  project_id uuid,
  model text,
  provider text,
  labels text[],
  at timestamptz,
  tokens_in bigint,
  tokens_out bigint,
  tokens_cached bigint,
  cost_usd numeric,
  principal_id uuid
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pm
AS $$
  with usage_in as (
    select a.id, a.agent_id, a.project_id, a.labels, a.metadata as m, a.principal_id,
           coalesce(agent_analytics_ts(a.metadata->>'recorded_at'), a.created_at) as at
    from agent_activities a
    where a.activity_type = 'usage.recorded'
      and a.agent_id is not null
      and a.created_at >= p_from - interval '1 day'
      and (p_agent_ids is null or a.agent_id = any (p_agent_ids))
      and coalesce(agent_analytics_ts(a.metadata->>'recorded_at'), a.created_at) >= p_from
      and coalesce(agent_analytics_ts(a.metadata->>'recorded_at'), a.created_at) < p_to
  ),
  ledger as (
    select distinct u.agent_id from usage_in u
  ),
  runs as (
    select r.id, r.agent_id, r.project_id, r.model, r.provider, r.started_at, r.tokens_in, r.tokens_out, r.cost_usd, r.principal_id
    from agent_runs r
    where r.started_at >= p_from and r.started_at < p_to
      and (p_agent_ids is null or r.agent_id = any (p_agent_ids))
  ),
  run_usage as (
    select r.id,
           sum(agent_analytics_int(a.metadata->>'input_tokens')) as tin,
           sum(agent_analytics_int(a.metadata->>'output_tokens')) as tout,
           sum(agent_analytics_int(a.metadata->>'cached_tokens')) as tcached,
           sum(agent_analytics_num(a.metadata->>'cost_usd')) filter (where agent_analytics_num(a.metadata->>'cost_usd') > 0) as cost
    from runs r
    join agent_activities a on a.metadata->>'run_id' = r.id::text and a.agent_id = r.agent_id
    where a.activity_type = 'usage.recorded'
    group by r.id
  ),
  run_turns as (
    select r.id,
           sum(agent_analytics_int(a.metadata->'tokens'->>'input')) filter (where a.metadata->'tokens' ? 'input') as tin,
           sum(agent_analytics_int(a.metadata->'tokens'->>'output')) filter (where a.metadata->'tokens' ? 'output') as tout
    from runs r
    join agent_activities a on a.metadata->>'run_id' = r.id::text and a.agent_id = r.agent_id
    where a.activity_type = 'turn.completed'
      and a.metadata->>'tokens_scope' = 'turn'
      and coalesce(r.tokens_in, 0) + coalesce(r.tokens_out, 0) = 0
    group by r.id
  )
  select 'run'::text, r.id::text, r.agent_id, r.project_id, r.model, r.provider, '{}'::text[], r.started_at,
    (case when coalesce(r.tokens_in, 0) + coalesce(r.tokens_out, 0) > 0 then coalesce(r.tokens_in, 0)
          when u.id is not null then coalesce(u.tin, 0)
          when l.agent_id is null then coalesce(t.tin, 0)
          else 0 end)::bigint,
    (case when coalesce(r.tokens_in, 0) + coalesce(r.tokens_out, 0) > 0 then coalesce(r.tokens_out, 0)
          when u.id is not null then coalesce(u.tout, 0)
          when l.agent_id is null then coalesce(t.tout, 0)
          else 0 end)::bigint,
    (case when coalesce(r.tokens_in, 0) + coalesce(r.tokens_out, 0) > 0 then 0
          when u.id is not null then coalesce(u.tcached, 0)
          else 0 end)::bigint,
    case when r.cost_usd > 0 then r.cost_usd else u.cost end,
    r.principal_id
  from runs r
  left join run_usage u on u.id = r.id
  left join run_turns t on t.id = r.id
  left join ledger l on l.agent_id = r.agent_id
  union all
  select 'usage'::text, u.id::text, u.agent_id, u.project_id, u.m->>'model', u.m->>'provider', coalesce(u.labels, '{}'::text[]), u.at,
    agent_analytics_int(u.m->>'input_tokens')::bigint,
    agent_analytics_int(u.m->>'output_tokens')::bigint,
    agent_analytics_int(u.m->>'cached_tokens')::bigint,
    case when agent_analytics_num(u.m->>'cost_usd') > 0 then agent_analytics_num(u.m->>'cost_usd') end,
    u.principal_id
  from usage_in u
  where u.m->>'run_id' is null
  union all
  select 'turn'::text, a.id::text, a.agent_id, a.project_id, a.metadata->>'model', null::text, '{}'::text[],
    coalesce(agent_analytics_ts(a.metadata->>'started_at'), a.created_at),
    (case when a.metadata->'tokens' ? 'input' then agent_analytics_int(a.metadata->'tokens'->>'input') else 0 end)::bigint,
    (case when a.metadata->'tokens' ? 'output' then agent_analytics_int(a.metadata->'tokens'->>'output') else 0 end)::bigint,
    0::bigint,
    null::numeric,
    a.principal_id
  from agent_activities a
  where a.activity_type = 'turn.completed'
    and a.agent_id is not null
    and a.metadata->>'tokens_scope' = 'turn'
    and (a.metadata->'tokens' ? 'input' or a.metadata->'tokens' ? 'output')
    and a.metadata->>'run_id' is null
    and a.created_at >= p_from - interval '1 day'
    and (p_agent_ids is null or a.agent_id = any (p_agent_ids))
    and coalesce(agent_analytics_ts(a.metadata->>'started_at'), a.created_at) >= p_from
    and coalesce(agent_analytics_ts(a.metadata->>'started_at'), a.created_at) < p_to
    and not exists (select 1 from ledger l where l.agent_id = a.agent_id)
$$;

REVOKE ALL ON FUNCTION pm.agent_spend_facts(timestamptz, timestamptz, uuid[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION pm.agent_spend_facts(timestamptz, timestamptz, uuid[]) TO authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Spend per agent in a window: the facts summed. spent_tokens is input plus
-- output (what budget_tokens caps); unpriced_tokens are the tokens of facts
-- with no cost above 0. Server only.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.agent_spend(p_from timestamptz, p_to timestamptz, p_agent_ids uuid[] DEFAULT NULL)
RETURNS TABLE (
  agent_id uuid,
  spent_usd numeric,
  spent_tokens bigint,
  tokens_in bigint,
  tokens_out bigint,
  tokens_cached bigint,
  unpriced_tokens bigint
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pm
AS $$
  select f.agent_id,
         coalesce(sum(f.cost_usd), 0),
         coalesce(sum(f.tokens_in + f.tokens_out), 0)::bigint,
         coalesce(sum(f.tokens_in), 0)::bigint,
         coalesce(sum(f.tokens_out), 0)::bigint,
         coalesce(sum(f.tokens_cached), 0)::bigint,
         coalesce(sum(f.tokens_in + f.tokens_out + f.tokens_cached) filter (where f.cost_usd is null), 0)::bigint
  from agent_spend_facts(p_from, p_to, p_agent_ids) f
  group by f.agent_id
$$;

REVOKE ALL ON FUNCTION pm.agent_spend(timestamptz, timestamptz, uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_spend(timestamptz, timestamptz, uuid[]) TO service_role;

-- ---------------------------------------------------------------------------
-- The budget: spend this period from pm.agent_spend (replaces the largest of
-- usage, runs and turns, which missed work reported one way beside other
-- work reported another).
-- ---------------------------------------------------------------------------
-- An agent's limits with what counts against them now: running runs and
-- live claims, and spend this budget period (UTC), counted by
-- pm.agent_spend. Without p_with_usage, only what the agent's limits need is
-- counted (nothing for an agent without limits), so the run and claim
-- checks stay cheap. Server only.
CREATE OR REPLACE FUNCTION pm.agent_limit_state(p_agent_id uuid, p_with_usage boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_limits pm.agent_limits%ROWTYPE;
  v_period text;
  v_from timestamptz;
  v_to timestamptz;
  v_spent_usd numeric := 0;
  v_spent_tokens bigint := 0;
  v_running integer := 0;
  v_claims integer := 0;
BEGIN
  SELECT * INTO v_limits FROM pm.agent_limits WHERE agent_id = p_agent_id;
  v_period := coalesce(v_limits.budget_period, 'month');
  v_from := date_trunc(v_period, now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  v_to := (date_trunc(v_period, now() AT TIME ZONE 'UTC') + ('1 ' || v_period)::interval) AT TIME ZONE 'UTC';
  IF p_with_usage OR v_limits.budget_usd IS NOT NULL OR v_limits.budget_tokens IS NOT NULL THEN
  SELECT coalesce(sum(s.spent_usd), 0), coalesce(sum(s.spent_tokens), 0)
    INTO v_spent_usd, v_spent_tokens
  FROM pm.agent_spend(v_from, v_to, ARRAY[p_agent_id]) s;
  END IF;
  IF p_with_usage OR v_limits.max_concurrent_runs IS NOT NULL THEN
  SELECT count(*) INTO v_running FROM pm.agent_runs r
  WHERE r.agent_id = p_agent_id AND r.status = 'running' AND r.updated_at > now() - interval '2 hours';
  SELECT count(*) INTO v_claims FROM pm.tasks t
  WHERE t.claimed_by = p_agent_id AND t.claim_expires_at > now() AND t.deleted_at IS NULL;
  END IF;
  RETURN jsonb_build_object(
    'limits', CASE WHEN v_limits.agent_id IS NULL THEN NULL ELSE jsonb_build_object(
      'max_concurrent_runs', v_limits.max_concurrent_runs,
      'rate_per_minute', v_limits.rate_per_minute,
      'budget_usd', v_limits.budget_usd,
      'budget_tokens', v_limits.budget_tokens,
      'budget_period', v_limits.budget_period,
      'budget_alerted_period', v_limits.budget_alerted_period) END,
    'period_start', v_from,
    'spent_usd', round(v_spent_usd, 4),
    'spent_tokens', v_spent_tokens,
    'running_runs', v_running,
    'live_claims', v_claims);
END;
$$;

REVOKE ALL ON FUNCTION pm.agent_limit_state(uuid, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_limit_state(uuid, boolean) TO service_role;

-- ---------------------------------------------------------------------------
-- Run aggregates for Analytics, now with spend: the run feed summed per
-- agent, project, model, provider and day (p_tz's calendar days from p_start
-- to p_end), read as the caller. The same rules as the screen's read model
-- (src/lib/agent-analytics-model.ts), so the two always agree:
-- - Runs are read where sort_at falls within a day either side of the range,
--   then placed on the day they started.
-- - Success and failure as the run pill reads them; a running run, or one
--   waiting on a person, is neither until it finishes.
-- - Busy time: each run keeps the part of its span no earlier run of the
--   same agent covers, so the parts add up to the union. With
--   p_project_ids, only those projects' runs clip against each other.
-- - A stored run that reports no tokens takes its attached turns' own
--   tokens. runs_no_tokens counts the stored runs still without any.
-- - Cost: a run's cost above 0, else its tokens are unpriced.
-- failures lists every failed run read (for incidents, which collapse
-- repeats across days).
-- spend is pm.agent_spend_facts over the range's days, summed per agent,
-- project, model, provider, day, labels and person: [agent, project, model,
-- provider, day, labels, tokens_in, tokens_out, tokens_cached, cost_usd,
-- unpriced_tokens, principal]. principal is who the work was for (null:
-- the agent worked as itself), so spend reads by person too. Analytics
-- takes tokens and cost from it alone, so its totals are the budget's
-- numbers whatever the range holds. groups keep their run-only tokens and
-- cost for the previous release's screens.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.agent_run_stats(
  p_start date,
  p_end date,
  p_tz text,
  p_project_ids uuid[] DEFAULT NULL,
  p_now timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pm
AS $$
  with feed as (
    select f.id, f.source, f.agent_id, f.project_id, f.status, f.outcome, f.title, f.model, r.provider,
           f.started_at, f.finished_at, f.duration_ms, f.tokens_in, f.tokens_out, f.cost_usd
    from agent_run_feed f
    left join agent_runs r on f.source = 'run' and r.id = f.id
    where f.sort_at >= (p_start::timestamp - interval '1 day') at time zone 'UTC'
      and f.sort_at <= (p_end::timestamp + interval '2 days' - interval '1 millisecond') at time zone 'UTC'
  ),
  attached as (
    select a.metadata->>'run_id' as run_id,
           sum(agent_analytics_int(a.metadata->'tokens'->>'input')) filter (where a.metadata->'tokens' ? 'input') as tokens_in,
           sum(agent_analytics_int(a.metadata->'tokens'->>'output')) filter (where a.metadata->'tokens' ? 'output') as tokens_out
    from agent_activities a
    where a.activity_type = 'turn.completed'
      and a.metadata->>'run_id' in (select id::text from feed where source = 'run' and tokens_in is null and tokens_out is null)
      and a.metadata->>'tokens_scope' = 'turn'
    group by a.metadata->>'run_id'
  ),
  runs as (
    select f.*,
      (f.started_at at time zone p_tz)::date as day,
      case
        when f.status in ('running', 'waiting') then f.status
        when f.source = 'run' then case f.status when 'succeeded' then 'success' when 'failed' then 'failure'
          when 'timed_out' then 'failure' else 'neutral' end
        when lower(coalesce(f.outcome, '')) = 'blocked' then 'neutral'
        when lower(coalesce(f.outcome, '')) in ('failed', 'error') then 'failure'
        when lower(coalesce(f.outcome, '')) in ('idle', 'skipped', 'waiting', 'no_work', 'nothing', 'nothing_to_do') then 'neutral'
        when coalesce(f.outcome, '') = '' or lower(f.outcome) in ('work', 'worked', 'ok', 'done', 'shipped', 'succeeded') then 'success'
        else 'neutral'
      end as verdict,
      case when f.source = 'run' and f.tokens_in is null and f.tokens_out is null then t.tokens_in else f.tokens_in end as tin,
      case when f.source = 'run' and f.tokens_in is null and f.tokens_out is null then t.tokens_out else f.tokens_out end as tout,
      case
        when f.duration_ms is not null then greatest(f.duration_ms, 0)
        when f.finished_at is not null then greatest(floor(extract(epoch from f.finished_at) * 1000) - floor(extract(epoch from f.started_at) * 1000), 0)::bigint
        when f.status = 'running' then greatest(floor(extract(epoch from p_now) * 1000) - floor(extract(epoch from f.started_at) * 1000), 0)::bigint
      end as span_ms
    from feed f
    left join attached t on t.run_id = f.id::text
  ),
  placed as (
    select * from runs where day >= p_start and day <= p_end
  ),
  spans as (
    select p.id, p.agent_id, p.project_id, p.model, p.provider, p.day,
           floor(extract(epoch from p.started_at) * 1000)::bigint as s,
           floor(extract(epoch from p.started_at) * 1000)::bigint + p.span_ms as e
    from placed p
    where p.span_ms > 0
      and (p_project_ids is null or p.project_id = any (p_project_ids))
  ),
  clipped as (
    select sp.*,
      max(sp.e) over (partition by sp.agent_id order by sp.s, sp.e, sp.id rows between unbounded preceding and 1 preceding) as covered
    from spans sp
  ),
  busy as (
    select agent_id, project_id, model, provider, day,
           sum(greatest(0, e - greatest(s, coalesce(covered, s)))) as busy_ms
    from clipped
    group by agent_id, project_id, model, provider, day
  ),
  counts as (
    select agent_id, project_id, model, provider, day,
      count(*) as runs,
      count(*) filter (where verdict = 'success') as succeeded,
      count(*) filter (where verdict = 'failure') as failed,
      coalesce(sum(tin), 0) as tokens_in,
      coalesce(sum(tout), 0) as tokens_out,
      coalesce(sum(cost_usd) filter (where cost_usd > 0), 0) as cost_usd,
      coalesce(sum(coalesce(tin, 0) + coalesce(tout, 0)) filter (where not (coalesce(cost_usd, 0) > 0)), 0) as unpriced_tokens,
      count(*) filter (where source = 'run' and tin is null and tout is null) as runs_no_tokens
    from placed
    group by agent_id, project_id, model, provider, day
  ),
  grouped as (
    select coalesce(c.agent_id, b.agent_id) as agent_id, coalesce(c.project_id, b.project_id) as project_id,
           coalesce(c.model, b.model) as model, coalesce(c.provider, b.provider) as provider, coalesce(c.day, b.day) as day,
           coalesce(c.runs, 0) as runs, coalesce(c.succeeded, 0) as succeeded, coalesce(c.failed, 0) as failed,
           coalesce(b.busy_ms, 0) as busy_ms, coalesce(c.tokens_in, 0) as tokens_in, coalesce(c.tokens_out, 0) as tokens_out,
           coalesce(c.cost_usd, 0) as cost_usd, coalesce(c.unpriced_tokens, 0) as unpriced_tokens,
           coalesce(c.runs_no_tokens, 0) as runs_no_tokens
    from counts c
    full join busy b on b.agent_id = c.agent_id and b.project_id is not distinct from c.project_id
      and b.model is not distinct from c.model and b.provider is not distinct from c.provider and b.day = c.day
  ),
  spend as (
    select f.agent_id, f.project_id, f.model, f.provider, (f.at at time zone p_tz)::date as day, f.labels, f.principal_id,
           sum(f.tokens_in) as tokens_in, sum(f.tokens_out) as tokens_out, sum(f.tokens_cached) as tokens_cached,
           coalesce(sum(f.cost_usd), 0) as cost_usd,
           coalesce(sum(f.tokens_in + f.tokens_out + f.tokens_cached) filter (where f.cost_usd is null), 0) as unpriced_tokens
    from agent_spend_facts(p_start::timestamp at time zone p_tz, (p_end + 1)::timestamp at time zone p_tz, null) f
    group by f.agent_id, f.project_id, f.model, f.provider, (f.at at time zone p_tz)::date, f.labels, f.principal_id
  )
  select jsonb_build_object(
    'groups', coalesce((
      select jsonb_agg(jsonb_build_array(g.agent_id, g.project_id, g.model, g.provider, to_char(g.day, 'YYYY-MM-DD'),
        g.runs, g.succeeded, g.failed, g.busy_ms, g.tokens_in, g.tokens_out, g.cost_usd, g.unpriced_tokens, g.runs_no_tokens))
      from grouped g
    ), '[]'::jsonb),
    'failures', coalesce((
      select jsonb_agg(jsonb_build_array(r.agent_id, r.project_id, r.model, r.provider, r.started_at, r.title, r.status)
        order by r.started_at)
      from runs r
      where r.verdict = 'failure'
    ), '[]'::jsonb),
    'spend', coalesce((
      select jsonb_agg(jsonb_build_array(sp.agent_id, sp.project_id, sp.model, sp.provider, to_char(sp.day, 'YYYY-MM-DD'),
        to_jsonb(sp.labels), sp.tokens_in, sp.tokens_out, sp.tokens_cached, sp.cost_usd, sp.unpriced_tokens, sp.principal_id))
      from spend sp
    ), '[]'::jsonb)
  );
$$;

REVOKE ALL ON FUNCTION pm.agent_run_stats(date, date, text, uuid[], timestamptz) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION pm.agent_run_stats(date, date, text, uuid[], timestamptz) TO authenticated, service_role;

-- ============================================================
-- WEBHOOK SETUP SCOPE (20261125000900_webhook_setup_scope.sql)
-- One webhook endpoint for every assistant a setup made; one pass
-- over the endpoints per event.
-- ============================================================
-- One webhook endpoint for every assistant an assistant setup made, and one
-- pass over the endpoints per event.
--
-- - team_members.assistant_setup_id: the setup that made a personal agent.
--   pm.provision_personal_agents records it (the setup the server planned
--   it from, else pm.assistant_setup_for works it out the same way), and the
--   personal agents made before are filled in once here. Only the server or
--   a signed-in Owner changes it (pm.team_members_assistant_setup_guard).
--   Deleting a setup clears it.
-- - webhook_endpoints.assistant_setup_id: an endpoint scoped to a setup
--   receives the events that concern any personal agent that setup made,
--   assistant.message included, so an assistant host serving 2,000 people
--   keeps one endpoint and one secret instead of 2,000. Never together with
--   member_id. Only the server (its own checks: an Owner, or a key with
--   assistants.provision) or a signed-in Owner sets it
--   (pm.webhook_endpoints_assistant_guard). A setup with such an endpoint
--   cannot be deleted until the endpoint goes (turn the setup off instead),
--   so its assistants never go quiet by surprise. Keys stay one per
--   assistant: nothing about keys changes.
-- - pm.webhook_endpoint_matches reads the setup scope. The event writers
--   (pm.emit_webhook_event, pm.emit_invoice_webhook_event,
--   pm.emit_assistant_message) find the endpoints that match once, through
--   a GIN index on the active endpoints' events, and fan out from that list:
--   no second scan. Same commit, same lines, same folding as before.
--
-- Additive and safe to run twice. 2.0.40 code never reads or writes the new
-- columns: its endpoints and per-member assistant endpoints work unchanged.

-- ---------------------------------------------------------------------------
-- Columns
-- ---------------------------------------------------------------------------
ALTER TABLE pm.team_members
  ADD COLUMN IF NOT EXISTS assistant_setup_id uuid REFERENCES pm.assistant_setups(id) ON DELETE SET NULL;

COMMENT ON COLUMN pm.team_members.assistant_setup_id IS
  'The assistant setup that made this personal agent (null: made another way, or its setup was deleted). Webhook endpoints scoped to the setup receive its events.';

CREATE INDEX IF NOT EXISTS idx_team_members_assistant_setup ON pm.team_members (assistant_setup_id) WHERE assistant_setup_id IS NOT NULL;

ALTER TABLE pm.webhook_endpoints
  ADD COLUMN IF NOT EXISTS assistant_setup_id uuid REFERENCES pm.assistant_setups(id) ON DELETE RESTRICT;

ALTER TABLE pm.webhook_endpoints DROP CONSTRAINT IF EXISTS webhook_endpoints_one_scope;
ALTER TABLE pm.webhook_endpoints
  ADD CONSTRAINT webhook_endpoints_one_scope CHECK (member_id IS NULL OR assistant_setup_id IS NULL);

COMMENT ON COLUMN pm.webhook_endpoints.assistant_setup_id IS
  'Only events that concern a personal agent this assistant setup made, assistant.message included (null: no setup scope). Never with member_id.';

-- The event writers look up active endpoints by event type, then by scope.
CREATE INDEX IF NOT EXISTS idx_webhook_endpoints_active_events ON pm.webhook_endpoints USING gin (events) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_webhook_endpoints_assistant_setup ON pm.webhook_endpoints (assistant_setup_id) WHERE assistant_setup_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Which setup made a personal agent
-- ---------------------------------------------------------------------------
-- The setup a person's agent from p_template comes from, as provisioning
-- picks it: the oldest setup with that template whose role the person has
-- or whose live group they are in, switched-on setups first.
CREATE OR REPLACE FUNCTION pm.assistant_setup_for(p_person uuid, p_template text)
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT s.id
  FROM pm.assistant_setups s
  JOIN pm.team_members p ON p.id = p_person
  WHERE s.template_key = p_template
    AND (s.match_role = p.role OR EXISTS (
      SELECT 1 FROM pm.group_members g JOIN pm.groups gr ON gr.id = g.group_id AND gr.deleted_at IS NULL
      WHERE g.group_id = s.match_group_id AND g.member_id = p.id
    ))
  ORDER BY s.enabled DESC, s.created_at, s.id
  LIMIT 1
$$;

REVOKE ALL ON FUNCTION pm.assistant_setup_for(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.assistant_setup_for(uuid, text) TO service_role;

-- Personal agents made before: the setup that matches them now, else the
-- one setup with their template when there is exactly one.
UPDATE pm.team_members a
SET assistant_setup_id = coalesce(
  pm.assistant_setup_for(a.delegate_of, a.assistant_template),
  (SELECT (array_agg(s.id))[1] FROM pm.assistant_setups s WHERE s.template_key = a.assistant_template HAVING count(*) = 1)
)
WHERE a.role = 'agent' AND a.delegate_of IS NOT NULL AND a.assistant_template IS NOT NULL AND a.assistant_setup_id IS NULL;

-- Only the server or a signed-in Owner says which setup made an agent.
CREATE OR REPLACE FUNCTION pm.team_members_assistant_setup_guard()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF auth.uid() IS NULL OR coalesce(auth.role(), '') = 'service_role' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.assistant_setup_id IS NULL THEN
      RETURN NEW;
    END IF;
  ELSIF NEW.assistant_setup_id IS NOT DISTINCT FROM OLD.assistant_setup_id THEN
    RETURN NEW;
  END IF;
  IF coalesce(pm.current_team_member_role(), '') <> 'owner' THEN
    RAISE EXCEPTION 'Which setup made an agent changes only by an Owner' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.team_members_assistant_setup_guard() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS team_members_assistant_setup_guard ON pm.team_members;
CREATE TRIGGER team_members_assistant_setup_guard
  BEFORE INSERT OR UPDATE OF assistant_setup_id ON pm.team_members
  FOR EACH ROW EXECUTE FUNCTION pm.team_members_assistant_setup_guard();

-- Makes personal agents in bulk: one row per element of p_agents (name,
-- email, delegate_of, assistant_template, assistant_setup_id, title,
-- agent_role, agent_profile, description, and the four rules). A person who
-- already has a personal agent from that template, or who is not an active
-- person, is skipped. Each one records the setup that made it (the one
-- given, else pm.assistant_setup_for) and gets the audit row that records
-- its template. Answers what was made.
CREATE OR REPLACE FUNCTION pm.provision_personal_agents(p_agents jsonb, p_actor uuid)
RETURNS TABLE (id uuid, delegate_of uuid, assistant_template text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
#variable_conflict use_column
BEGIN
  RETURN QUERY
  WITH made AS (
    INSERT INTO pm.team_members AS m (
      name, email, role, title, agent_role, agent_profile, description, delegate_of, assistant_template, assistant_setup_id,
      agent_self_assign, agent_close_policy, agent_create_policy, agent_escalate_to
    )
    SELECT x.name, x.email, 'agent', x.title, x.agent_role, coalesce(x.agent_profile, 'generic'), x.description,
      x.delegate_of, x.assistant_template,
      coalesce(x.assistant_setup_id, pm.assistant_setup_for(x.delegate_of, x.assistant_template)),
      coalesce(x.agent_self_assign, false), coalesce(x.agent_close_policy, 'close'), coalesce(x.agent_create_policy, 'live'),
      coalesce(x.agent_escalate_to, x.delegate_of)
    FROM jsonb_to_recordset(p_agents) AS x(
      name text, email text, title text, agent_role text, agent_profile text, description text,
      delegate_of uuid, assistant_template text, assistant_setup_id uuid,
      agent_self_assign boolean, agent_close_policy text, agent_create_policy text, agent_escalate_to uuid
    )
    JOIN pm.team_members p ON p.id = x.delegate_of AND p.role <> 'agent' AND coalesce(p.status, 'active') = 'active'
    ON CONFLICT (delegate_of, assistant_template) WHERE delegate_of IS NOT NULL AND assistant_template IS NOT NULL DO NOTHING
    RETURNING m.id, m.delegate_of, m.assistant_template, m.name, m.agent_role
  ), audited AS (
    INSERT INTO pm.api_audit_log (method, endpoint, entity_type, entity_id, team_member_id, request_body, after_snapshot, status_code, via)
    SELECT 'POST', '/api/workspace/agents', 'team_member', made.id, p_actor,
      jsonb_build_object('template', made.assistant_template, 'personal_of', made.delegate_of, 'provisioned', true),
      jsonb_build_object('agent', jsonb_build_object('id', made.id, 'name', made.name, 'agent_role', made.agent_role, 'delegate_of', made.delegate_of)),
      201, 'app'
    FROM made
  )
  SELECT made.id, made.delegate_of, made.assistant_template FROM made;
END;
$$;

REVOKE ALL ON FUNCTION pm.provision_personal_agents(jsonb, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.provision_personal_agents(jsonb, uuid) TO service_role;

-- ---------------------------------------------------------------------------
-- Matching
-- ---------------------------------------------------------------------------
-- Whether an endpoint receives an event: active, subscribed to its type, and
-- inside its filters. p_project_ids holds every project the event touches (a
-- task moved between projects touches both); p_member_ids is who it
-- concerns. A setup scope matches when one of them is a personal agent that
-- setup made.
CREATE OR REPLACE FUNCTION pm.webhook_endpoint_matches(
  p_endpoint pm.webhook_endpoints,
  p_event_type text,
  p_project_ids uuid[],
  p_member_ids uuid[]
)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = pm
AS $$
  SELECT p_endpoint.is_active
    AND p_event_type = ANY (p_endpoint.events)
    AND (p_endpoint.project_ids IS NULL OR p_endpoint.project_ids && coalesce(p_project_ids, '{}'))
    AND (p_endpoint.member_id IS NULL OR p_endpoint.member_id = ANY (coalesce(p_member_ids, '{}')))
    AND (p_endpoint.assistant_setup_id IS NULL OR EXISTS (
      SELECT 1 FROM pm.team_members a
      WHERE a.id = ANY (coalesce(p_member_ids, '{}'))
        AND a.assistant_setup_id = p_endpoint.assistant_setup_id
        AND a.role = 'agent' AND a.delegate_of IS NOT NULL
    ))
$$;

REVOKE ALL ON FUNCTION pm.webhook_endpoint_matches(pm.webhook_endpoints, text, uuid[], uuid[]) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- The event writer for everything but invoices
-- ---------------------------------------------------------------------------
-- Records one event and fans out one delivery per matching endpoint; writes
-- nothing when no endpoint matches. The matching endpoints are found once
-- (active ones subscribed to the type, through the events index, then the
-- filters) and the deliveries are made from that list. p_data becomes the
-- payload's data, with member_ids added.
--
-- p_folds_into: when the subject's latest event in this transaction is one of
-- these types (and nothing has been tried yet), it is refreshed instead: its
-- data becomes p_data, member_ids and changes become the union of both, and
-- endpoints that match now get a delivery too. Nothing else sees an event
-- before its transaction commits, so a refresh is never a change to
-- something sent.
CREATE OR REPLACE FUNCTION pm.emit_webhook_event(
  p_event_type text,
  p_subject_type text,
  p_subject_id uuid,
  p_project_ids uuid[],
  p_member_ids uuid[],
  p_data jsonb,
  p_folds_into text[] DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_latest pm.webhook_events;
  v_members uuid[] := coalesce(p_member_ids, '{}');
  v_data jsonb := coalesce(p_data, '{}'::jsonb);
  v_changes jsonb;
  v_endpoints uuid[];
  v_seq bigint;
  v_public_id text;
  v_event_uuid uuid;
BEGIN
  IF p_folds_into IS NOT NULL THEN
    SELECT * INTO v_latest
    FROM pm.webhook_events ev
    WHERE ev.resource_type = p_subject_type AND ev.resource_id = p_subject_id AND ev.created_at = now()
    ORDER BY ev.sequence DESC
    LIMIT 1;
    IF FOUND AND v_latest.event_type = ANY (p_folds_into) AND NOT EXISTS (
      SELECT 1 FROM pm.webhook_deliveries d
      WHERE d.webhook_event_id = v_latest.id AND (d.status <> 'pending' OR d.attempts > 0)
    ) THEN
      SELECT coalesce(array_agg(DISTINCT m ORDER BY m), '{}') INTO v_members
      FROM (
        SELECT unnest(v_members) AS m
        UNION ALL
        SELECT value::uuid FROM jsonb_array_elements_text(coalesce(v_latest.payload -> 'data' -> 'member_ids', '[]'::jsonb))
      ) folded;
      IF (v_latest.payload -> 'data') ? 'changes' THEN
        SELECT coalesce(jsonb_agg(DISTINCT c ORDER BY c), '[]'::jsonb) INTO v_changes
        FROM (
          SELECT jsonb_array_elements_text(v_latest.payload -> 'data' -> 'changes') AS c
          UNION ALL
          SELECT jsonb_array_elements_text(coalesce(v_data -> 'changes', '[]'::jsonb))
        ) folded;
        v_data := v_data || jsonb_build_object('changes', v_changes);
      ELSE
        v_data := v_data - 'changes';
      END IF;

      UPDATE pm.webhook_events
      SET payload = jsonb_set(payload, '{data}', v_data || jsonb_build_object('member_ids', to_jsonb(v_members)))
      WHERE id = v_latest.id;

      INSERT INTO pm.webhook_deliveries (webhook_event_id, endpoint_id)
      SELECT v_latest.id, e.id
      FROM pm.webhook_endpoints e
      WHERE e.is_active AND e.events @> ARRAY[v_latest.event_type]
        AND pm.webhook_endpoint_matches(e, v_latest.event_type, p_project_ids, v_members)
        AND NOT EXISTS (
          SELECT 1 FROM pm.webhook_deliveries d WHERE d.webhook_event_id = v_latest.id AND d.endpoint_id = e.id
        );
      RETURN;
    END IF;
  END IF;

  SELECT array_agg(e.id ORDER BY e.id) INTO v_endpoints
  FROM pm.webhook_endpoints e
  WHERE e.is_active AND e.events @> ARRAY[p_event_type]
    AND pm.webhook_endpoint_matches(e, p_event_type, p_project_ids, v_members);
  IF v_endpoints IS NULL THEN
    RETURN;
  END IF;

  v_seq := nextval('pm.webhook_event_seq');
  v_public_id := 'evt_' || replace(gen_random_uuid()::text, '-', '');

  INSERT INTO pm.webhook_events (event_id, sequence, event_type, resource_type, resource_id, payload)
  VALUES (
    v_public_id, v_seq, p_event_type, p_subject_type, p_subject_id,
    jsonb_build_object(
      'id', v_public_id,
      'type', p_event_type,
      'sequence', v_seq,
      'created_at', now(),
      'data', v_data || jsonb_build_object('member_ids', to_jsonb(v_members))
    )
  )
  RETURNING id INTO v_event_uuid;

  INSERT INTO pm.webhook_deliveries (webhook_event_id, endpoint_id)
  SELECT v_event_uuid, unnest(v_endpoints);
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_webhook_event(text, text, uuid, uuid[], uuid[], jsonb, text[]) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- The invoice event writer
-- ---------------------------------------------------------------------------
-- Split out of the trigger so a split change on a paid invoice can announce
-- itself too (see emit_invoice_webhook_for_shares). p_data is merged into
-- the payload's data (the payment events use it). The matching endpoints
-- are found once, as for every other event.
CREATE OR REPLACE FUNCTION pm.emit_invoice_webhook_event(
  p_row pm.project_invoices,
  p_event_type text,
  p_data jsonb DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_is_paid boolean := (p_event_type <> 'invoice.deleted' AND p_row.status = 'paid');
  v_project_name text;
  v_totals jsonb;
  v_endpoints uuid[];
  v_public_id text;
  v_seq bigint;
  v_event_uuid uuid;
  v_payload jsonb;
BEGIN
  -- An invoice concerns no member: an endpoint with a member or setup filter never gets one.
  SELECT array_agg(e.id ORDER BY e.id) INTO v_endpoints
  FROM pm.webhook_endpoints e
  WHERE e.is_active AND e.events @> ARRAY[p_event_type]
    AND pm.webhook_endpoint_matches(e, p_event_type, ARRAY[p_row.project_id], '{}');
  IF v_endpoints IS NULL THEN
    RETURN;
  END IF;

  SELECT name INTO v_project_name
  FROM pm.projects WHERE id = p_row.project_id;

  SELECT coalesce(jsonb_object_agg(t.item_type, t.subtotal), '{}'::jsonb)
    INTO v_totals
  FROM (
    SELECT li->>'item_type' AS item_type, sum((li->>'amount')::numeric) AS subtotal
    FROM jsonb_array_elements(
           coalesce(nullif(p_row.line_items, 'null'::jsonb), '[]'::jsonb)
         ) li
    WHERE li ? 'item_type'
    GROUP BY li->>'item_type'
  ) t;

  IF v_totals = '{}'::jsonb THEN
    v_totals := jsonb_build_object(p_row.invoice_type, p_row.amount);
  END IF;

  v_seq := nextval('pm.webhook_event_seq');
  v_public_id := 'evt_' || replace(gen_random_uuid()::text, '-', '');

  v_payload := jsonb_build_object(
    'id', v_public_id,
    'type', p_event_type,
    'sequence', v_seq,
    'created_at', now(),
    'data', jsonb_build_object(
      'invoice', jsonb_build_object(
        'id', p_row.id,
        'invoice_number', p_row.invoice_number,
        'project_id', p_row.project_id,
        'status', p_row.status,
        'paid', v_is_paid,
        'invoice_type', p_row.invoice_type,
        'amount', p_row.amount,
        'date', p_row.date,
        'due_date', p_row.due_date,
        'paid_date', p_row.paid_date,
        'description', p_row.description,
        'updated_at', p_row.updated_at
      ),
      'project', jsonb_build_object(
        'id', p_row.project_id,
        'name', coalesce(v_project_name, '')
      ),
      'line_items', coalesce(nullif(p_row.line_items, 'null'::jsonb), '[]'::jsonb),
      'totals_by_type', v_totals
    ) || coalesce(p_data, '{}'::jsonb)
  );

  INSERT INTO pm.webhook_events (
    event_id, sequence, event_type, resource_type, resource_id, payload, net_amounts
  )
  VALUES (
    v_public_id, v_seq, p_event_type, 'invoice', p_row.id, v_payload,
    pm.invoice_net_amounts(p_row)
  )
  RETURNING id INTO v_event_uuid;

  INSERT INTO pm.webhook_deliveries (webhook_event_id, endpoint_id)
  SELECT v_event_uuid, unnest(v_endpoints);
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_invoice_webhook_event(pm.project_invoices, text, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.emit_invoice_webhook_event(pm.project_invoices, text, jsonb) TO service_role;

-- ---------------------------------------------------------------------------
-- assistant.message
-- ---------------------------------------------------------------------------
-- Only an endpoint filtered to a personal agent (member_id), or scoped to an
-- assistant setup, takes assistant.message: chat is private, so no
-- workspace-wide endpoint ever lists it. Only a signed-in Owner or the
-- server (which checks for an Owner or a key with assistants.provision)
-- scopes an endpoint to a setup.
CREATE OR REPLACE FUNCTION pm.webhook_endpoints_assistant_guard()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF NEW.assistant_setup_id IS NOT NULL AND auth.uid() IS NOT NULL AND coalesce(auth.role(), '') <> 'service_role' THEN
    IF TG_OP = 'INSERT' OR NEW.assistant_setup_id IS DISTINCT FROM OLD.assistant_setup_id THEN
      IF coalesce(pm.current_team_member_role(), '') <> 'owner' THEN
        RAISE EXCEPTION 'Only an Owner scopes an endpoint to an assistant setup' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  IF 'assistant.message' = ANY (NEW.events) AND NEW.assistant_setup_id IS NULL AND NOT EXISTS (
    SELECT 1 FROM pm.team_members a WHERE a.id = NEW.member_id AND a.role = 'agent' AND a.delegate_of IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'assistant.message goes only to an endpoint filtered to a personal agent (member_id) or scoped to an assistant setup (assistant_setup_id)' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.webhook_endpoints_assistant_guard() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS webhook_endpoints_assistant_guard ON pm.webhook_endpoints;
CREATE TRIGGER webhook_endpoints_assistant_guard
  BEFORE INSERT OR UPDATE OF events, member_id, assistant_setup_id ON pm.webhook_endpoints
  FOR EACH ROW EXECUTE FUNCTION pm.webhook_endpoints_assistant_guard();

-- Queues one assistant.message event (its own line: resource chat_message)
-- to every active endpoint subscribed to it whose member filter is exactly
-- the agent, or whose setup made the agent. Never to an endpoint with
-- neither, nor one filtered to projects (an event has no project). Answers
-- whether any endpoint got it; nothing is written when none does.
CREATE OR REPLACE FUNCTION pm.emit_assistant_message(p_message_id uuid, p_agent_id uuid, p_data jsonb)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_endpoints uuid[];
  v_seq bigint;
  v_public_id text;
  v_event_uuid uuid;
BEGIN
  SELECT array_agg(e.id ORDER BY e.id) INTO v_endpoints
  FROM pm.webhook_endpoints e
  WHERE e.is_active AND e.events @> ARRAY['assistant.message']
    AND (e.member_id = p_agent_id OR (e.member_id IS NULL AND e.assistant_setup_id IS NOT NULL))
    AND pm.webhook_endpoint_matches(e, 'assistant.message', '{}'::uuid[], ARRAY[p_agent_id]);
  IF v_endpoints IS NULL THEN
    RETURN false;
  END IF;

  v_seq := nextval('pm.webhook_event_seq');
  v_public_id := 'evt_' || replace(gen_random_uuid()::text, '-', '');

  INSERT INTO pm.webhook_events (event_id, sequence, event_type, resource_type, resource_id, payload)
  VALUES (
    v_public_id, v_seq, 'assistant.message', 'chat_message', p_message_id,
    jsonb_build_object(
      'id', v_public_id,
      'type', 'assistant.message',
      'sequence', v_seq,
      'created_at', now(),
      'data', coalesce(p_data, '{}'::jsonb) || jsonb_build_object('member_ids', jsonb_build_array(p_agent_id))
    )
  )
  RETURNING id INTO v_event_uuid;

  INSERT INTO pm.webhook_deliveries (webhook_event_id, endpoint_id)
  SELECT v_event_uuid, unnest(v_endpoints);
  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_assistant_message(uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.emit_assistant_message(uuid, uuid, jsonb) TO service_role;

-- ============================================================
-- CONTRACT CLEANUP (20261125001200_contract_cleanup.sql)
-- New inboxes run triage plans; every webhook envelope carries
-- api_version.
-- ============================================================
-- The public contract, cleaned up for outside harnesses.
--
-- - New inboxes run triage plans: pm.inboxes.triage_mode defaults to 'plans'
--   (was 'legacy'). Only the column default changes: every existing inbox
--   keeps the mode it has, and a write that names a mode still gets it.
-- - Every webhook envelope carries api_version, the contract's version
--   (src/lib/api/version.ts), beside id, type, sequence, created_at and data.
--   It is stamped as the event is stored, by one BEFORE INSERT trigger on
--   pm.webhook_events, so every event writer (pm.emit_webhook_event,
--   pm.emit_invoice_webhook_event, pm.emit_agent_event_webhook,
--   pm.emit_assistant_message, and any later one) gets it while their bodies
--   stay exactly as they are. An envelope that already names api_version
--   keeps its own. Events stored before this migration have none; nothing is
--   rewritten. The value is written once, here.
--
-- Additive and safe to run twice. 2.0.40 code never reads the new key, and
-- an inbox it creates without naming a mode takes plans.

ALTER TABLE pm.inboxes ALTER COLUMN triage_mode SET DEFAULT 'plans';

CREATE OR REPLACE FUNCTION pm.webhook_envelope_api_version()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF jsonb_typeof(NEW.payload) = 'object' AND NOT NEW.payload ? 'api_version' THEN
    NEW.payload := NEW.payload || jsonb_build_object('api_version', '2026-11-25');
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.webhook_envelope_api_version() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS webhook_events_api_version ON pm.webhook_events;
CREATE TRIGGER webhook_events_api_version
  BEFORE INSERT ON pm.webhook_events
  FOR EACH ROW EXECUTE FUNCTION pm.webhook_envelope_api_version();

-- ============================================================
-- WATCHDOG AND RETENTION (20261125001300_watchdog_retention.sql)
-- When time passes, something happens: agents offline, runs timed
-- out, questions expired, failing webhooks told; old data goes.
-- ============================================================
-- When time passes, something happens: a watchdog, and data that does not
-- pile up forever.
--
-- The watchdog (pm.run_watchdog, pg_cron pm-agent-watchdog, every 5 minutes)
-- turns what readers used to work out on their own into one stored change,
-- made once, with its webhook event and its bell:
-- - An agent whose heartbeat is older than its staleness rule (two missed
--   beats plus a minute, as status views read it) has stopped responding:
--   its owners (or, with none, the Owners) are told once, agent.offline goes
--   out, and agent.online with a short "is back" when it reports again (the
--   bell only when the first one rang). Paused agents are skipped, and so
--   are personal assistants, which tell their admins on their own path.
-- - A run with no update for two hours is stored as timed_out, so
--   run.finished goes out once (the rule readers already used). A run
--   waiting on a person (status waiting) is skipped while a question or
--   approval naming it is open; waiting with none, it gets seven days.
-- - An open question past expires_at is stored as expired, and
--   question.expired goes out (from the question trigger, so a read that
--   stores it first sends it too). Whoever asked hears once; for an agent,
--   its owners.
-- - A webhook endpoint failing 5 attempts in a row, or for 24 hours, tells
--   the Owners and whoever manages webhooks once. A success resets it and
--   clears that bell. Nothing is sent to the endpoint itself.
-- Markers live in pm.watchdog_marks (server only), so nothing repeats.
--
-- Webhook retries are on by default: the app turns them on once their
-- prerequisites are there, unless an Owner turned them off
-- (business_settings.webhook_retries_off, read by pm.webhook_retry_kick).
--
-- Retention (pm.apply_data_retention, pg_cron pm-retention, daily), from
-- settings on the business row, each nullable (null keeps forever):
-- webhook_retention_days (default 30: finished deliveries, then events no
-- delivery needs), agent_health_history_days (default 90, the newest row
-- per agent always stays), agent_activity_retention_days,
-- agent_run_retention_days and chat_retention_days (chat text is blanked;
-- the row, its dedupe key and thread stay). Nothing a pending delivery, an
-- unfinished run or an open delegation needs is touched. In batches.
--
-- A run can wait on a person: status waiting, neither finished nor
-- running. A question or approval naming the run (questions.run_id, the
-- asking agent's own unfinished run) makes it wait while it is open; when
-- the last one is answered, cancelled or expires, the run is running again
-- and its two hours start over. An agent may also set waiting itself.
-- run.updated goes out when an unfinished run changes status.
--
-- Additive and safe to run twice. 2.0.40 code reads and writes nothing new;
-- a run or question it would have read as timed out or expired now reads
-- the same from the stored row.

-- ---------------------------------------------------------------------------
-- Settings
-- ---------------------------------------------------------------------------
ALTER TABLE pm.business_settings
  ADD COLUMN IF NOT EXISTS webhook_retention_days integer DEFAULT 30,
  ADD COLUMN IF NOT EXISTS agent_health_history_days integer DEFAULT 90,
  ADD COLUMN IF NOT EXISTS agent_activity_retention_days integer,
  ADD COLUMN IF NOT EXISTS agent_run_retention_days integer,
  ADD COLUMN IF NOT EXISTS chat_retention_days integer,
  ADD COLUMN IF NOT EXISTS webhook_retries_off boolean NOT NULL DEFAULT false;

ALTER TABLE pm.business_settings DROP CONSTRAINT IF EXISTS business_settings_retention_days_check;
ALTER TABLE pm.business_settings
  ADD CONSTRAINT business_settings_retention_days_check CHECK (
    (webhook_retention_days IS NULL OR webhook_retention_days BETWEEN 7 AND 3650)
    AND (agent_health_history_days IS NULL OR agent_health_history_days BETWEEN 7 AND 3650)
    AND (agent_activity_retention_days IS NULL OR agent_activity_retention_days BETWEEN 30 AND 3650)
    AND (agent_run_retention_days IS NULL OR agent_run_retention_days BETWEEN 30 AND 3650)
    AND (chat_retention_days IS NULL OR chat_retention_days BETWEEN 7 AND 3650)
  );

COMMENT ON COLUMN pm.business_settings.webhook_retention_days IS
  'How long delivered or failed webhook deliveries are kept (7 to 3650 days, default 30), and their events once no delivery needs them; null keeps them forever. pm.apply_data_retention, daily.';
COMMENT ON COLUMN pm.business_settings.agent_health_history_days IS
  'How long agent uptime history is kept (7 to 3650 days, default 90); the newest row per agent always stays. Null keeps it forever.';
COMMENT ON COLUMN pm.business_settings.agent_activity_retention_days IS
  'How long agent events are kept (30 to 3650 days); billing events always stay. Null (the default) keeps them forever.';
COMMENT ON COLUMN pm.business_settings.agent_run_retention_days IS
  'How long finished agent runs are kept (30 to 3650 days); a run a running run or an open delegation needs stays. Null (the default) keeps them forever.';
COMMENT ON COLUMN pm.business_settings.chat_retention_days IS
  'How long chat message text is kept (7 to 3650 days); after that the text is blanked and the row (dedupe key, thread) stays. Messages still waiting for their assistant keep it. Null (the default) keeps it forever.';
COMMENT ON COLUMN pm.business_settings.webhook_retries_off IS
  'An Owner turned webhook retries off: the app no longer turns them on by itself and pm.webhook_retry_kick sends nothing.';

-- Owner-only settings on the business row, now with retention and retries.
CREATE OR REPLACE FUNCTION pm.business_settings_owner_columns()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF auth.role() = 'service_role' OR auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  IF (TG_OP = 'INSERT' AND (NEW.auto_migrate IS DISTINCT FROM true OR NEW.owners_read_personal_inboxes IS DISTINCT FROM false
       OR NEW.agents_paused_at IS NOT NULL OR NEW.audit_retention_days IS NOT NULL OR NEW.audit_redact_keys <> '{}'
       OR NEW.connect_ai_enabled IS DISTINCT FROM true OR NEW.personal_key_lifetime_days IS NOT NULL
       OR NEW.sign_in_methods IS DISTINCT FROM 'both'
       OR NEW.webhook_retention_days IS DISTINCT FROM 30 OR NEW.agent_health_history_days IS DISTINCT FROM 90
       OR NEW.agent_activity_retention_days IS NOT NULL OR NEW.agent_run_retention_days IS NOT NULL
       OR NEW.chat_retention_days IS NOT NULL OR NEW.webhook_retries_off IS DISTINCT FROM false))
     OR (TG_OP = 'UPDATE' AND (NEW.auto_migrate IS DISTINCT FROM OLD.auto_migrate
       OR NEW.owners_read_personal_inboxes IS DISTINCT FROM OLD.owners_read_personal_inboxes
       OR NEW.agents_paused_at IS DISTINCT FROM OLD.agents_paused_at
       OR NEW.agents_paused_by IS DISTINCT FROM OLD.agents_paused_by
       OR NEW.audit_retention_days IS DISTINCT FROM OLD.audit_retention_days
       OR NEW.audit_redact_keys IS DISTINCT FROM OLD.audit_redact_keys
       OR NEW.connect_ai_enabled IS DISTINCT FROM OLD.connect_ai_enabled
       OR NEW.personal_key_lifetime_days IS DISTINCT FROM OLD.personal_key_lifetime_days
       OR NEW.sign_in_methods IS DISTINCT FROM OLD.sign_in_methods
       OR NEW.webhook_retention_days IS DISTINCT FROM OLD.webhook_retention_days
       OR NEW.agent_health_history_days IS DISTINCT FROM OLD.agent_health_history_days
       OR NEW.agent_activity_retention_days IS DISTINCT FROM OLD.agent_activity_retention_days
       OR NEW.agent_run_retention_days IS DISTINCT FROM OLD.agent_run_retention_days
       OR NEW.chat_retention_days IS DISTINCT FROM OLD.chat_retention_days
       OR NEW.webhook_retries_off IS DISTINCT FROM OLD.webhook_retries_off)) THEN
    IF COALESCE(pm.current_team_member_role(), '') <> 'owner' THEN
      RAISE EXCEPTION 'Only an Owner can change this setting' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.business_settings_owner_columns() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Notifications about a webhook endpoint
-- ---------------------------------------------------------------------------
ALTER TABLE pm.team_member_notifications
  DROP CONSTRAINT IF EXISTS team_member_notifications_entity_type_check;
ALTER TABLE pm.team_member_notifications
  ADD CONSTRAINT team_member_notifications_entity_type_check
    CHECK (entity_type IN ('task', 'project', 'lead', 'comment', 'member', 'contact', 'suggestion', 'goal', 'question', 'invoice', 'reminder', 'webhook'));

-- ---------------------------------------------------------------------------
-- Markers: what the watchdog already did (server only)
-- ---------------------------------------------------------------------------
-- agent_offline: the agent is offline since `since` (its last report);
--   notified_at says its people were told, so "is back" rings too.
-- question_expired: whoever asked was told (kept two days, past the window).
-- webhook_failing: failed attempts in a row (`failures`) since `since`, the
--   last error in detail; notified_at once its people were told. A success
--   removes it.
CREATE TABLE IF NOT EXISTS pm.watchdog_marks (
  kind text NOT NULL,
  subject_id uuid NOT NULL,
  since timestamptz NOT NULL DEFAULT now(),
  failures integer NOT NULL DEFAULT 0,
  detail jsonb NOT NULL DEFAULT '{}'::jsonb,
  notified_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (kind, subject_id)
);

ALTER TABLE pm.watchdog_marks DROP CONSTRAINT IF EXISTS watchdog_marks_kind_check;
ALTER TABLE pm.watchdog_marks
  ADD CONSTRAINT watchdog_marks_kind_check CHECK (kind IN ('agent_offline', 'question_expired', 'webhook_failing'));

COMMENT ON TABLE pm.watchdog_marks IS
  'What pm.run_watchdog already did, so each change is made and told once: agents offline, expired questions told, failing webhook endpoints. Server only.';

ALTER TABLE pm.watchdog_marks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.watchdog_marks FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.watchdog_marks TO service_role;

-- What the jobs scan.
CREATE INDEX IF NOT EXISTS idx_questions_expired
  ON pm.questions (expires_at) WHERE status = 'expired';
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_finished
  ON pm.webhook_deliveries (created_at) WHERE status IN ('succeeded', 'failed');
CREATE INDEX IF NOT EXISTS idx_webhook_events_created_at
  ON pm.webhook_events (created_at);
CREATE INDEX IF NOT EXISTS idx_agent_runs_finished
  ON pm.agent_runs (finished_at) WHERE status <> 'running';
CREATE INDEX IF NOT EXISTS idx_chat_messages_created_text
  ON pm.chat_messages (created_at) WHERE text <> '';

-- ---------------------------------------------------------------------------
-- Small rules the watchdog shares
-- ---------------------------------------------------------------------------
-- Seconds without a report before an agent reads as offline: two missed
-- beats plus a minute, a minute when it never said (heartbeatStaleAfterSeconds).
CREATE OR REPLACE FUNCTION pm.heartbeat_stale_after_seconds(p_interval_seconds integer)
RETURNS integer
LANGUAGE sql
IMMUTABLE
SET search_path = ''
AS $$
  SELECT 2 * CASE WHEN p_interval_seconds > 0 THEN p_interval_seconds ELSE 60 END + 60
$$;

REVOKE ALL ON FUNCTION pm.heartbeat_stale_after_seconds(integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.heartbeat_stale_after_seconds(integer) TO service_role;

-- "12 minutes", "3 hours", "2 days": how long ago, for a bell.
CREATE OR REPLACE FUNCTION pm.watchdog_ago(p_since timestamptz)
RETURNS text
LANGUAGE sql
STABLE
SET search_path = ''
AS $$
  SELECT CASE
    WHEN m < 2 THEN '1 minute'
    WHEN m < 120 THEN m || ' minutes'
    WHEN m < 2880 THEN (m / 60) || ' hours'
    ELSE (m / 1440) || ' days'
  END
  FROM (SELECT greatest(0, floor(extract(epoch FROM (now() - p_since)) / 60))::bigint AS m) elapsed
$$;

REVOKE ALL ON FUNCTION pm.watchdog_ago(timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.watchdog_ago(timestamptz) TO service_role;

-- Who hears about an agent: its people owners and owner groups' people (and
-- a personal agent's person), else the active Owners.
CREATE OR REPLACE FUNCTION pm.agent_people_to_tell(p_agent_id uuid)
RETURNS uuid[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  WITH named AS (
    SELECT o.member_id AS id FROM pm.agent_owners o WHERE o.agent_id = p_agent_id
    UNION
    SELECT gm.member_id FROM pm.agent_owner_groups g
    JOIN pm.group_members gm ON gm.group_id = g.group_id
    WHERE g.agent_id = p_agent_id
    UNION
    SELECT a.delegate_of FROM pm.team_members a WHERE a.id = p_agent_id AND a.delegate_of IS NOT NULL
  ), people AS (
    SELECT m.id FROM named JOIN pm.team_members m ON m.id = named.id
    WHERE m.role <> 'agent' AND coalesce(m.status, 'active') = 'active'
  )
  SELECT coalesce(
    (SELECT array_agg(id ORDER BY id) FROM people),
    (SELECT array_agg(m.id ORDER BY m.id) FROM pm.team_members m WHERE m.role = 'owner' AND coalesce(m.status, 'active') = 'active'),
    '{}'
  )
$$;

REVOKE ALL ON FUNCTION pm.agent_people_to_tell(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_people_to_tell(uuid) TO service_role;

-- ---------------------------------------------------------------------------
-- A run waiting on a person
-- ---------------------------------------------------------------------------
-- waiting: not finished (no finished_at), not running. Set by the agent
-- (PATCH status waiting), or by a question or approval naming the run while
-- it is open. Any later update from the agent brings it back to running (the
-- API); a finish from waiting is a finish. The watchdog skips it while a
-- question naming it is open; waiting with none, it times out after seven
-- days without an update.
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_status_check;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_status_check CHECK (status IN ('running', 'waiting', 'succeeded', 'failed', 'cancelled', 'timed_out'));
ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_finished_when_done;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_finished_when_done CHECK ((status IN ('running', 'waiting')) = (finished_at IS NULL));

COMMENT ON COLUMN pm.agent_runs.status IS
  'running, waiting (on a person), succeeded, failed, cancelled or timed_out. The watchdog stores timed_out for a run running two hours past updated_at, or waiting seven days with no open question naming it; readers read it so until then.';

-- What the watchdog scans for waiting runs.
CREATE INDEX IF NOT EXISTS idx_agent_runs_waiting ON pm.agent_runs (updated_at) WHERE status = 'waiting';

-- The run a question or approval holds: the asking agent's own run. While it
-- is open the run waits on a person. Cleared only when the run is gone.
ALTER TABLE pm.questions ADD COLUMN IF NOT EXISTS run_id uuid REFERENCES pm.agent_runs(id) ON DELETE SET NULL;
COMMENT ON COLUMN pm.questions.run_id IS
  'The run this question or approval holds (the asking agent''s own): while it is open, the run waits on a person. Fixed once asked.';
CREATE INDEX IF NOT EXISTS idx_questions_run_open ON pm.questions (run_id)
  WHERE run_id IS NOT NULL AND status = 'open' AND deleted_at IS NULL;

-- Whether an open question or approval (not past expires_at, not in Trash)
-- names the run. The watchdog and the run feed read it the same way. Only
-- while the AI agents module is on: with it off, no agent waits on anyone.
CREATE OR REPLACE FUNCTION pm.agent_run_has_open_question(p_run_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT pm.module_enabled('agents') AND EXISTS (
    SELECT 1 FROM pm.questions q
    WHERE q.run_id = p_run_id AND q.status = 'open' AND q.deleted_at IS NULL
      AND (q.expires_at IS NULL OR q.expires_at > now())
  );
$$;

REVOKE ALL ON FUNCTION pm.agent_run_has_open_question(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION pm.agent_run_has_open_question(uuid) TO authenticated, service_role;

-- A question names only its asker's own run, and keeps it: a later write
-- may clear it (the run is gone) but never point it elsewhere.
CREATE OR REPLACE FUNCTION pm.guard_question_run()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.run_id IS NOT NULL AND NEW.run_id IS DISTINCT FROM OLD.run_id THEN
      NEW.run_id := OLD.run_id;
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.run_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM pm.agent_runs r WHERE r.id = NEW.run_id AND r.agent_id = NEW.asked_by) THEN
    RAISE EXCEPTION 'A question names only its asker''s own run'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'questions_run_is_askers';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.guard_question_run() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS guard_question_run ON pm.questions;
CREATE TRIGGER guard_question_run
  BEFORE INSERT OR UPDATE OF run_id ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.guard_question_run();

-- Asked (or back from Trash) open, its run waits on a person. Answered,
-- cancelled, expired or moved to Trash, its run is running again once no
-- other open question names it; the write restarts its two hours.
CREATE OR REPLACE FUNCTION pm.sync_question_run()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_open_now boolean;
  v_open_before boolean;
BEGIN
  IF NEW.run_id IS NULL THEN
    RETURN NULL;
  END IF;
  v_open_now := NEW.status = 'open' AND NEW.deleted_at IS NULL;
  v_open_before := TG_OP = 'UPDATE' AND OLD.status = 'open' AND OLD.deleted_at IS NULL;
  IF v_open_now AND NOT v_open_before THEN
    UPDATE pm.agent_runs SET status = 'waiting'
    WHERE id = NEW.run_id AND status IN ('running', 'waiting');
  ELSIF v_open_before AND NOT v_open_now THEN
    UPDATE pm.agent_runs SET status = 'running'
    WHERE id = NEW.run_id AND status = 'waiting' AND NOT pm.agent_run_has_open_question(NEW.run_id);
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.sync_question_run() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS sync_question_run ON pm.questions;
CREATE TRIGGER sync_question_run
  AFTER INSERT OR UPDATE OF status, deleted_at ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.sync_question_run();

-- Every run write, as before, with waiting as unfinished: a finished run
-- stays as it finished; one that finishes gets its finish time.
CREATE OR REPLACE FUNCTION pm.handle_agent_run_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  task_project uuid;
BEGIN
  IF NEW.task_id IS NOT NULL THEN
    SELECT project_id INTO task_project FROM pm.tasks WHERE id = NEW.task_id;
    IF task_project IS NOT NULL THEN
      NEW.project_id := task_project;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.agent_id := OLD.agent_id;
    NEW.created_at := OLD.created_at;
    NEW.external_id := coalesce(OLD.external_id, NEW.external_id);
    -- A finished run stays as it finished, whoever writes: two finishes at
    -- once cannot both land. Its other details may still change.
    IF OLD.status NOT IN ('running', 'waiting') THEN
      NEW.status := OLD.status;
      NEW.finished_at := OLD.finished_at;
    END IF;
  END IF;
  IF NEW.status NOT IN ('running', 'waiting') AND NEW.finished_at IS NULL THEN
    NEW.finished_at := greatest(now(), NEW.started_at);
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_agent_run_before_write() FROM PUBLIC, anon, authenticated;

-- Run webhooks: run.started, run.finished, and run.updated when an
-- unfinished run changes status (running to waiting, or back). The chain
-- rides along as before.
CREATE OR REPLACE FUNCTION pm.emit_agent_run_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['run.started', 'run.updated', 'run.finished']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_type := CASE WHEN NEW.status IN ('running', 'waiting') THEN 'run.started' ELSE 'run.finished' END;
  ELSIF OLD.status IN ('running', 'waiting') AND NEW.status NOT IN ('running', 'waiting') THEN
    v_type := 'run.finished';
  ELSIF OLD.status IN ('running', 'waiting') AND NEW.status IS DISTINCT FROM OLD.status THEN
    v_type := 'run.updated';
  END IF;
  IF v_type IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'run',
    NEW.id,
    ARRAY[NEW.project_id],
    ARRAY[NEW.agent_id],
    jsonb_build_object(
      'run', jsonb_build_object(
        'id', NEW.id,
        'agent_id', NEW.agent_id,
        'task_id', NEW.task_id,
        'project_id', NEW.project_id,
        'status', NEW.status,
        'title', NEW.title,
        'summary', NEW.summary,
        'model', NEW.model,
        'trigger', NEW.trigger,
        'tokens_in', NEW.tokens_in,
        'tokens_out', NEW.tokens_out,
        'cost_usd', NEW.cost_usd,
        'external_id', NEW.external_id,
        'external_url', NEW.external_url,
        'started_at', NEW.started_at,
        'finished_at', NEW.finished_at,
        'updated_at', NEW.updated_at
      ) || CASE WHEN NEW.parent_run_id IS NOT NULL
        THEN jsonb_build_object('parent_run_id', NEW.parent_run_id, 'root_run_id', NEW.root_run_id)
        ELSE '{}'::jsonb END,
      'project', CASE WHEN NEW.project_id IS NOT NULL THEN jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ) END,
      'project_id', NEW.project_id,
      'task_id', NEW.task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_agent_run_webhook() FROM PUBLIC, anon, authenticated;

-- The run feed, as before, reading timed_out by the watchdog's rule until
-- it stores it: running two hours past its last update, or waiting seven
-- days with no open question naming it.
CREATE OR REPLACE VIEW pm.agent_run_feed
WITH (security_invoker = true) AS
SELECT
  r.id,
  'run'::text AS source,
  r.agent_id,
  r.task_id,
  r.project_id,
  CASE
    WHEN r.status = 'running' AND r.updated_at < now() - interval '2 hours' THEN 'timed_out'
    WHEN r.status = 'waiting' AND r.updated_at < now() - interval '7 days' AND NOT pm.agent_run_has_open_question(r.id) THEN 'timed_out'
    ELSE r.status
  END AS status,
  NULL::text AS outcome,
  r.title,
  r.summary,
  r.model,
  r.trigger,
  r.started_at,
  r.finished_at,
  CASE WHEN r.finished_at IS NOT NULL THEN (extract(epoch FROM r.finished_at - r.started_at) * 1000)::bigint END AS duration_ms,
  r.tokens_in,
  r.tokens_out,
  r.cost_usd,
  r.external_id,
  r.external_url,
  r.started_at AS sort_at,
  r.updated_at
FROM pm.agent_runs r
UNION ALL
SELECT
  a.id,
  'turn'::text AS source,
  a.agent_id,
  NULL::uuid AS task_id,
  a.project_id,
  'succeeded'::text AS status,
  a.metadata->>'outcome' AS outcome,
  a.title,
  NULL::text AS summary,
  a.metadata->>'model' AS model,
  CASE WHEN a.metadata->>'origin' = 'directed' THEN 'chat' ELSE 'scheduled' END AS trigger,
  coalesce(pm.agent_analytics_ts(a.metadata->>'started_at'), a.created_at) AS started_at,
  coalesce(pm.agent_analytics_ts(a.metadata->>'finished_at'), a.created_at) AS finished_at,
  pm.agent_analytics_int(a.metadata->>'duration_ms') AS duration_ms,
  CASE WHEN a.metadata->>'tokens_scope' = 'turn' AND a.metadata->'tokens' ? 'input'
    THEN pm.agent_analytics_int(a.metadata->'tokens'->>'input') END AS tokens_in,
  CASE WHEN a.metadata->>'tokens_scope' = 'turn' AND a.metadata->'tokens' ? 'output'
    THEN pm.agent_analytics_int(a.metadata->'tokens'->>'output') END AS tokens_out,
  NULL::numeric AS cost_usd,
  a.metadata->>'source_turn_id' AS external_id,
  NULL::text AS external_url,
  a.created_at AS sort_at,
  a.created_at AS updated_at
FROM pm.agent_activities a
WHERE a.activity_type = 'turn.completed'
  AND a.agent_id IS NOT NULL
  AND a.metadata->>'run_id' IS NULL
  AND NOT (a.metadata->>'origin' = 'scheduled' AND coalesce(a.metadata->>'outcome', '') IN ('idle', 'skipped', 'waiting'));

-- ---------------------------------------------------------------------------
-- Webhook endpoint health: every attempt's outcome, counted
-- ---------------------------------------------------------------------------
-- After pm.complete_webhook_delivery (or a lease that ran out on the last
-- attempt) records an attempt: a success removes the endpoint's mark and
-- clears its "keeps failing" bell; a failure counts one more in a row.
CREATE OR REPLACE FUNCTION pm.track_webhook_endpoint_health()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF NEW.status = 'succeeded' THEN
    DELETE FROM pm.watchdog_marks WHERE kind = 'webhook_failing' AND subject_id = NEW.endpoint_id;
    IF FOUND THEN
      PERFORM pm.set_notifications_cleared('webhook', NEW.endpoint_id::text, true);
    END IF;
  ELSE
    INSERT INTO pm.watchdog_marks AS w (kind, subject_id, since, failures, detail, updated_at)
    VALUES ('webhook_failing', NEW.endpoint_id, now(), 1,
      jsonb_build_object('last_error', left(coalesce(NEW.last_error, 'HTTP ' || NEW.last_status_code, 'No response'), 300),
        'last_status_code', NEW.last_status_code), now())
    ON CONFLICT (kind, subject_id) DO UPDATE
      SET failures = w.failures + 1, detail = EXCLUDED.detail, updated_at = now();
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.track_webhook_endpoint_health() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS track_webhook_endpoint_health ON pm.webhook_deliveries;
CREATE TRIGGER track_webhook_endpoint_health
  AFTER UPDATE OF status ON pm.webhook_deliveries
  FOR EACH ROW
  WHEN (OLD.status = 'delivering' AND NEW.status IN ('pending', 'succeeded', 'failed'))
  EXECUTE FUNCTION pm.track_webhook_endpoint_health();

-- ---------------------------------------------------------------------------
-- question.expired: from the question trigger, so whoever stores the expiry
-- (the watchdog, or a read that gets there first) sends it once. A question
-- that holds a run carries its run_id.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.emit_question_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['question.asked', 'question.answered', 'question.cancelled', 'question.expired']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'open' AND NEW.deleted_at IS NULL THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.deleted_at IS NOT NULL THEN
    IF OLD.deleted_at IS NULL AND OLD.status = 'open' THEN
      v_type := 'question.cancelled';
    END IF;
  ELSIF OLD.deleted_at IS NOT NULL THEN
    IF NEW.status = 'open' THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_type := CASE NEW.status
      WHEN 'open' THEN 'question.asked'
      WHEN 'answered' THEN 'question.answered'
      WHEN 'cancelled' THEN 'question.cancelled'
      WHEN 'expired' THEN 'question.expired'
    END;
  END IF;
  IF v_type IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'question',
    NEW.id,
    ARRAY[NEW.project_id],
    pm.webhook_event_members('question', NEW.id),
    jsonb_build_object(
      'question', jsonb_build_object(
        'id', NEW.id,
        'project_id', NEW.project_id,
        'task_id', NEW.task_id,
        'asked_by', NEW.asked_by,
        'asked_to', NEW.asked_to,
        'question', NEW.question,
        'choices', NEW.choices,
        'allow_other', NEW.allow_other,
        'status', NEW.status,
        'answer_choice', NEW.answer_choice,
        'answer_text', NEW.answer_text,
        'answered_by', NEW.answered_by,
        'answered_at', NEW.answered_at,
        'cancelled_by', NEW.cancelled_by,
        'cancelled_at', NEW.cancelled_at,
        'expires_at', NEW.expires_at,
        'created_at', NEW.created_at,
        'updated_at', NEW.updated_at,
        'deleted_at', NEW.deleted_at
      ) || CASE WHEN NEW.kind = 'approval' THEN jsonb_build_object(
        'kind', NEW.kind,
        'action', NEW.action,
        'decision', CASE NEW.answer_choice WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' END,
        'decided_by', CASE WHEN NEW.status = 'answered' THEN NEW.answered_by END,
        'decided_via', CASE WHEN NEW.status = 'answered' THEN NEW.decided_via END
      ) ELSE '{}'::jsonb END
        || CASE WHEN NEW.asked_to_group IS NOT NULL THEN jsonb_build_object('asked_to_group', NEW.asked_to_group) ELSE '{}'::jsonb END
        || CASE WHEN NEW.principal_id IS NOT NULL THEN jsonb_build_object('principal_id', NEW.principal_id) ELSE '{}'::jsonb END
        || CASE WHEN NEW.run_id IS NOT NULL THEN jsonb_build_object('run_id', NEW.run_id) ELSE '{}'::jsonb END,
      'project', CASE WHEN NEW.project_id IS NOT NULL THEN jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ) END,
      'project_id', NEW.project_id,
      'task_id', NEW.task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_question_webhook() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- The watchdog
-- ---------------------------------------------------------------------------
-- Every 5 minutes. Each change is made once (a stored status, or a marker),
-- so a second run in a row does nothing. Answers what it did.
CREATE OR REPLACE FUNCTION pm.run_watchdog()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  r record;
  v_person uuid;
  v_people uuid[];
  v_claims uuid[];
  v_stale integer;
  v_tell boolean;
  v_text text;
  v_title text;
  v_link text;
  v_workspace_paused boolean;
  v_offline integer := 0;
  v_online integer := 0;
  v_runs integer := 0;
  v_questions integer := 0;
  v_told integer := 0;
  v_webhooks integer := 0;
BEGIN
  -- One watchdog at a time; a run that overlaps the last one waits for the next.
  IF NOT pg_try_advisory_xact_lock(hashtext('pm.run_watchdog')) THEN
    RETURN jsonb_build_object('skipped', true);
  END IF;

  -- Agents that stopped responding, and agents that came back.
  IF pm.module_enabled('agents') THEN
    SELECT coalesce(bool_or(s.agents_paused_at IS NOT NULL), false) INTO v_workspace_paused FROM pm.business_settings s;

    FOR r IN
      SELECT a.id, a.name, h.reported_at, h.expected_interval_seconds AS interval_seconds
      FROM pm.agent_health h
      JOIN pm.team_members a ON a.id = h.member_id
      WHERE a.role = 'agent'
        AND a.delegate_of IS NULL
        AND coalesce(a.status, 'active') = 'active'
        AND a.agent_paused_at IS NULL
        AND NOT v_workspace_paused
        AND h.reported_at < now() - make_interval(secs => pm.heartbeat_stale_after_seconds(h.expected_interval_seconds))
        AND NOT EXISTS (SELECT 1 FROM pm.watchdog_marks w WHERE w.kind = 'agent_offline' AND w.subject_id = a.id)
      ORDER BY h.reported_at
    LOOP
      v_stale := pm.heartbeat_stale_after_seconds(r.interval_seconds);
      -- Claims that ran out while it was silent: those tasks are free again.
      SELECT coalesce(array_agg(t.id ORDER BY t.id), '{}') INTO v_claims
      FROM pm.tasks t
      WHERE t.claimed_by = r.id AND t.claim_expires_at <= now() AND t.claim_expires_at > r.reported_at
        AND t.status <> 'done' AND t.deleted_at IS NULL;
      -- An agent silent long before the watchdog first saw it is marked
      -- without a bell: nobody needs news that old.
      v_tell := now() - r.reported_at <= make_interval(secs => v_stale) + interval '1 day';
      v_people := CASE WHEN v_tell THEN pm.agent_people_to_tell(r.id) ELSE '{}'::uuid[] END;

      INSERT INTO pm.watchdog_marks (kind, subject_id, since, detail, notified_at)
      VALUES ('agent_offline', r.id, r.reported_at, jsonb_build_object('released_task_ids', to_jsonb(v_claims)),
        CASE WHEN cardinality(v_people) > 0 THEN now() END);

      PERFORM pm.emit_webhook_event('agent.offline', 'agent', r.id, '{}'::uuid[], ARRAY[r.id], jsonb_build_object(
        'agent', jsonb_build_object('id', r.id, 'name', r.name, 'reported_at', r.reported_at,
          'expected_interval_seconds', r.interval_seconds, 'stale_after_seconds', v_stale),
        'offline_since', r.reported_at,
        'released_task_ids', to_jsonb(v_claims),
        'project', NULL, 'project_id', NULL, 'task_id', NULL, 'actor_id', NULL));

      v_text := r.name || ' stopped responding ' || pm.watchdog_ago(r.reported_at) || ' ago'
        || CASE cardinality(v_claims)
             WHEN 0 THEN '.'
             WHEN 1 THEN ', its claimed task went back to the queue.'
             ELSE ', its ' || cardinality(v_claims) || ' claimed tasks went back to the queue.'
           END;
      FOREACH v_person IN ARRAY v_people LOOP
        PERFORM pm.upsert_notification(v_person, r.name || ' stopped responding', v_text, '/agent/' || r.id, 'member', r.id::text);
      END LOOP;
      v_offline := v_offline + 1;
    END LOOP;

    FOR r IN
      SELECT w.subject_id AS id, w.since, w.notified_at, a.name, h.reported_at, h.expected_interval_seconds AS interval_seconds
      FROM pm.watchdog_marks w
      JOIN pm.team_members a ON a.id = w.subject_id
      JOIN pm.agent_health h ON h.member_id = w.subject_id
      WHERE w.kind = 'agent_offline'
        AND h.reported_at >= now() - make_interval(secs => pm.heartbeat_stale_after_seconds(h.expected_interval_seconds))
    LOOP
      DELETE FROM pm.watchdog_marks WHERE kind = 'agent_offline' AND subject_id = r.id;
      PERFORM pm.emit_webhook_event('agent.online', 'agent', r.id, '{}'::uuid[], ARRAY[r.id], jsonb_build_object(
        'agent', jsonb_build_object('id', r.id, 'name', r.name, 'reported_at', r.reported_at,
          'expected_interval_seconds', r.interval_seconds, 'stale_after_seconds', pm.heartbeat_stale_after_seconds(r.interval_seconds)),
        'offline_since', r.since,
        'project', NULL, 'project_id', NULL, 'task_id', NULL, 'actor_id', NULL));
      IF r.notified_at IS NOT NULL THEN
        FOREACH v_person IN ARRAY pm.agent_people_to_tell(r.id) LOOP
          PERFORM pm.upsert_notification(v_person, r.name || ' is back', r.name || ' is responding again.', '/agent/' || r.id, 'member', r.id::text);
        END LOOP;
      END IF;
      v_online := v_online + 1;
    END LOOP;

    -- An agent removed, or no longer reporting at all, has nothing to come back from.
    DELETE FROM pm.watchdog_marks w
    WHERE w.kind = 'agent_offline'
      AND NOT EXISTS (
        SELECT 1 FROM pm.team_members a JOIN pm.agent_health h ON h.member_id = a.id
        WHERE a.id = w.subject_id AND a.role = 'agent' AND coalesce(a.status, 'active') = 'active'
      );
  END IF;

  -- Open questions past their time: stored as expired (the same update a
  -- read makes), which sends question.expired and clears the asked bells.
  -- A run one of them held is running again, its clock restarted.
  UPDATE pm.questions SET status = 'expired'
  WHERE status = 'open' AND expires_at <= now();
  GET DIAGNOSTICS v_questions = ROW_COUNT;

  -- Runs with no update for two hours: stored as timed_out, which sends
  -- run.finished. The run ends at its last update. A run waiting on a
  -- person is skipped while a question naming it is open; waiting with
  -- none, it gets seven days.
  UPDATE pm.agent_runs run
  SET status = 'timed_out', finished_at = greatest(run.started_at, run.updated_at)
  WHERE (run.status = 'running' AND run.updated_at < now() - interval '2 hours')
     OR (run.status = 'waiting' AND run.updated_at < now() - interval '7 days'
         AND NOT pm.agent_run_has_open_question(run.id));
  GET DIAGNOSTICS v_runs = ROW_COUNT;

  -- Whoever asked hears once, however the expiry was stored, within a day.
  FOR r IN
    SELECT q.id, q.kind, q.question, q.asked_by, q.asked_to, q.project_id, q.task_id,
      asker.name AS asker_name, asker.role AS asker_role, coalesce(target.name, g.name) AS target_name
    FROM pm.questions q
    JOIN pm.team_members asker ON asker.id = q.asked_by
    LEFT JOIN pm.team_members target ON target.id = q.asked_to
    LEFT JOIN pm.groups g ON g.id = q.asked_to_group
    WHERE q.status = 'expired' AND q.deleted_at IS NULL AND q.expires_at > now() - interval '1 day'
      AND NOT EXISTS (SELECT 1 FROM pm.watchdog_marks w WHERE w.kind = 'question_expired' AND w.subject_id = q.id)
    ORDER BY q.expires_at
  LOOP
    INSERT INTO pm.watchdog_marks (kind, subject_id, notified_at) VALUES ('question_expired', r.id, now());
    IF r.asker_role = 'agent' THEN
      v_people := pm.agent_people_to_tell(r.asked_by);
      v_title := r.asker_name || '''s ';
      v_link := '/agent/' || r.asked_by;
    ELSE
      SELECT coalesce(array_agg(m.id), '{}') INTO v_people FROM pm.team_members m
      WHERE m.id = r.asked_by AND coalesce(m.status, 'active') = 'active';
      v_title := 'Your ';
      v_link := '/my-tasks';
    END IF;
    IF r.task_id IS NOT NULL AND r.project_id IS NOT NULL THEN
      v_link := '/projects/' || r.project_id || '?task=' || r.task_id;
    END IF;
    v_title := v_title || CASE WHEN r.kind = 'approval' THEN 'approval request to ' ELSE 'question to ' END
      || coalesce(nullif(btrim(r.target_name), ''), 'a teammate')
      || CASE WHEN r.kind = 'approval' THEN ' expired without a decision' ELSE ' expired without an answer' END;
    FOREACH v_person IN ARRAY v_people LOOP
      -- Whoever was asked already knows.
      CONTINUE WHEN v_person IS NOT DISTINCT FROM r.asked_to;
      PERFORM pm.upsert_notification(v_person, v_title, left(r.question, 500), v_link, 'question', r.id::text);
      v_told := v_told + 1;
    END LOOP;
  END LOOP;
  DELETE FROM pm.watchdog_marks WHERE kind = 'question_expired' AND since < now() - interval '2 days';

  -- Webhook endpoints that keep failing: 5 attempts in a row, or failing for
  -- a day. Told once; a success resets it (track_webhook_endpoint_health).
  IF pm.module_enabled('webhooks') THEN
    FOR r IN
      SELECT w.subject_id AS id, w.detail, e.name
      FROM pm.watchdog_marks w
      JOIN pm.webhook_endpoints e ON e.id = w.subject_id
      WHERE w.kind = 'webhook_failing' AND w.notified_at IS NULL AND e.is_active
        AND (w.failures >= 5 OR w.since <= now() - interval '24 hours')
    LOOP
      UPDATE pm.watchdog_marks SET notified_at = now(), updated_at = now()
      WHERE kind = 'webhook_failing' AND subject_id = r.id;
      FOR v_person IN
        SELECT m.id FROM pm.team_members m
        WHERE m.role <> 'agent' AND coalesce(m.status, 'active') = 'active'
          AND (m.role = 'owner' OR pm.member_has_permission(m.id, 'webhooks.manage', 'app'))
        ORDER BY m.id
      LOOP
        PERFORM pm.upsert_notification(v_person, 'Webhook ' || r.name || ' keeps failing',
          'Last error: ' || coalesce(r.detail ->> 'last_error', 'unknown'), '/settings/developers#webhooks', 'webhook', r.id::text);
      END LOOP;
      v_webhooks := v_webhooks + 1;
    END LOOP;
  END IF;
  DELETE FROM pm.watchdog_marks w
  WHERE w.kind = 'webhook_failing'
    AND NOT EXISTS (SELECT 1 FROM pm.webhook_endpoints e WHERE e.id = w.subject_id);

  RETURN jsonb_build_object(
    'agents_offline', v_offline,
    'agents_online', v_online,
    'runs_timed_out', v_runs,
    'questions_expired', v_questions,
    'askers_told', v_told,
    'webhooks_failing', v_webhooks
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.run_watchdog() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.run_watchdog() TO service_role;

-- ---------------------------------------------------------------------------
-- Webhook retries: an Owner may turn them off
-- ---------------------------------------------------------------------------
-- As before, plus: nothing is sent while an Owner has retries turned off.
CREATE OR REPLACE FUNCTION pm.webhook_retry_kick()
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  app_url text;
  secret text;
BEGIN
  IF EXISTS (SELECT 1 FROM pm.business_settings s WHERE s.webhook_retries_off) THEN
    RETURN NULL;
  END IF;
  -- An invoice delivery waits while Client invoicing is off; it is not due.
  IF NOT EXISTS (
    SELECT 1
    FROM pm.webhook_deliveries d
    JOIN pm.webhook_endpoints e ON e.id = d.endpoint_id
    JOIN pm.webhook_events ev ON ev.id = d.webhook_event_id
    WHERE e.is_active
      AND (ev.resource_type <> 'invoice' OR pm.module_enabled('billing'))
      AND (
        (d.status = 'pending' AND d.next_attempt_at <= now())
        OR (d.status = 'delivering' AND coalesce(d.lease_expires_at, '-infinity') <= now())
      )
  ) THEN
    RETURN NULL;
  END IF;

  SELECT decrypted_secret INTO app_url FROM vault.decrypted_secrets WHERE name = 'pm_webhook_scheduler_url';
  SELECT decrypted_secret INTO secret FROM vault.decrypted_secrets WHERE name = 'pm_webhook_scheduler_secret';
  IF app_url IS NULL OR secret IS NULL THEN
    RAISE NOTICE 'webhook_scheduler_url or webhook_scheduler_secret is missing from Vault; webhook retries wait for the next in-app dispatch';
    RETURN NULL;
  END IF;

  RETURN net.http_post(
    url := rtrim(app_url, '/') || '/api/internal/webhooks/scheduled',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || secret),
    body := '{"source":"pg_cron"}'::jsonb,
    timeout_milliseconds := 60000
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.webhook_retry_kick() FROM PUBLIC, anon, authenticated, service_role;

-- Turning retries on writes the scheduler secret twice: sealed in
-- pm.app_secrets for the app, and in Vault for pm.webhook_retry_kick. Both
-- writes happen here, in one transaction and one set-up at a time, so two
-- app servers turning retries on at once never leave the app and Vault with
-- different secrets (every kick would be refused). With p_replace false
-- (the app turning them on by itself) a secret saved first stands: nothing
-- changes and false comes back. pm.store_webhook_scheduler, made only where
-- Supabase Vault is, checks the address and the secret. Server only.
CREATE OR REPLACE FUNCTION pm.set_up_webhook_scheduler(p_url text, p_secret text, p_sealed text, p_member_id uuid DEFAULT NULL, p_replace boolean DEFAULT true)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('pm.set_up_webhook_scheduler'));
  IF NOT coalesce(p_replace, true) AND EXISTS (SELECT 1 FROM pm.app_secrets WHERE name = 'webhook_scheduler_secret') THEN
    RETURN false;
  END IF;
  INSERT INTO pm.app_secrets (name, value, updated_at, updated_by)
  VALUES ('webhook_scheduler_secret', p_sealed, now(), p_member_id)
  ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value, updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by;
  PERFORM pm.store_webhook_scheduler(p_url, p_secret);
  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION pm.set_up_webhook_scheduler(text, text, text, uuid, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.set_up_webhook_scheduler(text, text, text, uuid, boolean) TO service_role;

-- ---------------------------------------------------------------------------
-- Retention
-- ---------------------------------------------------------------------------
-- Runs are never deleted by hand; only the retention job removes old ones.
CREATE OR REPLACE FUNCTION pm.agent_runs_forbid_delete()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF coalesce(current_setting('pm.data_retention', true), '') = 'on' AND current_user NOT IN ('anon', 'authenticated') THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Rows in % are never permanently deleted. Move them to Trash instead.', TG_TABLE_NAME
    USING ERRCODE = 'P0001', HINT = 'Old runs go only through the retention job (agent_run_retention_days).';
END;
$$;

REVOKE ALL ON FUNCTION pm.agent_runs_forbid_delete() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.agent_runs;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.agent_runs_forbid_delete();

-- The lineage guard (pm.stamp_run_lineage, 20261125000100) keeps a run's
-- parent and root as they were made, with one exception: a link cleared
-- because the run it named is gone. Retention deleting an old parent or
-- root clears the link on its newer children (ON DELETE SET NULL); before,
-- the guard put the old id back, the foreign key failed and the whole
-- retention run rolled back.
CREATE OR REPLACE FUNCTION pm.stamp_run_lineage()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_parent record;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NOT (NEW.parent_run_id IS NULL AND OLD.parent_run_id IS NOT NULL
            AND NOT EXISTS (SELECT 1 FROM pm.agent_runs r WHERE r.id = OLD.parent_run_id)) THEN
      NEW.parent_run_id := OLD.parent_run_id;
    END IF;
    IF NOT (NEW.root_run_id IS NULL AND OLD.root_run_id IS NOT NULL
            AND NOT EXISTS (SELECT 1 FROM pm.agent_runs r WHERE r.id = OLD.root_run_id)) THEN
      NEW.root_run_id := OLD.root_run_id;
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.parent_run_id IS NULL THEN
    NEW.root_run_id := NULL;
    RETURN NEW;
  END IF;
  SELECT r.id, r.root_run_id, r.principal_id INTO v_parent FROM pm.agent_runs r WHERE r.id = NEW.parent_run_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'The parent run does not exist' USING ERRCODE = '23503';
  END IF;
  NEW.root_run_id := coalesce(v_parent.root_run_id, v_parent.id);
  IF NEW.principal_id IS NULL THEN
    NEW.principal_id := v_parent.principal_id;
  ELSIF NEW.principal_id IS DISTINCT FROM v_parent.principal_id THEN
    RAISE EXCEPTION 'new row for relation "agent_runs" violates check constraint "agent_runs_principal_carried"'
      USING ERRCODE = '23514', DETAIL = 'A child run acts for the same person as its parent.';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.stamp_run_lineage() FROM PUBLIC, anon, authenticated;

-- Daily. Up to 20 batches of 5,000 rows per kind per run, so a large
-- backlog is worked down over a few days without a long transaction. Answers
-- how many rows went (chat: how many texts were blanked).
CREATE OR REPLACE FUNCTION pm.apply_data_retention()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  batch constant integer := 5000;
  max_rounds constant integer := 20;
  s record;
  v_cutoff timestamptz;
  v_n integer;
  v_round integer;
  v_deliveries integer := 0;
  v_events integer := 0;
  v_health integer := 0;
  v_activities integer := 0;
  v_runs integer := 0;
  v_chat integer := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('pm.apply_data_retention')) THEN
    RETURN jsonb_build_object('skipped', true);
  END IF;
  SELECT webhook_retention_days, agent_health_history_days, agent_activity_retention_days,
    agent_run_retention_days, chat_retention_days
  INTO s FROM pm.business_settings LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true);
  END IF;

  -- Webhooks: finished deliveries, then events no delivery needs any more.
  IF s.webhook_retention_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.webhook_retention_days);
    v_round := 0;
    LOOP
      DELETE FROM pm.webhook_deliveries WHERE id IN (
        SELECT d.id FROM pm.webhook_deliveries d
        WHERE d.status IN ('succeeded', 'failed') AND d.created_at < v_cutoff
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_deliveries := v_deliveries + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
    v_round := 0;
    LOOP
      DELETE FROM pm.webhook_events WHERE id IN (
        SELECT ev.id FROM pm.webhook_events ev
        WHERE ev.created_at < v_cutoff
          AND NOT EXISTS (SELECT 1 FROM pm.webhook_deliveries d WHERE d.webhook_event_id = ev.id)
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_events := v_events + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
  END IF;

  -- Uptime history: the newest row per agent stays, so its state is known.
  IF s.agent_health_history_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.agent_health_history_days);
    v_round := 0;
    LOOP
      DELETE FROM pm.agent_health_history WHERE id IN (
        SELECT h.id FROM pm.agent_health_history h
        WHERE h.changed_at < v_cutoff
          AND EXISTS (SELECT 1 FROM pm.agent_health_history newer
                      WHERE newer.member_id = h.member_id AND newer.changed_at > h.changed_at)
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_health := v_health + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
  END IF;

  -- Agent events: billing events (what agent time was billed from) stay.
  IF s.agent_activity_retention_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.agent_activity_retention_days);
    v_round := 0;
    LOOP
      DELETE FROM pm.agent_activities WHERE id IN (
        SELECT a.id FROM pm.agent_activities a
        WHERE a.created_at < v_cutoff AND a.activity_type NOT LIKE 'billing.%'
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_activities := v_activities + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
  END IF;

  -- Finished runs, unless an unfinished run, an open delegation or a pending
  -- delivery still needs them.
  IF s.agent_run_retention_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.agent_run_retention_days);
    PERFORM set_config('pm.data_retention', 'on', true);
    v_round := 0;
    LOOP
      DELETE FROM pm.agent_runs WHERE id IN (
        SELECT r.id FROM pm.agent_runs r
        WHERE r.status <> 'running' AND r.finished_at < v_cutoff
          AND NOT EXISTS (SELECT 1 FROM pm.agent_runs c
                          WHERE (c.parent_run_id = r.id OR c.root_run_id = r.id) AND c.status IN ('running', 'waiting'))
          AND NOT EXISTS (SELECT 1 FROM pm.task_delegations dl JOIN pm.tasks t ON t.id = dl.task_id
                          WHERE dl.run_id = r.id AND t.status <> 'done' AND t.deleted_at IS NULL)
          AND NOT EXISTS (SELECT 1 FROM pm.webhook_events ev JOIN pm.webhook_deliveries d ON d.webhook_event_id = ev.id
                          WHERE ev.resource_type = 'run' AND ev.resource_id = r.id AND d.status IN ('pending', 'delivering'))
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_runs := v_runs + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
    PERFORM set_config('pm.data_retention', 'off', true);
  END IF;

  -- Chat text is blanked, the row stays: its dedupe key (a provider retry,
  -- the one on-hold notice) and its place in the thread still count. A
  -- message still waiting for its assistant, or for a delivery, keeps it.
  IF s.chat_retention_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.chat_retention_days);
    v_round := 0;
    LOOP
      UPDATE pm.chat_messages SET text = '' WHERE id IN (
        SELECT m.id FROM pm.chat_messages m
        WHERE m.text <> '' AND m.created_at < v_cutoff
          AND NOT (m.direction = 'inbound' AND m.status IN ('pending', 'notified'))
          AND NOT EXISTS (SELECT 1 FROM pm.webhook_events ev JOIN pm.webhook_deliveries d ON d.webhook_event_id = ev.id
                          WHERE ev.resource_type = 'chat_message' AND ev.resource_id = m.id AND d.status IN ('pending', 'delivering'))
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_chat := v_chat + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
  END IF;

  IF v_deliveries + v_events + v_health + v_activities + v_runs + v_chat > 0 THEN
    INSERT INTO pm.api_audit_log (method, endpoint, entity_type, request_body, status_code, via)
    VALUES ('DELETE', '/app/data/retention', 'business_settings', jsonb_build_object(
      'webhook_deliveries', v_deliveries, 'webhook_events', v_events, 'agent_health_history', v_health,
      'agent_activities', v_activities, 'agent_runs', v_runs, 'chat_texts', v_chat), 200, 'app');
  END IF;
  RETURN jsonb_build_object(
    'webhook_deliveries', v_deliveries,
    'webhook_events', v_events,
    'agent_health_history', v_health,
    'agent_activities', v_activities,
    'agent_runs', v_runs,
    'chat_texts', v_chat
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.apply_data_retention() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.apply_data_retention() TO service_role;

-- ---------------------------------------------------------------------------
-- Schedules. Skipped where pg_cron is unavailable (PGlite). Re-running
-- cron.schedule updates a job in place.
-- ---------------------------------------------------------------------------
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron') THEN
    RAISE NOTICE 'pg_cron is unavailable here; run SELECT pm.run_watchdog() every 5 minutes and SELECT pm.apply_data_retention() daily';
    RETURN;
  END IF;
  CREATE EXTENSION IF NOT EXISTS pg_cron;
  PERFORM cron.schedule('pm-agent-watchdog', '*/5 * * * *', $job$SELECT pm.run_watchdog();$job$);
  PERFORM cron.schedule('pm-retention', '47 3 * * *', $job$SELECT pm.apply_data_retention();$job$);
END;
$do$;

-- ============================================================
-- CHAT TARGETS (20261125001100_chat_targets.sql)
-- Two bots: the personal bot (DMs, each person's own assistant)
-- and the company bot (channels and DMs, company agents).
-- ============================================================
-- Two bots: the personal bot and the company bot, and chat names that no
-- longer say "assistant".
--
-- - chat_connections.kind: personal (DMs only, each person's message goes to
--   their own personal assistant, as before) or company (channels and DMs,
--   routed to company agents). Every connection made before is personal.
--   chat_connections.external_bot_id: the bot's own id with the provider
--   (Slack's bot user, Telegram's bot), so one bot is one connection and a
--   Slack mention of the bot is recognised. One connection per provider
--   workspace and kind (a personal app and a company app may share a Slack
--   workspace). Telegram connections made before take their bot id from
--   external_workspace_id, which already held it.
-- - pm.chat_connection_agents: the company agents a company connection
--   reaches, one of them the default (a DM to the bot, or a mention of the
--   bot in a channel with no mapping). Server only.
-- - pm.chat_channel_routes: a channel of a company connection mapped to one
--   of its agents, with listen 'mentions' (the default: only a mention is
--   recorded) or 'all' (every message is recorded as context for that
--   agent, never a request to answer). An agent removed from the connection
--   takes its channel mappings with it. Server only.
-- - chat_messages.is_request (false: context, recorded only so the agent
--   knows what was said; status context), is_direct (a one-to-one chat with
--   the bot; null for messages before) and route (how it reached its agent:
--   direct, mention, channel or default; null for personal ones).
-- - The chat.message webhook event: ids only, like assistant.message, for
--   personal and company messages alike. pm.emit_chat_message queues it to
--   the active endpoints subscribed to it that are filtered to exactly the
--   agent, or scoped to the assistant setup that made it. An endpoint lists
--   chat.message only when filtered to an agent or scoped to a setup
--   (pm.webhook_endpoints_assistant_guard); assistant.message keeps its own
--   rule. Service role only.
--
-- Additive and safe to run twice. The previous release's code never reads
-- the new columns or tables: its connections read as personal, its messages
-- as requests, and nothing it writes trips a new check.

-- ---------------------------------------------------------------------------
-- Connections: kind and the bot's own id
-- ---------------------------------------------------------------------------
ALTER TABLE pm.chat_connections
  ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'personal',
  ADD COLUMN IF NOT EXISTS external_bot_id text;

ALTER TABLE pm.chat_connections DROP CONSTRAINT IF EXISTS chat_connections_kind_check;
ALTER TABLE pm.chat_connections
  ADD CONSTRAINT chat_connections_kind_check CHECK (kind IN ('personal', 'company'));
ALTER TABLE pm.chat_connections DROP CONSTRAINT IF EXISTS chat_connections_bot_id_length;
ALTER TABLE pm.chat_connections
  ADD CONSTRAINT chat_connections_bot_id_length CHECK (external_bot_id IS NULL OR length(external_bot_id) <= 255);

COMMENT ON COLUMN pm.chat_connections.kind IS
  'personal: DMs only, each person''s message goes to their own personal assistant. company: channels and DMs, routed to the company agents in chat_connection_agents.';
COMMENT ON COLUMN pm.chat_connections.external_bot_id IS
  'The bot''s own id with the provider (Slack bot user, Telegram bot): one connection per bot, and how a Slack mention of the bot is recognised.';

-- Telegram's workspace id was always its bot's id.
UPDATE pm.chat_connections SET external_bot_id = external_workspace_id
WHERE provider = 'telegram' AND external_bot_id IS NULL AND external_workspace_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS chat_connections_provider_bot
  ON pm.chat_connections (provider, external_bot_id) WHERE external_bot_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS chat_connections_provider_workspace_kind
  ON pm.chat_connections (provider, external_workspace_id, kind) WHERE external_workspace_id IS NOT NULL;
DROP INDEX IF EXISTS pm.chat_connections_provider_workspace;

-- Discord joins Slack and Telegram (its relay posts to the same inbound route).
ALTER TABLE pm.chat_connections DROP CONSTRAINT IF EXISTS chat_connections_provider_check;
ALTER TABLE pm.chat_connections
  ADD CONSTRAINT chat_connections_provider_check CHECK (provider IN ('slack', 'telegram', 'discord', 'teams', 'custom'));

-- ---------------------------------------------------------------------------
-- The company agents a company connection reaches
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.chat_connection_agents (
  connection_id uuid NOT NULL REFERENCES pm.chat_connections(id) ON DELETE CASCADE,
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  is_default boolean NOT NULL DEFAULT false,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (connection_id, agent_id)
);

COMMENT ON TABLE pm.chat_connection_agents IS
  'The company agents a company chat connection reaches; is_default marks the one a DM, or a mention of the bot in an unmapped channel, goes to. Server only.';

CREATE UNIQUE INDEX IF NOT EXISTS chat_connection_agents_one_default
  ON pm.chat_connection_agents (connection_id) WHERE is_default;
CREATE INDEX IF NOT EXISTS idx_chat_connection_agents_agent
  ON pm.chat_connection_agents (agent_id);

ALTER TABLE pm.chat_connection_agents ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON pm.chat_connection_agents FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.chat_connection_agents TO service_role;

-- ---------------------------------------------------------------------------
-- Channel mappings
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.chat_channel_routes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  connection_id uuid NOT NULL,
  channel_id text NOT NULL,
  channel_name text,
  agent_id uuid NOT NULL,
  listen text NOT NULL DEFAULT 'mentions',
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- Only an agent the connection reaches; removing it removes its channels.
  CONSTRAINT chat_channel_routes_agent_fkey FOREIGN KEY (connection_id, agent_id)
    REFERENCES pm.chat_connection_agents (connection_id, agent_id) ON DELETE CASCADE
);

ALTER TABLE pm.chat_channel_routes DROP CONSTRAINT IF EXISTS chat_channel_routes_listen_check;
ALTER TABLE pm.chat_channel_routes
  ADD CONSTRAINT chat_channel_routes_listen_check CHECK (listen IN ('all', 'mentions'));
ALTER TABLE pm.chat_channel_routes DROP CONSTRAINT IF EXISTS chat_channel_routes_text_lengths;
ALTER TABLE pm.chat_channel_routes
  ADD CONSTRAINT chat_channel_routes_text_lengths CHECK (
    length(channel_id) BETWEEN 1 AND 255
    AND (channel_name IS NULL OR length(channel_name) <= 255)
  );

COMMENT ON TABLE pm.chat_channel_routes IS
  'A channel of a company chat connection mapped to one of its agents. listen mentions: only a mention is recorded (as a request). listen all: every message is recorded as context for the agent, never a request. Server only.';

CREATE UNIQUE INDEX IF NOT EXISTS chat_channel_routes_channel
  ON pm.chat_channel_routes (connection_id, channel_id);

DROP TRIGGER IF EXISTS set_chat_channel_routes_updated_at ON pm.chat_channel_routes;
CREATE TRIGGER set_chat_channel_routes_updated_at
  BEFORE UPDATE ON pm.chat_channel_routes
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

ALTER TABLE pm.chat_channel_routes ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON pm.chat_channel_routes FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.chat_channel_routes TO service_role;

-- ---------------------------------------------------------------------------
-- Messages: requests and context
-- ---------------------------------------------------------------------------
ALTER TABLE pm.chat_messages
  ADD COLUMN IF NOT EXISTS is_request boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS is_direct boolean,
  ADD COLUMN IF NOT EXISTS route text;

ALTER TABLE pm.chat_messages DROP CONSTRAINT IF EXISTS chat_messages_direction_status;
ALTER TABLE pm.chat_messages
  ADD CONSTRAINT chat_messages_direction_status CHECK (
    (direction = 'inbound' AND status IN ('pending', 'notified', 'replied', 'handled', 'unrouted', 'context'))
    OR (direction = 'outbound' AND status IN ('sent', 'failed'))
  );
ALTER TABLE pm.chat_messages DROP CONSTRAINT IF EXISTS chat_messages_context_check;
ALTER TABLE pm.chat_messages
  ADD CONSTRAINT chat_messages_context_check CHECK ((status = 'context') = (direction = 'inbound' AND NOT is_request));
ALTER TABLE pm.chat_messages DROP CONSTRAINT IF EXISTS chat_messages_route_check;
ALTER TABLE pm.chat_messages
  ADD CONSTRAINT chat_messages_route_check CHECK (route IS NULL OR route IN ('direct', 'mention', 'channel', 'default'));

COMMENT ON COLUMN pm.chat_messages.is_request IS
  'false: context (status context), a channel message recorded so its agent knows what was said; never a request to answer.';
COMMENT ON COLUMN pm.chat_messages.is_direct IS
  'Sent in a one-to-one chat with the bot (null: recorded before 20261125001100).';
COMMENT ON COLUMN pm.chat_messages.route IS
  'How a company message reached its agent: direct (a DM, to the default agent), mention (the agent named), channel (the channel mapping), default (the bot mentioned in an unmapped channel). Null for personal messages.';

-- One provider message is recorded once. Slack sends a channel mention of
-- the company bot twice (app_mention and message, each with its own event
-- id, so the dedupe key differs), and two deliveries can arrive at once.
-- Twins recorded before keep their rows and text: only the newer ones give
-- up the provider message id, so the oldest stays that message.
UPDATE pm.chat_messages m SET external_message_id = NULL
WHERE m.direction = 'inbound' AND m.external_message_id IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM pm.chat_messages o
    WHERE o.direction = 'inbound' AND o.connection_id = m.connection_id
      AND o.conversation_id = m.conversation_id AND o.external_message_id = m.external_message_id
      AND (o.created_at, o.id) < (m.created_at, m.id)
  );
CREATE UNIQUE INDEX IF NOT EXISTS chat_messages_inbound_external
  ON pm.chat_messages (connection_id, conversation_id, external_message_id)
  WHERE direction = 'inbound' AND external_message_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Webhook chat.message
-- ---------------------------------------------------------------------------
-- assistant.message: only an endpoint filtered to a personal agent, or
-- scoped to an assistant setup, as before. chat.message: only an endpoint
-- filtered to an agent (personal or company), or scoped to a setup. Chat is
-- private: no workspace-wide endpoint ever lists either.
CREATE OR REPLACE FUNCTION pm.webhook_endpoints_assistant_guard()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF NEW.assistant_setup_id IS NOT NULL AND auth.uid() IS NOT NULL AND coalesce(auth.role(), '') <> 'service_role' THEN
    IF TG_OP = 'INSERT' OR NEW.assistant_setup_id IS DISTINCT FROM OLD.assistant_setup_id THEN
      IF coalesce(pm.current_team_member_role(), '') <> 'owner' THEN
        RAISE EXCEPTION 'Only an Owner scopes an endpoint to an assistant setup' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  IF 'assistant.message' = ANY (NEW.events) AND NEW.assistant_setup_id IS NULL AND NOT EXISTS (
    SELECT 1 FROM pm.team_members a WHERE a.id = NEW.member_id AND a.role = 'agent' AND a.delegate_of IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'assistant.message goes only to an endpoint filtered to a personal agent (member_id) or scoped to an assistant setup (assistant_setup_id)' USING ERRCODE = '23514';
  END IF;
  IF 'chat.message' = ANY (NEW.events) AND NEW.assistant_setup_id IS NULL AND NOT EXISTS (
    SELECT 1 FROM pm.team_members a WHERE a.id = NEW.member_id AND a.role = 'agent'
  ) THEN
    RAISE EXCEPTION 'chat.message goes only to an endpoint filtered to an agent (member_id) or scoped to an assistant setup (assistant_setup_id)' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.webhook_endpoints_assistant_guard() FROM PUBLIC, anon, authenticated;

-- Queues one chat.message event (resource chat_message) to every active
-- endpoint subscribed to it whose member filter is exactly the agent, or
-- whose setup made the agent. Never to an endpoint with neither. Answers
-- whether any endpoint got it; nothing is written when none does.
CREATE OR REPLACE FUNCTION pm.emit_chat_message(p_message_id uuid, p_agent_id uuid, p_data jsonb)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_endpoints uuid[];
  v_seq bigint;
  v_public_id text;
  v_event_uuid uuid;
BEGIN
  SELECT array_agg(e.id ORDER BY e.id) INTO v_endpoints
  FROM pm.webhook_endpoints e
  WHERE e.is_active AND e.events @> ARRAY['chat.message']
    AND (e.member_id = p_agent_id OR (e.member_id IS NULL AND e.assistant_setup_id IS NOT NULL))
    AND pm.webhook_endpoint_matches(e, 'chat.message', '{}'::uuid[], ARRAY[p_agent_id]);
  IF v_endpoints IS NULL THEN
    RETURN false;
  END IF;

  v_seq := nextval('pm.webhook_event_seq');
  v_public_id := 'evt_' || replace(gen_random_uuid()::text, '-', '');

  INSERT INTO pm.webhook_events (event_id, sequence, event_type, resource_type, resource_id, payload)
  VALUES (
    v_public_id, v_seq, 'chat.message', 'chat_message', p_message_id,
    jsonb_build_object(
      'id', v_public_id,
      'type', 'chat.message',
      'sequence', v_seq,
      'created_at', now(),
      'data', coalesce(p_data, '{}'::jsonb) || jsonb_build_object('member_ids', jsonb_build_array(p_agent_id))
    )
  )
  RETURNING id INTO v_event_uuid;

  INSERT INTO pm.webhook_deliveries (webhook_event_id, endpoint_id)
  SELECT v_event_uuid, unnest(v_endpoints);
  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_chat_message(uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.emit_chat_message(uuid, uuid, jsonb) TO service_role;

-- ============================================================
-- EXTERNAL AGENTS (20261125001400_external_agents.sql)
-- The app as the control plane for agents that work in other systems (a
-- bookkeeper in an accounting app): pause and budget reach work done
-- outside, a person can be asked without a project, and the harness hears
-- about pauses and a spent budget.
--
-- - pm.agent_status(member): what an agent checks before each turn, in one
--   call: the workspace pause, its own pause, its limits and its spend this
--   budget period (pm.agent_limit_state, the shared spend rule). Server
--   only: GET /api/v1/agents/me/status reads it for the calling key.
-- - agent.paused and agent.resumed, once per change of whether an agent may
--   start work: its own pause (team_members.agent_paused_at) or the
--   workspace pause (business_settings.agents_paused_at). One event per
--   agent, filtered to it. An agent's own pause while the workspace is
--   paused changes nothing it can do, so it sends nothing; neither does the
--   workspace pause for an agent already paused on its own.
-- - budget.exceeded, once a budget period: when the period whose overrun
--   the owners are told about moves on (agent_limits.budget_alerted_period,
--   claimed once by the server), with the spend at that moment.
-- - questions.ask: an agent may ask a question or request an approval that
--   names no task or project, without tasks.read. Core (no module, so no
--   permission_modules row). Agents hold it on the API, so a key for an
--   agent can carry it. Admins and members hold it on the API too (Owners
--   hold every permission), as with approvals.decide: a key hands on only
--   scopes its own member holds, so whoever hires an agent can give its key
--   this scope and apply the External agent template. No key carries it
--   until someone adds it; people ask with tasks.read as before.
--
-- Additive and safe to run twice. The previous release's code never calls
-- pm.agent_status, and the new events go only to endpoints subscribed to
-- them, which that code cannot make.
-- ============================================================

INSERT INTO pm.role_permissions (role, permission_key, access_channel) VALUES
  ('admin', 'questions.ask', 'api'),
  ('member', 'questions.ask', 'api'),
  ('agent', 'questions.ask', 'api')
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- What an agent checks before each turn
-- ---------------------------------------------------------------------------
-- One call: the member's role, its own pause and the workspace pause (for
-- an agent; people are never paused), its limits and spend this budget
-- period (UTC), and when the period ends. Null for a member that does not
-- exist. Server only.
CREATE OR REPLACE FUNCTION pm.agent_status(p_member_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_role text;
  v_agent_paused timestamptz;
  v_workspace_paused timestamptz;
  v_state jsonb;
  v_period text;
BEGIN
  SELECT role, agent_paused_at INTO v_role, v_agent_paused FROM pm.team_members WHERE id = p_member_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF v_role IS DISTINCT FROM 'agent' THEN
    RETURN jsonb_build_object('agent', false, 'workspace_paused_at', NULL, 'agent_paused_at', NULL, 'state', NULL);
  END IF;
  SELECT s.agents_paused_at INTO v_workspace_paused FROM pm.business_settings s ORDER BY s.agents_paused_at NULLS LAST LIMIT 1;
  v_state := pm.agent_limit_state(p_member_id, true);
  v_period := coalesce(v_state->'limits'->>'budget_period', 'month');
  RETURN jsonb_build_object(
    'agent', true,
    'workspace_paused_at', v_workspace_paused,
    'agent_paused_at', v_agent_paused,
    'budget_period', v_period,
    'period_end', (date_trunc(v_period, now() AT TIME ZONE 'UTC') + ('1 ' || v_period)::interval) AT TIME ZONE 'UTC',
    'state', v_state);
END;
$$;

REVOKE ALL ON FUNCTION pm.agent_status(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_status(uuid) TO service_role;

-- ---------------------------------------------------------------------------
-- agent.paused and agent.resumed
-- ---------------------------------------------------------------------------
-- One event for one agent. reason names the switch: agent_paused (its own)
-- or agents_paused (the workspace); on agent.resumed, the one turned off.
CREATE OR REPLACE FUNCTION pm.emit_agent_pause_event(
  p_agent_id uuid,
  p_paused boolean,
  p_reason text,
  p_agent_paused_at timestamptz,
  p_workspace_paused_at timestamptz
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  PERFORM pm.emit_webhook_event(
    CASE WHEN p_paused THEN 'agent.paused' ELSE 'agent.resumed' END,
    'agent',
    p_agent_id,
    '{}'::uuid[],
    ARRAY[p_agent_id],
    jsonb_build_object(
      'agent', jsonb_build_object('id', p_agent_id, 'name', coalesce((SELECT a.name FROM pm.team_members a WHERE a.id = p_agent_id), '')),
      'paused', p_paused,
      'reason', p_reason,
      'agent_paused_at', p_agent_paused_at,
      'workspace_paused_at', p_workspace_paused_at,
      'project', NULL,
      'project_id', NULL,
      'task_id', NULL,
      'actor_id', pm.webhook_actor_id()
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_agent_pause_event(uuid, boolean, text, timestamptz, timestamptz) FROM PUBLIC, anon, authenticated;

-- An agent's own pause: sent only while the workspace is not paused (paused
-- there, the agent could not start work either way).
CREATE OR REPLACE FUNCTION pm.emit_agent_pause_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM 'agent' OR (OLD.agent_paused_at IS NULL) = (NEW.agent_paused_at IS NULL) THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['agent.paused', 'agent.resumed']
  ) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM pm.business_settings s WHERE s.agents_paused_at IS NOT NULL) THEN
    RETURN NULL;
  END IF;
  PERFORM pm.emit_agent_pause_event(NEW.id, NEW.agent_paused_at IS NOT NULL, 'agent_paused', NEW.agent_paused_at, NULL);
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_agent_pause_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_agent_pause_webhook ON pm.team_members;
CREATE TRIGGER emit_agent_pause_webhook
  AFTER UPDATE OF agent_paused_at ON pm.team_members
  FOR EACH ROW
  WHEN (OLD.agent_paused_at IS DISTINCT FROM NEW.agent_paused_at)
  EXECUTE FUNCTION pm.emit_agent_pause_webhook();

-- The workspace pause: one event for each active agent not paused on its own.
CREATE OR REPLACE FUNCTION pm.emit_workspace_pause_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  r record;
BEGIN
  IF (OLD.agents_paused_at IS NULL) = (NEW.agents_paused_at IS NULL) THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['agent.paused', 'agent.resumed']
  ) THEN
    RETURN NULL;
  END IF;
  FOR r IN
    SELECT a.id FROM pm.team_members a
    WHERE a.role = 'agent' AND coalesce(a.status, 'active') = 'active' AND a.agent_paused_at IS NULL
    ORDER BY a.id
  LOOP
    PERFORM pm.emit_agent_pause_event(r.id, NEW.agents_paused_at IS NOT NULL, 'agents_paused', NULL, NEW.agents_paused_at);
  END LOOP;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_workspace_pause_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_workspace_pause_webhook ON pm.business_settings;
CREATE TRIGGER emit_workspace_pause_webhook
  AFTER UPDATE OF agents_paused_at ON pm.business_settings
  FOR EACH ROW
  WHEN (OLD.agents_paused_at IS DISTINCT FROM NEW.agents_paused_at)
  EXECUTE FUNCTION pm.emit_workspace_pause_webhook();

-- ---------------------------------------------------------------------------
-- budget.exceeded
-- ---------------------------------------------------------------------------
-- The server claims a period once (compare and swap on
-- budget_alerted_period) when it first sees the budget spent: after usage,
-- at a refused run start, or when the agent reads its status. That claim
-- sends the event, with the spend at that moment.
CREATE OR REPLACE FUNCTION pm.emit_budget_exceeded_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_state jsonb;
BEGIN
  IF NEW.budget_alerted_period IS NULL OR NEW.budget_alerted_period IS NOT DISTINCT FROM OLD.budget_alerted_period THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['budget.exceeded']
  ) THEN
    RETURN NULL;
  END IF;
  v_state := pm.agent_limit_state(NEW.agent_id, true);
  PERFORM pm.emit_webhook_event(
    'budget.exceeded',
    'agent',
    NEW.agent_id,
    '{}'::uuid[],
    ARRAY[NEW.agent_id],
    jsonb_build_object(
      'agent', jsonb_build_object('id', NEW.agent_id, 'name', coalesce((SELECT a.name FROM pm.team_members a WHERE a.id = NEW.agent_id), '')),
      'budget', jsonb_build_object(
        'period', NEW.budget_period,
        'period_start', NEW.budget_alerted_period,
        'budget_usd', NEW.budget_usd,
        'budget_tokens', NEW.budget_tokens,
        'spent_usd', v_state->'spent_usd',
        'spent_tokens', v_state->'spent_tokens'
      ),
      'project', NULL,
      'project_id', NULL,
      'task_id', NULL,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_budget_exceeded_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_budget_exceeded_webhook ON pm.agent_limits;
CREATE TRIGGER emit_budget_exceeded_webhook
  AFTER UPDATE OF budget_alerted_period ON pm.agent_limits
  FOR EACH ROW
  WHEN (NEW.budget_alerted_period IS DISTINCT FROM OLD.budget_alerted_period)
  EXECUTE FUNCTION pm.emit_budget_exceeded_webhook();

-- ============================================================
-- DELEGATION CHAIN (20261125001600_delegation_chain.sql)
-- Delegation at any depth: a person asks their personal agent, it hands
-- the work to a company agent, which hands pieces to specialists, all in
-- one run tree for that person. Subtasks stay one level deep: a whole
-- task can be handed over instead.
--
-- - pm.task_delegations.mode: how the task was handed over. subtask (as
--   before: a new subtask made for the receiver) or assign (an existing
--   task, top-level or not, handed to the receiver as it is). Existing
--   rows are subtasks.
-- - pm.task_delegations.from_task_id: the task the delegating run worked
--   on (for a subtask, its parent), so a task records the run and the task
--   it came from. Still one row per task: handing a task on again replaces
--   its row, and the runs keep the whole chain.
-- - pm.guard_run_chain, before a child run is stored: it sits at most 8
--   hand-offs below its root (agent_runs_chain_depth), and never under a
--   chain that loops (agent_runs_no_cycle). Runs already stored are
--   untouched. pm.stamp_run_lineage (root and person) is unchanged.
--
-- Additive and safe to run twice. The previous release's code writes
-- delegations without the new columns (they read as a subtask with no
-- source task); a child run past the depth limit is refused, which that
-- code reports as a failed run check (422).
-- ============================================================

-- ---------------------------------------------------------------------------
-- How a task was handed over, and where from
-- ---------------------------------------------------------------------------
ALTER TABLE pm.task_delegations ADD COLUMN IF NOT EXISTS mode text NOT NULL DEFAULT 'subtask';
ALTER TABLE pm.task_delegations ADD COLUMN IF NOT EXISTS from_task_id uuid REFERENCES pm.tasks(id) ON DELETE SET NULL;

ALTER TABLE pm.task_delegations DROP CONSTRAINT IF EXISTS task_delegations_mode_check;
ALTER TABLE pm.task_delegations
  ADD CONSTRAINT task_delegations_mode_check CHECK (mode IN ('subtask', 'assign'));

CREATE INDEX IF NOT EXISTS idx_task_delegations_from_task ON pm.task_delegations (from_task_id) WHERE from_task_id IS NOT NULL;

-- A subtask delegated before came from its parent.
UPDATE pm.task_delegations dl
SET from_task_id = t.parent_task_id
FROM pm.tasks t
WHERE t.id = dl.task_id AND dl.mode = 'subtask' AND dl.from_task_id IS NULL AND t.parent_task_id IS NOT NULL;

COMMENT ON TABLE pm.task_delegations IS
  'A task an agent handed to another agent (delegate_task), and the run that handed it over: a new subtask (mode subtask) or the task itself (mode assign). One row per task, replaced when it is handed on again. Written by the server only.';
COMMENT ON COLUMN pm.task_delegations.mode IS
  'subtask: a subtask made for the receiver. assign: an existing task handed to the receiver as it is.';
COMMENT ON COLUMN pm.task_delegations.from_task_id IS
  'The task the delegating run worked on (a subtask''s parent); null when the run had none.';

-- ---------------------------------------------------------------------------
-- Run chains: at most 8 hand-offs deep, never a loop
-- ---------------------------------------------------------------------------
-- A child run's parent is fixed once written (pm.stamp_run_lineage), so
-- only a new child can deepen a chain: walking up from its parent finds
-- how far below the root it would sit, and any loop links written around
-- the guards left behind.
CREATE OR REPLACE FUNCTION pm.guard_run_chain()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_at uuid;
  v_depth integer := 1;
  v_seen uuid[];
BEGIN
  IF NEW.parent_run_id IS NULL THEN
    RETURN NEW;
  END IF;
  v_seen := ARRAY[NEW.id, NEW.parent_run_id];
  SELECT r.parent_run_id INTO v_at FROM pm.agent_runs r WHERE r.id = NEW.parent_run_id;
  WHILE v_at IS NOT NULL LOOP
    IF v_at = ANY (v_seen) THEN
      RAISE EXCEPTION 'new row for relation "agent_runs" violates check constraint "agent_runs_no_cycle"'
        USING ERRCODE = '23514', DETAIL = 'A run cannot be its own ancestor.';
    END IF;
    v_depth := v_depth + 1;
    IF v_depth > 8 THEN
      RAISE EXCEPTION 'new row for relation "agent_runs" violates check constraint "agent_runs_chain_depth"'
        USING ERRCODE = '23514', DETAIL = 'A chain of runs goes at most 8 hand-offs below its root.';
    END IF;
    v_seen := v_seen || v_at;
    SELECT r.parent_run_id INTO v_at FROM pm.agent_runs r WHERE r.id = v_at;
  END LOOP;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.guard_run_chain() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS guard_run_chain ON pm.agent_runs;
CREATE TRIGGER guard_run_chain BEFORE INSERT ON pm.agent_runs
  FOR EACH ROW WHEN (NEW.parent_run_id IS NOT NULL) EXECUTE FUNCTION pm.guard_run_chain();

-- ============================================================
-- CHAT OUTBOUND AND MEDIA (20261125001500_chat_outbound_media.sql)
-- ============================================================
-- Agents start chat conversations, and people send them files.
--
-- - chat_messages.initiated: an outbound message an agent started
--   (POST /api/v1/chat/messages: a digest, an alert, a daily report), not
--   an answer to one. A reply to it (in its thread, quoting it, or the next
--   message in that DM) goes back to the same agent, with route 'reply' on
--   a company connection and reply_to_id naming the started message.
-- - chat_messages.attachments: the files sent with an inbound message
--   (photos, voice notes, audio, video, documents), as a JSON array of
--   { kind, ref, name, mime_type, size, duration_seconds }. ref is the
--   provider's own way back to the file (a Telegram file_id, a Slack
--   files.slack.com address, a Discord CDN address); the app fetches the
--   bytes only when the agent asks, and never shows ref.
-- - pm.apply_chat_attachment_retention: chat retention
--   (business_settings.chat_retention_days) also forgets these file
--   references, daily, with the same exceptions as the text (a message
--   still waiting for its agent or for a delivery keeps them). The text
--   sweep only visits messages with text, and a file needs no text.
-- - Permission chat.notify (AI agents module): a company agent may DM a
--   member who did not ask (an unprompted alert). No role holds it by
--   default; an Owner grants it to the agent and its key both.
--
-- Additive and safe to run twice. The previous release's code never reads
-- the new columns, writes neither, and never writes route 'reply'.

-- ---------------------------------------------------------------------------
-- Messages: started by an agent, and files
-- ---------------------------------------------------------------------------
ALTER TABLE pm.chat_messages
  ADD COLUMN IF NOT EXISTS initiated boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS attachments jsonb;

ALTER TABLE pm.chat_messages DROP CONSTRAINT IF EXISTS chat_messages_initiated_check;
ALTER TABLE pm.chat_messages
  ADD CONSTRAINT chat_messages_initiated_check CHECK (NOT initiated OR direction = 'outbound');
ALTER TABLE pm.chat_messages DROP CONSTRAINT IF EXISTS chat_messages_attachments_check;
ALTER TABLE pm.chat_messages
  ADD CONSTRAINT chat_messages_attachments_check CHECK (
    attachments IS NULL OR (jsonb_typeof(attachments) = 'array' AND jsonb_array_length(attachments) BETWEEN 1 AND 20)
  );
ALTER TABLE pm.chat_messages DROP CONSTRAINT IF EXISTS chat_messages_route_check;
ALTER TABLE pm.chat_messages
  ADD CONSTRAINT chat_messages_route_check CHECK (route IS NULL OR route IN ('direct', 'mention', 'channel', 'default', 'reply'));

COMMENT ON COLUMN pm.chat_messages.initiated IS
  'An outbound message an agent started (POST /api/v1/chat/messages), not an answer. A reply to it goes back to that agent.';
COMMENT ON COLUMN pm.chat_messages.attachments IS
  'Files sent with an inbound message: [{ kind, ref, name, mime_type, size, duration_seconds }]. ref is the provider''s file id or address, never shown to an agent; the bytes are fetched through the app on request. Null when none.';
COMMENT ON COLUMN pm.chat_messages.route IS
  'How a company message reached its agent: direct (a DM, to the default agent), mention (the agent named), channel (the channel mapping), default (the bot mentioned in an unmapped channel), reply (an answer to a message the agent started). Null for personal messages.';

-- A reply finds the message it answers: the provider id of a started message.
CREATE INDEX IF NOT EXISTS idx_chat_messages_initiated
  ON pm.chat_messages (connection_id, conversation_id, external_message_id)
  WHERE direction = 'outbound' AND initiated AND external_message_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Permission
-- ---------------------------------------------------------------------------
INSERT INTO pm.permission_modules (permission_key, module_id) VALUES
  ('chat.notify', 'agents')
ON CONFLICT (permission_key) DO UPDATE SET module_id = EXCLUDED.module_id;

-- ---------------------------------------------------------------------------
-- Retention of file references
-- ---------------------------------------------------------------------------
-- Forgets the file references of chat messages older than the chat
-- retention, in batches (the rest the next day), never one still waiting
-- for its agent or for a webhook delivery. Answers how many were forgotten.
CREATE OR REPLACE FUNCTION pm.apply_chat_attachment_retention()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  batch constant integer := 5000;
  max_rounds constant integer := 20;
  v_days integer;
  v_cutoff timestamptz;
  v_n integer;
  v_round integer := 0;
  v_total integer := 0;
BEGIN
  SELECT chat_retention_days INTO v_days FROM pm.business_settings LIMIT 1;
  IF v_days IS NULL THEN
    RETURN 0;
  END IF;
  v_cutoff := now() - make_interval(days => v_days);
  LOOP
    UPDATE pm.chat_messages SET attachments = NULL WHERE id IN (
      SELECT m.id FROM pm.chat_messages m
      WHERE m.attachments IS NOT NULL AND m.created_at < v_cutoff
        AND NOT (m.direction = 'inbound' AND m.status IN ('pending', 'notified'))
        AND NOT EXISTS (SELECT 1 FROM pm.webhook_events ev JOIN pm.webhook_deliveries d ON d.webhook_event_id = ev.id
                        WHERE ev.resource_type = 'chat_message' AND ev.resource_id = m.id AND d.status IN ('pending', 'delivering'))
      LIMIT batch);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_total := v_total + v_n;
    v_round := v_round + 1;
    EXIT WHEN v_n < batch OR v_round >= max_rounds;
  END LOOP;
  RETURN v_total;
END;
$$;

REVOKE ALL ON FUNCTION pm.apply_chat_attachment_retention() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.apply_chat_attachment_retention() TO service_role;

-- Daily, beside pm-retention. Skipped where pg_cron is unavailable (PGlite).
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron') THEN
    RAISE NOTICE 'pg_cron is unavailable here; run SELECT pm.apply_chat_attachment_retention() daily';
    RETURN;
  END IF;
  CREATE EXTENSION IF NOT EXISTS pg_cron;
  PERFORM cron.schedule('pm-chat-attachment-retention', '52 3 * * *', $job$SELECT pm.apply_chat_attachment_retention();$job$);
END;
$do$;

-- ============================================================
-- INITIATIVES (20261126000100_initiatives.sql)
-- ============================================================
-- Initiatives: a named body of work inside a project, with a description,
-- an owner, a status and its own board and log, that people and agents both
-- use. A goal (pm.project_goals) is an outcome; an initiative is the work.
--
-- - pm.initiatives: one per body of work, in one project (fixed once made).
--   status planned | active | paused | done; health on_track | at_risk |
--   blocked while active (cleared otherwise). One owner at most: a member or
--   a group (a deactivated member or a group in Trash reads as no owner).
--   Dates are calendar dates. In Trash (deleted_at) it reads as missing;
--   rows are never removed. Written by the server only.
-- - pm.initiative_entries: the initiative's log, the dated record: kind
--   update | decision | issue | note, a title and body, an optional task in
--   the same project, and for an issue a status (open | resolved, with who
--   resolved it and when). project_id is copied from the initiative.
--   Written by the server only.
-- - pm.tasks.initiative_id: a task belongs to at most one initiative, in its
--   own project. Subtasks always take their parent's (those in Trash too);
--   moving a task to another project clears it, unless the move names an
--   initiative there. A task whose initiative is in Trash keeps the link and
--   reads as having none; restoring the initiative brings it back.
-- - pm.initiative_progress: done and total top-level tasks per initiative
--   (subtasks excluded), one grouped count. Server only.
-- - Context scope 'initiative': an initiative's brief is project_context
--   rows with scope_type 'initiative' and scope_id the initiative, read and
--   written through the server as every scope beyond projects.
-- - Who may: whoever can open the project reads its initiatives; entries
--   also need tasks.read (the right to comment on a task) and are never a
--   guest's. Creating and changing an initiative needs tasks.create in the
--   project; Trash needs projects.manage or being its creator. No new
--   permission.
-- - Team activity, Trash and restore, live sync, and webhooks
--   initiative.created, initiative.updated, initiative.deleted,
--   initiative_entry.created and initiative_entry.updated (opt in).
--   task.* payloads gain initiative_id.
--
-- Additive and safe to run twice. The previous release's code never reads or
-- writes the new tables; its task writes keep working (a project move clears
-- the new column on its own).

-- ---------------------------------------------------------------------------
-- Initiatives
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.initiatives (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES pm.projects(id),
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  owner_member_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  owner_group_id uuid REFERENCES pm.groups(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'planned',
  health text,
  start_date date,
  target_date date,
  sort_order integer NOT NULL DEFAULT 0,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  -- The person the agent that made it acted for (X-Act-For); null otherwise.
  principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- Trash: when it was deleted and by whom (null = live). Rows are never removed.
  deleted_at timestamptz,
  deleted_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL
);

ALTER TABLE pm.initiatives DROP CONSTRAINT IF EXISTS initiatives_name_length;
ALTER TABLE pm.initiatives
  ADD CONSTRAINT initiatives_name_length CHECK (length(btrim(name)) BETWEEN 1 AND 120);
ALTER TABLE pm.initiatives DROP CONSTRAINT IF EXISTS initiatives_description_length;
ALTER TABLE pm.initiatives
  ADD CONSTRAINT initiatives_description_length CHECK (length(description) <= 5000);
ALTER TABLE pm.initiatives DROP CONSTRAINT IF EXISTS initiatives_status_check;
ALTER TABLE pm.initiatives
  ADD CONSTRAINT initiatives_status_check CHECK (status IN ('planned', 'active', 'paused', 'done'));
ALTER TABLE pm.initiatives DROP CONSTRAINT IF EXISTS initiatives_health_check;
ALTER TABLE pm.initiatives
  ADD CONSTRAINT initiatives_health_check CHECK (
    health IS NULL OR (status = 'active' AND health IN ('on_track', 'at_risk', 'blocked')));
ALTER TABLE pm.initiatives DROP CONSTRAINT IF EXISTS initiatives_one_owner;
ALTER TABLE pm.initiatives
  ADD CONSTRAINT initiatives_one_owner CHECK (num_nonnulls(owner_member_id, owner_group_id) <= 1);
ALTER TABLE pm.initiatives DROP CONSTRAINT IF EXISTS initiatives_dates_order;
ALTER TABLE pm.initiatives
  ADD CONSTRAINT initiatives_dates_order CHECK (start_date IS NULL OR target_date IS NULL OR target_date >= start_date);

COMMENT ON TABLE pm.initiatives IS
  'Initiatives: a named body of work inside a project, with its own board and log. A goal is an outcome; an initiative is the work. Written by the server only.';
COMMENT ON COLUMN pm.initiatives.description IS
  'What the initiative is for, in the owner''s words (the screens may label it Goal).';
COMMENT ON COLUMN pm.initiatives.health IS
  'on_track, at_risk or blocked while the initiative is active; null otherwise.';
COMMENT ON COLUMN pm.initiatives.principal_id IS
  'The person the agent that created it acted for (X-Act-For); null otherwise.';

-- A project's initiatives in order; Trash.
CREATE INDEX IF NOT EXISTS idx_initiatives_project ON pm.initiatives (project_id, sort_order, created_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_initiatives_deleted_at ON pm.initiatives (deleted_at DESC) WHERE deleted_at IS NOT NULL;

-- The name is trimmed; the project, who made it and when never change; health
-- belongs to an active initiative only.
CREATE OR REPLACE FUNCTION pm.handle_initiative_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  NEW.name := btrim(NEW.name);
  IF TG_OP = 'UPDATE' THEN
    NEW.project_id := OLD.project_id;
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
  END IF;
  IF NEW.status <> 'active' THEN
    NEW.health := NULL;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_initiative_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS initiatives_before_write ON pm.initiatives;
CREATE TRIGGER initiatives_before_write
  BEFORE INSERT OR UPDATE ON pm.initiatives
  FOR EACH ROW EXECUTE FUNCTION pm.handle_initiative_before_write();

DROP TRIGGER IF EXISTS set_initiatives_updated_at ON pm.initiatives;
CREATE TRIGGER set_initiatives_updated_at
  BEFORE UPDATE ON pm.initiatives
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

DROP TRIGGER IF EXISTS stamp_principal ON pm.initiatives;
CREATE TRIGGER stamp_principal BEFORE INSERT OR UPDATE OF principal_id ON pm.initiatives
  FOR EACH ROW EXECUTE FUNCTION pm.stamp_principal();

-- Never permanently deleted.
DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.initiatives;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.initiatives
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.initiatives;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.initiatives
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

ALTER TABLE pm.initiatives ENABLE ROW LEVEL SECURITY;

-- Whoever can open the project reads its initiatives (guests included).
DROP POLICY IF EXISTS initiatives_select ON pm.initiatives;
CREATE POLICY initiatives_select ON pm.initiatives FOR SELECT TO authenticated
  USING (pm.can_access_project(initiatives.project_id));

DROP POLICY IF EXISTS initiatives_not_deleted ON pm.initiatives;
CREATE POLICY initiatives_not_deleted ON pm.initiatives AS RESTRICTIVE FOR ALL TO authenticated
  USING (deleted_at IS NULL) WITH CHECK (deleted_at IS NULL);

REVOKE ALL ON pm.initiatives FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.initiatives TO authenticated;
GRANT ALL ON pm.initiatives TO service_role;

-- ---------------------------------------------------------------------------
-- The log: dated entries on an initiative
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.initiative_entries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  initiative_id uuid NOT NULL REFERENCES pm.initiatives(id),
  -- The initiative's project, copied on insert (row security reads it).
  project_id uuid NOT NULL REFERENCES pm.projects(id),
  kind text NOT NULL,
  title text NOT NULL,
  body text NOT NULL DEFAULT '',
  -- A task in the same project the entry is about.
  task_id uuid REFERENCES pm.tasks(id) ON DELETE SET NULL,
  -- Issues only: open or resolved.
  status text,
  resolved_at timestamptz,
  resolved_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  deleted_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL
);

ALTER TABLE pm.initiative_entries DROP CONSTRAINT IF EXISTS initiative_entries_kind_check;
ALTER TABLE pm.initiative_entries
  ADD CONSTRAINT initiative_entries_kind_check CHECK (kind IN ('update', 'decision', 'issue', 'note'));
ALTER TABLE pm.initiative_entries DROP CONSTRAINT IF EXISTS initiative_entries_status_check;
ALTER TABLE pm.initiative_entries
  ADD CONSTRAINT initiative_entries_status_check CHECK (
    CASE WHEN kind = 'issue' THEN status IN ('open', 'resolved') ELSE status IS NULL END);
ALTER TABLE pm.initiative_entries DROP CONSTRAINT IF EXISTS initiative_entries_title_length;
ALTER TABLE pm.initiative_entries
  ADD CONSTRAINT initiative_entries_title_length CHECK (length(btrim(title)) BETWEEN 1 AND 200);
ALTER TABLE pm.initiative_entries DROP CONSTRAINT IF EXISTS initiative_entries_body_length;
ALTER TABLE pm.initiative_entries
  ADD CONSTRAINT initiative_entries_body_length CHECK (length(body) <= 20000);

COMMENT ON TABLE pm.initiative_entries IS
  'An initiative''s log, the dated record: updates, decisions, issues (open or resolved) and notes. Standing knowledge belongs in its brief (project_context, scope initiative). Written by the server only.';
COMMENT ON COLUMN pm.initiative_entries.status IS
  'Issues only: open or resolved. Null for every other kind.';

-- An initiative's log, newest first; its open issues; Trash.
CREATE INDEX IF NOT EXISTS idx_initiative_entries_initiative ON pm.initiative_entries (initiative_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_initiative_entries_open_issues ON pm.initiative_entries (initiative_id, created_at DESC)
  WHERE deleted_at IS NULL AND kind = 'issue' AND status = 'open';
CREATE INDEX IF NOT EXISTS idx_initiative_entries_deleted_at ON pm.initiative_entries (deleted_at DESC) WHERE deleted_at IS NOT NULL;

-- The project comes from the initiative; the initiative, kind, author and
-- time never change; an issue starts open and its resolution is stamped; a
-- task must be in the same project.
CREATE OR REPLACE FUNCTION pm.handle_initiative_entry_before_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_task_project uuid;
BEGIN
  NEW.title := btrim(NEW.title);
  IF TG_OP = 'INSERT' THEN
    SELECT project_id INTO NEW.project_id FROM pm.initiatives WHERE id = NEW.initiative_id;
    IF NEW.kind = 'issue' THEN
      NEW.status := coalesce(NEW.status, 'open');
    ELSE
      NEW.status := NULL;
    END IF;
  ELSE
    NEW.initiative_id := OLD.initiative_id;
    NEW.project_id := OLD.project_id;
    NEW.kind := OLD.kind;
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
  END IF;
  IF NEW.kind <> 'issue' OR NEW.status = 'open' THEN
    NEW.resolved_at := NULL;
    NEW.resolved_by := NULL;
  ELSIF NEW.status = 'resolved' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'resolved') THEN
    NEW.resolved_at := now();
  ELSIF TG_OP = 'UPDATE' THEN
    NEW.resolved_at := OLD.resolved_at;
    NEW.resolved_by := OLD.resolved_by;
  END IF;
  IF NEW.task_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.task_id IS DISTINCT FROM OLD.task_id) THEN
    SELECT project_id INTO v_task_project FROM pm.tasks WHERE id = NEW.task_id AND deleted_at IS NULL;
    IF v_task_project IS DISTINCT FROM NEW.project_id THEN
      RAISE EXCEPTION 'A log entry''s task must be a live task in the initiative''s project.' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_initiative_entry_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS initiative_entries_before_write ON pm.initiative_entries;
CREATE TRIGGER initiative_entries_before_write
  BEFORE INSERT OR UPDATE ON pm.initiative_entries
  FOR EACH ROW EXECUTE FUNCTION pm.handle_initiative_entry_before_write();

DROP TRIGGER IF EXISTS set_initiative_entries_updated_at ON pm.initiative_entries;
CREATE TRIGGER set_initiative_entries_updated_at
  BEFORE UPDATE ON pm.initiative_entries
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

DROP TRIGGER IF EXISTS stamp_principal ON pm.initiative_entries;
CREATE TRIGGER stamp_principal BEFORE INSERT OR UPDATE OF principal_id ON pm.initiative_entries
  FOR EACH ROW EXECUTE FUNCTION pm.stamp_principal();

DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.initiative_entries;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.initiative_entries
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.initiative_entries;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.initiative_entries
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

ALTER TABLE pm.initiative_entries ENABLE ROW LEVEL SECURITY;

-- Project members who may comment on its tasks read the log while the
-- initiative is live; never a guest.
DROP POLICY IF EXISTS initiative_entries_select ON pm.initiative_entries;
CREATE POLICY initiative_entries_select ON pm.initiative_entries FOR SELECT TO authenticated
  USING (
    pm.can_access_project(initiative_entries.project_id)
    AND pm.has_permission('tasks.read')
    AND coalesce(pm.current_team_member_role(), '') <> 'guest'
    AND EXISTS (
      SELECT 1 FROM pm.initiatives i
      WHERE i.id = initiative_entries.initiative_id AND i.deleted_at IS NULL
    )
  );

DROP POLICY IF EXISTS initiative_entries_not_deleted ON pm.initiative_entries;
CREATE POLICY initiative_entries_not_deleted ON pm.initiative_entries AS RESTRICTIVE FOR ALL TO authenticated
  USING (deleted_at IS NULL) WITH CHECK (deleted_at IS NULL);

REVOKE ALL ON pm.initiative_entries FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.initiative_entries TO authenticated;
GRANT ALL ON pm.initiative_entries TO service_role;

-- ---------------------------------------------------------------------------
-- Tasks in an initiative
-- ---------------------------------------------------------------------------
ALTER TABLE pm.tasks ADD COLUMN IF NOT EXISTS initiative_id uuid REFERENCES pm.initiatives(id) ON DELETE SET NULL;

COMMENT ON COLUMN pm.tasks.initiative_id IS
  'The initiative the task belongs to, in its own project; a subtask always has its parent''s. Cleared when the task moves to another project.';

CREATE INDEX IF NOT EXISTS idx_tasks_initiative ON pm.tasks (initiative_id)
  WHERE initiative_id IS NOT NULL AND deleted_at IS NULL;

-- A subtask takes its parent's initiative. A move to another project clears
-- it unless the same write names an initiative there. A newly named
-- initiative must be live and in the task's project.
CREATE OR REPLACE FUNCTION pm.enforce_task_initiative()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_initiative pm.initiatives;
BEGIN
  IF NEW.parent_task_id IS NOT NULL THEN
    SELECT initiative_id INTO NEW.initiative_id FROM pm.tasks WHERE id = NEW.parent_task_id;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.project_id IS DISTINCT FROM OLD.project_id
     AND NEW.initiative_id IS NOT DISTINCT FROM OLD.initiative_id THEN
    NEW.initiative_id := NULL;
  END IF;
  IF NEW.initiative_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.initiative_id IS DISTINCT FROM OLD.initiative_id) THEN
    SELECT * INTO v_initiative FROM pm.initiatives WHERE id = NEW.initiative_id;
    IF v_initiative.id IS NULL OR v_initiative.deleted_at IS NOT NULL THEN
      RAISE EXCEPTION 'That initiative is not there or is in Trash.' USING ERRCODE = '23514';
    END IF;
    IF v_initiative.project_id IS DISTINCT FROM NEW.project_id THEN
      RAISE EXCEPTION 'A task''s initiative must be in the task''s own project.' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.enforce_task_initiative() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS enforce_task_initiative ON pm.tasks;
CREATE TRIGGER enforce_task_initiative
  BEFORE INSERT OR UPDATE OF initiative_id, parent_task_id, project_id ON pm.tasks
  FOR EACH ROW EXECUTE FUNCTION pm.enforce_task_initiative();

-- A parent's subtasks follow its initiative, those in Trash too (as they
-- follow it to another project), so a restore lands them beside it.
CREATE OR REPLACE FUNCTION pm.subtasks_follow_initiative()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  UPDATE pm.tasks
  SET initiative_id = NEW.initiative_id
  WHERE parent_task_id = NEW.id AND initiative_id IS DISTINCT FROM NEW.initiative_id;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.subtasks_follow_initiative() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS subtasks_follow_initiative ON pm.tasks;
CREATE TRIGGER subtasks_follow_initiative
  AFTER UPDATE ON pm.tasks
  FOR EACH ROW WHEN (NEW.initiative_id IS DISTINCT FROM OLD.initiative_id AND NEW.parent_task_id IS NULL)
  EXECUTE FUNCTION pm.subtasks_follow_initiative();

-- Done and total top-level tasks per initiative (subtasks excluded): one
-- grouped count for an overview. Server only: it counts every task, so the
-- server narrows it to what the reader may see.
CREATE OR REPLACE VIEW pm.initiative_progress WITH (security_invoker = true) AS
  SELECT
    initiative_id,
    count(*)::integer AS total,
    (count(*) FILTER (WHERE status = 'done'))::integer AS done
  FROM pm.tasks
  WHERE initiative_id IS NOT NULL AND parent_task_id IS NULL AND deleted_at IS NULL
  GROUP BY initiative_id;

REVOKE ALL ON pm.initiative_progress FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.initiative_progress TO service_role;

-- Open issues and the newest entry per initiative's log, for an overview in
-- one query. Server only.
CREATE OR REPLACE VIEW pm.initiative_log_stats WITH (security_invoker = true) AS
  SELECT
    initiative_id,
    (count(*) FILTER (WHERE kind = 'issue' AND status = 'open'))::integer AS open_issues,
    max(created_at) AS last_entry_at
  FROM pm.initiative_entries
  WHERE deleted_at IS NULL
  GROUP BY initiative_id;

REVOKE ALL ON pm.initiative_log_stats FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.initiative_log_stats TO service_role;

-- ---------------------------------------------------------------------------
-- The brief: context scope 'initiative'
-- ---------------------------------------------------------------------------
ALTER TABLE pm.project_context DROP CONSTRAINT IF EXISTS project_context_scope_type_check;
ALTER TABLE pm.project_context
  ADD CONSTRAINT project_context_scope_type_check CHECK (scope_type IN ('workspace', 'group', 'project', 'agent', 'member', 'initiative'));

COMMENT ON COLUMN pm.project_context.scope_type IS
  'Where the entry belongs: workspace (every member), group (its members), project (as always), agent (that agent and who manages it), member (one person''s memory: them and their own agent only) or initiative (its brief, for whoever reads the project''s context).';

-- ---------------------------------------------------------------------------
-- Team activity
-- ---------------------------------------------------------------------------
ALTER TABLE pm.activities DROP CONSTRAINT IF EXISTS activities_entity_type_check;
ALTER TABLE pm.activities ADD CONSTRAINT activities_entity_type_check CHECK (entity_type IN (
  'task', 'subtask', 'comment', 'project', 'member', 'time_entry', 'invoice', 'payment', 'file',
  'portal_update', 'portal_update_attachment', 'credential', 'reminder', 'contact', 'lead',
  'lead_interaction', 'lead_proposal', 'lead_field', 'communication', 'hourly_rate', 'retainer',
  'retainer_amount', 'initiative', 'initiative_entry'
));

CREATE OR REPLACE FUNCTION pm.log_initiative_activity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_meta jsonb := jsonb_build_object('initiative_id', NEW.id, 'initiative_name', NEW.name);
  v_fields text[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM pm.log_team_activity('initiative.created', 'initiative', NEW.id::text, NEW.project_id,
      format('Created initiative "%s"', NEW.name), v_meta);
    RETURN NULL;
  END IF;
  -- The Trash trigger logs moves to Trash and restores.
  IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    RETURN NULL;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM pm.log_team_activity('initiative.status', 'initiative', NEW.id::text, NEW.project_id,
      format('Set initiative "%s" to %s', NEW.name, CASE NEW.status
        WHEN 'planned' THEN 'Planned' WHEN 'active' THEN 'Active' WHEN 'paused' THEN 'Paused' ELSE 'Done' END),
      v_meta || jsonb_build_object('from', OLD.status, 'to', NEW.status));
  END IF;
  v_fields := pm.activity_changed_fields(to_jsonb(NEW), to_jsonb(OLD),
    ARRAY['status', 'sort_order', 'created_at', 'updated_at', 'deleted_at', 'deleted_by']);
  IF cardinality(v_fields) > 0 THEN
    PERFORM pm.log_team_activity('initiative.updated', 'initiative', NEW.id::text, NEW.project_id,
      format('Edited initiative "%s"', NEW.name), v_meta || jsonb_build_object('fields', to_jsonb(v_fields)));
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.log_initiative_activity() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS log_initiative_activity ON pm.initiatives;
CREATE TRIGGER log_initiative_activity AFTER INSERT OR UPDATE ON pm.initiatives
  FOR EACH ROW EXECUTE FUNCTION pm.log_initiative_activity();

-- A log entry added, and an issue resolved or reopened.
CREATE OR REPLACE FUNCTION pm.log_initiative_entry_activity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_name text;
  v_meta jsonb;
BEGIN
  SELECT name INTO v_name FROM pm.initiatives WHERE id = NEW.initiative_id;
  v_meta := jsonb_build_object('initiative_id', NEW.initiative_id, 'initiative_name', v_name,
    'kind', NEW.kind, 'title', NEW.title, 'task_id', NEW.task_id);
  IF TG_OP = 'INSERT' THEN
    PERFORM pm.log_team_activity('initiative_entry.added', 'initiative_entry', NEW.id::text, NEW.project_id,
      format('Logged %s "%s" on "%s"', CASE NEW.kind
        WHEN 'update' THEN 'an update' WHEN 'decision' THEN 'a decision' WHEN 'issue' THEN 'an issue' ELSE 'a note' END,
        NEW.title, v_name), v_meta);
    RETURN NULL;
  END IF;
  IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    RETURN NULL;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM pm.log_team_activity(
      CASE WHEN NEW.status = 'resolved' THEN 'initiative_entry.resolved' ELSE 'initiative_entry.reopened' END,
      'initiative_entry', NEW.id::text, NEW.project_id,
      format('%s issue "%s" on "%s"', CASE WHEN NEW.status = 'resolved' THEN 'Resolved' ELSE 'Reopened' END, NEW.title, v_name),
      v_meta);
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.log_initiative_entry_activity() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS log_initiative_entry_activity ON pm.initiative_entries;
CREATE TRIGGER log_initiative_entry_activity AFTER INSERT OR UPDATE ON pm.initiative_entries
  FOR EACH ROW EXECUTE FUNCTION pm.log_initiative_entry_activity();

-- The log's activity reads like the log: never a guest's.
CREATE OR REPLACE FUNCTION pm.can_read_activity(
  p_entity_type text,
  p_entity_id text,
  p_project_id uuid,
  p_actor uuid,
  p_metadata jsonb
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT CASE
    WHEN p_project_id IS NOT NULL AND NOT pm.project_is_live(p_project_id) THEN false
    WHEN p_actor = pm.current_team_member_id() THEN true
    WHEN p_entity_type = 'reminder' AND p_project_id IS NULL THEN false
    WHEN pm.has_permission('audit.read') THEN true
    WHEN p_project_id IS NULL THEN CASE
      WHEN p_entity_type = 'contact' THEN pm.has_permission('contacts.read_all')
      WHEN p_metadata ? 'lead_id' THEN pm.can_access_lead((p_metadata ->> 'lead_id')::uuid)
      ELSE false
    END
    WHEN NOT (pm.has_permission('projects.read_all')
      OR (pm.has_permission('projects.read') AND pm.can_access_project(p_project_id))) THEN false
    ELSE CASE
      WHEN p_entity_type IN ('task', 'subtask', 'comment') THEN
        pm.has_permission('tasks.read')
        OR coalesce(pm.can_access_task((p_metadata ->> 'task_id')::uuid), false)
      WHEN p_entity_type = 'time_entry' THEN pm.has_permission('time.read_all')
      WHEN p_entity_type IN ('invoice', 'payment', 'hourly_rate', 'retainer', 'retainer_amount') THEN pm.has_permission('invoices.read')
      WHEN p_entity_type = 'credential' THEN pm.has_permission('credentials.manage')
      WHEN p_entity_type = 'file' THEN pm.has_permission('files.read')
      WHEN p_entity_type IN ('portal_update', 'portal_update_attachment') THEN pm.has_permission('portal.read')
      WHEN p_entity_type = 'communication' THEN pm.has_permission('communications.read')
      WHEN p_entity_type = 'contact' THEN pm.has_permission('contacts.read') OR pm.has_permission('contacts.read_all')
      WHEN p_entity_type = 'initiative_entry' THEN
        pm.has_permission('tasks.read') AND coalesce(pm.current_team_member_role(), '') <> 'guest'
      ELSE true
    END
  END
$$;

CREATE OR REPLACE FUNCTION pm.activity_entity_noun(p_entity_type text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE p_entity_type
    WHEN 'time_entry' THEN 'time entry'
    WHEN 'portal_update' THEN 'portal update'
    WHEN 'portal_update_attachment' THEN 'portal attachment'
    WHEN 'lead_interaction' THEN 'lead interaction'
    WHEN 'lead_proposal' THEN 'proposal'
    WHEN 'lead_field' THEN 'lead field'
    WHEN 'hourly_rate' THEN 'hourly rate'
    WHEN 'retainer_amount' THEN 'retainer amount'
    WHEN 'initiative_entry' THEN 'log entry'
    ELSE p_entity_type
  END
$$;

-- A subtask's initiative follows its parent: the parent's change already says so.
CREATE OR REPLACE FUNCTION pm.log_task_activity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_meta jsonb := jsonb_build_object('task_id', NEW.id, 'task_title', NEW.title);
  v_fields text[];
  v_ignore text[] := ARRAY['status', 'sort_order', 'completed_at', 'created_at', 'updated_at', 'deleted_at', 'deleted_by', 'parent_task_id',
    'claimed_by', 'claimed_at', 'claim_expires_at', 'claim_assigned', 'occurrences', 'last_occurred_at'];
  v_parent record;
BEGIN
  IF NEW.parent_task_id IS NOT NULL THEN
    SELECT id, title INTO v_parent FROM pm.tasks WHERE id = NEW.parent_task_id;
    v_meta := v_meta || jsonb_build_object('parent_task_id', v_parent.id, 'parent_task_title', v_parent.title);
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.parent_task_id IS NOT NULL THEN
      PERFORM pm.log_team_activity('subtask.added', 'task', NEW.id::text, NEW.project_id,
        format('Added subtask "%s" to "%s"', NEW.title, v_parent.title), v_meta);
    ELSE
      PERFORM pm.log_team_activity('task.created', 'task', NEW.id::text, NEW.project_id,
        format('Created task "%s"', NEW.title), v_meta);
    END IF;
    RETURN NULL;
  END IF;
  -- The Trash trigger logs moves to Trash and restores.
  IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    RETURN NULL;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'done' THEN
      PERFORM pm.log_team_activity('task.completed', 'task', NEW.id::text, NEW.project_id,
        format('Completed task "%s"', NEW.title), v_meta);
    ELSIF OLD.status = 'done' THEN
      PERFORM pm.log_team_activity('task.reopened', 'task', NEW.id::text, NEW.project_id,
        format('Reopened task "%s"', NEW.title), v_meta);
    ELSE
      PERFORM pm.log_team_activity('task.moved', 'task', NEW.id::text, NEW.project_id,
        format('Moved task "%s" to %s', NEW.title, pm.activity_status_label(NEW.status)),
        v_meta || jsonb_build_object('from', OLD.status, 'to', NEW.status));
    END IF;
  END IF;

  IF NEW.parent_task_id IS DISTINCT FROM OLD.parent_task_id THEN
    IF NEW.parent_task_id IS NOT NULL THEN
      PERFORM pm.log_team_activity('task.nested', 'task', NEW.id::text, NEW.project_id,
        format('Moved "%s" under "%s"', NEW.title, v_parent.title), v_meta);
    ELSE
      PERFORM pm.log_team_activity('task.promoted', 'task', NEW.id::text, NEW.project_id,
        format('Made "%s" a top-level task', NEW.title), v_meta || jsonb_build_object('from_parent_task_id', OLD.parent_task_id));
    END IF;
  END IF;

  -- A subtask's project follows its parent: the parent's move (or the
  -- nesting above) already says so.
  IF NEW.parent_task_id IS NOT NULL THEN
    v_ignore := v_ignore || ARRAY['project_id', 'project_goal_id', 'initiative_id'];
  END IF;
  v_fields := pm.activity_changed_fields(to_jsonb(NEW), to_jsonb(OLD), v_ignore);
  IF cardinality(v_fields) > 0 THEN
    PERFORM pm.log_team_activity('task.updated', 'task', NEW.id::text, NEW.project_id,
      format('Edited task "%s"', NEW.title), v_meta || jsonb_build_object('fields', to_jsonb(v_fields)));
  END IF;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION pm.record_task_row_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_ignore text[] := ARRAY['sort_order', 'completed_at', 'created_at', 'updated_at', 'deleted_at', 'deleted_by',
    'created_via', 'created_by_key_id', 'created_note',
    'claimed_by', 'claimed_at', 'claim_expires_at', 'claim_assigned', 'occurrences', 'last_occurred_at'];
BEGIN
  IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    RETURN NULL;
  END IF;
  -- A subtask moving with its parent is the parent's change, not its own.
  IF NEW.parent_task_id IS NOT NULL AND NEW.parent_task_id IS NOT DISTINCT FROM OLD.parent_task_id THEN
    v_ignore := v_ignore || ARRAY['project_id', 'project_goal_id', 'initiative_id'];
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM pm.record_task_event(NEW.id, 'status');
  ELSIF cardinality(pm.activity_changed_fields(to_jsonb(NEW), to_jsonb(OLD), v_ignore)) > 0 THEN
    PERFORM pm.record_task_event(NEW.id, 'edit');
  END IF;
  RETURN NULL;
END;
$$;

-- ---------------------------------------------------------------------------
-- Webhooks
-- ---------------------------------------------------------------------------
-- task.* payloads carry the task's initiative_id.
CREATE OR REPLACE FUNCTION pm.webhook_task_data(p_task pm.tasks)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT jsonb_build_object(
    'task', jsonb_build_object(
      'id', p_task.id,
      'project_id', p_task.project_id,
      'parent_task_id', p_task.parent_task_id,
      'initiative_id', p_task.initiative_id,
      'title', p_task.title,
      'description', p_task.description,
      'status', p_task.status,
      'priority', p_task.priority,
      'due_date', p_task.due_date,
      'tags', to_jsonb(p_task.tags),
      'ai_readiness', p_task.ai_readiness,
      'assignee_ids', coalesce((
        SELECT jsonb_agg(a.member_id ORDER BY a.member_id) FROM pm.task_assignees a WHERE a.task_id = p_task.id
      ), '[]'::jsonb),
      'claimed_by', CASE WHEN p_task.claim_expires_at IS NULL OR p_task.claim_expires_at > now() THEN p_task.claimed_by END,
      'claim_expires_at', CASE WHEN p_task.claimed_by IS NOT NULL AND p_task.claim_expires_at > now() THEN p_task.claim_expires_at END,
      'created_by', p_task.created_by,
      'created_via', p_task.created_via,
      'source_task_suggestion_id', p_task.source_task_suggestion_id,
      'completed_at', p_task.completed_at,
      'created_at', p_task.created_at,
      'updated_at', p_task.updated_at,
      'deleted_at', p_task.deleted_at
    ),
    'project', jsonb_build_object('id', p_task.project_id, 'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = p_task.project_id), '')),
    'project_id', p_task.project_id,
    'task_id', p_task.id,
    'actor_id', pm.webhook_actor_id()
  )
$$;

-- An initiative as an event carries it: the row as it is now.
CREATE OR REPLACE FUNCTION pm.webhook_initiative_data(p_initiative pm.initiatives)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT jsonb_build_object(
    'initiative', jsonb_build_object(
      'id', p_initiative.id,
      'project_id', p_initiative.project_id,
      'name', p_initiative.name,
      'description', p_initiative.description,
      'owner_member_id', p_initiative.owner_member_id,
      'owner_group_id', p_initiative.owner_group_id,
      'status', p_initiative.status,
      'health', p_initiative.health,
      'start_date', p_initiative.start_date,
      'target_date', p_initiative.target_date,
      'created_by', p_initiative.created_by,
      'created_at', p_initiative.created_at,
      'updated_at', p_initiative.updated_at,
      'deleted_at', p_initiative.deleted_at
    ),
    'project', jsonb_build_object('id', p_initiative.project_id, 'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = p_initiative.project_id), '')),
    'project_id', p_initiative.project_id,
    'initiative_id', p_initiative.id,
    'actor_id', pm.webhook_actor_id()
  )
$$;

REVOKE ALL ON FUNCTION pm.webhook_initiative_data(pm.initiatives) FROM PUBLIC, anon, authenticated;

-- Who an initiative's events concern: its owner (a member, or the members of
-- its owner group) and whoever made it.
CREATE OR REPLACE FUNCTION pm.initiative_webhook_members(p_initiative pm.initiatives, p_also uuid[] DEFAULT '{}')
RETURNS uuid[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT coalesce(array_agg(DISTINCT m ORDER BY m) FILTER (WHERE m IS NOT NULL), '{}')
  FROM (
    SELECT p_initiative.owner_member_id AS m
    UNION ALL SELECT p_initiative.created_by
    UNION ALL SELECT gm.member_id FROM pm.group_members gm WHERE gm.group_id = p_initiative.owner_group_id
    UNION ALL SELECT unnest(coalesce(p_also, '{}'))
  ) members
$$;

REVOKE ALL ON FUNCTION pm.initiative_webhook_members(pm.initiatives, uuid[]) FROM PUBLIC, anon, authenticated;

-- initiative.created (made, or restored from Trash), initiative.updated with
-- the changed fields, initiative.deleted (moved to Trash). Reordering sends
-- nothing. One look at webhook_endpoints when nobody subscribes.
CREATE OR REPLACE FUNCTION pm.emit_initiative_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
  v_changes text[] := '{}';
  v_data jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['initiative.created', 'initiative.updated', 'initiative.deleted']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.deleted_at IS NOT NULL THEN
      RETURN NULL;
    END IF;
    v_type := 'initiative.created';
  ELSIF NEW.deleted_at IS NOT NULL THEN
    IF OLD.deleted_at IS NOT NULL THEN
      RETURN NULL;
    END IF;
    v_type := 'initiative.deleted';
  ELSIF OLD.deleted_at IS NOT NULL THEN
    v_type := 'initiative.created';
  ELSE
    IF NEW.name IS DISTINCT FROM OLD.name THEN v_changes := v_changes || 'name'::text; END IF;
    IF NEW.description IS DISTINCT FROM OLD.description THEN v_changes := v_changes || 'description'::text; END IF;
    IF NEW.owner_member_id IS DISTINCT FROM OLD.owner_member_id THEN v_changes := v_changes || 'owner_member_id'::text; END IF;
    IF NEW.owner_group_id IS DISTINCT FROM OLD.owner_group_id THEN v_changes := v_changes || 'owner_group_id'::text; END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN v_changes := v_changes || 'status'::text; END IF;
    IF NEW.health IS DISTINCT FROM OLD.health THEN v_changes := v_changes || 'health'::text; END IF;
    IF NEW.start_date IS DISTINCT FROM OLD.start_date THEN v_changes := v_changes || 'start_date'::text; END IF;
    IF NEW.target_date IS DISTINCT FROM OLD.target_date THEN v_changes := v_changes || 'target_date'::text; END IF;
    IF cardinality(v_changes) = 0 THEN
      RETURN NULL;
    END IF;
    v_type := 'initiative.updated';
  END IF;

  v_data := pm.webhook_initiative_data(NEW);
  IF v_type = 'initiative.updated' THEN
    v_data := v_data || jsonb_build_object('changes', to_jsonb(v_changes));
  END IF;
  PERFORM pm.emit_webhook_event(
    v_type,
    'initiative',
    NEW.id,
    ARRAY[NEW.project_id],
    pm.initiative_webhook_members(NEW, CASE WHEN TG_OP = 'UPDATE' THEN ARRAY[OLD.owner_member_id] ELSE '{}'::uuid[] END),
    v_data,
    CASE WHEN v_type = 'initiative.updated' THEN ARRAY['initiative.updated', 'initiative.created'] END
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_initiative_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_initiative_webhook ON pm.initiatives;
CREATE TRIGGER emit_initiative_webhook
  AFTER INSERT OR UPDATE ON pm.initiatives
  FOR EACH ROW EXECUTE FUNCTION pm.emit_initiative_webhook();

-- initiative_entry.created when an entry is logged; initiative_entry.updated
-- (with the changed fields) when it is edited or an issue is resolved or
-- reopened. Concerns its author and the initiative's owner.
CREATE OR REPLACE FUNCTION pm.emit_initiative_entry_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
  v_changes text[] := '{}';
  v_initiative pm.initiatives;
  v_data jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['initiative_entry.created', 'initiative_entry.updated']
  ) THEN
    RETURN NULL;
  END IF;
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'INSERT' THEN
    v_type := 'initiative_entry.created';
  ELSE
    IF OLD.deleted_at IS NOT NULL THEN
      RETURN NULL;
    END IF;
    IF NEW.title IS DISTINCT FROM OLD.title THEN v_changes := v_changes || 'title'::text; END IF;
    IF NEW.body IS DISTINCT FROM OLD.body THEN v_changes := v_changes || 'body'::text; END IF;
    IF NEW.task_id IS DISTINCT FROM OLD.task_id THEN v_changes := v_changes || 'task_id'::text; END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN v_changes := v_changes || 'status'::text; END IF;
    IF cardinality(v_changes) = 0 THEN
      RETURN NULL;
    END IF;
    v_type := 'initiative_entry.updated';
  END IF;

  SELECT * INTO v_initiative FROM pm.initiatives WHERE id = NEW.initiative_id;
  v_data := jsonb_build_object(
    'entry', jsonb_build_object(
      'id', NEW.id,
      'initiative_id', NEW.initiative_id,
      'project_id', NEW.project_id,
      'kind', NEW.kind,
      'title', NEW.title,
      'body', NEW.body,
      'task_id', NEW.task_id,
      'status', NEW.status,
      'resolved_at', NEW.resolved_at,
      'resolved_by', NEW.resolved_by,
      'created_by', NEW.created_by,
      'created_at', NEW.created_at,
      'updated_at', NEW.updated_at
    ),
    'initiative', jsonb_build_object('id', v_initiative.id, 'name', v_initiative.name),
    'project', jsonb_build_object('id', NEW.project_id, 'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')),
    'project_id', NEW.project_id,
    'initiative_id', NEW.initiative_id,
    'actor_id', pm.webhook_actor_id()
  );
  IF v_type = 'initiative_entry.updated' THEN
    v_data := v_data || jsonb_build_object('changes', to_jsonb(v_changes));
  END IF;
  PERFORM pm.emit_webhook_event(
    v_type,
    'initiative_entry',
    NEW.id,
    ARRAY[NEW.project_id],
    (SELECT coalesce(array_agg(DISTINCT m ORDER BY m) FILTER (WHERE m IS NOT NULL), '{}')
       FROM unnest(ARRAY[NEW.created_by, NEW.resolved_by, v_initiative.owner_member_id]) AS m),
    v_data,
    CASE WHEN v_type = 'initiative_entry.updated' THEN ARRAY['initiative_entry.updated', 'initiative_entry.created'] END
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_initiative_entry_webhook() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS emit_initiative_entry_webhook ON pm.initiative_entries;
CREATE TRIGGER emit_initiative_entry_webhook
  AFTER INSERT OR UPDATE ON pm.initiative_entries
  FOR EACH ROW EXECUTE FUNCTION pm.emit_initiative_entry_webhook();

-- ---------------------------------------------------------------------------
-- Live sync: open screens see initiatives and their logs change.
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables
                   WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'initiatives') THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE pm.initiatives;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables
                   WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'initiative_entries') THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE pm.initiative_entries;
    END IF;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Trash: initiatives and log entries join Settings > Trash
-- ---------------------------------------------------------------------------
-- Moved to Trash through soft_delete_record, listed by list_trash, restored
-- by restore_record: whoever can open the project and manages projects, or
-- made it (an entry: its author, or whoever manages projects). An initiative
-- comes back only after its project, an entry only after its initiative.
-- Trash never touches tasks: they keep initiative_id and read as having
-- none until it is restored.
CREATE OR REPLACE FUNCTION pm.trash_record_types()
RETURNS text[]
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT ARRAY[
    'projects', 'tasks', 'task_comments', 'reminders', 'project_credentials',
    'entity_files', 'portal_updates', 'portal_update_attachments', 'contacts', 'leads',
    'lead_interactions', 'lead_proposals', 'lead_fields',
    'project_time_entries', 'project_invoices', 'invoice_payments', 'project_hourly_rates',
    'project_retainers', 'project_retainer_amounts', 'task_files', 'task_templates',
    'initiatives', 'initiative_entries'
  ]
$$;

CREATE OR REPLACE FUNCTION pm.can_trash_record(p_table text, p_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  me uuid := pm.current_team_member_id();
  allowed boolean := false;
BEGIN
  IF me IS NULL THEN
    RETURN false;
  END IF;
  CASE p_table
    WHEN 'projects' THEN
      SELECT pm.has_permission('projects.manage') AND (
        pm.has_permission('projects.read_all')
        OR EXISTS (SELECT 1 FROM pm.project_members WHERE project_id = p_id AND member_id = me)
      ) INTO allowed;
    WHEN 'tasks' THEN
      -- A subtask can also go by whoever manages its parent as an assignee.
      SELECT pm.can_access_project(project_id) AND (
        pm.has_permission('tasks.manage_all') OR (
          parent_task_id IS NOT NULL AND pm.has_permission('tasks.manage_assigned') AND EXISTS (
            SELECT 1 FROM pm.task_assignees assignment
            WHERE assignment.task_id = tasks.parent_task_id AND assignment.member_id = me
          )
        )
      ) INTO allowed FROM pm.tasks WHERE id = p_id;
    WHEN 'task_comments' THEN
      SELECT pm.can_access_task(task_id) AND (user_id = me OR pm.has_permission('tasks.manage_all'))
      INTO allowed FROM pm.task_comments WHERE id = p_id;
    WHEN 'task_files' THEN
      SELECT pm.can_access_task(task_id) AND (added_by = me OR pm.has_permission('files.manage'))
      INTO allowed FROM pm.task_files WHERE id = p_id;
    WHEN 'reminders' THEN
      SELECT pm.can_see_reminder(owner_id, project_id, task_id)
        AND (owner_id = me OR created_by = me OR pm.has_permission('tasks.manage_all'))
      INTO allowed FROM pm.reminders WHERE id = p_id;
    WHEN 'project_credentials' THEN
      SELECT pm.has_permission('credentials.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_credentials WHERE id = p_id;
    WHEN 'entity_files' THEN
      SELECT pm.can_access_file_entity(entity_type, entity_id) AND (
        pm.has_permission('files.manage') OR (uploaded_by = me AND visibility = 'internal')
      ) INTO allowed FROM pm.entity_files WHERE id = p_id;
    WHEN 'portal_updates' THEN
      SELECT pm.has_permission('portal.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.portal_updates WHERE id = p_id;
    WHEN 'portal_update_attachments' THEN
      SELECT pm.has_permission('portal.manage') AND pm.can_access_project(update_row.project_id)
      INTO allowed
      FROM pm.portal_update_attachments attachment
      JOIN pm.portal_updates update_row ON update_row.id = attachment.update_id
      WHERE attachment.id = p_id AND update_row.deleted_at IS NULL;
    WHEN 'contacts' THEN
      SELECT pm.has_permission('contacts.manage') INTO allowed;
    WHEN 'leads' THEN
      SELECT pm.has_permission('leads.manage') INTO allowed;
    WHEN 'lead_interactions' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_interactions WHERE id = p_id;
    WHEN 'lead_proposals' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_proposals WHERE id = p_id;
    WHEN 'lead_fields' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_fields WHERE id = p_id;
    WHEN 'project_time_entries' THEN
      SELECT pm.can_access_project(project_id) AND (
        pm.has_permission('time.manage_all') OR (
          pm.has_permission('time.manage_own')
          AND member_id = me
          AND approval_status IN ('draft', 'pending', 'rejected')
        )
      ) INTO allowed FROM pm.project_time_entries WHERE id = p_id;
    WHEN 'project_invoices' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_invoices WHERE id = p_id;
    WHEN 'invoice_payments' THEN
      -- People remove only payments recorded by hand, as remove_invoice_payment.
      SELECT (pm.has_permission('invoices.record_payments') OR pm.has_permission('invoices.manage'))
        AND pm.can_access_project(invoice.project_id)
        AND invoice.deleted_at IS NULL
        AND payment.recorded_via = 'app'
      INTO allowed
      FROM pm.invoice_payments payment
      JOIN pm.project_invoices invoice ON invoice.id = payment.invoice_id
      WHERE payment.id = p_id;
    WHEN 'project_hourly_rates' THEN
      SELECT pm.has_permission('billing.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_hourly_rates WHERE id = p_id;
    WHEN 'project_retainers' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_retainers WHERE id = p_id;
    WHEN 'project_retainer_amounts' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(retainer.project_id)
        AND retainer.deleted_at IS NULL
      INTO allowed
      FROM pm.project_retainer_amounts amount
      JOIN pm.project_retainers retainer ON retainer.id = amount.retainer_id
      WHERE amount.id = p_id;
    WHEN 'task_templates' THEN
      -- The library is managed with templates.manage; a locked template also needs its project.
      SELECT pm.has_permission('templates.manage')
        AND (task_templates.project_id IS NULL OR pm.can_access_project(task_templates.project_id))
      INTO allowed FROM pm.task_templates WHERE id = p_id;
    WHEN 'initiatives' THEN
      -- Whoever manages projects, or whoever made it, on a project they can open.
      SELECT pm.can_access_project(project_id) AND (pm.has_permission('projects.manage') OR created_by = me)
      INTO allowed FROM pm.initiatives WHERE id = p_id;
    WHEN 'initiative_entries' THEN
      -- Its author, or whoever manages projects, while they may read the log.
      SELECT pm.can_access_project(project_id) AND pm.has_permission('tasks.read')
        AND coalesce(pm.current_team_member_role(), '') <> 'guest'
        AND (created_by = me OR pm.has_permission('projects.manage'))
      INTO allowed FROM pm.initiative_entries WHERE id = p_id;
    ELSE
      allowed := false;
  END CASE;
  RETURN coalesce(allowed, false);
END;
$$;

CREATE OR REPLACE FUNCTION pm.trash_restore_blocker(p_table text, p_id uuid)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  project_gone boolean := false;
  task_gone boolean := false;
  lead_gone boolean := false;
  parent_gone boolean := false;
  payment pm.invoice_payments;
  invoice pm.project_invoices;
  v_number text;
BEGIN
  CASE p_table
    WHEN 'tasks' THEN
      -- A subtask comes back after its parent.
      SELECT p.deleted_at IS NOT NULL, coalesce(parent.deleted_at IS NOT NULL, false) INTO project_gone, task_gone
      FROM pm.tasks t JOIN pm.projects p ON p.id = t.project_id
      LEFT JOIN pm.tasks parent ON parent.id = t.parent_task_id
      WHERE t.id = p_id;
    WHEN 'task_comments', 'task_files' THEN
      EXECUTE format('SELECT t.deleted_at IS NOT NULL OR coalesce(parent.deleted_at IS NOT NULL, false), p.deleted_at IS NOT NULL
        FROM pm.%I c JOIN pm.tasks t ON t.id = c.task_id JOIN pm.projects p ON p.id = t.project_id
        LEFT JOIN pm.tasks parent ON parent.id = t.parent_task_id
        WHERE c.id = $1', p_table)
      INTO task_gone, project_gone USING p_id;
    WHEN 'reminders' THEN
      SELECT coalesce(t.deleted_at IS NOT NULL OR parent.deleted_at IS NOT NULL, false), coalesce(p.deleted_at IS NOT NULL, false)
      INTO task_gone, project_gone
      FROM pm.reminders r
      LEFT JOIN pm.tasks t ON t.id = r.task_id
      LEFT JOIN pm.tasks parent ON parent.id = t.parent_task_id
      LEFT JOIN pm.projects p ON p.id = r.project_id
      WHERE r.id = p_id;
    WHEN 'project_credentials', 'portal_updates', 'project_time_entries', 'project_invoices',
         'project_hourly_rates', 'project_retainers', 'task_templates', 'initiatives' THEN
      EXECUTE format('SELECT p.deleted_at IS NOT NULL FROM pm.%I c
        JOIN pm.projects p ON p.id = c.project_id WHERE c.id = $1', p_table)
      INTO project_gone USING p_id;
    WHEN 'portal_update_attachments' THEN
      SELECT u.deleted_at IS NOT NULL INTO parent_gone
      FROM pm.portal_update_attachments a JOIN pm.portal_updates u ON u.id = a.update_id WHERE a.id = p_id;
      IF parent_gone THEN
        RETURN 'Restore the portal update it belongs to first.';
      END IF;
    WHEN 'invoice_payments' THEN
      SELECT p.deleted_at IS NOT NULL, i.deleted_at IS NOT NULL INTO project_gone, parent_gone
      FROM pm.invoice_payments pay
      JOIN pm.project_invoices i ON i.id = pay.invoice_id
      JOIN pm.projects p ON p.id = i.project_id
      WHERE pay.id = p_id;
      IF parent_gone AND NOT project_gone THEN
        RETURN 'Restore the invoice it belongs to first.';
      END IF;
    WHEN 'project_retainer_amounts' THEN
      SELECT p.deleted_at IS NOT NULL, r.deleted_at IS NOT NULL INTO project_gone, parent_gone
      FROM pm.project_retainer_amounts a
      JOIN pm.project_retainers r ON r.id = a.retainer_id
      JOIN pm.projects p ON p.id = r.project_id
      WHERE a.id = p_id;
      IF parent_gone AND NOT project_gone THEN
        RETURN 'Restore the retainer it belongs to first.';
      END IF;
    WHEN 'initiative_entries' THEN
      SELECT p.deleted_at IS NOT NULL, i.deleted_at IS NOT NULL INTO project_gone, parent_gone
      FROM pm.initiative_entries e
      JOIN pm.initiatives i ON i.id = e.initiative_id
      JOIN pm.projects p ON p.id = e.project_id
      WHERE e.id = p_id;
      IF parent_gone AND NOT project_gone THEN
        RETURN 'Restore the initiative it belongs to first.';
      END IF;
    WHEN 'entity_files' THEN
      SELECT CASE f.entity_type
          WHEN 'project' THEN EXISTS (SELECT 1 FROM pm.projects WHERE id = f.entity_id AND deleted_at IS NOT NULL)
          WHEN 'lead' THEN EXISTS (SELECT 1 FROM pm.leads WHERE id = f.entity_id AND deleted_at IS NOT NULL)
          WHEN 'contact' THEN EXISTS (SELECT 1 FROM pm.contacts WHERE id = f.entity_id AND deleted_at IS NOT NULL)
          ELSE false
        END
      INTO parent_gone
      FROM pm.entity_files f WHERE f.id = p_id;
      IF parent_gone THEN
        RETURN 'Restore the project, lead or contact this file belongs to first.';
      END IF;
    WHEN 'lead_interactions', 'lead_proposals', 'lead_fields' THEN
      EXECUTE format('SELECT l.deleted_at IS NOT NULL FROM pm.%I c
        JOIN pm.leads l ON l.id = c.lead_id WHERE c.id = $1', p_table)
      INTO lead_gone USING p_id;
    ELSE
      NULL;
  END CASE;
  IF coalesce(project_gone, false) THEN
    RETURN 'Restore the project it belongs to first.';
  ELSIF coalesce(task_gone, false) THEN
    RETURN 'Restore the task it belongs to first.';
  ELSIF coalesce(lead_gone, false) THEN
    RETURN 'Restore the lead it belongs to first.';
  END IF;

  -- Clashes with what was added while it was in Trash.
  CASE p_table
    WHEN 'project_time_entries' THEN
      IF EXISTS (
        SELECT 1 FROM pm.project_time_entries entry
        JOIN pm.project_time_entries other
          ON other.project_id = entry.project_id AND other.member_id = entry.member_id AND other.id <> entry.id
        WHERE entry.id = p_id AND entry.end_time IS NULL
          AND other.end_time IS NULL AND other.deleted_at IS NULL
      ) THEN
        RETURN 'This timer is still running and a newer one is running on the same project. Stop that one first.';
      END IF;
    WHEN 'project_invoices' THEN
      SELECT * INTO invoice FROM pm.project_invoices WHERE id = p_id;
      IF invoice.status <> 'cancelled' THEN
        SELECT other.invoice_number INTO v_number
        FROM pm.invoice_time_entry_allocations mine
        JOIN pm.invoice_time_entry_allocations theirs
          ON theirs.time_entry_id = mine.time_entry_id AND theirs.invoice_id <> mine.invoice_id
        JOIN pm.project_invoices other ON other.id = theirs.invoice_id
        WHERE mine.invoice_id = p_id AND other.status <> 'cancelled' AND other.deleted_at IS NULL
          AND mine.start_offset_hours < theirs.start_offset_hours + theirs.allocated_hours - 0.000001
          AND theirs.start_offset_hours < mine.start_offset_hours + mine.allocated_hours - 0.000001
        LIMIT 1;
        IF FOUND THEN
          RETURN 'Some of its hours are on invoice ' || v_number || ' now. Take them off that invoice first.';
        END IF;
        IF EXISTS (
          SELECT 1 FROM pm.invoice_time_entry_allocations allocation
          JOIN pm.project_time_entries entry ON entry.id = allocation.time_entry_id
          WHERE allocation.invoice_id = p_id AND entry.deleted_at IS NOT NULL
        ) THEN
          RETURN 'Some of its time is in Trash. Restore that time first.';
        END IF;
        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements(COALESCE(NULLIF(invoice.line_items, 'null'::jsonb), '[]'::jsonb)) line
          JOIN pm.project_retainers retainer ON retainer.id::text = line.value->>'retainer_id' AND retainer.deleted_at IS NULL
          JOIN pm.project_retainer_periods handled
            ON handled.retainer_id = retainer.id
           AND handled.period_start = GREATEST(date_trunc('month', (line.value->>'service_start_date')::date)::date, retainer.start_date)
          WHERE COALESCE(line.value->>'service_start_date', '') ~ '^\d{4}-\d{2}-\d{2}$'
            AND handled.status = 'invoiced' AND handled.invoice_id IS NOT NULL AND handled.invoice_id <> p_id
        ) THEN
          RETURN 'Its retainer period is on another invoice now.';
        END IF;
      END IF;
      -- Paid hours that are not linked to time entries cannot be checked
      -- against what was billed since; counting them again would under-bill.
      IF invoice.status = 'paid'
         AND (
           (jsonb_array_length(COALESCE(NULLIF(invoice.line_items, 'null'::jsonb), '[]'::jsonb)) = 0 AND invoice.invoice_type = 'hourly'
            AND NOT EXISTS (SELECT 1 FROM pm.invoice_time_entry_allocations a WHERE a.invoice_id = p_id))
           OR EXISTS (
             SELECT 1 FROM jsonb_array_elements(COALESCE(NULLIF(invoice.line_items, 'null'::jsonb), '[]'::jsonb)) line
             WHERE line.value->>'item_type' = 'hourly'
               AND NOT EXISTS (SELECT 1 FROM pm.invoice_time_entry_allocations a
                               WHERE a.invoice_id = p_id AND a.line_item_id = line.value->>'id')
           )
         )
         AND EXISTS (
           SELECT 1 FROM pm.project_invoices other
           WHERE other.project_id = invoice.project_id AND other.id <> p_id AND other.deleted_at IS NULL
             AND other.status <> 'cancelled' AND other.created_at > invoice.deleted_at
             AND (other.invoice_type = 'hourly' OR EXISTS (
               SELECT 1 FROM jsonb_array_elements(COALESCE(NULLIF(other.line_items, 'null'::jsonb), '[]'::jsonb)) line
               WHERE line.value->>'item_type' = 'hourly'))
         ) THEN
        RETURN 'Hours were invoiced after this invoice went to Trash, and its own hours are not linked to time entries, so restoring it could count hours twice. Check the hourly invoices first.';
      END IF;
    WHEN 'project_hourly_rates' THEN
      IF EXISTS (
        SELECT 1 FROM pm.project_hourly_rates rate
        JOIN pm.project_hourly_rates other
          ON other.project_id = rate.project_id AND other.effective_at = rate.effective_at AND other.id <> rate.id
        WHERE rate.id = p_id AND other.deleted_at IS NULL
      ) THEN
        RETURN 'Another rate now starts at the same time. Change or delete that one first.';
      END IF;
    WHEN 'lead_fields' THEN
      IF EXISTS (
        SELECT 1 FROM pm.lead_fields field
        JOIN pm.lead_fields other
          ON other.lead_id = field.lead_id AND other.field_key = field.field_key AND other.id <> field.id
        WHERE field.id = p_id AND other.deleted_at IS NULL
      ) THEN
        RETURN 'This field has been set again since. Change or delete that one first.';
      END IF;
    WHEN 'project_retainer_amounts' THEN
      IF EXISTS (
        SELECT 1 FROM pm.project_retainer_amounts amount
        JOIN pm.project_retainer_amounts other
          ON other.retainer_id = amount.retainer_id AND other.effective_date = amount.effective_date AND other.id <> amount.id
        WHERE amount.id = p_id AND other.deleted_at IS NULL
      ) THEN
        RETURN 'Another amount now starts on the same date. Change or delete that one first.';
      END IF;
    WHEN 'invoice_payments' THEN
      SELECT * INTO payment FROM pm.invoice_payments WHERE id = p_id;
      SELECT * INTO invoice FROM pm.project_invoices WHERE id = payment.invoice_id;
      IF invoice.status NOT IN ('sent', 'overdue', 'paid') THEN
        RETURN 'Its invoice is ' || invoice.status || ' now, so it cannot take a payment.';
      END IF;
      IF payment.amount > pm.invoice_total(invoice) - COALESCE((
        SELECT sum(other.amount) FROM pm.invoice_payments other
        WHERE other.invoice_id = invoice.id AND other.deleted_at IS NULL
      ), 0) + 0.005 THEN
        RETURN 'Its invoice no longer has enough outstanding for this payment.';
      END IF;
      IF payment.external_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM pm.invoice_payments other
        WHERE other.invoice_id = payment.invoice_id AND other.external_id = payment.external_id
          AND other.deleted_at IS NULL AND other.id <> payment.id
      ) THEN
        RETURN 'This payment was recorded again after it was removed.';
      END IF;
    ELSE
      NULL;
  END CASE;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION pm.trash_entity_type(p_table text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE p_table
    WHEN 'projects' THEN 'project'
    WHEN 'tasks' THEN 'task'
    WHEN 'task_subtasks' THEN 'subtask'
    WHEN 'task_comments' THEN 'comment'
    WHEN 'task_files' THEN 'task_file'
    WHEN 'reminders' THEN 'reminder'
    WHEN 'project_credentials' THEN 'credential'
    WHEN 'entity_files' THEN 'entity_file'
    WHEN 'portal_updates' THEN 'portal_update'
    WHEN 'portal_update_attachments' THEN 'portal_update_attachment'
    WHEN 'contacts' THEN 'contact'
    WHEN 'leads' THEN 'lead'
    WHEN 'lead_interactions' THEN 'lead_interaction'
    WHEN 'lead_proposals' THEN 'lead_proposal'
    WHEN 'lead_fields' THEN 'lead_field'
    WHEN 'project_time_entries' THEN 'time_entry'
    WHEN 'project_invoices' THEN 'invoice'
    WHEN 'invoice_payments' THEN 'invoice_payment'
    WHEN 'project_hourly_rates' THEN 'project_hourly_rate'
    WHEN 'project_retainers' THEN 'retainer'
    WHEN 'project_retainer_amounts' THEN 'retainer_amount'
    WHEN 'task_templates' THEN 'task_template'
    WHEN 'initiatives' THEN 'initiative'
    WHEN 'initiative_entries' THEN 'initiative_entry'
    ELSE p_table
  END
$$;

CREATE OR REPLACE FUNCTION pm.list_trash(p_types text[] DEFAULT NULL, p_limit integer DEFAULT 500)
RETURNS TABLE (
  record_type text,
  id uuid,
  label text,
  context text,
  project_id uuid,
  deleted_at timestamptz,
  deleted_by uuid,
  deleted_by_name text,
  blocker text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  spec record;
  is_service boolean := coalesce(auth.role(), '') = 'service_role';
BEGIN
  IF NOT is_service AND pm.current_team_member_id() IS NULL THEN
    RETURN;
  END IF;
  FOR spec IN
    SELECT * FROM (VALUES
      ('projects', 'r.name', 'NULL', 'r.id', ''),
      ('tasks', 'r.title', 'CASE WHEN parent.id IS NULL THEN p.name ELSE ''Subtask of '' || parent.title END', 'r.project_id',
        'LEFT JOIN pm.projects p ON p.id = r.project_id LEFT JOIN pm.tasks parent ON parent.id = r.parent_task_id'),
      ('task_comments', 'left(r.text, 120)', 't.title', 't.project_id', 'LEFT JOIN pm.tasks t ON t.id = r.task_id'),
      ('task_files', 'r.name', 't.title', 't.project_id', 'LEFT JOIN pm.tasks t ON t.id = r.task_id'),
      ('task_templates', 'r.name', 'coalesce(p.name, ''Task templates'')', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('initiatives', 'r.name', 'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('initiative_entries', 'r.title', 'i.name', 'r.project_id', 'LEFT JOIN pm.initiatives i ON i.id = r.initiative_id'),
      ('reminders', 'r.title', 'coalesce(t.title, p.name)', 'r.project_id',
        'LEFT JOIN pm.tasks t ON t.id = r.task_id LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('project_credentials', 'r.label', 'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('entity_files', 'r.name',
        'CASE r.entity_type WHEN ''project'' THEN (SELECT name FROM pm.projects WHERE id = r.entity_id)
           WHEN ''lead'' THEN (SELECT name FROM pm.leads WHERE id = r.entity_id)
           WHEN ''contact'' THEN (SELECT name FROM pm.contacts WHERE id = r.entity_id) END',
        'CASE WHEN r.entity_type = ''project'' THEN r.entity_id END', ''),
      ('portal_updates', 'r.title', 'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('portal_update_attachments', 'r.name', 'u.title', 'u.project_id', 'LEFT JOIN pm.portal_updates u ON u.id = r.update_id'),
      ('contacts', 'r.name', 'NULL', 'NULL', ''),
      ('leads', 'r.name', 'NULL', 'NULL', ''),
      ('lead_interactions', 'r.title', 'l.name', 'NULL', 'LEFT JOIN pm.leads l ON l.id = r.lead_id'),
      ('lead_proposals', 'r.title', 'l.name', 'NULL', 'LEFT JOIN pm.leads l ON l.id = r.lead_id'),
      ('lead_fields', 'r.field_key || '': '' || left(r.value, 80)', 'l.name', 'NULL', 'LEFT JOIN pm.leads l ON l.id = r.lead_id'),
      ('project_time_entries',
        'coalesce(nullif(btrim(r.description), ''''), ''Time entry'') || '' ('' || to_char(r.start_time AT TIME ZONE pm.workspace_timezone(), ''Mon FMDD, YYYY'') || '')''',
        'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('project_invoices', 'r.invoice_number || '' ('' || pm.format_money(r.amount, r.currency, true) || '')''', 'p.name', 'r.project_id',
        'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('invoice_payments', '''Payment of '' || pm.format_money(r.amount, i.currency, true) || '' on '' || i.invoice_number', 'p.name', 'i.project_id',
        'LEFT JOIN pm.project_invoices i ON i.id = r.invoice_id LEFT JOIN pm.projects p ON p.id = i.project_id'),
      ('project_hourly_rates', 'pm.format_money(r.hourly_rate, NULL, true) || ''/hr from '' || to_char(r.effective_at AT TIME ZONE pm.workspace_timezone(), ''Mon FMDD, YYYY'')',
        'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('project_retainers', 'r.name', 'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('project_retainer_amounts', 'rt.name || '': '' || pm.format_money(r.amount, rt.currency, true) || '' from '' || to_char(r.effective_date, ''Mon FMDD, YYYY'')',
        'p.name', 'rt.project_id',
        'LEFT JOIN pm.project_retainers rt ON rt.id = r.retainer_id LEFT JOIN pm.projects p ON p.id = rt.project_id')
    ) AS specs(record_type, label_sql, context_sql, project_sql, join_sql)
  LOOP
    CONTINUE WHEN p_types IS NOT NULL AND NOT spec.record_type = ANY (p_types);
    RETURN QUERY EXECUTE format(
      'SELECT %L::text, r.id, (%s)::text, (%s)::text, (%s)::uuid, r.deleted_at, r.deleted_by, m.name::text,
              pm.trash_restore_blocker(%L, r.id)
       FROM pm.%I r %s
       LEFT JOIN pm.team_members m ON m.id = r.deleted_by
       WHERE r.deleted_at IS NOT NULL AND ($1 OR pm.can_trash_record(%L, r.id))
       ORDER BY r.deleted_at DESC
       LIMIT %s',
      spec.record_type, spec.label_sql, spec.context_sql, spec.project_sql, spec.record_type,
      spec.record_type, spec.join_sql, spec.record_type, greatest(1, least(coalesce(p_limit, 500), 2000)))
    USING is_service;
  END LOOP;
END;
$$;

DROP TRIGGER IF EXISTS record_trash_event ON pm.initiatives;
CREATE TRIGGER record_trash_event AFTER UPDATE OF deleted_at ON pm.initiatives
  FOR EACH ROW WHEN (OLD.deleted_at IS DISTINCT FROM NEW.deleted_at)
  EXECUTE FUNCTION pm.record_trash_event();
DROP TRIGGER IF EXISTS record_trash_event ON pm.initiative_entries;
CREATE TRIGGER record_trash_event AFTER UPDATE OF deleted_at ON pm.initiative_entries
  FOR EACH ROW WHEN (OLD.deleted_at IS DISTINCT FROM NEW.deleted_at)
  EXECUTE FUNCTION pm.record_trash_event();
DROP TRIGGER IF EXISTS log_trash_activity ON pm.initiatives;
CREATE TRIGGER log_trash_activity AFTER UPDATE OF deleted_at ON pm.initiatives
  FOR EACH ROW WHEN (OLD.deleted_at IS DISTINCT FROM NEW.deleted_at)
  EXECUTE FUNCTION pm.log_trash_activity();
DROP TRIGGER IF EXISTS log_trash_activity ON pm.initiative_entries;
CREATE TRIGGER log_trash_activity AFTER UPDATE OF deleted_at ON pm.initiative_entries
  FOR EACH ROW WHEN (OLD.deleted_at IS DISTINCT FROM NEW.deleted_at)
  EXECUTE FUNCTION pm.log_trash_activity();

-- ============================================================
-- TEMPLATES V2 (20261126000200_templates_v2.sql)
-- ============================================================
-- Templates v2: playbooks planned around key dates, assigned by role, with
-- dependencies, that a run turns into an initiative with its tasks.
--
-- - pm.task_templates gains key_dates (named anchors: [{ key, label, main }],
--   "start" by default, so a 2.0.34 template's due_in_days keeps meaning
--   start + N), roles ([{ key, label, default_member_id, required }]) and
--   guidance (one note for whoever, person or agent, fills it in). Each item
--   in items may now carry key (stable, the server assigns one when missing),
--   anchor, role and depends_on (top-level items only); due_in_days may be
--   negative (before its key date). The scope is project_id: set, the
--   template belongs to that project; null, it is company-wide.
-- - Who may write: whoever manages the project (projects.manage on a project
--   they can open) or templates.manage for a project's templates;
--   templates.manage alone for company-wide ones. can_trash_record follows.
-- - The version follows the new columns too.
-- - pm.task_template_runs gains key_dates ({ key: date }), role_members
--   ({ role: member id }) and initiative_id (the initiative the run made).
-- - pm.task_template_run_tasks: one row per task a run made, with the item
--   key it came from and the due date it was planned for, so a later change
--   of key dates can tell planned dates from hand-changed ones. Server only.
-- - pm.record_task_template_run: the run row and its task links in one
--   transaction. Server only.
-- - Webhooks: template.run gains run.key_dates and run.initiative_id.
--
-- Additive and safe to run twice. The previous release's code never reads or
-- writes the new columns or table, and its runs still record (the new
-- columns default to empty).

-- ---------------------------------------------------------------------------
-- Templates: key dates, roles and guidance
-- ---------------------------------------------------------------------------
ALTER TABLE pm.task_templates ADD COLUMN IF NOT EXISTS key_dates jsonb NOT NULL DEFAULT '[{"key": "start", "label": "Start date"}]'::jsonb;
ALTER TABLE pm.task_templates ADD COLUMN IF NOT EXISTS roles jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE pm.task_templates ADD COLUMN IF NOT EXISTS guidance text NOT NULL DEFAULT '';

ALTER TABLE pm.task_templates DROP CONSTRAINT IF EXISTS task_templates_key_dates_shape;
ALTER TABLE pm.task_templates
  ADD CONSTRAINT task_templates_key_dates_shape CHECK (jsonb_typeof(key_dates) = 'array' AND jsonb_array_length(key_dates) BETWEEN 1 AND 10);
ALTER TABLE pm.task_templates DROP CONSTRAINT IF EXISTS task_templates_roles_shape;
ALTER TABLE pm.task_templates
  ADD CONSTRAINT task_templates_roles_shape CHECK (jsonb_typeof(roles) = 'array' AND jsonb_array_length(roles) <= 20);
ALTER TABLE pm.task_templates DROP CONSTRAINT IF EXISTS task_templates_guidance_length;
ALTER TABLE pm.task_templates
  ADD CONSTRAINT task_templates_guidance_length CHECK (length(guidance) <= 10000);

COMMENT ON COLUMN pm.task_templates.project_id IS
  'The project the template belongs to: it shows only there, always creates there, and whoever manages the project may change it. Null: company-wide, usable in any project, changed with templates.manage.';
COMMENT ON COLUMN pm.task_templates.key_dates IS
  'Named key dates each task''s due_in_days counts from: [{ "key", "label", "main" }]. The main one (or the first) is the target date of a run''s initiative.';
COMMENT ON COLUMN pm.task_templates.roles IS
  'Roles tasks are assigned by: [{ "key", "label", "default_member_id", "required" }]. A run maps each to one member, a person or an agent.';
COMMENT ON COLUMN pm.task_templates.guidance IS
  'How to fill the template in and what to look at first, for a person or an agent drafting a run.';
COMMENT ON COLUMN pm.task_templates.version IS
  'Goes up by one whenever what the template makes changes (name, description, project, fields, items, key dates, roles, guidance).';

-- Who made it, and when, never change; the version follows what it makes.
CREATE OR REPLACE FUNCTION pm.handle_task_template_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  NEW.name := btrim(NEW.name);
  IF TG_OP = 'INSERT' THEN
    NEW.version := 1;
  ELSE
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
    IF (NEW.name, NEW.description, NEW.project_id, NEW.fields, NEW.items, NEW.key_dates, NEW.roles, NEW.guidance)
       IS DISTINCT FROM (OLD.name, OLD.description, OLD.project_id, OLD.fields, OLD.items, OLD.key_dates, OLD.roles, OLD.guidance) THEN
      NEW.version := OLD.version + 1;
    ELSE
      NEW.version := OLD.version;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_task_template_before_write() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Runs: key dates, the role map and the initiative a run made
-- ---------------------------------------------------------------------------
ALTER TABLE pm.task_template_runs ADD COLUMN IF NOT EXISTS key_dates jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE pm.task_template_runs ADD COLUMN IF NOT EXISTS role_members jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE pm.task_template_runs ADD COLUMN IF NOT EXISTS initiative_id uuid REFERENCES pm.initiatives(id);

ALTER TABLE pm.task_template_runs DROP CONSTRAINT IF EXISTS task_template_runs_plan_shape;
ALTER TABLE pm.task_template_runs
  ADD CONSTRAINT task_template_runs_plan_shape CHECK (jsonb_typeof(key_dates) = 'object' AND jsonb_typeof(role_members) = 'object');

COMMENT ON COLUMN pm.task_template_runs.key_dates IS
  'The date each key date was set to: { "start": "2026-12-01", "launch": "2027-01-15" }. Empty for a run recorded before key dates existed (start_date is its start).';
COMMENT ON COLUMN pm.task_template_runs.role_members IS
  'The member each role was assigned to: { "designer": "<member id>" }.';
COMMENT ON COLUMN pm.task_template_runs.initiative_id IS
  'The initiative the run made, its tasks inside it. Null when the run made none.';

CREATE INDEX IF NOT EXISTS idx_task_template_runs_initiative ON pm.task_template_runs (initiative_id) WHERE initiative_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Run tasks: which item each task came from, and its planned due date
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.task_template_run_tasks (
  run_id uuid NOT NULL REFERENCES pm.task_template_runs(id),
  task_id uuid NOT NULL REFERENCES pm.tasks(id),
  item_key text NOT NULL,
  -- The due date the run planned (key date + offset); null for no due date.
  planned_due_date date,
  PRIMARY KEY (run_id, task_id)
);

ALTER TABLE pm.task_template_run_tasks DROP CONSTRAINT IF EXISTS task_template_run_tasks_item_key_length;
ALTER TABLE pm.task_template_run_tasks
  ADD CONSTRAINT task_template_run_tasks_item_key_length CHECK (length(item_key) BETWEEN 1 AND 80);

COMMENT ON TABLE pm.task_template_run_tasks IS
  'One row per task a template run made: the template item it came from (item_key) and the due date it was planned for. Never removed. Written by the server only.';

-- A task's run; one item per run.
CREATE INDEX IF NOT EXISTS idx_task_template_run_tasks_task ON pm.task_template_run_tasks (task_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_task_template_run_tasks_item ON pm.task_template_run_tasks (run_id, item_key);

-- Never permanently deleted.
DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.task_template_run_tasks;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.task_template_run_tasks
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.task_template_run_tasks;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.task_template_run_tasks
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

-- Server only: no member policy, no member grant.
ALTER TABLE pm.task_template_run_tasks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.task_template_run_tasks FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.task_template_run_tasks TO service_role;

-- The run and its task links in one transaction: nothing half recorded.
-- p_run carries the run's columns; p_tasks is [{ task_id, item_key, planned_due_date }].
CREATE OR REPLACE FUNCTION pm.record_task_template_run(p_run jsonb, p_tasks jsonb)
RETURNS uuid
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO pm.task_template_runs (
    template_id, template_version, snapshot, project_id, run_by, via, schedule_id, start_date,
    field_values, task_ids, key_dates, role_members, initiative_id
  ) VALUES (
    (p_run ->> 'template_id')::uuid,
    (p_run ->> 'template_version')::integer,
    p_run -> 'snapshot',
    (p_run ->> 'project_id')::uuid,
    nullif(p_run ->> 'run_by', '')::uuid,
    coalesce(p_run ->> 'via', 'app'),
    nullif(p_run ->> 'schedule_id', '')::uuid,
    (p_run ->> 'start_date')::date,
    coalesce(p_run -> 'field_values', '{}'::jsonb),
    coalesce(ARRAY(
      SELECT t.value::uuid FROM jsonb_array_elements_text(coalesce(p_run -> 'task_ids', '[]'::jsonb)) WITH ORDINALITY AS t(value, n) ORDER BY t.n
    ), '{}'),
    coalesce(p_run -> 'key_dates', '{}'::jsonb),
    coalesce(p_run -> 'role_members', '{}'::jsonb),
    nullif(p_run ->> 'initiative_id', '')::uuid
  )
  RETURNING id INTO v_id;

  INSERT INTO pm.task_template_run_tasks (run_id, task_id, item_key, planned_due_date)
  SELECT v_id, (link ->> 'task_id')::uuid, link ->> 'item_key', nullif(link ->> 'planned_due_date', '')::date
  FROM jsonb_array_elements(coalesce(p_tasks, '[]'::jsonb)) AS link;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION pm.record_task_template_run(jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.record_task_template_run(jsonb, jsonb) TO service_role;

-- ---------------------------------------------------------------------------
-- Webhooks: template.run gains the key dates and the initiative
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.emit_task_template_run_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_members uuid[];
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['template.run']
  ) THEN
    RETURN NULL;
  END IF;

  SELECT coalesce(array_agg(DISTINCT m ORDER BY m) FILTER (WHERE m IS NOT NULL), '{}') INTO v_members
  FROM (
    SELECT NEW.run_by AS m
    UNION ALL
    SELECT a.member_id FROM pm.task_assignees a WHERE a.task_id = ANY (NEW.task_ids)
  ) members;

  PERFORM pm.emit_webhook_event(
    'template.run',
    'template_run',
    NEW.id,
    ARRAY[NEW.project_id],
    v_members,
    jsonb_build_object(
      'run', jsonb_build_object(
        'id', NEW.id,
        'template_id', NEW.template_id,
        'template_version', NEW.template_version,
        'template_name', coalesce(NEW.snapshot ->> 'name', ''),
        'project_id', NEW.project_id,
        'run_by', NEW.run_by,
        'via', NEW.via,
        'schedule_id', NEW.schedule_id,
        'start_date', NEW.start_date,
        'field_values', NEW.field_values,
        'task_ids', to_jsonb(NEW.task_ids),
        'created_at', NEW.created_at,
        'key_dates', NEW.key_dates,
        'initiative_id', NEW.initiative_id
      ),
      'project', jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ),
      'project_id', NEW.project_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_task_template_run_webhook() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Trash: a project's templates go by whoever manages the project
-- ---------------------------------------------------------------------------
-- Moved to Trash, listed and restored with the rule the server applies to
-- writing them: a company-wide template needs templates.manage; a project's
-- template needs the project and projects.manage or templates.manage.
CREATE OR REPLACE FUNCTION pm.can_trash_record(p_table text, p_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  me uuid := pm.current_team_member_id();
  allowed boolean := false;
BEGIN
  IF me IS NULL THEN
    RETURN false;
  END IF;
  CASE p_table
    WHEN 'projects' THEN
      SELECT pm.has_permission('projects.manage') AND (
        pm.has_permission('projects.read_all')
        OR EXISTS (SELECT 1 FROM pm.project_members WHERE project_id = p_id AND member_id = me)
      ) INTO allowed;
    WHEN 'tasks' THEN
      -- A subtask can also go by whoever manages its parent as an assignee.
      SELECT pm.can_access_project(project_id) AND (
        pm.has_permission('tasks.manage_all') OR (
          parent_task_id IS NOT NULL AND pm.has_permission('tasks.manage_assigned') AND EXISTS (
            SELECT 1 FROM pm.task_assignees assignment
            WHERE assignment.task_id = tasks.parent_task_id AND assignment.member_id = me
          )
        )
      ) INTO allowed FROM pm.tasks WHERE id = p_id;
    WHEN 'task_comments' THEN
      SELECT pm.can_access_task(task_id) AND (user_id = me OR pm.has_permission('tasks.manage_all'))
      INTO allowed FROM pm.task_comments WHERE id = p_id;
    WHEN 'task_files' THEN
      SELECT pm.can_access_task(task_id) AND (added_by = me OR pm.has_permission('files.manage'))
      INTO allowed FROM pm.task_files WHERE id = p_id;
    WHEN 'reminders' THEN
      SELECT pm.can_see_reminder(owner_id, project_id, task_id)
        AND (owner_id = me OR created_by = me OR pm.has_permission('tasks.manage_all'))
      INTO allowed FROM pm.reminders WHERE id = p_id;
    WHEN 'project_credentials' THEN
      SELECT pm.has_permission('credentials.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_credentials WHERE id = p_id;
    WHEN 'entity_files' THEN
      SELECT pm.can_access_file_entity(entity_type, entity_id) AND (
        pm.has_permission('files.manage') OR (uploaded_by = me AND visibility = 'internal')
      ) INTO allowed FROM pm.entity_files WHERE id = p_id;
    WHEN 'portal_updates' THEN
      SELECT pm.has_permission('portal.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.portal_updates WHERE id = p_id;
    WHEN 'portal_update_attachments' THEN
      SELECT pm.has_permission('portal.manage') AND pm.can_access_project(update_row.project_id)
      INTO allowed
      FROM pm.portal_update_attachments attachment
      JOIN pm.portal_updates update_row ON update_row.id = attachment.update_id
      WHERE attachment.id = p_id AND update_row.deleted_at IS NULL;
    WHEN 'contacts' THEN
      SELECT pm.has_permission('contacts.manage') INTO allowed;
    WHEN 'leads' THEN
      SELECT pm.has_permission('leads.manage') INTO allowed;
    WHEN 'lead_interactions' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_interactions WHERE id = p_id;
    WHEN 'lead_proposals' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_proposals WHERE id = p_id;
    WHEN 'lead_fields' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_fields WHERE id = p_id;
    WHEN 'project_time_entries' THEN
      SELECT pm.can_access_project(project_id) AND (
        pm.has_permission('time.manage_all') OR (
          pm.has_permission('time.manage_own')
          AND member_id = me
          AND approval_status IN ('draft', 'pending', 'rejected')
        )
      ) INTO allowed FROM pm.project_time_entries WHERE id = p_id;
    WHEN 'project_invoices' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_invoices WHERE id = p_id;
    WHEN 'invoice_payments' THEN
      -- People remove only payments recorded by hand, as remove_invoice_payment.
      SELECT (pm.has_permission('invoices.record_payments') OR pm.has_permission('invoices.manage'))
        AND pm.can_access_project(invoice.project_id)
        AND invoice.deleted_at IS NULL
        AND payment.recorded_via = 'app'
      INTO allowed
      FROM pm.invoice_payments payment
      JOIN pm.project_invoices invoice ON invoice.id = payment.invoice_id
      WHERE payment.id = p_id;
    WHEN 'project_hourly_rates' THEN
      SELECT pm.has_permission('billing.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_hourly_rates WHERE id = p_id;
    WHEN 'project_retainers' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_retainers WHERE id = p_id;
    WHEN 'project_retainer_amounts' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(retainer.project_id)
        AND retainer.deleted_at IS NULL
      INTO allowed
      FROM pm.project_retainer_amounts amount
      JOIN pm.project_retainers retainer ON retainer.id = amount.retainer_id
      WHERE amount.id = p_id;
    WHEN 'task_templates' THEN
      -- Company-wide: templates.manage. A project's: whoever manages the
      -- project (projects.manage) or templates.manage, on a project they can open.
      SELECT CASE
          WHEN task_templates.project_id IS NULL THEN pm.has_permission('templates.manage')
          ELSE pm.can_access_project(task_templates.project_id)
            AND (pm.has_permission('templates.manage') OR pm.has_permission('projects.manage'))
        END
      INTO allowed FROM pm.task_templates WHERE id = p_id;
    WHEN 'initiatives' THEN
      -- Whoever manages projects, or whoever made it, on a project they can open.
      SELECT pm.can_access_project(project_id) AND (pm.has_permission('projects.manage') OR created_by = me)
      INTO allowed FROM pm.initiatives WHERE id = p_id;
    WHEN 'initiative_entries' THEN
      -- Its author, or whoever manages projects, while they may read the log.
      SELECT pm.can_access_project(project_id) AND pm.has_permission('tasks.read')
        AND coalesce(pm.current_team_member_role(), '') <> 'guest'
        AND (created_by = me OR pm.has_permission('projects.manage'))
      INTO allowed FROM pm.initiative_entries WHERE id = p_id;
    ELSE
      allowed := false;
  END CASE;
  RETURN coalesce(allowed, false);
END;
$$;

-- ============================================================
-- TEMPLATE REFLOW AND DRAFTS (20261126000300_template_reflow_drafts.sql)
-- ============================================================
-- Templates v2, live runs: changing a run's key dates (reflow) and runs an
-- agent drafts for a person to approve.
--
-- - pm.task_template_runs.key_dates becomes changeable: a reflow moves the
--   run's key dates, the due dates of its tasks nobody changed by hand, and
--   its initiative's target date, in one transaction
--   (pm.reflow_task_template_run, server only). Each change of key dates is
--   logged in the team activity log, as whoever made it, on the run's
--   initiative.
-- - pm.task_template_run_drafts: a run an agent (or anyone) proposes, with
--   the template as it was then (snapshot), what it proposes (key dates,
--   roles, values, the initiative, steps added and removed) and the approval
--   (pm.questions, kind approval) a person decides it with. The run itself
--   is recorded only when a person approves, through the one run path.
--   Server only.
-- - A draft expires when its approval expires or is withdrawn (a trigger on
--   pm.questions, so the watchdog's expiry counts too).
--
-- Additive and safe to run twice. The previous release's code never reads
-- the new table, never calls the new function, and its runs record as
-- before.

-- ---------------------------------------------------------------------------
-- Runs: key dates change with a reflow
-- ---------------------------------------------------------------------------
COMMENT ON TABLE pm.task_template_runs IS
  'One row per use of a task template: its version and snapshot, who ran it and how, the project, start date, fill-in values and the tasks it made. Never removed. Written by the server only; key_dates and start_date change only through a reflow (pm.reflow_task_template_run).';
COMMENT ON COLUMN pm.task_template_runs.key_dates IS
  'The date each key date is set to: { "start": "2026-12-01", "launch": "2027-01-15" }. A reflow changes it (logged in the team activity log). Empty for a run recorded before key dates existed (start_date is its start).';

-- ---------------------------------------------------------------------------
-- Drafts: a proposed run waiting for a person
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.task_template_run_drafts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  template_id uuid NOT NULL REFERENCES pm.task_templates(id),
  -- The template as the draft saw it: { name, description, fields, items, key_dates, roles, guidance }.
  template_version integer NOT NULL,
  snapshot jsonb NOT NULL,
  project_id uuid NOT NULL REFERENCES pm.projects(id),
  -- What it proposes: { key_dates, roles, values, create_initiative, initiative, extra_steps, removed_steps }.
  proposal jsonb NOT NULL,
  -- Why, in the proposer's words.
  note text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'pending',
  proposed_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  -- The person the proposing agent acted for (X-Act-For, a personal agent's person).
  principal_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  -- The approval a person decides it with.
  question_id uuid REFERENCES pm.questions(id),
  decided_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  decided_at timestamptz,
  -- The run an approval made.
  run_id uuid REFERENCES pm.task_template_runs(id),
  -- The proposer's own key for this proposal: the same key again answers the same draft.
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  deleted_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL
);

ALTER TABLE pm.task_template_run_drafts DROP CONSTRAINT IF EXISTS task_template_run_drafts_status_check;
ALTER TABLE pm.task_template_run_drafts
  ADD CONSTRAINT task_template_run_drafts_status_check CHECK (status IN ('pending', 'approved', 'rejected', 'expired'));
ALTER TABLE pm.task_template_run_drafts DROP CONSTRAINT IF EXISTS task_template_run_drafts_shape;
ALTER TABLE pm.task_template_run_drafts
  ADD CONSTRAINT task_template_run_drafts_shape CHECK (jsonb_typeof(snapshot) = 'object' AND jsonb_typeof(proposal) = 'object');
ALTER TABLE pm.task_template_run_drafts DROP CONSTRAINT IF EXISTS task_template_run_drafts_note_length;
ALTER TABLE pm.task_template_run_drafts
  ADD CONSTRAINT task_template_run_drafts_note_length CHECK (length(note) <= 2000);
ALTER TABLE pm.task_template_run_drafts DROP CONSTRAINT IF EXISTS task_template_run_drafts_idempotency_length;
ALTER TABLE pm.task_template_run_drafts
  ADD CONSTRAINT task_template_run_drafts_idempotency_length CHECK (idempotency_key IS NULL OR length(idempotency_key) BETWEEN 1 AND 255);

COMMENT ON TABLE pm.task_template_run_drafts IS
  'A template run proposed for a person to approve: the template as it was (snapshot), what it proposes, and the approval (question_id) it is decided with. Approved, the run is made as whoever approved it (run_id). Expires with its approval. Written by the server only.';
COMMENT ON COLUMN pm.task_template_run_drafts.status IS
  'pending (waiting for a person), approved (run_id is the run it made), rejected, or expired (its approval expired or was withdrawn).';

-- A project's drafts by status, newest first; a draft by its approval; a proposer's key.
CREATE INDEX IF NOT EXISTS idx_task_template_run_drafts_project ON pm.task_template_run_drafts (project_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_task_template_run_drafts_template ON pm.task_template_run_drafts (template_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_task_template_run_drafts_question ON pm.task_template_run_drafts (question_id) WHERE question_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_task_template_run_drafts_idempotency ON pm.task_template_run_drafts (proposed_by, idempotency_key) WHERE idempotency_key IS NOT NULL;

DROP TRIGGER IF EXISTS set_task_template_run_drafts_updated_at ON pm.task_template_run_drafts;
CREATE TRIGGER set_task_template_run_drafts_updated_at
  BEFORE UPDATE ON pm.task_template_run_drafts
  FOR EACH ROW EXECUTE FUNCTION pm.handle_updated_at();

-- Never permanently deleted.
DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.task_template_run_drafts;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.task_template_run_drafts
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.task_template_run_drafts;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.task_template_run_drafts
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

-- Server only: no member policy, no member grant.
ALTER TABLE pm.task_template_run_drafts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.task_template_run_drafts FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.task_template_run_drafts TO service_role;

-- A draft expires with its approval: expired (the watchdog, or a read that
-- stores it) or withdrawn (cancelled).
CREATE OR REPLACE FUNCTION pm.expire_task_template_run_drafts()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  UPDATE pm.task_template_run_drafts
  SET status = 'expired', decided_at = now()
  WHERE question_id = NEW.id AND status = 'pending';
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.expire_task_template_run_drafts() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS expire_task_template_run_drafts ON pm.questions;
CREATE TRIGGER expire_task_template_run_drafts
  AFTER UPDATE OF status ON pm.questions
  FOR EACH ROW
  WHEN (OLD.status = 'open' AND NEW.status IN ('expired', 'cancelled'))
  EXECUTE FUNCTION pm.expire_task_template_run_drafts();

-- ---------------------------------------------------------------------------
-- Reflow: new key dates, and the due dates that follow them
-- ---------------------------------------------------------------------------
-- In one transaction: the run's key dates (refused when they changed since
-- the caller read them: run_changed), each task in p_moves that is still
-- not done, not in Trash, and still due on its planned date (or forced: a
-- hand-changed task the caller opted in), its planned date with it, and the
-- initiative's target date when it still is the old main key date.
-- p_moves is [{ task_id, due_date, force }]; p_initiative is
-- { id, from, to } or null. Logs the change in the team activity log as
-- whoever made it (a person; agents keep their own log). Answers
-- { moved: [task ids], initiative_moved: boolean }.
CREATE OR REPLACE FUNCTION pm.reflow_task_template_run(
  p_run_id uuid,
  p_expected jsonb,
  p_key_dates jsonb,
  p_start_date date,
  p_moves jsonb,
  p_initiative jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_run pm.task_template_runs%ROWTYPE;
  v_moved uuid[];
  v_initiative_moved boolean := false;
  v_initiative pm.initiatives%ROWTYPE;
BEGIN
  SELECT * INTO v_run FROM pm.task_template_runs WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_run.key_dates IS DISTINCT FROM coalesce(p_expected, '{}'::jsonb) THEN
    RAISE EXCEPTION 'run_changed' USING ERRCODE = 'P0001';
  END IF;

  WITH wanted AS (
    SELECT (m ->> 'task_id')::uuid AS task_id, (m ->> 'due_date')::date AS due_date, coalesce((m ->> 'force')::boolean, false) AS force
    FROM jsonb_array_elements(coalesce(p_moves, '[]'::jsonb)) AS m
  ),
  moved AS (
    UPDATE pm.tasks t
    SET due_date = to_char(w.due_date, 'YYYY-MM-DD')
    FROM wanted w, pm.task_template_run_tasks l
    WHERE t.id = w.task_id
      AND l.run_id = p_run_id AND l.task_id = t.id
      AND t.deleted_at IS NULL
      AND t.status <> 'done'
      AND (w.force OR left(t.due_date, 10) IS NOT DISTINCT FROM to_char(l.planned_due_date, 'YYYY-MM-DD'))
    RETURNING t.id, w.due_date
  ),
  planned AS (
    UPDATE pm.task_template_run_tasks l
    SET planned_due_date = moved.due_date
    FROM moved
    WHERE l.run_id = p_run_id AND l.task_id = moved.id
    RETURNING l.task_id
  )
  SELECT coalesce(array_agg(task_id), '{}') INTO v_moved FROM planned;

  UPDATE pm.task_template_runs
  SET key_dates = coalesce(p_key_dates, '{}'::jsonb), start_date = coalesce(p_start_date, start_date)
  WHERE id = p_run_id;

  IF p_initiative IS NOT NULL AND p_initiative ? 'id' THEN
    UPDATE pm.initiatives
    SET target_date = nullif(p_initiative ->> 'to', '')::date
    WHERE id = (p_initiative ->> 'id')::uuid
      AND deleted_at IS NULL
      AND target_date IS NOT DISTINCT FROM nullif(p_initiative ->> 'from', '')::date;
    v_initiative_moved := FOUND;
  END IF;

  IF v_run.key_dates IS DISTINCT FROM coalesce(p_key_dates, '{}'::jsonb) AND v_run.initiative_id IS NOT NULL THEN
    SELECT * INTO v_initiative FROM pm.initiatives WHERE id = v_run.initiative_id;
    IF FOUND THEN
      PERFORM pm.log_team_activity(
        'initiative.key_dates',
        'initiative',
        v_initiative.id::text,
        v_run.project_id,
        format('Changed the key dates of "%s"', v_initiative.name),
        jsonb_build_object(
          'initiative_id', v_initiative.id,
          'initiative_name', v_initiative.name,
          'run_id', v_run.id,
          'template_id', v_run.template_id,
          'from', v_run.key_dates,
          'to', coalesce(p_key_dates, '{}'::jsonb),
          'moved', coalesce(array_length(v_moved, 1), 0)
        )
      );
    END IF;
  END IF;

  RETURN jsonb_build_object('moved', to_jsonb(v_moved), 'initiative_moved', v_initiative_moved);
END;
$$;

REVOKE ALL ON FUNCTION pm.reflow_task_template_run(uuid, jsonb, jsonb, date, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.reflow_task_template_run(uuid, jsonb, jsonb, date, jsonb, jsonb) TO service_role;

-- ============================================================
-- SCHEDULES (20261126000400_schedules.sql)
-- ============================================================
-- Schedules: one scheduler for recurring templates and repeating tasks.
--
-- - pm.schedules: kind template (runs a template on every date of its
--   recurrence, with its own project, role map, fill-in values, key date
--   offsets, create_initiative and skip_if_open) or kind task (makes the
--   next copy of a task: task_id is the newest copy in the series; mode
--   schedule makes it when the current copy falls due, after_done when the
--   current copy is completed). recurrence is jsonb ({ freq, interval,
--   weekdays, month_day, month_week, month_weekday }), worked out by the
--   app; timezone is an IANA zone. next_on is the next date (a template's
--   run date, or the due date of a task's next copy) and next_run_at the
--   instant it is due to run. run_as is whose rights each run uses. Never
--   removed (deleted_at). Server only.
-- - pm.schedule_occurrences: one row per date a schedule ran for, unique
--   on (schedule_id, scheduled_for) so an occurrence is never made twice,
--   with its outcome (created, skipped with a reason, failed with an
--   error) and attempts (a failure is retried once). Server only.
-- - pm.claim_schedule_occurrence: claims an occurrence by moving next_on
--   and next_run_at on only if they are still what the caller read, and
--   records it, in one transaction. Server only.
-- - pm.schedule_after_done: completing a task that an after_done repeat
--   follows marks the repeat due now.
-- - pm.schedules_kick, pg_cron pm-schedules-due every 5 minutes: while a
--   schedule is due, calls /api/internal/schedules/run with the app's
--   scheduler address and secret from Vault (the ones webhook retries use).
-- - Notifications may be about a schedule (entity_type schedule).
--
-- Additive and safe to run twice. The previous release's code never reads
-- or writes the new tables; the trigger touches only pm.schedules.

-- ---------------------------------------------------------------------------
-- Schedules
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.schedules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind text NOT NULL,
  template_id uuid REFERENCES pm.task_templates(id),
  task_id uuid REFERENCES pm.tasks(id),
  project_id uuid NOT NULL REFERENCES pm.projects(id),
  recurrence jsonb NOT NULL,
  timezone text NOT NULL DEFAULT 'UTC',
  start_date date NOT NULL,
  end_date date,
  mode text NOT NULL DEFAULT 'schedule',
  role_members jsonb NOT NULL DEFAULT '{}'::jsonb,
  field_values jsonb NOT NULL DEFAULT '{}'::jsonb,
  key_date_offsets jsonb NOT NULL DEFAULT '{}'::jsonb,
  create_initiative boolean NOT NULL DEFAULT false,
  skip_if_open boolean NOT NULL DEFAULT true,
  status text NOT NULL DEFAULT 'active',
  paused_reason text,
  next_on date,
  next_run_at timestamptz,
  -- after_done: the day (in the schedule's zone) the current copy was completed.
  done_on date,
  last_run_at timestamptz,
  last_outcome text,
  last_reason text,
  run_as uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  deleted_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL
);

ALTER TABLE pm.schedules DROP CONSTRAINT IF EXISTS schedules_kind_check;
ALTER TABLE pm.schedules
  ADD CONSTRAINT schedules_kind_check CHECK (
    (kind = 'template' AND template_id IS NOT NULL AND task_id IS NULL AND mode = 'schedule')
    OR (kind = 'task' AND task_id IS NOT NULL AND template_id IS NULL)
  );
ALTER TABLE pm.schedules DROP CONSTRAINT IF EXISTS schedules_values_check;
ALTER TABLE pm.schedules
  ADD CONSTRAINT schedules_values_check CHECK (
    mode IN ('schedule', 'after_done')
    AND status IN ('active', 'paused', 'ended')
    AND (last_outcome IS NULL OR last_outcome IN ('created', 'skipped', 'failed'))
    AND jsonb_typeof(recurrence) = 'object'
    AND jsonb_typeof(role_members) = 'object'
    AND jsonb_typeof(field_values) = 'object'
    AND jsonb_typeof(key_date_offsets) = 'object'
    AND length(timezone) BETWEEN 1 AND 64
    AND (end_date IS NULL OR end_date >= start_date)
  );

COMMENT ON TABLE pm.schedules IS
  'Recurring work, one scheduler for two kinds: a template run on every date of a recurrence (kind template), or the next copy of a task (kind task: task_id is the newest copy; mode schedule makes it when the current copy falls due, after_done when it is completed). Worked out and run by the app (/api/internal/schedules/run, kicked by pg_cron pm-schedules-due). Never removed (deleted_at). Server only.';
COMMENT ON COLUMN pm.schedules.recurrence IS
  'How often: { "freq": daily|weekly|monthly, "interval", "weekdays" (weekly, 0 Sunday to 6 Saturday), "month_day" (monthly, 1 to 31, clamped to the month''s last day) or "month_week" (1 to 4, -1 last) with "month_weekday" }.';
COMMENT ON COLUMN pm.schedules.next_on IS
  'The next date: a template schedule''s next run date, or the due date of a task''s next copy. Null while waiting for a task to be completed (after_done) or once ended.';
COMMENT ON COLUMN pm.schedules.next_run_at IS
  'When the next occurrence is due to run (the start of a day in the schedule''s time zone, or now for a completed after_done task). A run claims it by moving it on (pm.claim_schedule_occurrence).';
COMMENT ON COLUMN pm.schedules.run_as IS
  'Whose rights each run uses, checked at run time: whoever set the schedule up or last changed what it makes. Losing them pauses the schedule.';
COMMENT ON COLUMN pm.schedules.key_date_offsets IS
  'Template schedules: days from the run date to each key date by key (default 0, the run date).';

-- What is due; a template's and a task's schedules; one live repeat per task.
CREATE INDEX IF NOT EXISTS idx_schedules_due ON pm.schedules (next_run_at) WHERE status = 'active' AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_schedules_template ON pm.schedules (template_id) WHERE template_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_schedules_project ON pm.schedules (project_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_schedules_one_repeat_per_task ON pm.schedules (task_id) WHERE kind = 'task' AND deleted_at IS NULL;

DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.schedules;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.schedules
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.schedules;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.schedules
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

ALTER TABLE pm.schedules ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.schedules FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.schedules TO service_role;

-- ---------------------------------------------------------------------------
-- Occurrences: each date a schedule ran for, once
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.schedule_occurrences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  schedule_id uuid NOT NULL REFERENCES pm.schedules(id),
  scheduled_for date NOT NULL,
  status text NOT NULL DEFAULT 'running',
  reason text,
  error text,
  attempts integer NOT NULL DEFAULT 1,
  -- The run a template schedule made, or the copy a task repeat made.
  run_id uuid REFERENCES pm.task_template_runs(id),
  task_id uuid REFERENCES pm.tasks(id),
  -- The copy a task repeat made it from.
  source_task_id uuid REFERENCES pm.tasks(id),
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.schedule_occurrences DROP CONSTRAINT IF EXISTS schedule_occurrences_values_check;
ALTER TABLE pm.schedule_occurrences
  ADD CONSTRAINT schedule_occurrences_values_check CHECK (
    status IN ('running', 'created', 'skipped', 'failed')
    AND attempts BETWEEN 1 AND 10
    AND (reason IS NULL OR length(reason) <= 80)
    AND (error IS NULL OR length(error) <= 2000)
  );

COMMENT ON TABLE pm.schedule_occurrences IS
  'One row per date a schedule ran for, never two (unique schedule_id, scheduled_for): created (run_id or task_id), skipped (reason) or failed (error; retried once, then the schedule pauses). Never removed. Server only.';

CREATE UNIQUE INDEX IF NOT EXISTS idx_schedule_occurrences_once ON pm.schedule_occurrences (schedule_id, scheduled_for);
CREATE INDEX IF NOT EXISTS idx_schedule_occurrences_recent ON pm.schedule_occurrences (schedule_id, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_schedule_occurrences_retry ON pm.schedule_occurrences (status) WHERE status IN ('failed', 'running');

DROP TRIGGER IF EXISTS forbid_hard_delete ON pm.schedule_occurrences;
CREATE TRIGGER forbid_hard_delete BEFORE DELETE ON pm.schedule_occurrences
  FOR EACH ROW EXECUTE FUNCTION pm.forbid_hard_delete();
DROP TRIGGER IF EXISTS forbid_truncate ON pm.schedule_occurrences;
CREATE TRIGGER forbid_truncate BEFORE TRUNCATE ON pm.schedule_occurrences
  FOR EACH STATEMENT EXECUTE FUNCTION pm.forbid_hard_delete();

ALTER TABLE pm.schedule_occurrences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.schedule_occurrences FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.schedule_occurrences TO service_role;

-- ---------------------------------------------------------------------------
-- Claiming an occurrence
-- ---------------------------------------------------------------------------
-- Moves the schedule on to (p_next_on, p_next_run_at, p_status) only while
-- it is active and next_run_at is still p_expected_run_at, then records the
-- occurrence for p_scheduled_for. Answers its id, or null when another run
-- claimed it first (nothing changes) or the date already has an
-- occurrence (the schedule still moves on; nothing is made twice).
CREATE OR REPLACE FUNCTION pm.claim_schedule_occurrence(
  p_schedule_id uuid,
  p_expected_run_at timestamptz,
  p_scheduled_for date,
  p_next_on date,
  p_next_run_at timestamptz,
  p_status text DEFAULT 'active',
  p_source_task_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_id uuid;
BEGIN
  UPDATE pm.schedules
  SET next_on = p_next_on,
      next_run_at = p_next_run_at,
      status = coalesce(p_status, 'active'),
      done_on = NULL,
      updated_at = now()
  WHERE id = p_schedule_id
    AND status = 'active'
    AND deleted_at IS NULL
    AND next_run_at IS NOT DISTINCT FROM p_expected_run_at;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  INSERT INTO pm.schedule_occurrences (schedule_id, scheduled_for, source_task_id)
  VALUES (p_schedule_id, p_scheduled_for, p_source_task_id)
  ON CONFLICT (schedule_id, scheduled_for) DO NOTHING
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION pm.claim_schedule_occurrence(uuid, timestamptz, date, date, timestamptz, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.claim_schedule_occurrence(uuid, timestamptz, date, date, timestamptz, text, uuid) TO service_role;

-- ---------------------------------------------------------------------------
-- After done: completing the followed task makes its repeat due now
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.schedule_after_done()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  UPDATE pm.schedules s
  SET next_run_at = now(),
      done_on = (now() AT TIME ZONE s.timezone)::date,
      updated_at = now()
  WHERE s.kind = 'task'
    AND s.task_id = NEW.id
    AND s.mode = 'after_done'
    AND s.status = 'active'
    AND s.deleted_at IS NULL
    AND s.next_run_at IS NULL;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.schedule_after_done() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS schedule_after_done ON pm.tasks;
CREATE TRIGGER schedule_after_done
  AFTER UPDATE OF status ON pm.tasks
  FOR EACH ROW
  WHEN (NEW.status = 'done' AND OLD.status IS DISTINCT FROM 'done')
  EXECUTE FUNCTION pm.schedule_after_done();

-- ---------------------------------------------------------------------------
-- The kick: pg_cron wakes the app while a schedule is due
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.schedules_kick()
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  app_url text;
  secret text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.schedules s
    WHERE s.status = 'active' AND s.deleted_at IS NULL AND s.next_run_at <= now()
  ) AND NOT EXISTS (
    SELECT 1 FROM pm.schedule_occurrences o
    JOIN pm.schedules s ON s.id = o.schedule_id
    WHERE s.status IN ('active', 'ended') AND s.deleted_at IS NULL
      AND ((o.status = 'failed' AND o.attempts < 2) OR (o.status = 'running' AND o.started_at < now() - interval '15 minutes'))
  ) THEN
    RETURN NULL;
  END IF;

  SELECT decrypted_secret INTO app_url FROM vault.decrypted_secrets WHERE name = 'pm_webhook_scheduler_url';
  SELECT decrypted_secret INTO secret FROM vault.decrypted_secrets WHERE name = 'pm_webhook_scheduler_secret';
  IF app_url IS NULL OR secret IS NULL THEN
    RAISE NOTICE 'webhook_scheduler_url or webhook_scheduler_secret is missing from Vault; schedules wait until the app sets up its scheduler';
    RETURN NULL;
  END IF;

  RETURN net.http_post(
    url := rtrim(app_url, '/') || '/api/internal/schedules/run',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || secret),
    body := '{"source":"pg_cron"}'::jsonb,
    timeout_milliseconds := 60000
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.schedules_kick() FROM PUBLIC, anon, authenticated, service_role;

-- Supabase only: skipped where pg_cron or pg_net is unavailable (PGlite).
-- Re-running cron.schedule updates the job in place.
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron')
     AND EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_net') THEN
    CREATE EXTENSION IF NOT EXISTS pg_cron;
    CREATE EXTENSION IF NOT EXISTS pg_net;
    PERFORM cron.schedule('pm-schedules-due', '*/5 * * * *', $job$SELECT pm.schedules_kick();$job$);
  ELSE
    RAISE NOTICE 'pg_cron or pg_net is unavailable here; schedules will not be kicked';
  END IF;
END;
$do$;

-- ---------------------------------------------------------------------------
-- Notifications about a schedule
-- ---------------------------------------------------------------------------
ALTER TABLE pm.team_member_notifications
  DROP CONSTRAINT IF EXISTS team_member_notifications_entity_type_check;
ALTER TABLE pm.team_member_notifications
  ADD CONSTRAINT team_member_notifications_entity_type_check
    CHECK (entity_type IN ('task', 'project', 'lead', 'comment', 'member', 'contact', 'suggestion', 'goal', 'question', 'invoice', 'reminder', 'webhook', 'schedule'));

-- ============================================================
-- ASSISTANT FIXES (20261127000100_assistant_fixes.sql)
-- ============================================================
-- Assistant fixes: off means on hold, honest chat status, company agents in one step.
--
-- - pm.api_request_gate also answers assistants_off: true for a personal
--   agent (team_members.delegate_of set) while assistants are switched off
--   for the workspace (business_settings.assistants_enabled false). The app
--   refuses its writes with 423, as for any hold; reads, heartbeats and
--   telemetry still work. Everything else it answers is unchanged.
-- - pm.chat_connections.last_refused_at: the last request to a connection's
--   inbound address that failed the provider's check (a wrong Slack signing
--   secret, an old Discord relay secret). Settings > Assistants reads it as
--   "Not receiving" until a verified request arrives after it.
-- - pm.set_chat_connection_agents: the company agents a company connection
--   reaches, and its default, set in one transaction, so removing an agent
--   and the channel mappings that go with it never half happens. Server only.
--
-- Additive and safe to run twice. The previous release's code ignores the
-- new gate field and column and never calls the new function.

-- ---------------------------------------------------------------------------
-- One gate per API request: the rate limit and what is paused
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.api_request_gate(
  p_api_key_id uuid,
  p_member_id uuid,
  p_default_limit integer DEFAULT 120,
  p_window_seconds integer DEFAULT 60
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_role text;
  v_agent_paused timestamptz;
  v_delegate_of uuid;
  v_rate integer;
  v_window pm.agent_rate_limit_windows%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_result jsonb;
  v_workspace_paused timestamptz;
  v_assistants_on boolean;
  v_projects uuid[];
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;
  IF p_default_limit <= 0 OR p_window_seconds <= 0 THEN RAISE EXCEPTION 'Invalid rate limit'; END IF;
  SELECT role, agent_paused_at, delegate_of INTO v_role, v_agent_paused, v_delegate_of FROM pm.team_members WHERE id = p_member_id;
  IF v_role = 'agent' THEN
    SELECT rate_per_minute INTO v_rate FROM pm.agent_limits WHERE agent_id = p_member_id;
  END IF;
  IF v_rate IS NOT NULL THEN
    INSERT INTO pm.agent_rate_limit_windows (agent_id, window_start, request_count)
    VALUES (p_member_id, v_now, 1)
    ON CONFLICT (agent_id) DO UPDATE
    SET window_start = CASE WHEN agent_rate_limit_windows.window_start + make_interval(secs => p_window_seconds) <= v_now THEN v_now ELSE agent_rate_limit_windows.window_start END,
        request_count = CASE WHEN agent_rate_limit_windows.window_start + make_interval(secs => p_window_seconds) <= v_now THEN 1 ELSE agent_rate_limit_windows.request_count + 1 END
    RETURNING * INTO v_window;
    v_result := jsonb_build_object(
      'allowed', v_window.request_count <= v_rate,
      'remaining', GREATEST(0, v_rate - v_window.request_count),
      'reset_at', v_window.window_start + make_interval(secs => p_window_seconds),
      'limit', v_rate,
      'scope', 'agent');
  ELSE
    SELECT to_jsonb(r) INTO v_result FROM pm.consume_api_rate_limit(p_api_key_id, p_default_limit, p_window_seconds) r;
    v_result := v_result || jsonb_build_object('limit', p_default_limit, 'scope', 'key');
  END IF;
  IF v_role = 'agent' THEN
    SELECT agents_paused_at, assistants_enabled INTO v_workspace_paused, v_assistants_on FROM pm.business_settings LIMIT 1;
    SELECT array_agg(project_id ORDER BY project_id) INTO v_projects
    FROM pm.project_agents WHERE agent_id = p_member_id AND status = 'paused';
  END IF;
  RETURN v_result || jsonb_build_object(
    'agent', v_role = 'agent',
    'workspace_paused_at', v_workspace_paused,
    'agent_paused_at', CASE WHEN v_role = 'agent' THEN v_agent_paused END,
    'assistants_off', v_role = 'agent' AND v_delegate_of IS NOT NULL AND v_assistants_on IS NOT TRUE,
    'paused_project_ids', to_jsonb(coalesce(v_projects, '{}'::uuid[])));
END;
$$;

REVOKE ALL ON FUNCTION pm.api_request_gate(uuid, uuid, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.api_request_gate(uuid, uuid, integer, integer) TO service_role;

-- ---------------------------------------------------------------------------
-- A chat connection's last refused request
-- ---------------------------------------------------------------------------
ALTER TABLE pm.chat_connections ADD COLUMN IF NOT EXISTS last_refused_at timestamptz;

COMMENT ON COLUMN pm.chat_connections.last_refused_at IS
  'The last request to its inbound address that failed the provider''s check (a wrong signing secret, an old relay secret). Not receiving while newer than last_inbound_at.';

-- ---------------------------------------------------------------------------
-- A company connection's agents, in one transaction
-- ---------------------------------------------------------------------------
-- Keeps the agents in p_agent_ids (adding the new ones), removes the rest
-- (their channel mappings go with them, by the foreign key), and marks
-- p_default as the default (none when null). The app checks each agent
-- first (a company agent that may act for people). Server only.
CREATE OR REPLACE FUNCTION pm.set_chat_connection_agents(
  p_connection_id uuid,
  p_agent_ids uuid[],
  p_default uuid,
  p_actor uuid
)
RETURNS void
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF p_default IS NOT NULL AND NOT (p_default = ANY (coalesce(p_agent_ids, '{}'::uuid[]))) THEN
    RAISE EXCEPTION 'The default agent must be one of the agents' USING ERRCODE = '22023';
  END IF;
  DELETE FROM pm.chat_connection_agents
  WHERE connection_id = p_connection_id AND NOT (agent_id = ANY (coalesce(p_agent_ids, '{}'::uuid[])));
  UPDATE pm.chat_connection_agents SET is_default = false WHERE connection_id = p_connection_id AND is_default;
  INSERT INTO pm.chat_connection_agents (connection_id, agent_id, created_by)
  SELECT p_connection_id, a, p_actor FROM unnest(coalesce(p_agent_ids, '{}'::uuid[])) AS a
  ON CONFLICT (connection_id, agent_id) DO NOTHING;
  IF p_default IS NOT NULL THEN
    UPDATE pm.chat_connection_agents SET is_default = true WHERE connection_id = p_connection_id AND agent_id = p_default;
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION pm.set_chat_connection_agents(uuid, uuid[], uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.set_chat_connection_agents(uuid, uuid[], uuid, uuid) TO service_role;

-- ============================================================
-- AGENTS HOME FIXES (20261127000200_agents_home_fixes.sql)
-- ============================================================
-- Agents home fixes: the run list says what each row shows.
--
-- - pm.agent_run_rows (a new view, security invoker, over pm.agent_run_feed):
--   every run feed row plus display_status, what the row's pill says and what
--   the Runs status filter matches. A stored run's status (already read as
--   timed_out by the watchdog's rule); a turn (always "succeeded" as a
--   process) by its outcome: blocked, failed, no_work, succeeded, or other
--   for a word outside these. runDisplayStatus in src/lib/agent-runs.ts is the
--   same rule for the browser. A new view, because pm.agent_run_feed keeps
--   its columns (a second run of the migrations that made it must still work).
-- - pm.agent_run_feed, same columns: a turn row carries its task (the
--   activity's own task reference, else a task_id in its metadata; it read
--   NULL before).
--
-- Additive and safe to run twice: CREATE OR REPLACE VIEW only.

CREATE OR REPLACE VIEW pm.agent_run_feed
WITH (security_invoker = true) AS
SELECT
  r.id,
  'run'::text AS source,
  r.agent_id,
  r.task_id,
  r.project_id,
  CASE
    WHEN r.status = 'running' AND r.updated_at < now() - interval '2 hours' THEN 'timed_out'
    WHEN r.status = 'waiting' AND r.updated_at < now() - interval '7 days' AND NOT pm.agent_run_has_open_question(r.id) THEN 'timed_out'
    ELSE r.status
  END AS status,
  NULL::text AS outcome,
  r.title,
  r.summary,
  r.model,
  r.trigger,
  r.started_at,
  r.finished_at,
  CASE WHEN r.finished_at IS NOT NULL THEN (extract(epoch FROM r.finished_at - r.started_at) * 1000)::bigint END AS duration_ms,
  r.tokens_in,
  r.tokens_out,
  r.cost_usd,
  r.external_id,
  r.external_url,
  r.started_at AS sort_at,
  r.updated_at
FROM pm.agent_runs r
UNION ALL
SELECT
  a.id,
  'turn'::text AS source,
  a.agent_id,
  coalesce(
    CASE WHEN a.reference_type = 'task' THEN a.reference_id END,
    CASE WHEN a.metadata->>'task_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (a.metadata->>'task_id')::uuid END
  ) AS task_id,
  a.project_id,
  'succeeded'::text AS status,
  a.metadata->>'outcome' AS outcome,
  a.title,
  NULL::text AS summary,
  a.metadata->>'model' AS model,
  CASE WHEN a.metadata->>'origin' = 'directed' THEN 'chat' ELSE 'scheduled' END AS trigger,
  coalesce(pm.agent_analytics_ts(a.metadata->>'started_at'), a.created_at) AS started_at,
  coalesce(pm.agent_analytics_ts(a.metadata->>'finished_at'), a.created_at) AS finished_at,
  pm.agent_analytics_int(a.metadata->>'duration_ms') AS duration_ms,
  CASE WHEN a.metadata->>'tokens_scope' = 'turn' AND a.metadata->'tokens' ? 'input'
    THEN pm.agent_analytics_int(a.metadata->'tokens'->>'input') END AS tokens_in,
  CASE WHEN a.metadata->>'tokens_scope' = 'turn' AND a.metadata->'tokens' ? 'output'
    THEN pm.agent_analytics_int(a.metadata->'tokens'->>'output') END AS tokens_out,
  NULL::numeric AS cost_usd,
  a.metadata->>'source_turn_id' AS external_id,
  NULL::text AS external_url,
  a.created_at AS sort_at,
  a.created_at AS updated_at
FROM pm.agent_activities a
WHERE a.activity_type = 'turn.completed'
  AND a.agent_id IS NOT NULL
  AND a.metadata->>'run_id' IS NULL
  AND NOT (a.metadata->>'origin' = 'scheduled' AND coalesce(a.metadata->>'outcome', '') IN ('idle', 'skipped', 'waiting'));

CREATE OR REPLACE VIEW pm.agent_run_rows
WITH (security_invoker = true) AS
SELECT
  f.id,
  f.source,
  f.agent_id,
  f.task_id,
  f.project_id,
  f.status,
  f.outcome,
  f.title,
  f.summary,
  f.model,
  f.trigger,
  f.started_at,
  f.finished_at,
  f.duration_ms,
  f.tokens_in,
  f.tokens_out,
  f.cost_usd,
  f.external_id,
  f.external_url,
  f.sort_at,
  f.updated_at,
  CASE
    WHEN f.source = 'run' OR f.status = 'running' THEN f.status
    WHEN lower(coalesce(f.outcome, '')) = 'blocked' THEN 'blocked'
    WHEN lower(coalesce(f.outcome, '')) IN ('failed', 'error') THEN 'failed'
    WHEN lower(coalesce(f.outcome, '')) IN ('idle', 'skipped', 'waiting', 'no_work', 'nothing', 'nothing_to_do') THEN 'no_work'
    WHEN lower(coalesce(f.outcome, '')) IN ('', 'work', 'worked', 'ok', 'done', 'shipped', 'succeeded') THEN 'succeeded'
    ELSE 'other'
  END AS display_status
FROM pm.agent_run_feed f;

COMMENT ON VIEW pm.agent_run_rows IS
  'The run feed (pm.agent_run_feed) with display_status: what a row shows and the Runs status filter matches (a run''s status, a turn''s outcome).';

REVOKE ALL ON pm.agent_run_rows FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.agent_run_rows TO authenticated;
GRANT SELECT ON pm.agent_run_rows TO service_role;

-- ============================================================
-- PROJECT AGENT FIXES (20261127000400_project_agent_fixes.sql)
-- ============================================================
-- Project agent fixes: losing access ends the setup, and pinning keeps freshness.
--
-- - pm.project_agents follows pm.project_members: when an agent's
--   membership of a project is removed (Edit project, Take off, a member
--   change over the API), its setup there (settings, instructions, a pause)
--   goes with it, so the Agents tab never lists an agent as set up on a
--   project it cannot open. Setups already left without access are not
--   touched here: the Agents tab marks them "No access".
-- - pm.project_context keeps updated_at when only pinned changes: pinning
--   or unpinning an old entry no longer reads as "Updated just now", and the
--   list keeps its order. Every other change stamps it as before.
--
-- Additive and safe to run twice: CREATE OR REPLACE FUNCTION and
-- DROP TRIGGER IF EXISTS before each CREATE TRIGGER. Works with the previous
-- release's code (it never relied on either behaviour).

CREATE OR REPLACE FUNCTION pm.end_project_agent_on_member_removed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  DELETE FROM pm.project_agents
  WHERE project_id = OLD.project_id AND agent_id = OLD.member_id;
  RETURN OLD;
END;
$$;

REVOKE ALL ON FUNCTION pm.end_project_agent_on_member_removed() FROM PUBLIC, anon, authenticated;

COMMENT ON FUNCTION pm.end_project_agent_on_member_removed() IS
  'Removes an agent''s setup on a project (pm.project_agents) when its project membership goes: no access, no setup.';

DROP TRIGGER IF EXISTS end_project_agent_on_member_removed ON pm.project_members;
CREATE TRIGGER end_project_agent_on_member_removed
  AFTER DELETE ON pm.project_members
  FOR EACH ROW EXECUTE FUNCTION pm.end_project_agent_on_member_removed();

CREATE OR REPLACE FUNCTION pm.handle_project_context_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF (to_jsonb(NEW) - 'pinned' - 'updated_at') = (to_jsonb(OLD) - 'pinned' - 'updated_at') THEN
    NEW.updated_at := OLD.updated_at;
  ELSE
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_project_context_updated_at() FROM PUBLIC, anon, authenticated;

COMMENT ON FUNCTION pm.handle_project_context_updated_at() IS
  'A context entry''s updated_at: stamped on every change except pinning or unpinning alone, so freshness reads what was written.';

DROP TRIGGER IF EXISTS set_project_context_updated_at ON pm.project_context;
CREATE TRIGGER set_project_context_updated_at
  BEFORE UPDATE ON pm.project_context
  FOR EACH ROW EXECUTE FUNCTION pm.handle_project_context_updated_at();

-- ============================================================
-- AI SETUP (20261127000500_ai_setup.sql)
-- ============================================================
-- Set up agents with AI: an Owner lets their own AI tool hire and configure
-- agents for one hour, from the first screen of Hire an agent.
--
-- - pm.ai_setup_sessions: one hour of agent setup by an AI tool, for one
--   person (an Owner). Either a connected AI tool (kind connection, its
--   pm.oauth_grants row), whose calls on the agent setup routes carry the
--   person's own API powers while the session lives, or a setup key (kind
--   key, an API key of the person's own that lasts as long as the session
--   and works on the setup routes only). scopes are the person's API powers
--   when the session started; every call is checked against their access
--   again. A session ends on its own at expires_at, or early (ended_at)
--   when the person ends it; ending a key session disables its key.
--   Server only: members hold nothing on it.
--
-- Additive and safe to run twice. The previous release's code never reads
-- the table and keeps working: no session exists until this release's code
-- makes one.

CREATE TABLE IF NOT EXISTS pm.ai_setup_sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  member_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  kind text NOT NULL,
  -- The connection it elevates (kind connection).
  grant_id uuid REFERENCES pm.oauth_grants(id) ON DELETE CASCADE,
  -- The key its calls come with: the connection's key, or the setup key.
  api_key_id uuid REFERENCES pm.api_keys(id) ON DELETE SET NULL,
  client_name text NOT NULL,
  scopes text[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  ended_at timestamptz,
  ended_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  CONSTRAINT ai_setup_sessions_kind_check CHECK (kind IN ('connection', 'key')),
  CONSTRAINT ai_setup_sessions_target_check CHECK (
    (kind = 'connection' AND grant_id IS NOT NULL) OR (kind = 'key' AND grant_id IS NULL)
  ),
  CONSTRAINT ai_setup_sessions_length_check CHECK (expires_at > created_at AND expires_at <= created_at + interval '2 hours')
);

COMMENT ON TABLE pm.ai_setup_sessions IS
  'One hour of agent setup by an AI tool for a person (an Owner): a connected tool elevated to the agent setup routes, or a setup key. Ends at expires_at or when ended early.';

CREATE INDEX IF NOT EXISTS idx_ai_setup_sessions_grant ON pm.ai_setup_sessions (grant_id) WHERE ended_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_ai_setup_sessions_key ON pm.ai_setup_sessions (api_key_id) WHERE ended_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_ai_setup_sessions_member ON pm.ai_setup_sessions (member_id, created_at DESC);

ALTER TABLE pm.ai_setup_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.ai_setup_sessions FROM PUBLIC, anon, authenticated;

-- ============================================================
-- KEY MANAGEMENT (20261127000600_key_management.sql)
-- ============================================================

-- API keys you can manage: a key can be paused and resumed.
--
-- - pm.api_keys.paused_at: when the key was paused (null: not paused). A
--   paused key keeps its secret, name and scopes, and is refused at sign-in
--   (401 api_key_paused) until someone who manages it resumes it, which
--   clears both columns. A revoke still ends it for good.
-- - pm.api_keys.paused_by: who paused it (null once that member is gone).
--   Pausing an agent's key never touches the agent's own pause.
-- - pm.rotate_api_key refuses a paused key under its row lock (HINT
--   key_paused), so a pause that lands while a rotation is checked never
--   leaves a working successor. Same signature and grants as before. (A
--   replaced key still in its overlap is refused at sign-in while its
--   successor is paused: the server checks that, no schema change.)
--
-- Additive and safe to run twice. The previous release's code never reads
-- either column and keeps working: no key is paused until this release's
-- code pauses one.

ALTER TABLE pm.api_keys
  ADD COLUMN IF NOT EXISTS paused_at timestamptz,
  ADD COLUMN IF NOT EXISTS paused_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL;

COMMENT ON COLUMN pm.api_keys.paused_at IS
  'When the key was paused (null: not paused). A paused key keeps its secret and is refused at sign-in until resumed.';
COMMENT ON COLUMN pm.api_keys.paused_by IS
  'The member who paused the key (null when not paused, or once that member is gone).';

CREATE OR REPLACE FUNCTION pm.rotate_api_key(
  p_key_id uuid, p_key_prefix text, p_key_hash text, p_created_by uuid, p_expires_at timestamptz, p_overlap_seconds integer
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_old pm.api_keys;
  v_new uuid;
BEGIN
  IF p_overlap_seconds IS NULL OR p_overlap_seconds < 0 OR p_overlap_seconds > 7 * 86400 THEN
    RAISE EXCEPTION 'The overlap is 0 to 7 days' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_old FROM pm.api_keys WHERE id = p_key_id FOR UPDATE;
  IF v_old.id IS NULL THEN
    RAISE EXCEPTION 'API key % does not exist', p_key_id USING ERRCODE = 'P0002';
  END IF;
  IF v_old.permissions = 'connection' THEN
    RAISE EXCEPTION 'API key % belongs to a connected app and cannot be rotated', p_key_id USING ERRCODE = '55000';
  END IF;
  IF v_old.revoked_at IS NOT NULL OR (v_old.expires_at IS NOT NULL AND v_old.expires_at <= now())
    OR EXISTS (SELECT 1 FROM pm.api_keys s WHERE s.rotated_from = p_key_id) THEN
    RAISE EXCEPTION 'API key % cannot be rotated: it is revoked, expired or already replaced', p_key_id USING ERRCODE = '55000';
  END IF;
  -- A paused key is not rotated: a working successor would undo the pause.
  IF v_old.paused_at IS NOT NULL THEN
    RAISE EXCEPTION 'API key % is paused: resume it before rotating it', p_key_id
      USING ERRCODE = '55000', HINT = 'key_paused';
  END IF;
  INSERT INTO pm.api_keys (name, key_prefix, key_hash, created_by, team_member_id, permissions, scopes, created_by_key_id, rotated_from, expires_at)
  VALUES (v_old.name, p_key_prefix, p_key_hash, p_created_by, v_old.team_member_id, v_old.permissions, v_old.scopes,
    v_old.created_by_key_id, v_old.id, p_expires_at)
  RETURNING id INTO v_new;
  UPDATE pm.api_keys SET expires_at = least(coalesce(expires_at, 'infinity'::timestamptz), now() + make_interval(secs => p_overlap_seconds))
  WHERE id = p_key_id;
  RETURN v_new;
END;
$$;

REVOKE ALL ON FUNCTION pm.rotate_api_key(uuid, text, text, uuid, timestamptz, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.rotate_api_key(uuid, text, text, uuid, timestamptz, integer) TO service_role;

-- ============================================================
-- NOTIFICATIONS FOUNDATION (20261127000700_notifications_foundation.sql)
-- ============================================================
-- Notifications foundation: what a notification is, done apart from read,
-- snoozes, and one feed the app and the API read.
--
-- - pm.team_member_notifications gains category (what kind of notice it is:
--   question_asked, invoice_drafts, task_comments and so on), project_id and
--   actor_id (where it hangs and who caused it, when known) and done_at
--   (finished with: hidden from Updates; done implies read, and marking it
--   unread again undoes done). is_read stays as it was.
-- - pm.notification_category: the category of a notice from its entity type,
--   entity id and title, for every producer that does not name one. A
--   trigger fills category, and project_id and actor_id where the entity
--   says, on insert, so code from the previous release that inserts rows or
--   calls the 6 argument upsert gets them too.
-- - pm.notification_is_receipt: notices that announce something waiting on
--   a person (a question or approval asked, an agent's findings nudge, an
--   inbox decision). That thing is listed in Needs you; its notice is only a
--   delivery receipt, never shown in Updates or counted as unread. A receipt
--   never comes from free text: question_asked and approval_requested only
--   for a notice about a real pm.questions row of that kind (as
--   notify_question_asked raises them), findings_nudge only for the project
--   nudge whose title sync_findings_notification clears by, inbox_decision
--   only when its producer names it.
-- - pm.upsert_notification gains an overload with category, project_id and
--   actor_id; the 6 argument form delegates to it. Raising a notice again
--   refreshes the person's unread one about the same thing only when both are
--   receipts or both are not, so a receipt never swallows an update (the
--   unread dedup index gains that split); it brings back one marked done
--   (unread, done_at cleared) rather than adding a second row.
-- - pm.member_snoozes (member_id, item_kind, item_id, until): a member hides
--   a question, task, suggestion or notification until a time. Read at read
--   time, so nothing runs when it wakes. A member reads and writes only
--   their own rows.
-- - pm.notification_feed, pm.notification_groups and
--   pm.notification_unread_count: a member's Updates (receipts, done,
--   cleared and snoozed left out), newest first and keyset paged; the same
--   grouped by what they are about (the latest row per entity with a
--   count); the unread count. Server only: the app passes the signed-in
--   member.
--
-- Additive and safe to run twice. The previous release's code reads and
-- writes notifications as before; the new columns fill themselves.

ALTER TABLE pm.team_member_notifications
  ADD COLUMN IF NOT EXISTS category text,
  ADD COLUMN IF NOT EXISTS project_id uuid REFERENCES pm.projects(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS actor_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS done_at timestamptz;

ALTER TABLE pm.team_member_notifications
  DROP CONSTRAINT IF EXISTS team_member_notifications_category_check;
ALTER TABLE pm.team_member_notifications
  ADD CONSTRAINT team_member_notifications_category_check
    CHECK (category IS NULL OR category ~ '^[a-z][a-z0-9_]{0,59}$');

COMMENT ON COLUMN pm.team_member_notifications.category IS
  'What kind of notice this is (question_asked, invoice_drafts, task_comments...). Filled from entity_type, entity_id and title when the producer names none.';
COMMENT ON COLUMN pm.team_member_notifications.done_at IS
  'Finished with: hidden from Updates. Done implies read; marking it unread clears it; raising the notice again clears it.';

-- A member's open Updates, newest first.
CREATE INDEX IF NOT EXISTS idx_team_member_notifications_open
  ON pm.team_member_notifications (user_id, created_at DESC)
  WHERE cleared_at IS NULL AND done_at IS NULL;

-- The category of a notice from what it is about, for producers that name
-- none. A receipt is never read from free text alone: question_asked and
-- approval_requested need a pm.questions row of that kind behind the notice;
-- inbox_decision is never worked out here. Mirrored by
-- notificationCategoryOf in src/lib/notifications.ts.
CREATE OR REPLACE FUNCTION pm.notification_category(p_entity_type text, p_entity_id text, p_title text)
RETURNS text
LANGUAGE plpgsql
STABLE
SET search_path = pm
AS $$
DECLARE
  v_kind text;
BEGIN
  IF p_entity_type = 'question' AND p_entity_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    SELECT q.kind INTO v_kind FROM pm.questions q WHERE q.id = p_entity_id::uuid;
  END IF;
  RETURN CASE
    WHEN p_entity_type = 'question' AND p_title LIKE '%expired without %' THEN 'question_expired'
    WHEN p_entity_type = 'question' AND v_kind = 'approval' AND p_title LIKE 'Approval request from %' THEN 'approval_requested'
    WHEN p_entity_type = 'question' AND v_kind = 'question' AND p_title LIKE 'Question from %' THEN 'question_asked'
    WHEN p_entity_type = 'question' AND p_title LIKE 'Reply draft ready%' THEN 'reply_draft'
    WHEN p_entity_type = 'project' AND p_title LIKE '%findings are waiting on you' THEN 'findings_nudge'
    WHEN p_entity_type = 'project' AND p_title = 'Retainer draft failed' THEN 'retainer_failed'
    WHEN p_entity_type = 'project' AND p_title LIKE '% ready for review' THEN 'client_comm_review'
    WHEN p_entity_type = 'member' AND p_title LIKE '% stopped responding' THEN 'agent_offline'
    WHEN p_entity_type = 'member' AND p_title LIKE '% is back' THEN 'agent_back'
    WHEN p_entity_type = 'member' AND p_title LIKE '% spent its budget' THEN 'agent_budget'
    WHEN p_entity_type = 'member' AND p_title LIKE '%assistant is %' THEN 'assistant_alert'
    WHEN p_entity_type = 'invoice' THEN 'invoice_drafts'
    WHEN p_entity_type = 'reminder' THEN 'reminder'
    WHEN p_entity_type = 'schedule' THEN 'schedule_paused'
    WHEN p_entity_type = 'webhook' THEN 'webhook_failing'
    WHEN p_entity_type IS NULL THEN 'general'
    ELSE p_entity_type
  END;
END;
$$;

REVOKE ALL ON FUNCTION pm.notification_category(text, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_category(text, text, text) TO service_role;

-- Notices that announce a Needs you item: delivery receipts. Mirrored by
-- RECEIPT_CATEGORIES in src/lib/notifications.ts. Members execute it: the
-- unread dedup index is on it, so marking their own notification read
-- evaluates it as them.
CREATE OR REPLACE FUNCTION pm.notification_is_receipt(p_category text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = pm
AS $$
  SELECT coalesce(p_category IN ('question_asked', 'approval_requested', 'findings_nudge', 'inbox_decision'), false)
$$;

REVOKE ALL ON FUNCTION pm.notification_is_receipt(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_is_receipt(text) TO authenticated, service_role;

-- Fills category, project_id and actor_id on insert, and keeps done and
-- read consistent: done marks it read, unread clears done.
CREATE OR REPLACE FUNCTION pm.notification_before_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_entity uuid;
BEGIN
  IF NEW.category IS NULL THEN
    NEW.category := pm.notification_category(NEW.entity_type, NEW.entity_id, NEW.title);
  END IF;
  IF TG_OP = 'INSERT' AND NEW.entity_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_entity := NEW.entity_id::uuid;
    IF NEW.project_id IS NULL THEN
      NEW.project_id := CASE NEW.entity_type
        WHEN 'project' THEN (SELECT p.id FROM pm.projects p WHERE p.id = v_entity)
        WHEN 'task' THEN (SELECT t.project_id FROM pm.tasks t WHERE t.id = v_entity)
        WHEN 'invoice' THEN (SELECT i.project_id FROM pm.project_invoices i WHERE i.id = v_entity)
        WHEN 'reminder' THEN (SELECT r.project_id FROM pm.reminders r WHERE r.id = v_entity)
        WHEN 'suggestion' THEN (SELECT s.project_id FROM pm.task_suggestions s WHERE s.id = v_entity)
        WHEN 'question' THEN (SELECT q.project_id FROM pm.questions q WHERE q.id = v_entity)
        WHEN 'schedule' THEN (SELECT s.project_id FROM pm.schedules s WHERE s.id = v_entity)
      END;
    END IF;
    IF NEW.actor_id IS NULL AND NEW.entity_type = 'question' THEN
      NEW.actor_id := (SELECT q.asked_by FROM pm.questions q WHERE q.id = v_entity);
    END IF;
  END IF;
  IF NEW.done_at IS NOT NULL AND NOT NEW.is_read THEN
    IF TG_OP = 'UPDATE' AND OLD.done_at IS NOT DISTINCT FROM NEW.done_at THEN
      NEW.done_at := NULL;
    ELSE
      NEW.is_read := true;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.notification_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS notification_before_write ON pm.team_member_notifications;
CREATE TRIGGER notification_before_write
  BEFORE INSERT OR UPDATE ON pm.team_member_notifications
  FOR EACH ROW EXECUTE FUNCTION pm.notification_before_write();

-- Rows from before: their category from what they say. Only rows without one.
UPDATE pm.team_member_notifications
SET category = pm.notification_category(entity_type, entity_id, title)
WHERE category IS NULL;

-- One unread notice per person and thing, a receipt apart from an update:
-- a question asked about a task never takes the place of an unread update
-- about it.
DROP INDEX IF EXISTS pm.idx_team_member_notifications_dedup;
CREATE UNIQUE INDEX idx_team_member_notifications_dedup
  ON pm.team_member_notifications (user_id, entity_type, entity_id, pm.notification_is_receipt(category))
  WHERE is_read = false;

-- Raises a notice: refreshes the person's unread one about the same thing
-- (a receipt only a receipt, an update only an update), else brings back the latest one of its kind they marked done, else adds
-- one. A null category is worked out from the entity type and title.
CREATE OR REPLACE FUNCTION pm.upsert_notification(
  p_user_id uuid,
  p_title text,
  p_message text,
  p_link text,
  p_entity_type text,
  p_entity_id text,
  p_category text,
  p_project_id uuid DEFAULT NULL,
  p_actor_id uuid DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_category text := coalesce(nullif(btrim(p_category), ''), pm.notification_category(p_entity_type, p_entity_id, p_title));
  v_done uuid;
BEGIN
  UPDATE pm.team_member_notifications
  SET title = p_title, message = p_message, link = p_link, created_at = now(), cleared_at = NULL, done_at = NULL,
      category = v_category, project_id = coalesce(p_project_id, project_id), actor_id = coalesce(p_actor_id, actor_id)
  WHERE user_id = p_user_id
    AND entity_type = p_entity_type
    AND entity_id = p_entity_id
    AND is_read = false
    AND pm.notification_is_receipt(category) = pm.notification_is_receipt(v_category);
  IF FOUND THEN
    RETURN;
  END IF;

  SELECT id INTO v_done
  FROM pm.team_member_notifications
  WHERE user_id = p_user_id
    AND entity_type = p_entity_type
    AND entity_id = p_entity_id
    AND category IS NOT DISTINCT FROM v_category
    AND done_at IS NOT NULL
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;
  IF v_done IS NOT NULL THEN
    UPDATE pm.team_member_notifications
    SET title = p_title, message = p_message, link = p_link, created_at = now(), cleared_at = NULL, done_at = NULL,
        is_read = false, project_id = coalesce(p_project_id, project_id), actor_id = coalesce(p_actor_id, actor_id)
    WHERE id = v_done;
    RETURN;
  END IF;

  INSERT INTO pm.team_member_notifications (user_id, title, message, link, entity_type, entity_id, category, project_id, actor_id)
  VALUES (p_user_id, p_title, p_message, p_link, p_entity_type, p_entity_id, v_category, p_project_id, p_actor_id);
END;
$$;

REVOKE ALL ON FUNCTION pm.upsert_notification(uuid, text, text, text, text, text, text, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.upsert_notification(uuid, text, text, text, text, text, text, uuid, uuid) TO service_role;

-- The 6 argument form, as every producer before this release calls it.
CREATE OR REPLACE FUNCTION pm.upsert_notification(
  p_user_id uuid,
  p_title text,
  p_message text,
  p_link text,
  p_entity_type text,
  p_entity_id text
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  PERFORM pm.upsert_notification(p_user_id, p_title, p_message, p_link, p_entity_type, p_entity_id, NULL::text, NULL::uuid, NULL::uuid);
END;
$$;

REVOKE ALL ON FUNCTION pm.upsert_notification(uuid, text, text, text, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.upsert_notification(uuid, text, text, text, text, text) TO service_role;

-- Snoozes: a member hides one item until a time.
CREATE TABLE IF NOT EXISTS pm.member_snoozes (
  member_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  item_kind text NOT NULL CHECK (item_kind IN ('question', 'task', 'suggestion', 'notification')),
  item_id uuid NOT NULL,
  until timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (member_id, item_kind, item_id)
);

COMMENT ON TABLE pm.member_snoozes IS
  'A member hides a question, task, suggestion or notification until a time. Applied when read; a passed until is ignored.';

ALTER TABLE pm.member_snoozes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS member_snoozes_own ON pm.member_snoozes;
CREATE POLICY member_snoozes_own ON pm.member_snoozes FOR ALL TO authenticated
  USING (member_id = pm.current_team_member_id())
  WITH CHECK (member_id = pm.current_team_member_id());

REVOKE ALL ON pm.member_snoozes FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON pm.member_snoozes TO authenticated;
GRANT ALL ON pm.member_snoozes TO service_role;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables
                   WHERE pubname = 'supabase_realtime' AND schemaname = 'pm' AND tablename = 'member_snoozes') THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE pm.member_snoozes;
    END IF;
  END IF;
END;
$$;

-- A member's Updates: view updates (not done), unread, or done (newest
-- done first). Receipts, cleared and snoozed rows never show. Keyset paged
-- on (created_at, id), or (done_at, id) for done.
CREATE OR REPLACE FUNCTION pm.notification_feed(
  p_member_id uuid,
  p_view text DEFAULT 'updates',
  p_limit integer DEFAULT 30,
  p_before_at timestamptz DEFAULT NULL,
  p_before_id uuid DEFAULT NULL
) RETURNS SETOF pm.team_member_notifications
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT n.*
  FROM pm.team_member_notifications n
  WHERE n.user_id = p_member_id
    AND n.cleared_at IS NULL
    AND NOT pm.notification_is_receipt(n.category)
    AND CASE p_view
      WHEN 'done' THEN n.done_at IS NOT NULL
      WHEN 'unread' THEN n.done_at IS NULL AND NOT n.is_read
      ELSE n.done_at IS NULL
    END
    AND NOT EXISTS (
      SELECT 1 FROM pm.member_snoozes s
      WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
    )
    AND (
      p_before_at IS NULL
      OR (CASE WHEN p_view = 'done' THEN n.done_at ELSE n.created_at END, n.id) < (p_before_at, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
    )
  ORDER BY CASE WHEN p_view = 'done' THEN n.done_at ELSE n.created_at END DESC, n.id DESC
  LIMIT least(greatest(coalesce(p_limit, 30), 1), 100)
$$;

REVOKE ALL ON FUNCTION pm.notification_feed(uuid, text, integer, timestamptz, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_feed(uuid, text, integer, timestamptz, uuid) TO service_role;

-- The same Updates grouped by what they are about (entity type and id; a
-- notice about nothing is its own group): the latest row of each group, how
-- many it holds and how many are unread, newest group first, keyset paged
-- on the latest row's (created_at, id).
CREATE OR REPLACE FUNCTION pm.notification_groups(
  p_member_id uuid,
  p_limit integer DEFAULT 30,
  p_before_at timestamptz DEFAULT NULL,
  p_before_id uuid DEFAULT NULL
) RETURNS TABLE (
  id uuid,
  title text,
  message text,
  link text,
  is_read boolean,
  entity_type text,
  entity_id text,
  category text,
  project_id uuid,
  actor_id uuid,
  created_at timestamptz,
  group_key text,
  group_count integer,
  unread_count integer
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  WITH open_rows AS (
    SELECT n.*,
      CASE WHEN n.entity_type IS NOT NULL AND n.entity_id IS NOT NULL
        THEN n.entity_type || ':' || n.entity_id ELSE 'notification:' || n.id::text END AS gkey
    FROM pm.team_member_notifications n
    WHERE n.user_id = p_member_id
      AND n.cleared_at IS NULL
      AND n.done_at IS NULL
      AND NOT pm.notification_is_receipt(n.category)
      AND NOT EXISTS (
        SELECT 1 FROM pm.member_snoozes s
        WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
      )
  ), ranked AS (
    SELECT o.*,
      row_number() OVER (PARTITION BY o.gkey ORDER BY o.created_at DESC, o.id DESC) AS rn,
      count(*) OVER (PARTITION BY o.gkey) AS cnt,
      count(*) FILTER (WHERE NOT o.is_read) OVER (PARTITION BY o.gkey) AS unread
    FROM open_rows o
  )
  SELECT r.id, r.title, r.message, r.link, r.is_read, r.entity_type, r.entity_id, r.category, r.project_id, r.actor_id,
    r.created_at, r.gkey, r.cnt::integer, r.unread::integer
  FROM ranked r
  WHERE r.rn = 1
    AND (p_before_at IS NULL OR (r.created_at, r.id) < (p_before_at, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
  ORDER BY r.created_at DESC, r.id DESC
  LIMIT least(greatest(coalesce(p_limit, 30), 1), 100)
$$;

REVOKE ALL ON FUNCTION pm.notification_groups(uuid, integer, timestamptz, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_groups(uuid, integer, timestamptz, uuid) TO service_role;

-- How many of a member's Updates are unread: the Notifications count.
CREATE OR REPLACE FUNCTION pm.notification_unread_count(p_member_id uuid)
RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT count(*)::integer
  FROM pm.team_member_notifications n
  WHERE n.user_id = p_member_id
    AND n.cleared_at IS NULL
    AND n.done_at IS NULL
    AND NOT n.is_read
    AND NOT pm.notification_is_receipt(n.category)
    AND NOT EXISTS (
      SELECT 1 FROM pm.member_snoozes s
      WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
    )
$$;

REVOKE ALL ON FUNCTION pm.notification_unread_count(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_unread_count(uuid) TO service_role;

-- ============================================================
-- ORCHESTRATORS AND WHO CAN USE AN AGENT (20261127001000_agent_hierarchy_access.sql)
-- ============================================================
-- Orchestrators and who can use an agent: company agents as an org chart,
-- with access managed at every level.
--
-- - pm.team_members.orchestrator_id: the agent a company agent works under
--   (its orchestrator). Only an agent has one, it is always another company
--   agent, never itself, never a loop, and a chart is at most 4 levels deep
--   (a top orchestrator and three levels under it). Personal agents
--   (delegate_of) are never in a chart. Null for every agent today: nothing
--   changes until someone sets one. Orchestrator changes take one lock, so
--   two at once never make a loop or too deep a chart. An agent that gets an
--   orchestrator has "pick up unassigned work" (agent_self_assign) turned
--   off; a manager can turn it on again.
-- - pm.team_members.reachable_directly (default true): people may use the
--   agent directly (give it a task, talk to it in chat). False: only through
--   its orchestrator. Only matters while it has an orchestrator.
-- - pm.team_members.ask_first (default false): work someone gives it waits
--   for one of its managers to approve (an approval asked to them), unless
--   that someone manages it.
-- - pm.agent_audience (agent_id, kind, ref, effect): who can use an agent.
--   kind everyone (no ref), role (owner, admin, member or guest), group (a
--   group id) or member (a person's id); effect include or exclude. An agent
--   with no include rows admits everyone who may otherwise give it work, as
--   today; an exclude row always wins. Written by the server only; members
--   with team.read (and the agent itself) read it.
-- - pm.member_may_use_agent(agent, member): the agent's own audience AND
--   every orchestrator's above it. A personal agent admits only its own person.
--   Server only.
-- - pm.agent_audience_members(agent): the active people who may use it, for
--   the "N people can use it" preview. Server only.
-- - pm.member_manages_agent(agent, member): a workspace Owner, a member with
--   team.manage, or one of the agent's owners (in person or through a
--   group). Server only.
-- - pm.replace_agent_audience(agent, rows, created_by): replaces an agent's
--   audience in one transaction, so a failure leaves the old rows. Server
--   only.
-- - A signed-in member who assigns a company agent to a task (the browser
--   and pm.save_task, a new row or a row changed to point at the agent) is
--   checked by the database: refused when the agent is only reachable
--   through its orchestrator, when they are not in its audience, or when it asks
--   first and none of its managers approved that task for them. Personal
--   agents keep today's behaviour. Server routes (the API, MCP, chat) check
--   the same rules in code, where they know the person a chain of agents
--   works for.
-- - One open ask-first approval per agent, asker and piece of work: a
--   unique index on pm.questions.
-- - pm.agent_status also answers assistants_off for a personal agent while
--   assistants are switched off for the workspace (get_my_status).
--
-- Additive and safe to run twice. The previous release's code reads and
-- writes agents as before: no orchestrator, no audience rows, reachable, never asks.

ALTER TABLE pm.team_members
  ADD COLUMN IF NOT EXISTS orchestrator_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS reachable_directly boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS ask_first boolean NOT NULL DEFAULT false;

ALTER TABLE pm.team_members DROP CONSTRAINT IF EXISTS team_members_orchestrator_not_self;
ALTER TABLE pm.team_members
  ADD CONSTRAINT team_members_orchestrator_not_self CHECK (orchestrator_id IS NULL OR orchestrator_id <> id);

COMMENT ON COLUMN pm.team_members.orchestrator_id IS
  'The company agent this agent works under (its orchestrator). Agents only; no loops; at most 4 levels. Work reaches it only from its orchestrator.';
COMMENT ON COLUMN pm.team_members.reachable_directly IS
  'People may use the agent directly. False: only through its orchestrator (matters only while it has one).';
COMMENT ON COLUMN pm.team_members.ask_first IS
  'Work given to the agent waits for one of its managers to approve, unless the giver manages it.';

-- The agents under an orchestrator.
CREATE INDEX IF NOT EXISTS idx_team_members_orchestrator ON pm.team_members (orchestrator_id) WHERE orchestrator_id IS NOT NULL;

-- An orchestrator is a company agent; the chart has no loops and at most 4 levels.
CREATE OR REPLACE FUNCTION pm.team_members_orchestrator_guard()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
DECLARE
  v_at uuid;
  v_above integer := 0;
  v_below integer := 0;
BEGIN
  -- One orchestrator change at a time: two moves at once never make a loop or too deep a chart.
  PERFORM pg_advisory_xact_lock(hashtext('pm.team_members.orchestrator_id'));
  IF NEW.orchestrator_id IS NULL THEN
    -- A personal agent is never an orchestrator.
    IF NEW.delegate_of IS NOT NULL AND EXISTS (SELECT 1 FROM pm.team_members r WHERE r.orchestrator_id = NEW.id) THEN
      RAISE EXCEPTION 'agent_orchestrator_personal: a personal agent is never an orchestrator of other agents' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.role IS DISTINCT FROM 'agent' THEN
    RAISE EXCEPTION 'agent_orchestrator_agents_only: only an agent works under an orchestrator' USING ERRCODE = '23514';
  END IF;
  IF NEW.delegate_of IS NOT NULL THEN
    RAISE EXCEPTION 'agent_orchestrator_personal: a personal agent never works under an orchestrator' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pm.team_members l WHERE l.id = NEW.orchestrator_id AND l.role = 'agent' AND l.delegate_of IS NULL) THEN
    RAISE EXCEPTION 'agent_orchestrator_not_agent: an orchestrator is a company agent' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.orchestrator_id IS NOT DISTINCT FROM OLD.orchestrator_id
    AND NEW.role IS NOT DISTINCT FROM OLD.role AND NEW.delegate_of IS NOT DISTINCT FROM OLD.delegate_of THEN
    RETURN NEW;
  END IF;
  -- Up from the orchestrator: never back to this agent.
  v_at := NEW.orchestrator_id;
  WHILE v_at IS NOT NULL LOOP
    IF v_at = NEW.id THEN
      RAISE EXCEPTION 'agent_orchestrator_loop: that orchestrator already works under this agent' USING ERRCODE = '23514';
    END IF;
    v_above := v_above + 1;
    IF v_above > 4 THEN
      RAISE EXCEPTION 'agent_orchestrator_too_deep: a chart of agents is at most 4 levels deep' USING ERRCODE = '23514';
    END IF;
    SELECT l.orchestrator_id INTO v_at FROM pm.team_members l WHERE l.id = v_at;
  END LOOP;
  -- Down from this agent: the levels it brings with it.
  WITH RECURSIVE below AS (
    SELECT r.id, 1 AS depth FROM pm.team_members r WHERE r.orchestrator_id = NEW.id
    UNION ALL
    SELECT r.id, b.depth + 1 FROM pm.team_members r JOIN below b ON r.orchestrator_id = b.id WHERE b.depth < 5
  )
  SELECT coalesce(max(depth), 0) INTO v_below FROM below;
  IF v_above + 1 + v_below > 4 THEN
    RAISE EXCEPTION 'agent_orchestrator_too_deep: a chart of agents is at most 4 levels deep' USING ERRCODE = '23514';
  END IF;
  -- A sub-agent goes through its orchestrator: getting an orchestrator turns
  -- off picking up unassigned work; one of its managers can turn it back on
  -- afterwards.
  IF TG_OP = 'INSERT' OR OLD.orchestrator_id IS NULL THEN
    NEW.agent_self_assign := false;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.team_members_orchestrator_guard() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS team_members_orchestrator_guard ON pm.team_members;
CREATE TRIGGER team_members_orchestrator_guard
  BEFORE INSERT OR UPDATE OF orchestrator_id, role, delegate_of ON pm.team_members
  FOR EACH ROW EXECUTE FUNCTION pm.team_members_orchestrator_guard();

-- ---------------------------------------------------------------------------
-- Who can use an agent
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.agent_audience (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  kind text NOT NULL,
  ref text,
  effect text NOT NULL DEFAULT 'include',
  created_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.agent_audience DROP CONSTRAINT IF EXISTS agent_audience_kind_check;
ALTER TABLE pm.agent_audience
  ADD CONSTRAINT agent_audience_kind_check CHECK (kind IN ('everyone', 'role', 'group', 'member'));
ALTER TABLE pm.agent_audience DROP CONSTRAINT IF EXISTS agent_audience_effect_check;
ALTER TABLE pm.agent_audience
  ADD CONSTRAINT agent_audience_effect_check CHECK (effect IN ('include', 'exclude'));
ALTER TABLE pm.agent_audience DROP CONSTRAINT IF EXISTS agent_audience_ref_check;
ALTER TABLE pm.agent_audience
  ADD CONSTRAINT agent_audience_ref_check CHECK (
    (kind = 'everyone' AND ref IS NULL)
    OR (kind = 'role' AND ref IN ('owner', 'admin', 'member', 'guest'))
    OR (kind IN ('group', 'member') AND ref ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  );

COMMENT ON TABLE pm.agent_audience IS
  'Who can use an agent: everyone, a role, a group or a person, included or excluded. No include rows: everyone who may otherwise give it work. Exclude wins. Effective audience is this AND every orchestrator''s above it. Written by the server only.';

-- One row per subject on an agent.
CREATE UNIQUE INDEX IF NOT EXISTS agent_audience_subject ON pm.agent_audience (agent_id, kind, coalesce(ref, ''));

-- Only an agent has an audience, and a personal agent never has one (it is its person's).
CREATE OR REPLACE FUNCTION pm.handle_agent_audience_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pm.team_members m WHERE m.id = NEW.agent_id AND m.role = 'agent' AND m.delegate_of IS NULL) THEN
    RAISE EXCEPTION 'agent_audience_agents_only: only a company agent has an audience' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.handle_agent_audience_before_write() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS agent_audience_before_write ON pm.agent_audience;
CREATE TRIGGER agent_audience_before_write
  BEFORE INSERT OR UPDATE ON pm.agent_audience
  FOR EACH ROW EXECUTE FUNCTION pm.handle_agent_audience_before_write();

ALTER TABLE pm.agent_audience ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS agent_audience_select ON pm.agent_audience;
CREATE POLICY agent_audience_select ON pm.agent_audience FOR SELECT TO authenticated
  USING (pm.has_permission('team.read') OR agent_id = pm.current_team_member_id());

DROP POLICY IF EXISTS agent_audience_module_on ON pm.agent_audience;
CREATE POLICY agent_audience_module_on ON pm.agent_audience AS RESTRICTIVE FOR ALL TO authenticated
  USING ((select pm.module_enabled('agents')));

REVOKE ALL ON pm.agent_audience FROM PUBLIC, anon, authenticated;
GRANT SELECT ON pm.agent_audience TO authenticated;
GRANT ALL ON pm.agent_audience TO service_role;

-- Replaces an agent's audience with exactly these rows ([{ kind, ref,
-- effect }]), in one transaction: a row the table refuses leaves the old
-- audience as it was. Kept in the order given.
CREATE OR REPLACE FUNCTION pm.replace_agent_audience(p_agent uuid, p_rows jsonb, p_created_by uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'replace_agent_audience: rows must be a JSON array' USING ERRCODE = '22023';
  END IF;
  DELETE FROM pm.agent_audience WHERE agent_id = p_agent;
  INSERT INTO pm.agent_audience (agent_id, kind, ref, effect, created_by, created_at)
  SELECT p_agent, r.value->>'kind', r.value->>'ref', coalesce(r.value->>'effect', 'include'), p_created_by,
    now() + ((r.ordinality - 1) * interval '1 millisecond')
  FROM jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) WITH ORDINALITY AS r(value, ordinality);
END;
$$;

REVOKE ALL ON FUNCTION pm.replace_agent_audience(uuid, jsonb, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.replace_agent_audience(uuid, jsonb, uuid) TO service_role;

-- Whether a member may use an agent: its own audience and every orchestrator's above it.
CREATE OR REPLACE FUNCTION pm.member_may_use_agent(p_agent uuid, p_member uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_role text;
  v_delegate uuid;
  v_member_role text;
  v_member_status text;
  v_at uuid;
  v_seen uuid[] := '{}';
BEGIN
  SELECT role, delegate_of INTO v_role, v_delegate FROM pm.team_members WHERE id = p_agent;
  IF NOT FOUND OR v_role IS DISTINCT FROM 'agent' THEN
    RETURN false;
  END IF;
  -- A personal agent works for its own person only.
  IF v_delegate IS NOT NULL THEN
    RETURN p_member IS NOT DISTINCT FROM v_delegate;
  END IF;
  SELECT role, coalesce(status, 'active') INTO v_member_role, v_member_status FROM pm.team_members WHERE id = p_member;
  IF NOT FOUND OR v_member_status <> 'active' THEN
    RETURN false;
  END IF;
  v_at := p_agent;
  WHILE v_at IS NOT NULL AND NOT (v_at = ANY (v_seen)) AND cardinality(v_seen) < 8 LOOP
    -- Include rows narrow it to who they name; none admits everyone.
    IF EXISTS (SELECT 1 FROM pm.agent_audience a WHERE a.agent_id = v_at AND a.effect = 'include')
      AND NOT EXISTS (
        SELECT 1 FROM pm.agent_audience a
        WHERE a.agent_id = v_at AND a.effect = 'include'
          AND (a.kind = 'everyone'
            OR (a.kind = 'role' AND a.ref = v_member_role)
            OR (a.kind = 'member' AND a.ref = p_member::text)
            OR (a.kind = 'group' AND EXISTS (
              SELECT 1 FROM pm.group_members gm JOIN pm.groups g ON g.id = gm.group_id AND g.deleted_at IS NULL
              WHERE gm.group_id::text = a.ref AND gm.member_id = p_member)))
      ) THEN
      RETURN false;
    END IF;
    -- An exclude row always wins.
    IF EXISTS (
      SELECT 1 FROM pm.agent_audience a
      WHERE a.agent_id = v_at AND a.effect = 'exclude'
        AND (a.kind = 'everyone'
          OR (a.kind = 'role' AND a.ref = v_member_role)
          OR (a.kind = 'member' AND a.ref = p_member::text)
          OR (a.kind = 'group' AND EXISTS (
            SELECT 1 FROM pm.group_members gm JOIN pm.groups g ON g.id = gm.group_id AND g.deleted_at IS NULL
            WHERE gm.group_id::text = a.ref AND gm.member_id = p_member)))
    ) THEN
      RETURN false;
    END IF;
    v_seen := v_seen || v_at;
    SELECT orchestrator_id INTO v_at FROM pm.team_members WHERE id = v_at;
  END LOOP;
  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION pm.member_may_use_agent(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.member_may_use_agent(uuid, uuid) TO service_role;

-- The active people who may use an agent (agents and suspended members left out).
CREATE OR REPLACE FUNCTION pm.agent_audience_members(p_agent uuid)
RETURNS TABLE (member_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT m.id FROM pm.team_members m
  WHERE m.role <> 'agent' AND coalesce(m.status, 'active') = 'active' AND pm.member_may_use_agent(p_agent, m.id)
  ORDER BY m.name, m.id
$$;

REVOKE ALL ON FUNCTION pm.agent_audience_members(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_audience_members(uuid) TO service_role;

-- Whether a member manages an agent: a workspace Owner, team.manage, or one of its owners.
CREATE OR REPLACE FUNCTION pm.member_manages_agent(p_agent uuid, p_member uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT p_agent IS DISTINCT FROM p_member AND EXISTS (
    SELECT 1 FROM pm.team_members m
    WHERE m.id = p_member AND coalesce(m.status, 'active') = 'active' AND m.role <> 'agent'
      AND (m.role = 'owner'
        OR EXISTS (SELECT 1 FROM pm.team_member_permissions p
          WHERE p.member_id = m.id AND p.permission_key = 'team.manage' AND p.access_channel = 'app' AND p.effect = 'allow')
        OR (EXISTS (SELECT 1 FROM pm.role_permissions r
          WHERE r.role = m.role AND r.permission_key = 'team.manage' AND r.access_channel = 'app')
          AND NOT EXISTS (SELECT 1 FROM pm.team_member_permissions p
            WHERE p.member_id = m.id AND p.permission_key = 'team.manage' AND p.access_channel = 'app' AND p.effect = 'deny'))
        OR EXISTS (SELECT 1 FROM pm.agent_owners o WHERE o.agent_id = p_agent AND o.member_id = m.id)
        OR EXISTS (SELECT 1 FROM pm.agent_owner_groups og
          JOIN pm.groups g ON g.id = og.group_id AND g.deleted_at IS NULL
          JOIN pm.group_members gm ON gm.group_id = og.group_id AND gm.member_id = m.id
          WHERE og.agent_id = p_agent))
  )
$$;

REVOKE ALL ON FUNCTION pm.member_manages_agent(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.member_manages_agent(uuid, uuid) TO service_role;

-- ---------------------------------------------------------------------------
-- A signed-in member assigning an agent
-- ---------------------------------------------------------------------------
-- The browser and pm.save_task write task_assignees as the member. A
-- company agent newly on a task (a new row, or a row changed to another
-- agent or task) is refused when it is only reachable through its orchestrator,
-- when the member is not in its audience, or when it asks first and none of
-- its managers approved this task for this member (the approval answered by
-- someone who manages it). An assignment already there (a save that keeps
-- it), personal agents (today's behaviour) and server writes (no signed-in
-- member: the server checks in code) pass.
CREATE OR REPLACE FUNCTION pm.guard_agent_assignment()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_actor uuid := pm.current_team_member_id();
  v_role text;
  v_delegate uuid;
  v_orchestrator uuid;
  v_reachable boolean;
  v_ask boolean;
BEGIN
  IF v_actor IS NULL OR v_actor = NEW.member_id THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.member_id = OLD.member_id AND NEW.task_id = OLD.task_id THEN
    RETURN NEW;
  END IF;
  SELECT role, delegate_of, orchestrator_id, reachable_directly, ask_first INTO v_role, v_delegate, v_orchestrator, v_reachable, v_ask
  FROM pm.team_members WHERE id = NEW.member_id;
  IF NOT FOUND OR v_role IS DISTINCT FROM 'agent' OR v_delegate IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM pm.task_assignees a WHERE a.task_id = NEW.task_id AND a.member_id = NEW.member_id) THEN
    RETURN NEW;
  END IF;
  IF v_orchestrator IS NOT NULL AND NOT v_reachable THEN
    RAISE EXCEPTION 'agent_not_available: this agent takes work only through its orchestrator'
      USING ERRCODE = '42501', HINT = 'Give the task to its orchestrator instead.';
  END IF;
  IF NOT pm.member_may_use_agent(NEW.member_id, v_actor) THEN
    RAISE EXCEPTION 'agent_not_available: you cannot give this agent work'
      USING ERRCODE = '42501', HINT = 'Ask one of its managers to add you to who can use it.';
  END IF;
  IF v_ask AND NOT pm.member_manages_agent(NEW.member_id, v_actor) AND NOT EXISTS (
    SELECT 1 FROM pm.questions q
    WHERE q.kind = 'approval' AND q.deleted_at IS NULL AND q.status = 'answered' AND q.answer_choice = 'approve'
      AND q.action->>'type' = 'agent.use'
      AND q.action->'details'->>'key' = NEW.member_id::text || ':' || v_actor::text || ':task:' || NEW.task_id::text
      AND pm.member_manages_agent(NEW.member_id, q.answered_by)
  ) THEN
    RAISE EXCEPTION 'agent_ask_first: this agent asks its managers before it takes work'
      USING ERRCODE = '42501', HINT = 'Ask its managers to approve this task for you first.';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.guard_agent_assignment() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS guard_agent_assignment ON pm.task_assignees;
CREATE TRIGGER guard_agent_assignment
  BEFORE INSERT OR UPDATE OF member_id, task_id ON pm.task_assignees
  FOR EACH ROW EXECUTE FUNCTION pm.guard_agent_assignment();

-- When an ask-first approval for a new task was used (it makes one task).
-- Null for every other question.
ALTER TABLE pm.questions ADD COLUMN IF NOT EXISTS used_at timestamptz;

COMMENT ON COLUMN pm.questions.used_at IS
  'An ask-first approval (action type agent.use) for a new task: when the one task it allows was made. Set by the server only.';

-- One open ask-first approval per agent, asker and piece of work: two
-- requests at once make one approval (the second reads the first).
CREATE UNIQUE INDEX IF NOT EXISTS questions_open_agent_use ON pm.questions ((action->'details'->>'key'))
  WHERE kind = 'approval' AND status = 'open' AND deleted_at IS NULL AND action->>'type' = 'agent.use';

-- ---------------------------------------------------------------------------
-- What an agent checks before each turn: assistants switched off
-- ---------------------------------------------------------------------------
-- As before, plus assistants_off: true for a personal agent while assistants
-- are switched off for the workspace (it is on hold, as pm.api_request_gate
-- says on every write).
CREATE OR REPLACE FUNCTION pm.agent_status(p_member_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_role text;
  v_delegate_of uuid;
  v_agent_paused timestamptz;
  v_workspace_paused timestamptz;
  v_assistants_on boolean;
  v_state jsonb;
  v_period text;
BEGIN
  SELECT role, agent_paused_at, delegate_of INTO v_role, v_agent_paused, v_delegate_of FROM pm.team_members WHERE id = p_member_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF v_role IS DISTINCT FROM 'agent' THEN
    RETURN jsonb_build_object('agent', false, 'workspace_paused_at', NULL, 'agent_paused_at', NULL, 'assistants_off', false, 'state', NULL);
  END IF;
  SELECT s.agents_paused_at INTO v_workspace_paused FROM pm.business_settings s ORDER BY s.agents_paused_at NULLS LAST LIMIT 1;
  SELECT s.assistants_enabled INTO v_assistants_on FROM pm.business_settings s LIMIT 1;
  v_state := pm.agent_limit_state(p_member_id, true);
  v_period := coalesce(v_state->'limits'->>'budget_period', 'month');
  RETURN jsonb_build_object(
    'agent', true,
    'workspace_paused_at', v_workspace_paused,
    'agent_paused_at', v_agent_paused,
    'assistants_off', v_delegate_of IS NOT NULL AND v_assistants_on IS NOT TRUE,
    'budget_period', v_period,
    'period_end', (date_trunc(v_period, now() AT TIME ZONE 'UTC') + ('1 ' || v_period)::interval) AT TIME ZONE 'UTC',
    'state', v_state);
END;
$$;

REVOKE ALL ON FUNCTION pm.agent_status(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_status(uuid) TO service_role;

-- ============================================================
-- EVENT FEED (20261127001100_event_feed.sql)
-- ============================================================
-- The event feed: what an agent harness with no public address long-polls
-- (GET /api/v1/events?since=&wait=, MCP get_events), and the wake signal
-- behind GET /api/v1/chat/messages?wait=.
--
-- - pm.event_feed: one row per event a harness may hear, written by AFTER
--   triggers, so every writer (REST, MCP, the app, the watchdog, provider
--   webhooks) feeds it:
--   chat.message (an inbound chat message routed to an agent: inserted
--   routed, re-routed, or released after it was held), question.answered,
--   question.cancelled and question.expired (to the member who asked),
--   run.updated (an agent's run started or changed status, with who changed
--   it) and agent_event.created (any agent event; the API reads these by
--   project, as GET /api/v1/agent-activities does). Rows carry ids and
--   status only: the API composes what each caller may read.
-- - Order: (change_txid, seq), as the agent event export. A row is served
--   only once every transaction below its own has ended, so a cursor never
--   passes a row that commits late. A write transaction left open holds the
--   feed back until it ends.
-- - Retention: pm.prune_event_feed deletes rows older than 7 days (pg_cron
--   pm-event-feed-prune, hourly), in batches, and records the position it
--   pruned through in pm.event_feed_state, in the same transaction. A
--   cursor below that position answers 410 resync, never a silent gap.
-- - pm.event_feed_waits: the long-poll waits open per API key, each a lease
--   that ends by itself if its server dies. pm.event_feed_wait_begin
--   refuses a wait beyond the API's limit (2 per key) and says when the
--   earliest open one ends.
-- - pm.event_feed_read (a page after a cursor, for one caller's filters)
--   and pm.event_feed_heads (the newest visible position per waiting member
--   and per project a wait reads agent events on, one cheap indexed probe a
--   server shares across all its open waits).
--
-- Server only. Additive and safe to run twice. 2.0.49 code never reads the
-- new tables; the triggers only add rows beside what they did before.

-- ---------------------------------------------------------------------------
-- The feed
-- ---------------------------------------------------------------------------
CREATE SEQUENCE IF NOT EXISTS pm.event_feed_seq;
REVOKE ALL ON SEQUENCE pm.event_feed_seq FROM PUBLIC, anon, authenticated;
GRANT USAGE, SELECT ON SEQUENCE pm.event_feed_seq TO service_role;

CREATE TABLE IF NOT EXISTS pm.event_feed (
  seq bigint PRIMARY KEY DEFAULT nextval('pm.event_feed_seq'),
  -- The transaction that wrote the row: the feed orders by (change_txid, seq).
  change_txid bigint NOT NULL DEFAULT (pg_current_xact_id()::text::bigint),
  event_type text NOT NULL,
  -- Who it is routed to (chat.message, question.*, run.updated); null for
  -- agent_event.created, which is read by project.
  member_id uuid,
  -- The agent it is about.
  agent_id uuid,
  project_id uuid,
  subject_type text NOT NULL,
  subject_id uuid NOT NULL,
  -- agent_event.created: the agent event's own type (work.done, ...).
  agent_event_type text,
  data jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE pm.event_feed IS
  'Events a harness long-polls (GET /api/v1/events): ids and status only, ordered by (change_txid, seq), kept 7 days (pm.prune_event_feed). Server only.';

CREATE INDEX IF NOT EXISTS idx_event_feed_member
  ON pm.event_feed (member_id, change_txid, seq) WHERE member_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_event_feed_agent_events
  ON pm.event_feed (change_txid, seq) WHERE event_type = 'agent_event.created';
CREATE INDEX IF NOT EXISTS idx_event_feed_agent_events_project
  ON pm.event_feed (project_id, change_txid, seq) WHERE event_type = 'agent_event.created';
CREATE INDEX IF NOT EXISTS idx_event_feed_position
  ON pm.event_feed (change_txid, seq);
CREATE INDEX IF NOT EXISTS idx_event_feed_created_at
  ON pm.event_feed (created_at);

ALTER TABLE pm.event_feed ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.event_feed FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.event_feed TO service_role;

-- One row: the position retention pruned through.
CREATE TABLE IF NOT EXISTS pm.event_feed_state (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  pruned_txid bigint NOT NULL DEFAULT 0,
  pruned_seq bigint NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE pm.event_feed_state IS
  'The (change_txid, seq) pm.prune_event_feed deleted through; a cursor below it must resync. Server only.';

ALTER TABLE pm.event_feed_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.event_feed_state FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.event_feed_state TO service_role;

-- Open long-poll waits, one lease each.
CREATE TABLE IF NOT EXISTS pm.event_feed_waits (
  id uuid PRIMARY KEY,
  api_key_id uuid NOT NULL REFERENCES pm.api_keys(id) ON DELETE CASCADE,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE pm.event_feed_waits IS
  'Long-poll waits open per API key; a lease past expires_at is over (its server died). Server only.';

CREATE INDEX IF NOT EXISTS idx_event_feed_waits_key
  ON pm.event_feed_waits (api_key_id, expires_at);

ALTER TABLE pm.event_feed_waits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.event_feed_waits FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.event_feed_waits TO service_role;

-- ---------------------------------------------------------------------------
-- Writers
-- ---------------------------------------------------------------------------
-- A chat message routed to an agent: inserted routed, given to another
-- agent, or released from unrouted (held while the agent was paused). Moving
-- between pending, notified and context is the same message, not a new one.
CREATE OR REPLACE FUNCTION pm.feed_chat_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF NEW.direction <> 'inbound' OR NEW.agent_id IS NULL OR NEW.status NOT IN ('pending', 'notified', 'context') THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.agent_id IS NOT DISTINCT FROM NEW.agent_id
     AND OLD.status IN ('pending', 'notified', 'context') THEN
    RETURN NULL;
  END IF;
  INSERT INTO pm.event_feed (event_type, member_id, agent_id, subject_type, subject_id, data)
  VALUES ('chat.message', NEW.agent_id, NEW.agent_id, 'chat_message', NEW.id, jsonb_build_object(
    'message', jsonb_build_object(
      'id', NEW.id,
      'status', NEW.status,
      'connection_id', NEW.connection_id,
      'conversation_id', NEW.conversation_id,
      'thread_id', NEW.thread_id,
      'created_at', NEW.created_at
    )
  ));
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.feed_chat_message() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS feed_chat_message ON pm.chat_messages;
CREATE TRIGGER feed_chat_message
  AFTER INSERT OR UPDATE OF agent_id, status ON pm.chat_messages
  FOR EACH ROW EXECUTE FUNCTION pm.feed_chat_message();

-- A question or approval the member asked is answered, cancelled or expires.
CREATE OR REPLACE FUNCTION pm.feed_question_closed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF OLD.status <> 'open' OR NEW.status NOT IN ('answered', 'cancelled', 'expired') THEN
    RETURN NULL;
  END IF;
  INSERT INTO pm.event_feed (event_type, member_id, agent_id, project_id, subject_type, subject_id, data)
  VALUES ('question.' || NEW.status, NEW.asked_by, NEW.asked_by, NEW.project_id, 'question', NEW.id, jsonb_build_object(
    'question', jsonb_build_object(
      'id', NEW.id,
      'kind', NEW.kind,
      'status', NEW.status,
      'task_id', NEW.task_id,
      'project_id', NEW.project_id,
      'run_id', NEW.run_id
    ),
    'actor_id', pm.webhook_actor_id()
  ));
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.feed_question_closed() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS feed_question_closed ON pm.questions;
CREATE TRIGGER feed_question_closed
  AFTER UPDATE OF status ON pm.questions
  FOR EACH ROW EXECUTE FUNCTION pm.feed_question_closed();

-- An agent's run starts or changes status (waiting, running again, finished,
-- timed out by the watchdog, cancelled by a person). actor_id says who did
-- it, so a harness skips what it did itself.
CREATE OR REPLACE FUNCTION pm.feed_agent_run()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NULL;
  END IF;
  INSERT INTO pm.event_feed (event_type, member_id, agent_id, project_id, subject_type, subject_id, data)
  VALUES ('run.updated', NEW.agent_id, NEW.agent_id, NEW.project_id, 'run', NEW.id, jsonb_build_object(
    'run', jsonb_build_object(
      'id', NEW.id,
      'status', NEW.status,
      'previous_status', CASE WHEN TG_OP = 'UPDATE' THEN OLD.status END,
      'task_id', NEW.task_id,
      'project_id', NEW.project_id,
      'parent_run_id', NEW.parent_run_id
    ),
    'actor_id', pm.webhook_actor_id()
  ));
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.feed_agent_run() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS feed_agent_run ON pm.agent_runs;
CREATE TRIGGER feed_agent_run
  AFTER INSERT OR UPDATE OF status ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.feed_agent_run();

-- Any agent event. The row is the pointer; the API reads the event itself
-- (the export's row shape) when it serves it.
CREATE OR REPLACE FUNCTION pm.feed_agent_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  INSERT INTO pm.event_feed (event_type, agent_id, project_id, subject_type, subject_id, agent_event_type)
  VALUES ('agent_event.created', NEW.agent_id, NEW.project_id, 'agent_activity', NEW.id, NEW.activity_type);
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.feed_agent_event() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS feed_agent_event ON pm.agent_activities;
CREATE TRIGGER feed_agent_event
  AFTER INSERT ON pm.agent_activities
  FOR EACH ROW EXECUTE FUNCTION pm.feed_agent_event();

-- ---------------------------------------------------------------------------
-- Readers
-- ---------------------------------------------------------------------------
-- One page for one caller after a cursor, in (change_txid, seq) order, only
-- from finished transactions. p_after_txid null starts from now. Member
-- events (p_member_types) are the caller's own; agent events are filtered
-- by project (null: every project), agent and type. Answers
-- { resync: true, cursor } when the cursor is below what retention pruned,
-- else { resync: false, events, has_more, cursor }: cursor is the last
-- event's position when the page is full, else the horizon (the oldest
-- transaction still open, seq 0), so an idle feed moves forward and a later
-- read starts past everything already decided. Positions are text, as
-- bigint does not fit a JSON number.
CREATE OR REPLACE FUNCTION pm.event_feed_read(
  p_after_txid bigint,
  p_after_seq bigint,
  p_limit integer,
  p_member_id uuid,
  p_member_types text[],
  p_agent_events boolean,
  p_agent_event_types text[] DEFAULT NULL,
  p_agents uuid[] DEFAULT NULL,
  p_project_ids uuid[] DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = pm
AS $$
DECLARE
  v_xmin bigint := pg_snapshot_xmin(pg_current_snapshot())::text::bigint;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 1000);
  v_txid bigint := coalesce(p_after_txid, v_xmin);
  v_seq bigint := CASE WHEN p_after_txid IS NULL THEN 0 ELSE coalesce(p_after_seq, 0) END;
  v_state pm.event_feed_state;
  v_rows jsonb;
  v_count integer;
  v_last jsonb;
BEGIN
  SELECT * INTO v_state FROM pm.event_feed_state WHERE id;
  IF FOUND AND (v_txid, v_seq) < (v_state.pruned_txid, v_state.pruned_seq) THEN
    RETURN jsonb_build_object('resync', true, 'cursor', jsonb_build_array(v_xmin::text, '0'));
  END IF;

  WITH picked AS (
    (
      SELECT f.*
      FROM pm.event_feed f
      WHERE p_member_id IS NOT NULL
        AND f.member_id = p_member_id
        AND f.event_type = ANY (coalesce(p_member_types, '{}'))
        AND (f.change_txid, f.seq) > (v_txid, v_seq)
        AND f.change_txid < v_xmin
      ORDER BY f.change_txid, f.seq
      LIMIT v_limit + 1
    )
    UNION ALL
    (
      SELECT f.*
      FROM pm.event_feed f
      WHERE coalesce(p_agent_events, false)
        AND f.event_type = 'agent_event.created'
        AND (f.change_txid, f.seq) > (v_txid, v_seq)
        AND f.change_txid < v_xmin
        AND (p_project_ids IS NULL OR f.project_id = ANY (p_project_ids))
        AND (p_agents IS NULL OR f.agent_id = ANY (p_agents))
        AND (p_agent_event_types IS NULL OR f.agent_event_type = ANY (p_agent_event_types))
      ORDER BY f.change_txid, f.seq
      LIMIT v_limit + 1
    )
  ), ordered AS (
    SELECT p.*, row_number() OVER (ORDER BY p.change_txid, p.seq) AS n
    FROM picked p
    ORDER BY p.change_txid, p.seq
    LIMIT v_limit + 1
  )
  SELECT
    coalesce(jsonb_agg(jsonb_build_object(
      'txid', o.change_txid::text,
      'seq', o.seq::text,
      'type', o.event_type,
      'member_id', o.member_id,
      'agent_id', o.agent_id,
      'project_id', o.project_id,
      'subject_type', o.subject_type,
      'subject_id', o.subject_id,
      'created_at', o.created_at,
      'data', o.data,
      'agent_event', CASE WHEN o.event_type = 'agent_event.created'
        THEN (SELECT pm.agent_event_row(a) FROM pm.agent_activities a WHERE a.id = o.subject_id) END
    ) ORDER BY o.change_txid, o.seq) FILTER (WHERE o.n <= v_limit), '[]'::jsonb),
    count(*)
  INTO v_rows, v_count
  FROM ordered o;

  IF v_count > v_limit THEN
    v_last := v_rows -> (v_limit - 1);
    RETURN jsonb_build_object('resync', false, 'events', v_rows, 'has_more', true,
      'cursor', jsonb_build_array(v_last ->> 'txid', v_last ->> 'seq'));
  END IF;
  RETURN jsonb_build_object('resync', false, 'events', v_rows, 'has_more', false,
    'cursor', jsonb_build_array(greatest(v_xmin, v_txid)::text, CASE WHEN v_xmin > v_txid THEN '0' ELSE v_seq::text END));
END;
$$;

REVOKE ALL ON FUNCTION pm.event_feed_read(bigint, bigint, integer, uuid, text[], boolean, text[], uuid[], uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.event_feed_read(bigint, bigint, integer, uuid, text[], boolean, text[], uuid[], uuid[]) TO service_role;

-- The newest visible position routed to each member, of any agent event
-- (p_agent_events, for waits that read every project) and of agent events on
-- each of p_projects (for waits that read only some): one probe a server
-- makes every few seconds for all its open waits. Each is a single backward
-- step on an index.
CREATE OR REPLACE FUNCTION pm.event_feed_heads(p_members uuid[], p_agent_events boolean DEFAULT false, p_projects uuid[] DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = pm
AS $$
DECLARE
  v_xmin bigint := pg_snapshot_xmin(pg_current_snapshot())::text::bigint;
  v_members jsonb;
  v_agent_events jsonb;
  v_projects jsonb;
BEGIN
  SELECT coalesce(jsonb_object_agg(p.id, (
    SELECT jsonb_build_array(f.change_txid::text, f.seq::text)
    FROM pm.event_feed f
    WHERE f.event_type = 'agent_event.created' AND f.project_id = p.id AND f.change_txid < v_xmin
    ORDER BY f.change_txid DESC, f.seq DESC
    LIMIT 1
  )), '{}'::jsonb)
  INTO v_projects
  FROM (SELECT DISTINCT unnest(coalesce(p_projects, '{}')) AS id) p;

  SELECT coalesce(jsonb_object_agg(m.id, (
    SELECT jsonb_build_array(f.change_txid::text, f.seq::text)
    FROM pm.event_feed f
    WHERE f.member_id = m.id AND f.change_txid < v_xmin
    ORDER BY f.change_txid DESC, f.seq DESC
    LIMIT 1
  )), '{}'::jsonb)
  INTO v_members
  FROM (SELECT DISTINCT unnest(coalesce(p_members, '{}')) AS id) m;

  IF coalesce(p_agent_events, false) THEN
    SELECT jsonb_build_array(f.change_txid::text, f.seq::text) INTO v_agent_events
    FROM pm.event_feed f
    WHERE f.event_type = 'agent_event.created' AND f.change_txid < v_xmin
    ORDER BY f.change_txid DESC, f.seq DESC
    LIMIT 1;
  END IF;

  RETURN jsonb_build_object('members', v_members, 'agent_events', v_agent_events, 'projects', v_projects);
END;
$$;

REVOKE ALL ON FUNCTION pm.event_feed_heads(uuid[], boolean, uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.event_feed_heads(uuid[], boolean, uuid[]) TO service_role;

-- ---------------------------------------------------------------------------
-- Waits: at most p_max open per key
-- ---------------------------------------------------------------------------
-- Takes a lease for p_seconds, or answers { ok: false, retry_after } (the
-- seconds until the earliest open wait on the key ends). Leases past their
-- time are over: a server that died mid-wait frees its slot by itself.
CREATE OR REPLACE FUNCTION pm.event_feed_wait_begin(p_api_key_id uuid, p_wait_id uuid, p_seconds integer, p_max integer)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_open integer;
  v_next timestamptz;
BEGIN
  -- One key's waits are counted one at a time, so two at once never both slip in.
  PERFORM pg_advisory_xact_lock(hashtextextended('pm.event_feed_waits:' || p_api_key_id::text, 0));
  DELETE FROM pm.event_feed_waits WHERE api_key_id = p_api_key_id AND expires_at <= now();
  SELECT count(*), min(expires_at) INTO v_open, v_next FROM pm.event_feed_waits WHERE api_key_id = p_api_key_id;
  IF v_open >= greatest(p_max, 1) THEN
    RETURN jsonb_build_object('ok', false, 'open', v_open,
      'retry_after', greatest(1, ceil(extract(epoch FROM v_next - now()))::integer));
  END IF;
  INSERT INTO pm.event_feed_waits (id, api_key_id, expires_at)
  VALUES (p_wait_id, p_api_key_id, now() + make_interval(secs => least(greatest(p_seconds, 1), 600)))
  ON CONFLICT (id) DO NOTHING;
  RETURN jsonb_build_object('ok', true, 'open', v_open + 1);
END;
$$;

REVOKE ALL ON FUNCTION pm.event_feed_wait_begin(uuid, uuid, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.event_feed_wait_begin(uuid, uuid, integer, integer) TO service_role;

CREATE OR REPLACE FUNCTION pm.event_feed_wait_end(p_wait_id uuid)
RETURNS void
LANGUAGE sql
SET search_path = pm
AS $$
  DELETE FROM pm.event_feed_waits WHERE id = p_wait_id;
$$;

REVOKE ALL ON FUNCTION pm.event_feed_wait_end(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.event_feed_wait_end(uuid) TO service_role;

-- ---------------------------------------------------------------------------
-- Retention
-- ---------------------------------------------------------------------------
-- Rows older than p_keep go, through the newest such position whose
-- transaction and every one below it have ended (so nothing still to commit
-- lies behind it). The position is recorded in the same transaction as the
-- delete: a reader sees both or neither. In batches of 5000. Answers how
-- many rows went. Expired wait leases go too.
CREATE OR REPLACE FUNCTION pm.prune_event_feed(p_keep interval DEFAULT interval '7 days')
RETURNS integer
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_xmin bigint := pg_snapshot_xmin(pg_current_snapshot())::text::bigint;
  v_txid bigint;
  v_seq bigint;
  v_count integer;
  v_total integer := 0;
BEGIN
  DELETE FROM pm.event_feed_waits WHERE expires_at <= now();

  SELECT f.change_txid, f.seq INTO v_txid, v_seq
  FROM pm.event_feed f
  WHERE f.created_at < now() - p_keep AND f.change_txid < v_xmin
  ORDER BY f.change_txid DESC, f.seq DESC
  LIMIT 1;
  IF v_txid IS NULL THEN
    RETURN 0;
  END IF;

  INSERT INTO pm.event_feed_state AS s (id, pruned_txid, pruned_seq, updated_at)
  VALUES (true, v_txid, v_seq, now())
  ON CONFLICT (id) DO UPDATE
    SET pruned_txid = EXCLUDED.pruned_txid, pruned_seq = EXCLUDED.pruned_seq, updated_at = now()
    WHERE (s.pruned_txid, s.pruned_seq) < (EXCLUDED.pruned_txid, EXCLUDED.pruned_seq);

  LOOP
    DELETE FROM pm.event_feed WHERE seq IN (
      SELECT f.seq FROM pm.event_feed f
      WHERE (f.change_txid, f.seq) <= (v_txid, v_seq)
      ORDER BY f.change_txid, f.seq
      LIMIT 5000
    );
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_total := v_total + v_count;
    EXIT WHEN v_count = 0;
  END LOOP;
  RETURN v_total;
END;
$$;

REVOKE ALL ON FUNCTION pm.prune_event_feed(interval) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.prune_event_feed(interval) TO service_role;

-- Hourly. Skipped where pg_cron is unavailable (PGlite).
-- Re-running cron.schedule updates the job in place.
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron') THEN
    RAISE NOTICE 'pg_cron is unavailable here; the event feed will not be pruned on a schedule';
    RETURN;
  END IF;
  CREATE EXTENSION IF NOT EXISTS pg_cron;
  PERFORM cron.schedule('pm-event-feed-prune', '29 * * * *', $job$SELECT pm.prune_event_feed();$job$);
END;
$do$;

-- ============================================================
-- SECURITY HARDENING (20261127001200_security_hardening.sql)
-- ============================================================
-- Security hardening (break-it round, 2026-11-27).
--
-- Safe to run twice; works with the 2.0.49 code (every path that writes these
-- tables from the browser keeps working; server routes use the service role).
--
-- 1. Storage: who reads, uploads, changes or deletes a stored file is decided
--    by the record it belongs to, through pm.storage_object_allowed():
--    - pm-entity-files: {project|lead|contact}/{id}/... follows that record's
--      file rules (files.read / files.upload, files.manage or the uploader to
--      change or delete); invoices/{project}/... follows invoices.read /
--      invoices.manage on that project.
--    - pm-portal-files: updates/{project}/... follows portal.read /
--      portal.manage on that project.
--    - pm-avatars: still public to read (pictures show everywhere, signed out
--      on the portal too); team/{member}.jpg is written only by that member,
--      a holder of team.manage, or one of the agent's owners (by name or through a group);
--      contacts/{contact}.jpg by contacts.manage on a contact they reach;
--      portal/{project}.* by portal.manage on that project.
--    pm-entity-files and pm-portal-files become private: the app serves them
--    through short signed links (/api/storage/file, the portal routes). The
--    pre-2.0 buckets of an upgraded install (entity-files, portal-files,
--    avatars) lose the app's old member-wide write policies, and the two file
--    buckets turn private too; the app signs their files the same way.
-- 2. task_comments: a comment stays on its task and keeps its author. The
--    update policy checks the task on both sides, and a trigger refuses a
--    browser write that moves a comment or changes its author.
-- 3. time_entry_tasks: read with the time entry; written only by whoever may
--    edit that entry, and only with tasks of the entry's project.
-- 4. Manage without View all: leads.manage, contacts.manage and
--    tasks.manage_all no longer read or change every row; they act on the
--    leads, contacts and tasks the person reaches (and what they created).
--    projects_manage reads only reachable projects.
-- 5. Personal inboxes: verification is the server's. A browser write never
--    sets verified_at or verification_code, and changing an inbox's address
--    from the browser clears its verification.
-- 6. Server-set columns: a browser insert or update of a task or comment
--    never sets created_at, a task's completed_at (outside a status change),
--    its claim or its repeat count.
-- 7. Trash: soft_delete_record checks permission before saying whether a
--    record exists, and restore_record answers a missing record as it answers
--    one the member may not restore.
-- 8. Webhooks: an endpoint receives a project's events only while its maker
--    reads that project.
-- 9. Avatars: team_members.avatar and contacts.avatar_url hold only an https
--    picture link or a path on the app.

-- ---------------------------------------------------------------------------
-- 1. Storage
-- ---------------------------------------------------------------------------

-- Whether the signed-in member may read, write (upload) or delete (also
-- change) a stored object, from its bucket and path. Old bucket names (before
-- 2.0) follow the same rules as their pm- twins. p_owner is the object's
-- owner (storage.objects.owner), so an uploader may remove what they put.
CREATE OR REPLACE FUNCTION pm.storage_object_allowed(p_bucket text, p_name text, p_action text, p_owner uuid DEFAULT NULL)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  me uuid := pm.current_team_member_id();
  v_bucket text := CASE WHEN p_bucket LIKE 'pm-%' THEN p_bucket ELSE 'pm-' || coalesce(p_bucket, '') END;
  v_parts text[] := string_to_array(coalesce(p_name, ''), '/');
  v_depth integer := coalesce(array_length(string_to_array(coalesce(p_name, ''), '/'), 1), 0);
  v_kind text;
  v_target_text text;
  v_target uuid;
BEGIN
  IF me IS NULL OR p_action IS NULL OR p_action NOT IN ('read', 'write', 'delete') OR v_depth < 2 THEN
    RETURN false;
  END IF;
  v_kind := v_parts[1];
  IF v_bucket = 'pm-avatars' THEN
    IF p_action = 'read' THEN
      RETURN true;
    END IF;
    -- One picture per record: <kind>/<id>.<ext>
    IF v_depth <> 2 THEN
      RETURN false;
    END IF;
    v_target_text := substring(v_parts[2] FROM '^([0-9A-Fa-f-]{36})(\.[A-Za-z0-9]{1,8})?$');
  ELSE
    -- <kind>/<id>/<file name>
    IF v_depth < 3 OR v_parts[v_depth] = '' THEN
      RETURN false;
    END IF;
    v_target_text := v_parts[2];
  END IF;
  IF v_target_text IS NULL
     OR v_target_text !~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$' THEN
    RETURN false;
  END IF;
  v_target := v_target_text::uuid;

  IF v_bucket = 'pm-entity-files' THEN
    IF v_kind IN ('project', 'lead', 'contact') THEN
      IF NOT pm.can_access_file_entity(v_kind, v_target) THEN
        RETURN false;
      END IF;
      RETURN CASE p_action
        WHEN 'read' THEN pm.has_permission('files.read') OR pm.has_permission('files.manage')
        WHEN 'write' THEN pm.has_permission('files.upload') OR pm.has_permission('files.manage')
        ELSE pm.has_permission('files.manage') OR (p_owner IS NOT NULL AND p_owner = auth.uid())
      END;
    ELSIF v_kind = 'invoices' THEN
      RETURN pm.can_access_project(v_target) AND (
        pm.has_permission('invoices.manage')
        OR (p_action = 'read' AND pm.has_permission('invoices.read'))
      );
    END IF;
    RETURN false;
  ELSIF v_bucket = 'pm-portal-files' THEN
    IF v_kind = 'updates' THEN
      RETURN pm.can_access_project(v_target) AND (
        pm.has_permission('portal.manage')
        OR (p_action = 'read' AND pm.has_permission('portal.read'))
      );
    END IF;
    RETURN false;
  ELSIF v_bucket = 'pm-avatars' THEN
    IF v_kind = 'team' THEN
      IF pm.has_permission('team.manage') THEN
        RETURN true;
      END IF;
      -- A person's own picture (an agent's is its managers', as canManageAgent says).
      IF v_target = me THEN
        RETURN NOT EXISTS (SELECT 1 FROM pm.team_members self_row WHERE self_row.id = me AND self_row.role = 'agent');
      END IF;
      -- An agent's picture: its owners, by name, or as an active person in a
      -- live group that owns it (isAgentOwner in agent-owners.ts).
      RETURN EXISTS (SELECT 1 FROM pm.team_members agent WHERE agent.id = v_target AND agent.role = 'agent')
        AND (
          EXISTS (SELECT 1 FROM pm.agent_owners owner_row WHERE owner_row.agent_id = v_target AND owner_row.member_id = me)
          OR (
            EXISTS (SELECT 1 FROM pm.team_members person WHERE person.id = me AND person.role <> 'agent' AND coalesce(person.status, 'active') = 'active')
            AND EXISTS (
              SELECT 1 FROM pm.agent_owner_groups owner_group
              JOIN pm.groups owning ON owning.id = owner_group.group_id AND owning.deleted_at IS NULL
              JOIN pm.group_members membership ON membership.group_id = owner_group.group_id AND membership.member_id = me
              WHERE owner_group.agent_id = v_target
            )
          )
        );
    ELSIF v_kind = 'contacts' THEN
      RETURN pm.has_permission('contacts.manage') AND EXISTS (
        SELECT 1 FROM pm.contacts contact
        WHERE contact.id = v_target AND contact.deleted_at IS NULL
          AND (contact.created_by = me OR pm.can_access_file_entity('contact', v_target))
      );
    ELSIF v_kind = 'portal' THEN
      RETURN pm.has_permission('portal.manage') AND pm.can_access_project(v_target);
    END IF;
    RETURN false;
  END IF;
  RETURN false;
END;
$$;

REVOKE ALL ON FUNCTION pm.storage_object_allowed(text, text, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.storage_object_allowed(text, text, text, uuid) TO authenticated, service_role;

UPDATE storage.buckets SET public = false WHERE id IN ('pm-entity-files', 'pm-portal-files') AND public;

-- Entity files (project, lead and contact files, invoice PDFs).
DROP POLICY IF EXISTS "pm: Authenticated users can upload entity files" ON storage.objects;
DROP POLICY IF EXISTS "pm: Authenticated users can update entity files" ON storage.objects;
DROP POLICY IF EXISTS "pm: Authenticated users can delete entity files" ON storage.objects;
DROP POLICY IF EXISTS "pm: Authenticated users can read entity files" ON storage.objects;
DROP POLICY IF EXISTS "pm: Entity files are read by who opens their record" ON storage.objects;
CREATE POLICY "pm: Entity files are read by who opens their record" ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id = 'pm-entity-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'read'));
DROP POLICY IF EXISTS "pm: Entity files are added by who may upload to their record" ON storage.objects;
CREATE POLICY "pm: Entity files are added by who may upload to their record" ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'pm-entity-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'write'));
DROP POLICY IF EXISTS "pm: Entity files are changed by who manages them" ON storage.objects;
CREATE POLICY "pm: Entity files are changed by who manages them" ON storage.objects FOR UPDATE TO authenticated
  USING (bucket_id = 'pm-entity-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'delete', owner))
  WITH CHECK (bucket_id = 'pm-entity-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'write'));
DROP POLICY IF EXISTS "pm: Entity files are removed by who manages them" ON storage.objects;
CREATE POLICY "pm: Entity files are removed by who manages them" ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id = 'pm-entity-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'delete', owner));

-- Portal update attachments.
DROP POLICY IF EXISTS "pm: Authenticated users can upload portal files" ON storage.objects;
DROP POLICY IF EXISTS "pm: Authenticated users can update portal files" ON storage.objects;
DROP POLICY IF EXISTS "pm: Authenticated users can delete portal files" ON storage.objects;
DROP POLICY IF EXISTS "pm: Public can read portal files" ON storage.objects;
DROP POLICY IF EXISTS "pm: Portal files are read by who sees the portal" ON storage.objects;
CREATE POLICY "pm: Portal files are read by who sees the portal" ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id = 'pm-portal-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'read'));
DROP POLICY IF EXISTS "pm: Portal files are added by who manages the portal" ON storage.objects;
CREATE POLICY "pm: Portal files are added by who manages the portal" ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'pm-portal-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'write'));
DROP POLICY IF EXISTS "pm: Portal files are changed by who manages the portal" ON storage.objects;
CREATE POLICY "pm: Portal files are changed by who manages the portal" ON storage.objects FOR UPDATE TO authenticated
  USING (bucket_id = 'pm-portal-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'delete', owner))
  WITH CHECK (bucket_id = 'pm-portal-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'write'));
DROP POLICY IF EXISTS "pm: Portal files are removed by who manages the portal" ON storage.objects;
CREATE POLICY "pm: Portal files are removed by who manages the portal" ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id = 'pm-portal-files' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'delete', owner));

-- Avatars: public to read ("pm: Public can read avatars" stays), written by
-- the picture's own person or record managers.
DROP POLICY IF EXISTS "pm: Authenticated users can upload avatars" ON storage.objects;
DROP POLICY IF EXISTS "pm: Authenticated users can update avatars" ON storage.objects;
DROP POLICY IF EXISTS "pm: Authenticated users can delete avatars" ON storage.objects;
DROP POLICY IF EXISTS "pm: Avatars are added by their person or record managers" ON storage.objects;
CREATE POLICY "pm: Avatars are added by their person or record managers" ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'pm-avatars' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'write'));
DROP POLICY IF EXISTS "pm: Avatars are changed by their person or record managers" ON storage.objects;
CREATE POLICY "pm: Avatars are changed by their person or record managers" ON storage.objects FOR UPDATE TO authenticated
  USING (bucket_id = 'pm-avatars' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'delete', owner))
  WITH CHECK (bucket_id = 'pm-avatars' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'write'));
DROP POLICY IF EXISTS "pm: Avatars are removed by their person or record managers" ON storage.objects;
CREATE POLICY "pm: Avatars are removed by their person or record managers" ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id = 'pm-avatars' AND (select pm.current_team_member_id()) IS NOT NULL AND pm.storage_object_allowed(bucket_id, name, 'delete', owner));

-- The pre-2.0 buckets of an upgraded install: read-only fallbacks the server
-- reads (and signs) until 2.1. The app's old member-wide policies go, found
-- by their exact names so another app's buckets are never touched; the file
-- buckets turn private. A fresh install has none of this.
DO $legacy_storage$
BEGIN
  IF to_regclass('storage.objects') IS NULL THEN
    RETURN;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname IN (
    'Authenticated users can upload entity files', 'Authenticated users can update entity files',
    'Authenticated users can delete entity files', 'Authenticated users can read entity files')) THEN
    DROP POLICY IF EXISTS "Authenticated users can upload entity files" ON storage.objects;
    DROP POLICY IF EXISTS "Authenticated users can update entity files" ON storage.objects;
    DROP POLICY IF EXISTS "Authenticated users can delete entity files" ON storage.objects;
    DROP POLICY IF EXISTS "Authenticated users can read entity files" ON storage.objects;
    UPDATE storage.buckets SET public = false WHERE id = 'entity-files';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname IN (
    'Authenticated users can upload portal files', 'Authenticated users can update portal files',
    'Authenticated users can delete portal files', 'Public can read portal files')) THEN
    DROP POLICY IF EXISTS "Authenticated users can upload portal files" ON storage.objects;
    DROP POLICY IF EXISTS "Authenticated users can update portal files" ON storage.objects;
    DROP POLICY IF EXISTS "Authenticated users can delete portal files" ON storage.objects;
    DROP POLICY IF EXISTS "Public can read portal files" ON storage.objects;
    UPDATE storage.buckets SET public = false WHERE id = 'portal-files';
  END IF;
  DROP POLICY IF EXISTS "Authenticated users can upload avatars" ON storage.objects;
  DROP POLICY IF EXISTS "Authenticated users can update avatars" ON storage.objects;
  DROP POLICY IF EXISTS "Authenticated users can delete avatars" ON storage.objects;
END
$legacy_storage$;

-- ---------------------------------------------------------------------------
-- 2. task_comments: a comment stays on its task and keeps its author
-- ---------------------------------------------------------------------------
DROP POLICY IF EXISTS task_comments_update_delete ON pm.task_comments;
DROP POLICY IF EXISTS task_comments_update ON pm.task_comments;
CREATE POLICY task_comments_update ON pm.task_comments FOR UPDATE TO authenticated
  USING (pm.can_access_task(task_id) AND (user_id = pm.current_team_member_id() OR pm.has_permission('tasks.manage_all')))
  WITH CHECK (pm.can_access_task(task_id) AND (user_id = pm.current_team_member_id() OR pm.has_permission('tasks.manage_all')));
DROP POLICY IF EXISTS task_comments_delete ON pm.task_comments;
CREATE POLICY task_comments_delete ON pm.task_comments FOR DELETE TO authenticated
  USING (pm.can_access_task(task_id) AND (user_id = pm.current_team_member_id() OR pm.has_permission('tasks.manage_all')));

-- Browser writes (the authenticated role itself; server code and SECURITY
-- DEFINER functions run as another role): a new comment is the writer's, made
-- now; an edit never moves it to another task, never changes its author and
-- never changes when it was made.
CREATE OR REPLACE FUNCTION pm.task_comments_server_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF current_user <> 'authenticated' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    RETURN NEW;
  END IF;
  IF NEW.task_id IS DISTINCT FROM OLD.task_id OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'A comment stays on its task and keeps its author'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW.created_at := OLD.created_at;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.task_comments_server_fields() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS task_comments_server_fields ON pm.task_comments;
CREATE TRIGGER task_comments_server_fields
  BEFORE INSERT OR UPDATE ON pm.task_comments
  FOR EACH ROW EXECUTE FUNCTION pm.task_comments_server_fields();

-- ---------------------------------------------------------------------------
-- 3. time_entry_tasks: the time entry's own rules
-- ---------------------------------------------------------------------------
-- Read with the entry (the subquery reads project_time_entries under the
-- reader's own row policies). Written by whoever may edit the entry, as
-- time_entries_update allows, and only with tasks of the entry's project.
DROP POLICY IF EXISTS time_entry_tasks_all ON pm.time_entry_tasks;
DROP POLICY IF EXISTS time_entry_tasks_select ON pm.time_entry_tasks;
CREATE POLICY time_entry_tasks_select ON pm.time_entry_tasks FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM pm.project_time_entries entry WHERE entry.id = time_entry_tasks.time_entry_id));
DROP POLICY IF EXISTS time_entry_tasks_insert ON pm.time_entry_tasks;
CREATE POLICY time_entry_tasks_insert ON pm.time_entry_tasks FOR INSERT TO authenticated
  WITH CHECK (EXISTS (
    SELECT 1 FROM pm.project_time_entries entry
    WHERE entry.id = time_entry_tasks.time_entry_id
      AND pm.can_access_project(entry.project_id)
      AND (pm.has_permission('time.manage_all') OR (
        pm.has_permission('time.manage_own')
        AND entry.member_id = pm.current_team_member_id()
        AND entry.approval_status IN ('draft', 'pending', 'rejected')
      ))
      AND EXISTS (SELECT 1 FROM pm.tasks task WHERE task.id = time_entry_tasks.task_id AND task.project_id = entry.project_id)
  ));
DROP POLICY IF EXISTS time_entry_tasks_update ON pm.time_entry_tasks;
CREATE POLICY time_entry_tasks_update ON pm.time_entry_tasks FOR UPDATE TO authenticated
  USING (EXISTS (
    SELECT 1 FROM pm.project_time_entries entry
    WHERE entry.id = time_entry_tasks.time_entry_id
      AND pm.can_access_project(entry.project_id)
      AND (pm.has_permission('time.manage_all') OR (
        pm.has_permission('time.manage_own')
        AND entry.member_id = pm.current_team_member_id()
        AND entry.approval_status IN ('draft', 'pending', 'rejected')
      ))
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM pm.project_time_entries entry
    WHERE entry.id = time_entry_tasks.time_entry_id
      AND pm.can_access_project(entry.project_id)
      AND (pm.has_permission('time.manage_all') OR (
        pm.has_permission('time.manage_own')
        AND entry.member_id = pm.current_team_member_id()
        AND entry.approval_status IN ('draft', 'pending', 'rejected')
      ))
      AND EXISTS (SELECT 1 FROM pm.tasks task WHERE task.id = time_entry_tasks.task_id AND task.project_id = entry.project_id)
  ));
DROP POLICY IF EXISTS time_entry_tasks_delete ON pm.time_entry_tasks;
CREATE POLICY time_entry_tasks_delete ON pm.time_entry_tasks FOR DELETE TO authenticated
  USING (EXISTS (
    SELECT 1 FROM pm.project_time_entries entry
    WHERE entry.id = time_entry_tasks.time_entry_id
      AND pm.can_access_project(entry.project_id)
      AND (pm.has_permission('time.manage_all') OR (
        pm.has_permission('time.manage_own')
        AND entry.member_id = pm.current_team_member_id()
        AND entry.approval_status IN ('draft', 'pending', 'rejected')
      ))
  ));

-- ---------------------------------------------------------------------------
-- 4. Manage without View all
-- ---------------------------------------------------------------------------
-- leads.manage acts on the leads the person reaches (can_access_lead), plus
-- the ones they created or hold. It still adds leads. The extra read policy
-- keeps a new lead readable to its maker in the same statement (INSERT ...
-- RETURNING), where can_access_lead cannot see the row yet.
DROP POLICY IF EXISTS leads_manage ON pm.leads;
DROP POLICY IF EXISTS leads_manage_select ON pm.leads;
CREATE POLICY leads_manage_select ON pm.leads FOR SELECT TO authenticated
  USING (pm.has_permission('leads.manage') AND (
    pm.has_permission('leads.read_all')
    OR assigned_to = pm.current_team_member_id()
    OR created_by = pm.current_team_member_id()
  ));
DROP POLICY IF EXISTS leads_insert ON pm.leads;
CREATE POLICY leads_insert ON pm.leads FOR INSERT TO authenticated
  WITH CHECK (pm.has_permission('leads.manage'));
DROP POLICY IF EXISTS leads_update ON pm.leads;
CREATE POLICY leads_update ON pm.leads FOR UPDATE TO authenticated
  USING (pm.has_permission('leads.manage') AND (pm.can_access_lead(id) OR created_by = pm.current_team_member_id()))
  WITH CHECK (pm.has_permission('leads.manage'));
DROP POLICY IF EXISTS leads_delete ON pm.leads;
CREATE POLICY leads_delete ON pm.leads FOR DELETE TO authenticated
  USING (pm.has_permission('leads.manage') AND (pm.can_access_lead(id) OR created_by = pm.current_team_member_id()));

-- contacts.manage acts on the contacts the person reaches (contacts.read_all,
-- or linked to a project they open), plus the ones they created.
DROP POLICY IF EXISTS contacts_manage ON pm.contacts;
DROP POLICY IF EXISTS contacts_manage_select ON pm.contacts;
CREATE POLICY contacts_manage_select ON pm.contacts FOR SELECT TO authenticated
  USING (pm.has_permission('contacts.manage') AND (
    pm.has_permission('contacts.read_all') OR created_by = pm.current_team_member_id()
  ));
DROP POLICY IF EXISTS contacts_insert ON pm.contacts;
CREATE POLICY contacts_insert ON pm.contacts FOR INSERT TO authenticated
  WITH CHECK (pm.has_permission('contacts.manage'));
DROP POLICY IF EXISTS contacts_update ON pm.contacts;
CREATE POLICY contacts_update ON pm.contacts FOR UPDATE TO authenticated
  USING (pm.has_permission('contacts.manage') AND (
    pm.can_access_file_entity('contact', id) OR created_by = pm.current_team_member_id()
  ))
  WITH CHECK (pm.has_permission('contacts.manage'));
DROP POLICY IF EXISTS contacts_delete ON pm.contacts;
CREATE POLICY contacts_delete ON pm.contacts FOR DELETE TO authenticated
  USING (pm.has_permission('contacts.manage') AND (
    pm.can_access_file_entity('contact', id) OR created_by = pm.current_team_member_id()
  ));

-- Linking a contact to a project needs that project.
DROP POLICY IF EXISTS project_contacts_manage ON pm.project_contacts;
CREATE POLICY project_contacts_manage ON pm.project_contacts FOR ALL TO authenticated
  USING (pm.has_permission('contacts.manage') AND pm.can_access_project(project_id))
  WITH CHECK (pm.has_permission('contacts.manage') AND pm.can_access_project(project_id));

-- tasks.manage_all changes the assignees of tasks the person reaches.
DROP POLICY IF EXISTS task_assignees_manage ON pm.task_assignees;
CREATE POLICY task_assignees_manage ON pm.task_assignees FOR ALL TO authenticated
  USING (pm.has_permission('tasks.manage_all') AND pm.can_access_task(task_id))
  WITH CHECK (pm.has_permission('tasks.manage_all') AND pm.can_access_task(task_id));

-- projects has no member write grants: this policy only ever read. It reads
-- the projects the person opens.
DROP POLICY IF EXISTS projects_manage ON pm.projects;
CREATE POLICY projects_manage ON pm.projects FOR ALL TO authenticated
  USING (pm.has_permission('projects.manage') AND pm.can_access_project(id))
  WITH CHECK (pm.has_permission('projects.manage') AND pm.can_access_project(id));

-- ---------------------------------------------------------------------------
-- 5. Personal inboxes: verification is the server's
-- ---------------------------------------------------------------------------
-- Inboxes are made and verified by the server (the settings service and
-- ingestion run as the service role). A browser write never sets
-- verified_at or verification_code, and a browser change of address clears
-- the verification until the new code arrives.
CREATE OR REPLACE FUNCTION pm.inboxes_server_verification()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF current_user <> 'authenticated' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.verified_at := NULL;
    NEW.verification_code := pm.email_inbox_verification_code();
    RETURN NEW;
  END IF;
  NEW.verification_code := OLD.verification_code;
  IF NEW.address IS DISTINCT FROM OLD.address THEN
    NEW.verified_at := NULL;
  ELSE
    NEW.verified_at := OLD.verified_at;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.inboxes_server_verification() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS inboxes_server_verification ON pm.inboxes;
CREATE TRIGGER inboxes_server_verification
  BEFORE INSERT OR UPDATE ON pm.inboxes
  FOR EACH ROW EXECUTE FUNCTION pm.inboxes_server_verification();

-- ---------------------------------------------------------------------------
-- 6. Server-set task columns
-- ---------------------------------------------------------------------------
-- A browser write (the authenticated role itself) never backdates a task,
-- never sets when it was finished outside a status change, never takes or
-- extends a claim (it may release one) and never sets the repeat count.
-- Claims go through pm.claim_task and friends, which run as their owner.
CREATE OR REPLACE FUNCTION pm.tasks_server_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF current_user <> 'authenticated' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    NEW.completed_at := CASE WHEN NEW.status = 'done' THEN now() END;
    NEW.claimed_by := NULL;
    NEW.claimed_at := NULL;
    NEW.claim_expires_at := NULL;
    NEW.claim_assigned := false;
    NEW.occurrences := 1;
    NEW.last_occurred_at := NULL;
    RETURN NEW;
  END IF;
  NEW.created_at := OLD.created_at;
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    NEW.completed_at := OLD.completed_at;
  END IF;
  IF NEW.claimed_by IS NOT NULL
     AND (NEW.claimed_by, NEW.claimed_at, NEW.claim_expires_at, NEW.claim_assigned)
       IS DISTINCT FROM (OLD.claimed_by, OLD.claimed_at, OLD.claim_expires_at, OLD.claim_assigned) THEN
    NEW.claimed_by := OLD.claimed_by;
    NEW.claimed_at := OLD.claimed_at;
    NEW.claim_expires_at := OLD.claim_expires_at;
    NEW.claim_assigned := OLD.claim_assigned;
  END IF;
  NEW.occurrences := OLD.occurrences;
  NEW.last_occurred_at := OLD.last_occurred_at;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.tasks_server_fields() FROM PUBLIC, anon, authenticated;

-- Named to run after tasks_before_update, which stamps completed_at on a
-- status change and ends the claim of a finished task.
DROP TRIGGER IF EXISTS tasks_server_fields ON pm.tasks;
CREATE TRIGGER tasks_server_fields
  BEFORE INSERT OR UPDATE ON pm.tasks
  FOR EACH ROW EXECUTE FUNCTION pm.tasks_server_fields();

-- ---------------------------------------------------------------------------
-- 7. Trash: permission before existence
-- ---------------------------------------------------------------------------
-- A member without the right gets the same answer for a record that exists
-- and one that does not (restore_record: see the note inside it).
CREATE OR REPLACE FUNCTION pm.soft_delete_record(p_table text, p_id uuid, p_actor uuid DEFAULT NULL)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  is_service boolean := coalesce(auth.role(), '') = 'service_role';
  actor uuid;
  changed integer;
  found_row boolean;
  before jsonb;
  after jsonb;
BEGIN
  IF NOT p_table = ANY (pm.trash_record_types()) THEN
    RAISE EXCEPTION 'Trash does not handle %', p_table USING ERRCODE = '22023';
  END IF;
  IF NOT is_service AND NOT coalesce(pm.can_trash_record(p_table, p_id), false) THEN
    RAISE EXCEPTION 'You do not have permission to delete this' USING ERRCODE = '42501';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM pm.%I WHERE id = $1)', p_table) INTO found_row USING p_id;
  IF NOT found_row THEN
    RAISE EXCEPTION 'Record not found' USING ERRCODE = 'P0002';
  END IF;
  actor := CASE WHEN is_service THEN p_actor ELSE pm.current_team_member_id() END;
  EXECUTE format('SELECT to_jsonb(t) FROM pm.%I t WHERE id = $1', p_table) INTO before USING p_id;
  EXECUTE format('UPDATE pm.%I t SET deleted_at = now(), deleted_by = $1 WHERE id = $2 AND deleted_at IS NULL RETURNING to_jsonb(t)', p_table)
    INTO after USING actor, p_id;
  changed := CASE WHEN after IS NULL THEN 0 ELSE 1 END;
  IF changed > 0 AND NOT is_service THEN
    PERFORM pm.audit_trash_change(p_table, p_id, false, before, after);
  END IF;
  RETURN changed > 0;
END;
$$;

CREATE OR REPLACE FUNCTION pm.restore_record(p_table text, p_id uuid, p_actor uuid DEFAULT NULL)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  is_service boolean := coalesce(auth.role(), '') = 'service_role';
  blocker text;
  changed integer;
  found_row boolean;
  before jsonb;
  after jsonb;
BEGIN
  IF NOT p_table = ANY (pm.trash_record_types()) THEN
    RAISE EXCEPTION 'Trash does not handle %', p_table USING ERRCODE = '22023';
  END IF;
  -- A member hears "no permission" for a record that does not exist, as for
  -- one they may not restore. What still blocks a restore (its task or
  -- project in Trash) is said first, so whoever trashed both learns the order.
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM pm.%I WHERE id = $1)', p_table) INTO found_row USING p_id;
  IF NOT found_row THEN
    IF is_service THEN
      RAISE EXCEPTION 'Record not found' USING ERRCODE = 'P0002';
    END IF;
    RAISE EXCEPTION 'You do not have permission to restore this' USING ERRCODE = '42501';
  END IF;
  blocker := pm.trash_restore_blocker(p_table, p_id);
  IF blocker IS NOT NULL THEN
    RAISE EXCEPTION '%', blocker USING ERRCODE = '55000';
  END IF;
  IF NOT is_service AND NOT coalesce(pm.can_trash_record(p_table, p_id), false) THEN
    RAISE EXCEPTION 'You do not have permission to restore this' USING ERRCODE = '42501';
  END IF;
  -- Restoring re-runs the record's own rules (an invoice links its hours
  -- and retainer period again); a clash with what happened meanwhile
  -- refuses it, saying why.
  EXECUTE format('SELECT to_jsonb(t) FROM pm.%I t WHERE id = $1', p_table) INTO before USING p_id;
  BEGIN
    EXECUTE format('UPDATE pm.%I t SET deleted_at = NULL, deleted_by = NULL WHERE id = $1 AND deleted_at IS NOT NULL RETURNING to_jsonb(t)', p_table)
      INTO after USING p_id;
    changed := CASE WHEN after IS NULL THEN 0 ELSE 1 END;
  EXCEPTION WHEN raise_exception THEN
    RAISE EXCEPTION 'It cannot come back as it was: %', SQLERRM USING ERRCODE = '55000';
  END;
  IF changed > 0 AND NOT is_service THEN
    PERFORM pm.audit_trash_change(p_table, p_id, true, before, after);
  END IF;
  -- Retainer months that came due while it (or its project) was in Trash
  -- are skipped, as a pause skips them: restoring never back-bills.
  IF changed > 0 AND p_table IN ('projects', 'project_retainers') THEN
    INSERT INTO pm.project_retainer_periods (retainer_id, period_start, period_end, status)
    SELECT due.retainer_id, due.period_start, due.period_end, 'skipped'
    FROM pm.retainer_due_periods_internal(
      CASE WHEN p_table = 'projects' THEN p_id ELSE (after->>'project_id')::uuid END,
      pm.workspace_today()) due
    WHERE (p_table = 'projects' OR due.retainer_id = p_id)
      AND due.bill_date >= ((before->>'deleted_at')::timestamptz AT TIME ZONE pm.workspace_timezone())::date
    ON CONFLICT (retainer_id, period_start) DO NOTHING;
  END IF;
  RETURN changed > 0;
END;
$$;

REVOKE ALL ON FUNCTION pm.soft_delete_record(text, uuid, uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION pm.soft_delete_record(text, uuid, uuid) TO authenticated, service_role;
REVOKE ALL ON FUNCTION pm.restore_record(text, uuid, uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION pm.restore_record(text, uuid, uuid) TO authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 8. Webhooks: an endpoint never receives what its maker could not read
-- ---------------------------------------------------------------------------
-- An endpoint with project_ids NULL received every project's events, whoever
-- made it. Now an event that touches projects reaches an endpoint only while
-- the endpoint's maker (created_by) reads at least one of those projects
-- (projects.read_all, or projects.read and a member of one). Events that
-- touch no project are unchanged. An endpoint whose maker left the team
-- (created_by NULL) is the workspace's own and is unchanged. A suspended
-- maker reads nothing, so their endpoints stop receiving project events.
CREATE OR REPLACE FUNCTION pm.webhook_maker_reaches(p_maker uuid, p_project_ids uuid[])
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT p_maker IS NULL
    OR coalesce(cardinality(p_project_ids), 0) = 0
    -- Either channel: an agent's reach is granted on the API channel only (2.0.49), a person's usually on the app.
    OR pm.member_has_permission(p_maker, 'projects.read_all', 'app')
    OR pm.member_has_permission(p_maker, 'projects.read_all', 'api')
    OR ((pm.member_has_permission(p_maker, 'projects.read', 'app') OR pm.member_has_permission(p_maker, 'projects.read', 'api')) AND EXISTS (
      SELECT 1 FROM pm.project_members pmb
      WHERE pmb.member_id = p_maker AND pmb.project_id = ANY (p_project_ids)
    ))
$$;

REVOKE ALL ON FUNCTION pm.webhook_maker_reaches(uuid, uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.webhook_maker_reaches(uuid, uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION pm.webhook_endpoint_matches(
  p_endpoint pm.webhook_endpoints,
  p_event_type text,
  p_project_ids uuid[],
  p_member_ids uuid[]
)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = pm
AS $$
  SELECT p_endpoint.is_active
    AND p_event_type = ANY (p_endpoint.events)
    AND (p_endpoint.project_ids IS NULL OR p_endpoint.project_ids && coalesce(p_project_ids, '{}'))
    AND (p_endpoint.member_id IS NULL OR p_endpoint.member_id = ANY (coalesce(p_member_ids, '{}')))
    AND (p_endpoint.assistant_setup_id IS NULL OR EXISTS (
      SELECT 1 FROM pm.team_members a
      WHERE a.id = ANY (coalesce(p_member_ids, '{}'))
        AND a.assistant_setup_id = p_endpoint.assistant_setup_id
        AND a.role = 'agent' AND a.delegate_of IS NOT NULL
    ))
    AND pm.webhook_maker_reaches(p_endpoint.created_by, p_project_ids)
$$;

REVOKE ALL ON FUNCTION pm.webhook_endpoint_matches(pm.webhook_endpoints, text, uuid[], uuid[]) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 9. Avatars: only a picture link or a path on the app is stored
-- ---------------------------------------------------------------------------
-- The server routes check this (src/lib/schemas/profile.ts); this catches the
-- direct writes (contacts by contacts.manage holders, team_members by an
-- Owner). Checked only when the avatar changes, so a row stored before this
-- (rendered through safeImageUrl, which drops anything unsafe) never blocks
-- an unrelated update.
CREATE OR REPLACE FUNCTION pm.guard_avatar_url()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_new text := CASE WHEN TG_TABLE_NAME = 'contacts' THEN to_jsonb(NEW)->>'avatar_url' ELSE to_jsonb(NEW)->>'avatar' END;
  v_old text := CASE WHEN TG_OP = 'UPDATE' THEN (CASE WHEN TG_TABLE_NAME = 'contacts' THEN to_jsonb(OLD)->>'avatar_url' ELSE to_jsonb(OLD)->>'avatar' END) END;
BEGIN
  IF (TG_OP = 'INSERT' OR v_new IS DISTINCT FROM v_old) AND v_new IS NOT NULL AND v_new <> '' AND NOT (
    length(v_new) <= 2000 AND (
      v_new ~ '^https://[^[:space:][:cntrl:]]+$'
      OR v_new ~ '^http://(localhost|127\.0\.0\.1|\[::1\])([:/][^[:space:][:cntrl:]]*)?$'
      OR (v_new ~ '^/[^/[:space:][:cntrl:]][^[:space:][:cntrl:]]*$' AND strpos(v_new, chr(92)) = 0)
    )
  ) THEN
    RAISE EXCEPTION 'An avatar must be an https picture link or a path on this app' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.guard_avatar_url() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.guard_avatar_url() TO service_role;

DROP TRIGGER IF EXISTS team_members_avatar_guard ON pm.team_members;
CREATE TRIGGER team_members_avatar_guard BEFORE INSERT OR UPDATE OF avatar ON pm.team_members
  FOR EACH ROW EXECUTE FUNCTION pm.guard_avatar_url();
DROP TRIGGER IF EXISTS contacts_avatar_guard ON pm.contacts;
CREATE TRIGGER contacts_avatar_guard BEFORE INSERT OR UPDATE OF avatar_url ON pm.contacts
  FOR EACH ROW EXECUTE FUNCTION pm.guard_avatar_url();


-- ============================================================
-- API HARDENING (20261127001300_api_hardening.sql)
-- ============================================================

CREATE OR REPLACE FUNCTION pm.extend_task_claim(
  p_task_id uuid,
  p_member_id uuid,
  p_lease_minutes integer DEFAULT 30
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_task pm.tasks;
BEGIN
  IF p_lease_minutes IS NULL OR p_lease_minutes < 1 OR p_lease_minutes > 240 THEN
    RAISE EXCEPTION 'A claim lasts 1 to 240 minutes' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_task FROM pm.tasks WHERE id = p_task_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;
  IF v_task.claimed_by IS NULL THEN
    RETURN jsonb_build_object('outcome', 'not_held');
  END IF;
  IF v_task.claimed_by <> p_member_id THEN
    IF v_task.claim_expires_at > now() THEN
      RETURN jsonb_build_object('outcome', 'held', 'holder', pm.task_claim_holder(v_task));
    END IF;
    RETURN jsonb_build_object('outcome', 'not_held');
  END IF;
  -- Theirs, but run out: a lapsed claim is no claim. Claim it again.
  IF v_task.claim_expires_at IS NULL OR v_task.claim_expires_at <= now() THEN
    RETURN jsonb_build_object('outcome', 'not_held', 'expired', true, 'expired_at', v_task.claim_expires_at);
  END IF;
  UPDATE pm.tasks SET claim_expires_at = now() + make_interval(mins => p_lease_minutes)
  WHERE id = p_task_id
  RETURNING * INTO v_task;
  RETURN jsonb_build_object('outcome', 'extended', 'task', to_jsonb(v_task));
END;
$$;

REVOKE ALL ON FUNCTION pm.extend_task_claim(uuid, uuid, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.extend_task_claim(uuid, uuid, integer) TO service_role;

-- ============================================================
-- LIFECYCLE FIXES (20261127001400_lifecycle_fixes.sql)
-- ============================================================
-- Lifecycle fixes: schedules, suspended members, the AI agents switch,
-- races, Change dates and data retention.
--
-- - pm.claim_schedule_occurrence: a date that made nothing (skipped, or
--   failed twice) is claimed again when the schedule comes back to it, so
--   resuming a schedule on a day it skipped makes that day's run, as the
--   resume answer says. A date that made its work (created, or still
--   running) is still never made twice.
-- - pm.clear_schedule_paused_notice: the "A schedule paused" notice clears
--   when its schedule is active again, ends or is removed (a later pause
--   raises it again).
-- - pm.schedules_kick: a schedule run by an agent is not due while the AI
--   agents module is off (the app holds it back too, claiming nothing), so
--   it runs when the module is on again.
-- - pm.team_member_permissions.given_with_key: a power an agent was given
--   beyond its role by making or editing its key; the app takes it away
--   again when no live key of the agent carries that scope.
-- - pm.questions.expired_reason, pm.close_asks_of_suspended_member: a
--   member who is suspended stops being asked. Their open questions and
--   approvals expire at once with expired_reason asked_member_suspended
--   (question.expired carries it), the asked bell clears, a run one of them
--   held runs again, and whoever asked is told (an agent's people, as the
--   watchdog tells them).
-- - pm.run_watchdog: while the AI agents module is off, runs do not time
--   out (agents cannot report then).
-- - pm.move_task_to_position: POST /api/v1/tasks/reorder in one
--   transaction, one at a time per sibling list, so positions stay unique.
-- - pm.save_task: one save at a time per task, so two "replace assignees"
--   at once leave one list, never both.
-- - pm.reflow_task_template_run: refuses while the run's initiative is in
--   Trash (initiative_in_trash), and moves the initiative's start date with
--   the earliest key date (p_initiative start_from, start_to), under the
--   same rule as its target: only while it still is the old date.
-- - pm.apply_data_retention: a finished run stays while any run in its tree
--   is unfinished or finished inside the window, so a recent run never
--   loses its lineage.
--
-- Additive and safe to run twice. The previous release's code calls every
-- function here with the same arguments and gets the same answer shape
-- (plus new fields), and never reads expired_reason.

-- ---------------------------------------------------------------------------
-- Claiming an occurrence: a date that made nothing is tried again
-- ---------------------------------------------------------------------------
-- Moves the schedule on to (p_next_on, p_next_run_at, p_status) only while
-- it is active and next_run_at is still p_expected_run_at, then records the
-- occurrence for p_scheduled_for. Answers its id, or null when another run
-- claimed it first (nothing changes) or the date already made its work (the
-- schedule still moves on; nothing is made twice). A date whose occurrence
-- made nothing (skipped, or failed on both tries) is reached again only by
-- resuming or changing the schedule: it is claimed again, from its first try.
CREATE OR REPLACE FUNCTION pm.claim_schedule_occurrence(
  p_schedule_id uuid,
  p_expected_run_at timestamptz,
  p_scheduled_for date,
  p_next_on date,
  p_next_run_at timestamptz,
  p_status text DEFAULT 'active',
  p_source_task_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_id uuid;
BEGIN
  UPDATE pm.schedules
  SET next_on = p_next_on,
      next_run_at = p_next_run_at,
      status = coalesce(p_status, 'active'),
      done_on = NULL,
      updated_at = now()
  WHERE id = p_schedule_id
    AND status = 'active'
    AND deleted_at IS NULL
    AND next_run_at IS NOT DISTINCT FROM p_expected_run_at;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  INSERT INTO pm.schedule_occurrences (schedule_id, scheduled_for, source_task_id)
  VALUES (p_schedule_id, p_scheduled_for, p_source_task_id)
  ON CONFLICT (schedule_id, scheduled_for) DO UPDATE
    SET status = 'running', reason = NULL, error = NULL, attempts = 1, run_id = NULL, task_id = NULL,
        source_task_id = EXCLUDED.source_task_id, started_at = now(), finished_at = NULL
    WHERE pm.schedule_occurrences.status = 'skipped'
       OR (pm.schedule_occurrences.status = 'failed' AND pm.schedule_occurrences.attempts >= 2)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION pm.claim_schedule_occurrence(uuid, timestamptz, date, date, timestamptz, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.claim_schedule_occurrence(uuid, timestamptz, date, date, timestamptz, text, uuid) TO service_role;

-- ---------------------------------------------------------------------------
-- The "A schedule paused" notice follows its schedule
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.clear_schedule_paused_notice()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF NEW.status <> 'paused' OR NEW.deleted_at IS NOT NULL THEN
    PERFORM pm.set_notifications_cleared('schedule', NEW.id::text, true, 'A schedule paused');
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.clear_schedule_paused_notice() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS clear_schedule_paused_notice ON pm.schedules;
CREATE TRIGGER clear_schedule_paused_notice
  AFTER UPDATE OF status, deleted_at ON pm.schedules
  FOR EACH ROW
  WHEN (OLD.status = 'paused' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at))
  EXECUTE FUNCTION pm.clear_schedule_paused_notice();

-- ---------------------------------------------------------------------------
-- The kick: a schedule run by an agent waits while the AI agents module is off
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.schedules_kick()
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  app_url text;
  secret text;
  v_agents boolean := pm.module_enabled('agents');
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.schedules s
    WHERE s.status = 'active' AND s.deleted_at IS NULL AND s.next_run_at <= now()
      AND (v_agents OR NOT EXISTS (
        SELECT 1 FROM pm.team_members m WHERE m.id = coalesce(s.run_as, s.created_by) AND m.role = 'agent'))
  ) AND NOT EXISTS (
    SELECT 1 FROM pm.schedule_occurrences o
    JOIN pm.schedules s ON s.id = o.schedule_id
    WHERE s.status IN ('active', 'ended') AND s.deleted_at IS NULL
      AND ((o.status = 'failed' AND o.attempts < 2) OR (o.status = 'running' AND o.started_at < now() - interval '15 minutes'))
      AND (v_agents OR NOT EXISTS (
        SELECT 1 FROM pm.team_members m WHERE m.id = coalesce(s.run_as, s.created_by) AND m.role = 'agent'))
  ) THEN
    RETURN NULL;
  END IF;

  SELECT decrypted_secret INTO app_url FROM vault.decrypted_secrets WHERE name = 'pm_webhook_scheduler_url';
  SELECT decrypted_secret INTO secret FROM vault.decrypted_secrets WHERE name = 'pm_webhook_scheduler_secret';
  IF app_url IS NULL OR secret IS NULL THEN
    RAISE NOTICE 'webhook_scheduler_url or webhook_scheduler_secret is missing from Vault; schedules wait until the app sets up its scheduler';
    RETURN NULL;
  END IF;

  RETURN net.http_post(
    url := rtrim(app_url, '/') || '/api/internal/schedules/run',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || secret),
    body := '{"source":"pg_cron"}'::jsonb,
    timeout_milliseconds := 60000
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.schedules_kick() FROM PUBLIC, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- A power given to an agent with a key is marked as such
-- ---------------------------------------------------------------------------
-- Set by the server when making or editing an agent's key gives it a power
-- beyond its role. Taking that scope off the last live key carrying it takes
-- the power away again; an allow an Owner set in Team > Roles & permissions
-- (false) is never touched by a key edit.
ALTER TABLE pm.team_member_permissions ADD COLUMN IF NOT EXISTS given_with_key boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN pm.team_member_permissions.given_with_key IS
  'True when making or editing an agent''s key gave it this power beyond its role: it goes again when no live key of the agent carries the scope.';

-- ---------------------------------------------------------------------------
-- A suspended member is no longer asked
-- ---------------------------------------------------------------------------
ALTER TABLE pm.questions ADD COLUMN IF NOT EXISTS expired_reason text;
ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_expired_reason_check;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_expired_reason_check CHECK (expired_reason IS NULL OR expired_reason IN ('asked_member_suspended'));

COMMENT ON COLUMN pm.questions.expired_reason IS
  'Why it expired before its time: asked_member_suspended (the member it was asked to was suspended). Null when its time ran out, or it did not expire.';

-- Their open questions and approvals expire now, saying why. Whoever asked
-- is told here, once (the watchdog mark keeps the watchdog from telling
-- them again): an agent's people (its owners, else the Owners), or the
-- person who asked.
CREATE OR REPLACE FUNCTION pm.close_asks_of_suspended_member()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  r record;
  v_people uuid[];
  v_person uuid;
  v_title text;
  v_link text;
BEGIN
  FOR r IN
    WITH closed AS (
      UPDATE pm.questions q
      SET status = 'expired', expires_at = now(), expired_reason = 'asked_member_suspended'
      WHERE q.asked_to = NEW.id AND q.status = 'open' AND q.deleted_at IS NULL
      RETURNING q.id, q.kind, q.question, q.asked_by, q.project_id, q.task_id
    )
    SELECT c.*, asker.name AS asker_name, asker.role AS asker_role
    FROM closed c JOIN pm.team_members asker ON asker.id = c.asked_by
  LOOP
    INSERT INTO pm.watchdog_marks (kind, subject_id, notified_at) VALUES ('question_expired', r.id, now())
    ON CONFLICT (kind, subject_id) DO NOTHING;
    IF r.asker_role = 'agent' THEN
      v_people := pm.agent_people_to_tell(r.asked_by);
      v_title := r.asker_name || '''s ';
      v_link := '/agent/' || r.asked_by;
    ELSE
      SELECT coalesce(array_agg(m.id), '{}') INTO v_people FROM pm.team_members m
      WHERE m.id = r.asked_by AND coalesce(m.status, 'active') = 'active';
      v_title := 'Your ';
      v_link := '/my-tasks';
    END IF;
    IF r.task_id IS NOT NULL AND r.project_id IS NOT NULL THEN
      v_link := '/projects/' || r.project_id || '?task=' || r.task_id;
    END IF;
    v_title := v_title || CASE WHEN r.kind = 'approval' THEN 'approval request to ' ELSE 'question to ' END
      || coalesce(nullif(btrim(NEW.name), ''), 'a teammate')
      || CASE WHEN r.kind = 'approval' THEN ' expired without a decision' ELSE ' expired without an answer' END
      || ': ' || coalesce(nullif(btrim(NEW.name), ''), 'they') || ' was suspended';
    FOREACH v_person IN ARRAY v_people LOOP
      CONTINUE WHEN v_person = NEW.id;
      PERFORM pm.upsert_notification(v_person, left(v_title, 200), left(r.question, 500), v_link, 'question', r.id::text);
    END LOOP;
  END LOOP;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.close_asks_of_suspended_member() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS close_asks_of_suspended_member ON pm.team_members;
CREATE TRIGGER close_asks_of_suspended_member
  AFTER UPDATE OF status ON pm.team_members
  FOR EACH ROW
  WHEN (NEW.status = 'suspended' AND OLD.status IS DISTINCT FROM 'suspended')
  EXECUTE FUNCTION pm.close_asks_of_suspended_member();

-- question.expired says why, when it expired before its time (expired_reason).
CREATE OR REPLACE FUNCTION pm.emit_question_webhook()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_type text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.webhook_endpoints e
    WHERE e.is_active AND e.events && ARRAY['question.asked', 'question.answered', 'question.cancelled', 'question.expired']
  ) THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'open' AND NEW.deleted_at IS NULL THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.deleted_at IS NOT NULL THEN
    IF OLD.deleted_at IS NULL AND OLD.status = 'open' THEN
      v_type := 'question.cancelled';
    END IF;
  ELSIF OLD.deleted_at IS NOT NULL THEN
    IF NEW.status = 'open' THEN
      v_type := 'question.asked';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_type := CASE NEW.status
      WHEN 'open' THEN 'question.asked'
      WHEN 'answered' THEN 'question.answered'
      WHEN 'cancelled' THEN 'question.cancelled'
      WHEN 'expired' THEN 'question.expired'
    END;
  END IF;
  IF v_type IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pm.emit_webhook_event(
    v_type,
    'question',
    NEW.id,
    ARRAY[NEW.project_id],
    pm.webhook_event_members('question', NEW.id),
    jsonb_build_object(
      'question', jsonb_build_object(
        'id', NEW.id,
        'project_id', NEW.project_id,
        'task_id', NEW.task_id,
        'asked_by', NEW.asked_by,
        'asked_to', NEW.asked_to,
        'question', NEW.question,
        'choices', NEW.choices,
        'allow_other', NEW.allow_other,
        'status', NEW.status,
        'answer_choice', NEW.answer_choice,
        'answer_text', NEW.answer_text,
        'answered_by', NEW.answered_by,
        'answered_at', NEW.answered_at,
        'cancelled_by', NEW.cancelled_by,
        'cancelled_at', NEW.cancelled_at,
        'expires_at', NEW.expires_at,
        'created_at', NEW.created_at,
        'updated_at', NEW.updated_at,
        'deleted_at', NEW.deleted_at
      ) || CASE WHEN NEW.kind = 'approval' THEN jsonb_build_object(
        'kind', NEW.kind,
        'action', NEW.action,
        'decision', CASE NEW.answer_choice WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' END,
        'decided_by', CASE WHEN NEW.status = 'answered' THEN NEW.answered_by END,
        'decided_via', CASE WHEN NEW.status = 'answered' THEN NEW.decided_via END
      ) ELSE '{}'::jsonb END
        || CASE WHEN NEW.asked_to_group IS NOT NULL THEN jsonb_build_object('asked_to_group', NEW.asked_to_group) ELSE '{}'::jsonb END
        || CASE WHEN NEW.principal_id IS NOT NULL THEN jsonb_build_object('principal_id', NEW.principal_id) ELSE '{}'::jsonb END
        || CASE WHEN NEW.run_id IS NOT NULL THEN jsonb_build_object('run_id', NEW.run_id) ELSE '{}'::jsonb END
        || CASE WHEN NEW.expired_reason IS NOT NULL THEN jsonb_build_object('expired_reason', NEW.expired_reason) ELSE '{}'::jsonb END,
      'project', CASE WHEN NEW.project_id IS NOT NULL THEN jsonb_build_object(
        'id', NEW.project_id,
        'name', coalesce((SELECT p.name FROM pm.projects p WHERE p.id = NEW.project_id), '')
      ) END,
      'project_id', NEW.project_id,
      'task_id', NEW.task_id,
      'actor_id', pm.webhook_actor_id()
    )
  );
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.emit_question_webhook() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- The watchdog: runs do not time out while the AI agents module is off
-- ---------------------------------------------------------------------------
-- Every 5 minutes. Each change is made once (a stored status, or a marker),
-- so a second run in a row does nothing. Answers what it did.
CREATE OR REPLACE FUNCTION pm.run_watchdog()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  r record;
  v_person uuid;
  v_people uuid[];
  v_claims uuid[];
  v_stale integer;
  v_tell boolean;
  v_text text;
  v_title text;
  v_link text;
  v_workspace_paused boolean;
  v_offline integer := 0;
  v_online integer := 0;
  v_runs integer := 0;
  v_questions integer := 0;
  v_told integer := 0;
  v_webhooks integer := 0;
BEGIN
  -- One watchdog at a time; a run that overlaps the last one waits for the next.
  IF NOT pg_try_advisory_xact_lock(hashtext('pm.run_watchdog')) THEN
    RETURN jsonb_build_object('skipped', true);
  END IF;

  -- Agents that stopped responding, and agents that came back.
  IF pm.module_enabled('agents') THEN
    SELECT coalesce(bool_or(s.agents_paused_at IS NOT NULL), false) INTO v_workspace_paused FROM pm.business_settings s;

    FOR r IN
      SELECT a.id, a.name, h.reported_at, h.expected_interval_seconds AS interval_seconds
      FROM pm.agent_health h
      JOIN pm.team_members a ON a.id = h.member_id
      WHERE a.role = 'agent'
        AND a.delegate_of IS NULL
        AND coalesce(a.status, 'active') = 'active'
        AND a.agent_paused_at IS NULL
        AND NOT v_workspace_paused
        AND h.reported_at < now() - make_interval(secs => pm.heartbeat_stale_after_seconds(h.expected_interval_seconds))
        AND NOT EXISTS (SELECT 1 FROM pm.watchdog_marks w WHERE w.kind = 'agent_offline' AND w.subject_id = a.id)
      ORDER BY h.reported_at
    LOOP
      v_stale := pm.heartbeat_stale_after_seconds(r.interval_seconds);
      -- Claims that ran out while it was silent: those tasks are free again.
      SELECT coalesce(array_agg(t.id ORDER BY t.id), '{}') INTO v_claims
      FROM pm.tasks t
      WHERE t.claimed_by = r.id AND t.claim_expires_at <= now() AND t.claim_expires_at > r.reported_at
        AND t.status <> 'done' AND t.deleted_at IS NULL;
      -- An agent silent long before the watchdog first saw it is marked
      -- without a bell: nobody needs news that old.
      v_tell := now() - r.reported_at <= make_interval(secs => v_stale) + interval '1 day';
      v_people := CASE WHEN v_tell THEN pm.agent_people_to_tell(r.id) ELSE '{}'::uuid[] END;

      INSERT INTO pm.watchdog_marks (kind, subject_id, since, detail, notified_at)
      VALUES ('agent_offline', r.id, r.reported_at, jsonb_build_object('released_task_ids', to_jsonb(v_claims)),
        CASE WHEN cardinality(v_people) > 0 THEN now() END);

      PERFORM pm.emit_webhook_event('agent.offline', 'agent', r.id, '{}'::uuid[], ARRAY[r.id], jsonb_build_object(
        'agent', jsonb_build_object('id', r.id, 'name', r.name, 'reported_at', r.reported_at,
          'expected_interval_seconds', r.interval_seconds, 'stale_after_seconds', v_stale),
        'offline_since', r.reported_at,
        'released_task_ids', to_jsonb(v_claims),
        'project', NULL, 'project_id', NULL, 'task_id', NULL, 'actor_id', NULL));

      v_text := r.name || ' stopped responding ' || pm.watchdog_ago(r.reported_at) || ' ago'
        || CASE cardinality(v_claims)
             WHEN 0 THEN '.'
             WHEN 1 THEN ', its claimed task went back to the queue.'
             ELSE ', its ' || cardinality(v_claims) || ' claimed tasks went back to the queue.'
           END;
      FOREACH v_person IN ARRAY v_people LOOP
        PERFORM pm.upsert_notification(v_person, r.name || ' stopped responding', v_text, '/agent/' || r.id, 'member', r.id::text);
      END LOOP;
      v_offline := v_offline + 1;
    END LOOP;

    FOR r IN
      SELECT w.subject_id AS id, w.since, w.notified_at, a.name, h.reported_at, h.expected_interval_seconds AS interval_seconds
      FROM pm.watchdog_marks w
      JOIN pm.team_members a ON a.id = w.subject_id
      JOIN pm.agent_health h ON h.member_id = w.subject_id
      WHERE w.kind = 'agent_offline'
        AND h.reported_at >= now() - make_interval(secs => pm.heartbeat_stale_after_seconds(h.expected_interval_seconds))
    LOOP
      DELETE FROM pm.watchdog_marks WHERE kind = 'agent_offline' AND subject_id = r.id;
      PERFORM pm.emit_webhook_event('agent.online', 'agent', r.id, '{}'::uuid[], ARRAY[r.id], jsonb_build_object(
        'agent', jsonb_build_object('id', r.id, 'name', r.name, 'reported_at', r.reported_at,
          'expected_interval_seconds', r.interval_seconds, 'stale_after_seconds', pm.heartbeat_stale_after_seconds(r.interval_seconds)),
        'offline_since', r.since,
        'project', NULL, 'project_id', NULL, 'task_id', NULL, 'actor_id', NULL));
      IF r.notified_at IS NOT NULL THEN
        FOREACH v_person IN ARRAY pm.agent_people_to_tell(r.id) LOOP
          PERFORM pm.upsert_notification(v_person, r.name || ' is back', r.name || ' is responding again.', '/agent/' || r.id, 'member', r.id::text);
        END LOOP;
      END IF;
      v_online := v_online + 1;
    END LOOP;

    -- An agent removed, or no longer reporting at all, has nothing to come back from.
    DELETE FROM pm.watchdog_marks w
    WHERE w.kind = 'agent_offline'
      AND NOT EXISTS (
        SELECT 1 FROM pm.team_members a JOIN pm.agent_health h ON h.member_id = a.id
        WHERE a.id = w.subject_id AND a.role = 'agent' AND coalesce(a.status, 'active') = 'active'
      );
  END IF;

  -- Open questions past their time: stored as expired (the same update a
  -- read makes), which sends question.expired and clears the asked bells.
  -- A run one of them held is running again, its clock restarted.
  UPDATE pm.questions SET status = 'expired'
  WHERE status = 'open' AND expires_at <= now();
  GET DIAGNOSTICS v_questions = ROW_COUNT;

  -- Runs with no update for two hours: stored as timed_out, which sends
  -- run.finished. The run ends at its last update. A run waiting on a
  -- person is skipped while a question naming it is open; waiting with
  -- none, it gets seven days.
  -- While the AI agents module is off, agents cannot report, so nothing times out.
  IF pm.module_enabled('agents') THEN
    UPDATE pm.agent_runs run
    SET status = 'timed_out', finished_at = greatest(run.started_at, run.updated_at)
    WHERE (run.status = 'running' AND run.updated_at < now() - interval '2 hours')
       OR (run.status = 'waiting' AND run.updated_at < now() - interval '7 days'
           AND NOT pm.agent_run_has_open_question(run.id));
    GET DIAGNOSTICS v_runs = ROW_COUNT;
  END IF;

  -- Whoever asked hears once, however the expiry was stored, within a day.
  FOR r IN
    SELECT q.id, q.kind, q.question, q.asked_by, q.asked_to, q.project_id, q.task_id,
      asker.name AS asker_name, asker.role AS asker_role, coalesce(target.name, g.name) AS target_name
    FROM pm.questions q
    JOIN pm.team_members asker ON asker.id = q.asked_by
    LEFT JOIN pm.team_members target ON target.id = q.asked_to
    LEFT JOIN pm.groups g ON g.id = q.asked_to_group
    WHERE q.status = 'expired' AND q.deleted_at IS NULL AND q.expires_at > now() - interval '1 day'
      AND NOT EXISTS (SELECT 1 FROM pm.watchdog_marks w WHERE w.kind = 'question_expired' AND w.subject_id = q.id)
    ORDER BY q.expires_at
  LOOP
    INSERT INTO pm.watchdog_marks (kind, subject_id, notified_at) VALUES ('question_expired', r.id, now());
    IF r.asker_role = 'agent' THEN
      v_people := pm.agent_people_to_tell(r.asked_by);
      v_title := r.asker_name || '''s ';
      v_link := '/agent/' || r.asked_by;
    ELSE
      SELECT coalesce(array_agg(m.id), '{}') INTO v_people FROM pm.team_members m
      WHERE m.id = r.asked_by AND coalesce(m.status, 'active') = 'active';
      v_title := 'Your ';
      v_link := '/my-tasks';
    END IF;
    IF r.task_id IS NOT NULL AND r.project_id IS NOT NULL THEN
      v_link := '/projects/' || r.project_id || '?task=' || r.task_id;
    END IF;
    v_title := v_title || CASE WHEN r.kind = 'approval' THEN 'approval request to ' ELSE 'question to ' END
      || coalesce(nullif(btrim(r.target_name), ''), 'a teammate')
      || CASE WHEN r.kind = 'approval' THEN ' expired without a decision' ELSE ' expired without an answer' END;
    FOREACH v_person IN ARRAY v_people LOOP
      -- Whoever was asked already knows.
      CONTINUE WHEN v_person IS NOT DISTINCT FROM r.asked_to;
      PERFORM pm.upsert_notification(v_person, v_title, left(r.question, 500), v_link, 'question', r.id::text);
      v_told := v_told + 1;
    END LOOP;
  END LOOP;
  DELETE FROM pm.watchdog_marks WHERE kind = 'question_expired' AND since < now() - interval '2 days';

  -- Webhook endpoints that keep failing: 5 attempts in a row, or failing for
  -- a day. Told once; a success resets it (track_webhook_endpoint_health).
  IF pm.module_enabled('webhooks') THEN
    FOR r IN
      SELECT w.subject_id AS id, w.detail, e.name
      FROM pm.watchdog_marks w
      JOIN pm.webhook_endpoints e ON e.id = w.subject_id
      WHERE w.kind = 'webhook_failing' AND w.notified_at IS NULL AND e.is_active
        AND (w.failures >= 5 OR w.since <= now() - interval '24 hours')
    LOOP
      UPDATE pm.watchdog_marks SET notified_at = now(), updated_at = now()
      WHERE kind = 'webhook_failing' AND subject_id = r.id;
      FOR v_person IN
        SELECT m.id FROM pm.team_members m
        WHERE m.role <> 'agent' AND coalesce(m.status, 'active') = 'active'
          AND (m.role = 'owner' OR pm.member_has_permission(m.id, 'webhooks.manage', 'app'))
        ORDER BY m.id
      LOOP
        PERFORM pm.upsert_notification(v_person, 'Webhook ' || r.name || ' keeps failing',
          'Last error: ' || coalesce(r.detail ->> 'last_error', 'unknown'), '/settings/developers#webhooks', 'webhook', r.id::text);
      END LOOP;
      v_webhooks := v_webhooks + 1;
    END LOOP;
  END IF;
  DELETE FROM pm.watchdog_marks w
  WHERE w.kind = 'webhook_failing'
    AND NOT EXISTS (SELECT 1 FROM pm.webhook_endpoints e WHERE e.id = w.subject_id);

  RETURN jsonb_build_object(
    'agents_offline', v_offline,
    'agents_online', v_online,
    'runs_timed_out', v_runs,
    'questions_expired', v_questions,
    'askers_told', v_told,
    'webhooks_failing', v_webhooks
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.run_watchdog() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.run_watchdog() TO service_role;

-- ---------------------------------------------------------------------------
-- Reordering a task, one at a time per sibling list
-- ---------------------------------------------------------------------------
-- Moves a task to p_position among its siblings (a subtask's: its parent's
-- other subtasks; a top-level task's: the top-level tasks in its project and
-- status column), then numbers them 0, 1, 2... in that order, writing only
-- the rows that change. One move at a time per sibling list, so moves sent
-- together never leave two tasks on one position. Answers the task's new
-- position, or null when it is missing or in Trash.
CREATE OR REPLACE FUNCTION pm.move_task_to_position(p_task_id uuid, p_position integer)
RETURNS integer
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_task pm.tasks%ROWTYPE;
  v_count integer;
  v_at integer;
BEGIN
  SELECT * INTO v_task FROM pm.tasks WHERE id = p_task_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('pm.task_order'),
    hashtext(coalesce(v_task.parent_task_id::text, v_task.project_id::text || ':' || coalesce(v_task.status, ''))));
  -- Read again under the lock: another move may have changed it.
  SELECT * INTO v_task FROM pm.tasks WHERE id = p_task_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_count FROM pm.tasks t
  WHERE t.deleted_at IS NULL AND t.id <> p_task_id
    AND CASE WHEN v_task.parent_task_id IS NOT NULL THEN t.parent_task_id = v_task.parent_task_id
             ELSE t.parent_task_id IS NULL AND t.project_id = v_task.project_id AND t.status IS NOT DISTINCT FROM v_task.status END;
  v_at := least(greatest(coalesce(p_position, 0), 0), v_count);

  WITH siblings AS (
    SELECT t.id, (row_number() OVER (ORDER BY t.sort_order, t.created_at, t.id) - 1)::integer AS pos
    FROM pm.tasks t
    WHERE t.deleted_at IS NULL AND t.id <> p_task_id
      AND CASE WHEN v_task.parent_task_id IS NOT NULL THEN t.parent_task_id = v_task.parent_task_id
               ELSE t.parent_task_id IS NULL AND t.project_id = v_task.project_id AND t.status IS NOT DISTINCT FROM v_task.status END
  ), placed AS (
    SELECT s.id, CASE WHEN s.pos < v_at THEN s.pos ELSE s.pos + 1 END AS sort_order FROM siblings s
    UNION ALL
    SELECT p_task_id, v_at
  )
  UPDATE pm.tasks t SET sort_order = p.sort_order
  FROM placed p
  WHERE t.id = p.id AND t.sort_order IS DISTINCT FROM p.sort_order;

  RETURN v_at;
END;
$$;

REVOKE ALL ON FUNCTION pm.move_task_to_position(uuid, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.move_task_to_position(uuid, integer) TO service_role;

-- ---------------------------------------------------------------------------
-- Saving a task: one save at a time per task
-- ---------------------------------------------------------------------------
-- As before: a task row and its assignees, criteria and blockers in one
-- transaction. SECURITY INVOKER, so every RLS policy still applies. p_task is
-- a column patch; a NULL list is left unchanged, an empty list clears it.
CREATE OR REPLACE FUNCTION pm.save_task(
  p_task_id uuid,
  p_task jsonb,
  p_assignee_ids uuid[] DEFAULT NULL,
  p_criteria text[] DEFAULT NULL,
  p_blocked_by uuid[] DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pm
AS $$
DECLARE
  v_task_id uuid := p_task_id;
  v_payload jsonb := COALESCE(p_task, '{}'::jsonb);
  v_unknown text;
  v_cols text[];
  v_rows integer;
  v_task pm.tasks;
BEGIN
  IF jsonb_typeof(v_payload) <> 'object' THEN
    RAISE EXCEPTION 'save_task: p_task must be a JSON object' USING ERRCODE = '22023';
  END IF;

  -- Same contract as a PostgREST update: an unknown column is an error, not
  -- a silently dropped field.
  SELECT key INTO v_unknown
  FROM jsonb_object_keys(v_payload) AS key
  WHERE NOT EXISTS (
    SELECT 1 FROM pg_attribute a
    WHERE a.attrelid = 'pm.tasks'::regclass
      AND a.attnum > 0
      AND NOT a.attisdropped
      AND a.attname = key
  )
  LIMIT 1;
  IF v_unknown IS NOT NULL THEN
    RAISE EXCEPTION 'save_task: unknown task column "%"', v_unknown USING ERRCODE = '42703';
  END IF;

  -- One save at a time per task: two saves replacing its lists at once
  -- would each keep what the other added (each delete misses the other's
  -- uncommitted rows). Held to the end of the transaction.
  IF v_task_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('pm.save_task'), hashtext(v_task_id::text));
  END IF;

  SELECT array_agg(key ORDER BY key) INTO v_cols
  FROM jsonb_object_keys(v_payload) AS key
  WHERE key NOT IN ('id', 'created_at');

  IF v_task_id IS NULL THEN
    IF v_cols IS NULL THEN
      RAISE EXCEPTION 'save_task: a new task needs its columns' USING ERRCODE = '22023';
    END IF;
    EXECUTE format(
      'INSERT INTO pm.tasks (%s) SELECT %s FROM jsonb_populate_record(NULL::pm.tasks, $1) r RETURNING id',
      (SELECT string_agg(format('%I', c), ', ') FROM unnest(v_cols) c),
      (SELECT string_agg(format('r.%I', c), ', ') FROM unnest(v_cols) c)
    ) INTO v_task_id USING v_payload;
  ELSIF v_cols IS NOT NULL THEN
    EXECUTE format(
      'UPDATE pm.tasks t SET %s FROM jsonb_populate_record(NULL::pm.tasks, $1) r WHERE t.id = $2',
      (SELECT string_agg(format('%I = r.%I', c, c), ', ') FROM unnest(v_cols) c)
    ) USING v_payload, v_task_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    -- RLS turns a denied update into zero rows; that is a failure, not a save.
    IF v_rows = 0 THEN
      RAISE EXCEPTION 'save_task: task % not found or not permitted', v_task_id USING ERRCODE = 'P0002';
    END IF;
  ELSE
    PERFORM 1 FROM pm.tasks WHERE id = v_task_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'save_task: task % not found or not permitted', v_task_id USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_assignee_ids IS NOT NULL THEN
    DELETE FROM pm.task_assignees
    WHERE task_id = v_task_id AND NOT (member_id = ANY (p_assignee_ids));
    INSERT INTO pm.task_assignees (task_id, member_id)
    SELECT DISTINCT v_task_id, member_id FROM unnest(p_assignee_ids) AS member_id
    ON CONFLICT (task_id, member_id) DO NOTHING;
  END IF;

  IF p_criteria IS NOT NULL THEN
    DELETE FROM pm.task_acceptance_criteria WHERE task_id = v_task_id;
    INSERT INTO pm.task_acceptance_criteria (task_id, criterion, sort_order)
    SELECT v_task_id, c.criterion, (c.ordinality - 1)::int
    FROM unnest(p_criteria) WITH ORDINALITY AS c(criterion, ordinality);
  END IF;

  IF p_blocked_by IS NOT NULL THEN
    DELETE FROM pm.task_dependencies WHERE task_id = v_task_id;
    INSERT INTO pm.task_dependencies (task_id, blocked_by_task_id)
    SELECT DISTINCT v_task_id, blocked_by FROM unnest(p_blocked_by) AS blocked_by;
  END IF;

  SELECT * INTO v_task FROM pm.tasks WHERE id = v_task_id;
  RETURN jsonb_build_object(
    'task', to_jsonb(v_task),
    'criteria', COALESCE((
      SELECT jsonb_agg(to_jsonb(c) ORDER BY c.sort_order)
      FROM pm.task_acceptance_criteria c
      WHERE c.task_id = v_task_id
    ), '[]'::jsonb)
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.save_task(uuid, jsonb, uuid[], text[], uuid[]) FROM public, anon;
GRANT EXECUTE ON FUNCTION pm.save_task(uuid, jsonb, uuid[], text[], uuid[]) TO authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Reflow: refused while the initiative is in Trash; its start follows too
-- ---------------------------------------------------------------------------
-- In one transaction: the run's key dates (refused when they changed since
-- the caller read them: run_changed; refused while the run's initiative is
-- in Trash: initiative_in_trash), each task in p_moves that is still not
-- done, not in Trash, and still due on its planned date (or forced: a
-- hand-changed task the caller opted in), its planned date with it, and the
-- initiative's dates: its target when it still is the old main key date,
-- its start when it still is the old earliest key date. p_moves is
-- [{ task_id, due_date, force }]; p_initiative is { id, from, to,
-- start_from, start_to } (each pair only when that date follows) or null.
-- Logs the change in the team activity log as whoever made it (a person;
-- agents keep their own log). Answers { moved: [task ids],
-- initiative_moved: boolean, initiative_start_moved: boolean }.
CREATE OR REPLACE FUNCTION pm.reflow_task_template_run(
  p_run_id uuid,
  p_expected jsonb,
  p_key_dates jsonb,
  p_start_date date,
  p_moves jsonb,
  p_initiative jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_run pm.task_template_runs%ROWTYPE;
  v_moved uuid[];
  v_initiative_moved boolean := false;
  v_start_moved boolean := false;
  v_initiative pm.initiatives%ROWTYPE;
BEGIN
  SELECT * INTO v_run FROM pm.task_template_runs WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_run.key_dates IS DISTINCT FROM coalesce(p_expected, '{}'::jsonb) THEN
    RAISE EXCEPTION 'run_changed' USING ERRCODE = 'P0001';
  END IF;
  -- The run lives on its initiative: while that is in Trash, nothing moves.
  IF EXISTS (SELECT 1 FROM pm.initiatives i WHERE i.id = v_run.initiative_id AND i.deleted_at IS NOT NULL) THEN
    RAISE EXCEPTION 'initiative_in_trash' USING ERRCODE = 'P0001';
  END IF;

  WITH wanted AS (
    SELECT (m ->> 'task_id')::uuid AS task_id, (m ->> 'due_date')::date AS due_date, coalesce((m ->> 'force')::boolean, false) AS force
    FROM jsonb_array_elements(coalesce(p_moves, '[]'::jsonb)) AS m
  ),
  moved AS (
    UPDATE pm.tasks t
    SET due_date = to_char(w.due_date, 'YYYY-MM-DD')
    FROM wanted w, pm.task_template_run_tasks l
    WHERE t.id = w.task_id
      AND l.run_id = p_run_id AND l.task_id = t.id
      AND t.deleted_at IS NULL
      AND t.status <> 'done'
      AND (w.force OR left(t.due_date, 10) IS NOT DISTINCT FROM to_char(l.planned_due_date, 'YYYY-MM-DD'))
    RETURNING t.id, w.due_date
  ),
  planned AS (
    UPDATE pm.task_template_run_tasks l
    SET planned_due_date = moved.due_date
    FROM moved
    WHERE l.run_id = p_run_id AND l.task_id = moved.id
    RETURNING l.task_id
  )
  SELECT coalesce(array_agg(task_id), '{}') INTO v_moved FROM planned;

  UPDATE pm.task_template_runs
  SET key_dates = coalesce(p_key_dates, '{}'::jsonb), start_date = coalesce(p_start_date, start_date)
  WHERE id = p_run_id;

  IF p_initiative IS NOT NULL AND p_initiative ? 'id' AND (p_initiative ? 'to' OR NOT p_initiative ? 'start_to') THEN
    UPDATE pm.initiatives
    SET target_date = nullif(p_initiative ->> 'to', '')::date
    WHERE id = (p_initiative ->> 'id')::uuid
      AND deleted_at IS NULL
      AND target_date IS NOT DISTINCT FROM nullif(p_initiative ->> 'from', '')::date;
    v_initiative_moved := FOUND;
  END IF;
  -- Its start follows the earliest key date, under the same rule.
  IF p_initiative IS NOT NULL AND p_initiative ? 'id' AND p_initiative ? 'start_to' THEN
    UPDATE pm.initiatives
    SET start_date = nullif(p_initiative ->> 'start_to', '')::date
    WHERE id = (p_initiative ->> 'id')::uuid
      AND deleted_at IS NULL
      AND start_date IS NOT DISTINCT FROM nullif(p_initiative ->> 'start_from', '')::date;
    v_start_moved := FOUND;
  END IF;

  IF v_run.key_dates IS DISTINCT FROM coalesce(p_key_dates, '{}'::jsonb) AND v_run.initiative_id IS NOT NULL THEN
    SELECT * INTO v_initiative FROM pm.initiatives WHERE id = v_run.initiative_id;
    IF FOUND THEN
      PERFORM pm.log_team_activity(
        'initiative.key_dates',
        'initiative',
        v_initiative.id::text,
        v_run.project_id,
        format('Changed the key dates of "%s"', v_initiative.name),
        jsonb_build_object(
          'initiative_id', v_initiative.id,
          'initiative_name', v_initiative.name,
          'run_id', v_run.id,
          'template_id', v_run.template_id,
          'from', v_run.key_dates,
          'to', coalesce(p_key_dates, '{}'::jsonb),
          'moved', coalesce(array_length(v_moved, 1), 0)
        )
      );
    END IF;
  END IF;

  RETURN jsonb_build_object('moved', to_jsonb(v_moved), 'initiative_moved', v_initiative_moved, 'initiative_start_moved', v_start_moved);
END;
$$;

REVOKE ALL ON FUNCTION pm.reflow_task_template_run(uuid, jsonb, jsonb, date, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.reflow_task_template_run(uuid, jsonb, jsonb, date, jsonb, jsonb) TO service_role;

-- ---------------------------------------------------------------------------
-- Data retention: a run tree goes together
-- ---------------------------------------------------------------------------
-- Daily. Up to 20 batches of 5,000 rows per kind per run, so a large
-- backlog is worked down over a few days without a long transaction. Answers
-- how many rows went (chat: how many texts were blanked). A finished run
-- stays while any run in its tree (its root and every run under it) is
-- unfinished or finished inside the window.
CREATE OR REPLACE FUNCTION pm.apply_data_retention()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  batch constant integer := 5000;
  max_rounds constant integer := 20;
  s record;
  v_cutoff timestamptz;
  v_n integer;
  v_round integer;
  v_deliveries integer := 0;
  v_events integer := 0;
  v_health integer := 0;
  v_activities integer := 0;
  v_runs integer := 0;
  v_chat integer := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('pm.apply_data_retention')) THEN
    RETURN jsonb_build_object('skipped', true);
  END IF;
  SELECT webhook_retention_days, agent_health_history_days, agent_activity_retention_days,
    agent_run_retention_days, chat_retention_days
  INTO s FROM pm.business_settings LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true);
  END IF;

  -- Webhooks: finished deliveries, then events no delivery needs any more.
  IF s.webhook_retention_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.webhook_retention_days);
    v_round := 0;
    LOOP
      DELETE FROM pm.webhook_deliveries WHERE id IN (
        SELECT d.id FROM pm.webhook_deliveries d
        WHERE d.status IN ('succeeded', 'failed') AND d.created_at < v_cutoff
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_deliveries := v_deliveries + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
    v_round := 0;
    LOOP
      DELETE FROM pm.webhook_events WHERE id IN (
        SELECT ev.id FROM pm.webhook_events ev
        WHERE ev.created_at < v_cutoff
          AND NOT EXISTS (SELECT 1 FROM pm.webhook_deliveries d WHERE d.webhook_event_id = ev.id)
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_events := v_events + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
  END IF;

  -- Uptime history: the newest row per agent stays, so its state is known.
  IF s.agent_health_history_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.agent_health_history_days);
    v_round := 0;
    LOOP
      DELETE FROM pm.agent_health_history WHERE id IN (
        SELECT h.id FROM pm.agent_health_history h
        WHERE h.changed_at < v_cutoff
          AND EXISTS (SELECT 1 FROM pm.agent_health_history newer
                      WHERE newer.member_id = h.member_id AND newer.changed_at > h.changed_at)
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_health := v_health + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
  END IF;

  -- Agent events: billing events (what agent time was billed from) stay.
  IF s.agent_activity_retention_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.agent_activity_retention_days);
    v_round := 0;
    LOOP
      DELETE FROM pm.agent_activities WHERE id IN (
        SELECT a.id FROM pm.agent_activities a
        WHERE a.created_at < v_cutoff AND a.activity_type NOT LIKE 'billing.%'
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_activities := v_activities + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
  END IF;

  -- Finished runs, unless an unfinished run, an open delegation or a pending
  -- delivery still needs them.
  IF s.agent_run_retention_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.agent_run_retention_days);
    PERFORM set_config('pm.data_retention', 'on', true);
    v_round := 0;
    LOOP
      DELETE FROM pm.agent_runs WHERE id IN (
        SELECT r.id FROM pm.agent_runs r
        WHERE r.status <> 'running' AND r.finished_at < v_cutoff
          AND NOT EXISTS (SELECT 1 FROM pm.agent_runs c
                          WHERE (c.parent_run_id = r.id OR c.root_run_id = r.id) AND c.status IN ('running', 'waiting'))
          -- The whole tree goes together: none of it while any run in it is
          -- unfinished or finished inside the window.
          AND NOT EXISTS (SELECT 1 FROM pm.agent_runs o
                          WHERE (o.id = coalesce(r.root_run_id, r.id) OR o.root_run_id = coalesce(r.root_run_id, r.id))
                            AND (o.finished_at IS NULL OR o.finished_at >= v_cutoff))
          AND NOT EXISTS (SELECT 1 FROM pm.task_delegations dl JOIN pm.tasks t ON t.id = dl.task_id
                          WHERE dl.run_id = r.id AND t.status <> 'done' AND t.deleted_at IS NULL)
          AND NOT EXISTS (SELECT 1 FROM pm.webhook_events ev JOIN pm.webhook_deliveries d ON d.webhook_event_id = ev.id
                          WHERE ev.resource_type = 'run' AND ev.resource_id = r.id AND d.status IN ('pending', 'delivering'))
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_runs := v_runs + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
    PERFORM set_config('pm.data_retention', 'off', true);
  END IF;

  -- Chat text is blanked, the row stays: its dedupe key (a provider retry,
  -- the one on-hold notice) and its place in the thread still count. A
  -- message still waiting for its assistant, or for a delivery, keeps it.
  IF s.chat_retention_days IS NOT NULL THEN
    v_cutoff := now() - make_interval(days => s.chat_retention_days);
    v_round := 0;
    LOOP
      UPDATE pm.chat_messages SET text = '' WHERE id IN (
        SELECT m.id FROM pm.chat_messages m
        WHERE m.text <> '' AND m.created_at < v_cutoff
          AND NOT (m.direction = 'inbound' AND m.status IN ('pending', 'notified'))
          AND NOT EXISTS (SELECT 1 FROM pm.webhook_events ev JOIN pm.webhook_deliveries d ON d.webhook_event_id = ev.id
                          WHERE ev.resource_type = 'chat_message' AND ev.resource_id = m.id AND d.status IN ('pending', 'delivering'))
        LIMIT batch);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_chat := v_chat + v_n;
      v_round := v_round + 1;
      EXIT WHEN v_n < batch OR v_round >= max_rounds;
    END LOOP;
  END IF;

  IF v_deliveries + v_events + v_health + v_activities + v_runs + v_chat > 0 THEN
    INSERT INTO pm.api_audit_log (method, endpoint, entity_type, request_body, status_code, via)
    VALUES ('DELETE', '/app/data/retention', 'business_settings', jsonb_build_object(
      'webhook_deliveries', v_deliveries, 'webhook_events', v_events, 'agent_health_history', v_health,
      'agent_activities', v_activities, 'agent_runs', v_runs, 'chat_texts', v_chat), 200, 'app');
  END IF;
  RETURN jsonb_build_object(
    'webhook_deliveries', v_deliveries,
    'webhook_events', v_events,
    'agent_health_history', v_health,
    'agent_activities', v_activities,
    'agent_runs', v_runs,
    'chat_texts', v_chat
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.apply_data_retention() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.apply_data_retention() TO service_role;

-- ============================================================
-- UI FIXES (20261127001500_ui_fixes.sql)
-- ============================================================

-- ---------------------------------------------------------------------------
-- Questions: a guest sees only what is addressed to them
-- ---------------------------------------------------------------------------
-- A guest (a client let into some projects) saw the team's own questions and
-- approvals on the tasks they can open. A guest now reads a question only as a
-- party: asked by them, asked of them, or asked of a group they are in.
-- Everyone else reads as before. The app's read (lib/api/questions.ts,
-- isGuestReader) applies the same rule.
DROP POLICY IF EXISTS questions_select ON pm.questions;
CREATE POLICY questions_select ON pm.questions FOR SELECT TO authenticated
  USING (
    asked_by = pm.current_team_member_id()
    OR asked_to = pm.current_team_member_id()
    OR (asked_to_group IS NOT NULL AND EXISTS (SELECT 1 FROM pm.group_members gm WHERE gm.group_id = questions.asked_to_group AND gm.member_id = pm.current_team_member_id()))
    OR (
      pm.current_team_member_role() IS DISTINCT FROM 'guest'
      AND (
        (task_id IS NOT NULL AND pm.can_access_task(task_id))
        OR (task_id IS NULL AND project_id IS NOT NULL AND pm.can_access_project(project_id))
      )
    )
  );


-- ---------------------------------------------------------------------------
-- Agents and keys
-- ---------------------------------------------------------------------------
-- One hire per attempt: the Hire screen (and any API caller) sends a
-- request_id once per attempt; the first call claims it here in one insert,
-- so a double click makes one agent and one key. Read and written by the
-- server only.
CREATE TABLE IF NOT EXISTS pm.agent_hire_requests (
  request_id uuid PRIMARY KEY,
  hired_by uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  -- Set once the hire went through; null while it runs.
  agent_id uuid REFERENCES pm.team_members(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE pm.agent_hire_requests IS
  'One row per hire attempt (request_id from POST /api/workspace/agents or /api/v1/agents/hire): a second call with the same id hires nothing more.';

ALTER TABLE pm.agent_hire_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.agent_hire_requests FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.agent_hire_requests TO service_role;

-- ---------------------------------------------------------------------------
-- Agent analytics: runs still going are counted apart (a 15th group value)
-- ---------------------------------------------------------------------------
-- Agents > Analytics read "15 runs, 100% succeeded" with 14 still running:
-- each group now also carries how many of its runs are running or waiting,
-- appended as the last value, so a previous release's code reads it as before.
CREATE OR REPLACE FUNCTION pm.agent_run_stats(
  p_start date,
  p_end date,
  p_tz text,
  p_project_ids uuid[] DEFAULT NULL,
  p_now timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pm
AS $$
  with feed as (
    select f.id, f.source, f.agent_id, f.project_id, f.status, f.outcome, f.title, f.model, r.provider,
           f.started_at, f.finished_at, f.duration_ms, f.tokens_in, f.tokens_out, f.cost_usd
    from agent_run_feed f
    left join agent_runs r on f.source = 'run' and r.id = f.id
    where f.sort_at >= (p_start::timestamp - interval '1 day') at time zone 'UTC'
      and f.sort_at <= (p_end::timestamp + interval '2 days' - interval '1 millisecond') at time zone 'UTC'
  ),
  attached as (
    select a.metadata->>'run_id' as run_id,
           sum(agent_analytics_int(a.metadata->'tokens'->>'input')) filter (where a.metadata->'tokens' ? 'input') as tokens_in,
           sum(agent_analytics_int(a.metadata->'tokens'->>'output')) filter (where a.metadata->'tokens' ? 'output') as tokens_out
    from agent_activities a
    where a.activity_type = 'turn.completed'
      and a.metadata->>'run_id' in (select id::text from feed where source = 'run' and tokens_in is null and tokens_out is null)
      and a.metadata->>'tokens_scope' = 'turn'
    group by a.metadata->>'run_id'
  ),
  runs as (
    select f.*,
      (f.started_at at time zone p_tz)::date as day,
      case
        when f.status in ('running', 'waiting') then f.status
        when f.source = 'run' then case f.status when 'succeeded' then 'success' when 'failed' then 'failure'
          when 'timed_out' then 'failure' else 'neutral' end
        when lower(coalesce(f.outcome, '')) = 'blocked' then 'neutral'
        when lower(coalesce(f.outcome, '')) in ('failed', 'error') then 'failure'
        when lower(coalesce(f.outcome, '')) in ('idle', 'skipped', 'waiting', 'no_work', 'nothing', 'nothing_to_do') then 'neutral'
        when coalesce(f.outcome, '') = '' or lower(f.outcome) in ('work', 'worked', 'ok', 'done', 'shipped', 'succeeded') then 'success'
        else 'neutral'
      end as verdict,
      case when f.source = 'run' and f.tokens_in is null and f.tokens_out is null then t.tokens_in else f.tokens_in end as tin,
      case when f.source = 'run' and f.tokens_in is null and f.tokens_out is null then t.tokens_out else f.tokens_out end as tout,
      case
        when f.duration_ms is not null then greatest(f.duration_ms, 0)
        when f.finished_at is not null then greatest(floor(extract(epoch from f.finished_at) * 1000) - floor(extract(epoch from f.started_at) * 1000), 0)::bigint
        when f.status = 'running' then greatest(floor(extract(epoch from p_now) * 1000) - floor(extract(epoch from f.started_at) * 1000), 0)::bigint
      end as span_ms
    from feed f
    left join attached t on t.run_id = f.id::text
  ),
  placed as (
    select * from runs where day >= p_start and day <= p_end
  ),
  spans as (
    select p.id, p.agent_id, p.project_id, p.model, p.provider, p.day,
           floor(extract(epoch from p.started_at) * 1000)::bigint as s,
           floor(extract(epoch from p.started_at) * 1000)::bigint + p.span_ms as e
    from placed p
    where p.span_ms > 0
      and (p_project_ids is null or p.project_id = any (p_project_ids))
  ),
  clipped as (
    select sp.*,
      max(sp.e) over (partition by sp.agent_id order by sp.s, sp.e, sp.id rows between unbounded preceding and 1 preceding) as covered
    from spans sp
  ),
  busy as (
    select agent_id, project_id, model, provider, day,
           sum(greatest(0, e - greatest(s, coalesce(covered, s)))) as busy_ms
    from clipped
    group by agent_id, project_id, model, provider, day
  ),
  counts as (
    select agent_id, project_id, model, provider, day,
      count(*) as runs,
      count(*) filter (where verdict = 'success') as succeeded,
      count(*) filter (where verdict = 'failure') as failed,
      count(*) filter (where verdict in ('running', 'waiting')) as running,
      coalesce(sum(tin), 0) as tokens_in,
      coalesce(sum(tout), 0) as tokens_out,
      coalesce(sum(cost_usd) filter (where cost_usd > 0), 0) as cost_usd,
      coalesce(sum(coalesce(tin, 0) + coalesce(tout, 0)) filter (where not (coalesce(cost_usd, 0) > 0)), 0) as unpriced_tokens,
      count(*) filter (where source = 'run' and tin is null and tout is null) as runs_no_tokens
    from placed
    group by agent_id, project_id, model, provider, day
  ),
  grouped as (
    select coalesce(c.agent_id, b.agent_id) as agent_id, coalesce(c.project_id, b.project_id) as project_id,
           coalesce(c.model, b.model) as model, coalesce(c.provider, b.provider) as provider, coalesce(c.day, b.day) as day,
           coalesce(c.runs, 0) as runs, coalesce(c.succeeded, 0) as succeeded, coalesce(c.failed, 0) as failed,
           coalesce(b.busy_ms, 0) as busy_ms, coalesce(c.tokens_in, 0) as tokens_in, coalesce(c.tokens_out, 0) as tokens_out,
           coalesce(c.cost_usd, 0) as cost_usd, coalesce(c.unpriced_tokens, 0) as unpriced_tokens,
           coalesce(c.runs_no_tokens, 0) as runs_no_tokens,
           coalesce(c.running, 0) as running
    from counts c
    full join busy b on b.agent_id = c.agent_id and b.project_id is not distinct from c.project_id
      and b.model is not distinct from c.model and b.provider is not distinct from c.provider and b.day = c.day
  ),
  spend as (
    select f.agent_id, f.project_id, f.model, f.provider, (f.at at time zone p_tz)::date as day, f.labels, f.principal_id,
           sum(f.tokens_in) as tokens_in, sum(f.tokens_out) as tokens_out, sum(f.tokens_cached) as tokens_cached,
           coalesce(sum(f.cost_usd), 0) as cost_usd,
           coalesce(sum(f.tokens_in + f.tokens_out + f.tokens_cached) filter (where f.cost_usd is null), 0) as unpriced_tokens
    from agent_spend_facts(p_start::timestamp at time zone p_tz, (p_end + 1)::timestamp at time zone p_tz, null) f
    group by f.agent_id, f.project_id, f.model, f.provider, (f.at at time zone p_tz)::date, f.labels, f.principal_id
  )
  select jsonb_build_object(
    'groups', coalesce((
      select jsonb_agg(jsonb_build_array(g.agent_id, g.project_id, g.model, g.provider, to_char(g.day, 'YYYY-MM-DD'),
        g.runs, g.succeeded, g.failed, g.busy_ms, g.tokens_in, g.tokens_out, g.cost_usd, g.unpriced_tokens, g.runs_no_tokens, g.running))
      from grouped g
    ), '[]'::jsonb),
    'failures', coalesce((
      select jsonb_agg(jsonb_build_array(r.agent_id, r.project_id, r.model, r.provider, r.started_at, r.title, r.status)
        order by r.started_at)
      from runs r
      where r.verdict = 'failure'
    ), '[]'::jsonb),
    'spend', coalesce((
      select jsonb_agg(jsonb_build_array(sp.agent_id, sp.project_id, sp.model, sp.provider, to_char(sp.day, 'YYYY-MM-DD'),
        to_jsonb(sp.labels), sp.tokens_in, sp.tokens_out, sp.tokens_cached, sp.cost_usd, sp.unpriced_tokens, sp.principal_id))
      from spend sp
    ), '[]'::jsonb)
  );
$$;

REVOKE ALL ON FUNCTION pm.agent_run_stats(date, date, text, uuid[], timestamptz) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION pm.agent_run_stats(date, date, text, uuid[], timestamptz) TO authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Time zones: a person's profile zone is the one the app uses
-- ---------------------------------------------------------------------------
-- Every profile started as UTC, so a stored UTC could not tell "chosen" from
-- "never set". timezone_set says the person chose it (or their first sign-in
-- took it from the browser); until then the app uses the browser's zone and
-- the first sign-in saves it. A zone other than UTC was chosen by someone.
ALTER TABLE pm.team_members
  ADD COLUMN IF NOT EXISTS timezone_set boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN pm.team_members.timezone_set IS
  'The time zone was chosen (in Settings, or from the browser on first sign-in); false while it is the default.';

UPDATE pm.team_members SET timezone_set = true WHERE NOT timezone_set AND timezone IS DISTINCT FROM 'UTC';

-- A change to the zone from any path (the app, the API) makes it chosen.
CREATE OR REPLACE FUNCTION pm.team_members_mark_timezone_set()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.timezone_set := NEW.timezone_set OR NEW.timezone IS DISTINCT FROM 'UTC';
  ELSIF NEW.timezone IS DISTINCT FROM OLD.timezone THEN
    NEW.timezone_set := true;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.team_members_mark_timezone_set() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS team_members_mark_timezone_set ON pm.team_members;
CREATE TRIGGER team_members_mark_timezone_set
  BEFORE INSERT OR UPDATE OF timezone ON pm.team_members
  FOR EACH ROW EXECUTE FUNCTION pm.team_members_mark_timezone_set();

-- ============================================================
-- RUNTIME FOR WORKER POOLS (20261127002000_agent_runtime.sql)
-- ============================================================
-- Agent runtime: what a pool of workers behind one agent needs from core.
--
-- - Instances: agent_runs.instance_id (which worker runs it), and
--   pm.agent_instances (one row per worker that beats or reports), so an
--   agent's detail says how many workers are live ("3 working now").
-- - Resume notes and blocked runs: agent_runs.resume_notes (where a worker
--   picking the run up again starts), blocked_at and blocked_reason (a run
--   that cannot go on without a person, surfaced on Needs you for its
--   managers and the task's people through pm.my_blocked_runs until it moves).
-- - A spend limit per run: agent_limits.max_run_spend_cents.
-- - Chat claims: a lease on a chat message (chat_messages.claim_*) or a whole
--   conversation (pm.chat_conversations), held by an agent and, optionally,
--   one of its workers (instance). pm.chat_claim claims, extends and
--   releases; a lapsed lease is no lease. New inbound requests are linked to
--   their conversation (one per DM, per channel thread) by a trigger.
-- - Answers that do the thing: questions.performs (an action from the app's
--   whitelist the answer performs, as whoever answers) and performed (what
--   happened). Orchestrator routing: questions.requested_to and
--   requested_to_group (whom the agent asked, when the question went to its
--   orchestrator first) and team_members.ask_people_directly.
-- - Host keys: permission agents.host (AI agents module) and
--   api_keys.host_agent_ids, the agents a host key serves; the host feed
--   reads those agents' events (pm.event_feed_read_host).
--
-- Additive and safe to run twice. 2.0.50 code never reads the new columns
-- and tables; the replaced feed triggers only add fields to what they wrote.

-- ---------------------------------------------------------------------------
-- Runs: instance, resume notes, blocked
-- ---------------------------------------------------------------------------
ALTER TABLE pm.agent_runs
  ADD COLUMN IF NOT EXISTS instance_id text,
  ADD COLUMN IF NOT EXISTS resume_notes text,
  ADD COLUMN IF NOT EXISTS blocked_at timestamptz,
  ADD COLUMN IF NOT EXISTS blocked_reason text;

ALTER TABLE pm.agent_runs DROP CONSTRAINT IF EXISTS agent_runs_runtime_shape;
ALTER TABLE pm.agent_runs
  ADD CONSTRAINT agent_runs_runtime_shape CHECK (
    (instance_id IS NULL OR instance_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$')
    AND (resume_notes IS NULL OR length(resume_notes) <= 8000)
    AND (blocked_reason IS NULL OR length(blocked_reason) BETWEEN 1 AND 500)
    AND (blocked_reason IS NULL OR blocked_at IS NOT NULL)
  );

COMMENT ON COLUMN pm.agent_runs.instance_id IS
  'The worker of the agent running it (a harness''s own instance id), when it runs several. Null: the agent itself.';
COMMENT ON COLUMN pm.agent_runs.resume_notes IS
  'Where to pick the run up again (written by the agent, replaced each time, at most 8000 characters).';
COMMENT ON COLUMN pm.agent_runs.blocked_at IS
  'Set while the run cannot go on without a person (with blocked_reason); cleared when it moves.';

CREATE INDEX IF NOT EXISTS idx_agent_runs_live_instances
  ON pm.agent_runs (agent_id, instance_id) WHERE status = 'running' AND instance_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_agent_runs_blocked
  ON pm.agent_runs (blocked_at) WHERE blocked_at IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Instances: the workers behind an agent
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.agent_instances (
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  instance_id text NOT NULL,
  working boolean NOT NULL DEFAULT false,
  turn_started_at timestamptz,
  status_note text,
  expected_interval_seconds integer NOT NULL DEFAULT 60,
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (agent_id, instance_id)
);

ALTER TABLE pm.agent_instances DROP CONSTRAINT IF EXISTS agent_instances_shape;
ALTER TABLE pm.agent_instances
  ADD CONSTRAINT agent_instances_shape CHECK (
    instance_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$'
    AND (status_note IS NULL OR length(status_note) <= 280)
    AND expected_interval_seconds BETWEEN 30 AND 86400
  );

COMMENT ON TABLE pm.agent_instances IS
  'One row per worker of an agent that reported (a heartbeat or a fleet report with instance_id). Live while last_seen_at is within two missed beats plus a minute. Server only.';

CREATE INDEX IF NOT EXISTS idx_agent_instances_seen ON pm.agent_instances (agent_id, last_seen_at DESC);

ALTER TABLE pm.agent_instances ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.agent_instances FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.agent_instances TO service_role;

-- ---------------------------------------------------------------------------
-- Limits: spend per run
-- ---------------------------------------------------------------------------
ALTER TABLE pm.agent_limits
  ADD COLUMN IF NOT EXISTS max_run_spend_cents integer;

ALTER TABLE pm.agent_limits DROP CONSTRAINT IF EXISTS agent_limits_run_spend;
ALTER TABLE pm.agent_limits
  ADD CONSTRAINT agent_limits_run_spend CHECK (max_run_spend_cents IS NULL OR max_run_spend_cents BETWEEN 1 AND 1000000000);

COMMENT ON COLUMN pm.agent_limits.max_run_spend_cents IS
  'The most one run may spend, in US cents. A run reported past it is stopped (cancelled) and a start past it refused.';

-- ---------------------------------------------------------------------------
-- Chat: conversations and claims
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pm.chat_conversations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  connection_id uuid NOT NULL REFERENCES pm.chat_connections(id) ON DELETE CASCADE,
  -- The provider's conversation (a DM, a channel) and the thread in it ('' for none).
  conversation_id text NOT NULL,
  thread_key text NOT NULL DEFAULT '',
  -- The lease: an agent and, optionally, one of its workers.
  holder_agent_id uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  holder_instance text,
  claimed_at timestamptz,
  claim_expires_at timestamptz,
  -- The running summary its agents keep.
  summary text,
  summary_updated_at timestamptz,
  summary_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_message_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE pm.chat_conversations DROP CONSTRAINT IF EXISTS chat_conversations_shape;
ALTER TABLE pm.chat_conversations
  ADD CONSTRAINT chat_conversations_shape CHECK (
    length(conversation_id) BETWEEN 1 AND 255
    AND length(thread_key) <= 255
    AND (holder_instance IS NULL OR holder_instance ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$')
    AND (summary IS NULL OR length(summary) <= 4000)
  );

COMMENT ON TABLE pm.chat_conversations IS
  'A chat conversation (a DM, or a thread in a channel) its agents can claim as a whole and keep a running summary of. Server only.';

CREATE UNIQUE INDEX IF NOT EXISTS chat_conversations_key
  ON pm.chat_conversations (connection_id, conversation_id, thread_key);

ALTER TABLE pm.chat_conversations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.chat_conversations FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.chat_conversations TO service_role;

ALTER TABLE pm.chat_messages
  ADD COLUMN IF NOT EXISTS chat_conversation_id uuid REFERENCES pm.chat_conversations(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS claim_instance text,
  ADD COLUMN IF NOT EXISTS claimed_at timestamptz,
  ADD COLUMN IF NOT EXISTS claim_expires_at timestamptz;

ALTER TABLE pm.chat_messages DROP CONSTRAINT IF EXISTS chat_messages_claim_shape;
ALTER TABLE pm.chat_messages
  ADD CONSTRAINT chat_messages_claim_shape CHECK (claim_instance IS NULL OR claim_instance ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$');

COMMENT ON COLUMN pm.chat_messages.claim_expires_at IS
  'A lease on the message by its agent (and claim_instance, one of its workers) until then; a lapsed lease is no lease.';

CREATE INDEX IF NOT EXISTS idx_chat_messages_chat_conversation
  ON pm.chat_messages (chat_conversation_id, created_at) WHERE chat_conversation_id IS NOT NULL;

-- Where a message sits: its thread; a top-level message in a company channel
-- starts its own thread; anything else (a DM, a personal chat) is the whole conversation.
CREATE OR REPLACE FUNCTION pm.chat_thread_key(p_connection uuid, p_thread text, p_external text, p_is_direct boolean)
RETURNS text
LANGUAGE sql
STABLE
SET search_path = pm
AS $$
  SELECT CASE
    WHEN p_thread IS NOT NULL AND p_thread <> '' THEN p_thread
    WHEN coalesce(p_is_direct, false) THEN ''
    WHEN p_external IS NOT NULL AND (SELECT c.kind FROM pm.chat_connections c WHERE c.id = p_connection) = 'company' THEN p_external
    ELSE ''
  END
$$;

REVOKE ALL ON FUNCTION pm.chat_thread_key(uuid, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.chat_thread_key(uuid, text, text, boolean) TO service_role;

-- The conversation a message belongs to: found, or (create true) made.
CREATE OR REPLACE FUNCTION pm.chat_conversation_of(p_connection uuid, p_conversation text, p_thread_key text, p_create boolean)
RETURNS uuid
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_id uuid;
BEGIN
  SELECT c.id INTO v_id FROM pm.chat_conversations c
  WHERE c.connection_id = p_connection AND c.conversation_id = p_conversation AND c.thread_key = coalesce(p_thread_key, '');
  IF v_id IS NOT NULL OR NOT p_create THEN
    RETURN v_id;
  END IF;
  INSERT INTO pm.chat_conversations (connection_id, conversation_id, thread_key)
  VALUES (p_connection, p_conversation, coalesce(p_thread_key, ''))
  ON CONFLICT (connection_id, conversation_id, thread_key) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT c.id INTO v_id FROM pm.chat_conversations c
    WHERE c.connection_id = p_connection AND c.conversation_id = p_conversation AND c.thread_key = coalesce(p_thread_key, '');
  END IF;
  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION pm.chat_conversation_of(uuid, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.chat_conversation_of(uuid, text, text, boolean) TO service_role;

-- A new inbound message routed to an agent joins its conversation: a request
-- makes one if none exists; context joins one only when it is already there.
CREATE OR REPLACE FUNCTION pm.link_chat_conversation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF NEW.direction <> 'inbound' OR NEW.chat_conversation_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  NEW.chat_conversation_id := pm.chat_conversation_of(
    NEW.connection_id, NEW.conversation_id,
    pm.chat_thread_key(NEW.connection_id, NEW.thread_id, NEW.external_message_id, NEW.is_direct),
    NEW.agent_id IS NOT NULL AND coalesce(NEW.is_request, true));
  IF NEW.chat_conversation_id IS NOT NULL THEN
    UPDATE pm.chat_conversations SET last_message_at = now() WHERE id = NEW.chat_conversation_id;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.link_chat_conversation() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS link_chat_conversation ON pm.chat_messages;
CREATE TRIGGER link_chat_conversation
  BEFORE INSERT ON pm.chat_messages
  FOR EACH ROW EXECUTE FUNCTION pm.link_chat_conversation();

-- A message recorded before this update: its conversation, made on first use.
CREATE OR REPLACE FUNCTION pm.ensure_chat_conversation(p_message_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_row pm.chat_messages%ROWTYPE;
  v_id uuid;
BEGIN
  SELECT * INTO v_row FROM pm.chat_messages WHERE id = p_message_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF v_row.chat_conversation_id IS NOT NULL THEN
    RETURN v_row.chat_conversation_id;
  END IF;
  v_id := pm.chat_conversation_of(v_row.connection_id, v_row.conversation_id,
    pm.chat_thread_key(v_row.connection_id, v_row.thread_id, v_row.external_message_id, v_row.is_direct), true);
  UPDATE pm.chat_messages SET chat_conversation_id = v_id WHERE id = p_message_id AND chat_conversation_id IS NULL;
  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION pm.ensure_chat_conversation(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.ensure_chat_conversation(uuid) TO service_role;

-- Claims, extends or releases a lease on a chat message (routed to p_agent)
-- or a conversation (one with a message routed to p_agent), as task claims
-- do. The holder is the agent and its worker (p_instance, null for the
-- agent itself); a lease past its time is no lease. Answers { outcome,
-- holder?, expired?, expired_at? }: claimed, renewed, extended, released,
-- held (someone else holds it), not_held, not_claimed, done (a message
-- already replied or handled) or not_found.
CREATE OR REPLACE FUNCTION pm.chat_claim(p_subject text, p_id uuid, p_agent uuid, p_instance text, p_action text, p_lease_minutes integer DEFAULT 30)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path = pm
AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_lease interval := make_interval(mins => least(greatest(coalesce(p_lease_minutes, 30), 1), 240));
  v_agent uuid;
  v_instance text;
  v_claimed_at timestamptz;
  v_expires timestamptz;
  v_status text;
  v_live boolean;
  v_mine boolean;
  v_holder jsonb;
BEGIN
  IF p_subject NOT IN ('message', 'conversation') OR p_action NOT IN ('claim', 'extend', 'release') THEN
    RAISE EXCEPTION 'chat_claim: unknown subject or action' USING ERRCODE = '22023';
  END IF;
  IF p_subject = 'message' THEN
    SELECT m.agent_id, m.claim_instance, m.claimed_at, m.claim_expires_at, m.status
      INTO v_agent, v_instance, v_claimed_at, v_expires, v_status
    FROM pm.chat_messages m
    WHERE m.id = p_id AND m.direction = 'inbound' AND m.agent_id = p_agent
    FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('outcome', 'not_found');
    END IF;
  ELSE
    SELECT c.holder_agent_id, c.holder_instance, c.claimed_at, c.claim_expires_at
      INTO v_agent, v_instance, v_claimed_at, v_expires
    FROM pm.chat_conversations c
    WHERE c.id = p_id
      AND EXISTS (SELECT 1 FROM pm.chat_messages m WHERE m.chat_conversation_id = c.id AND m.direction = 'inbound' AND m.agent_id = p_agent)
    FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('outcome', 'not_found');
    END IF;
  END IF;

  v_live := v_expires IS NOT NULL AND v_expires > v_now AND v_agent IS NOT NULL;
  v_mine := v_live AND v_agent = p_agent AND v_instance IS NOT DISTINCT FROM p_instance;
  v_holder := CASE WHEN v_live THEN jsonb_build_object(
    'agent_id', v_agent,
    'agent_name', (SELECT t.name FROM pm.team_members t WHERE t.id = v_agent),
    'instance_id', v_instance,
    'claimed_at', v_claimed_at,
    'expires_at', v_expires) END;

  IF p_action = 'claim' THEN
    IF p_subject = 'message' AND v_status IN ('replied', 'handled') THEN
      RETURN jsonb_build_object('outcome', 'done', 'status', v_status);
    END IF;
    IF v_live AND NOT v_mine THEN
      RETURN jsonb_build_object('outcome', 'held', 'holder', v_holder);
    END IF;
    IF p_subject = 'message' THEN
      UPDATE pm.chat_messages
        SET claim_instance = p_instance, claimed_at = CASE WHEN v_mine THEN claimed_at ELSE v_now END, claim_expires_at = v_now + v_lease
      WHERE id = p_id;
    ELSE
      UPDATE pm.chat_conversations
        SET holder_agent_id = p_agent, holder_instance = p_instance,
            claimed_at = CASE WHEN v_mine THEN claimed_at ELSE v_now END, claim_expires_at = v_now + v_lease
      WHERE id = p_id;
    END IF;
    RETURN jsonb_build_object('outcome', CASE WHEN v_mine THEN 'renewed' ELSE 'claimed' END,
      'claimed_at', CASE WHEN v_mine THEN v_claimed_at ELSE v_now END, 'expires_at', v_now + v_lease);
  END IF;

  IF p_action = 'extend' THEN
    IF v_mine THEN
      IF p_subject = 'message' THEN
        UPDATE pm.chat_messages SET claim_expires_at = v_now + v_lease WHERE id = p_id;
      ELSE
        UPDATE pm.chat_conversations SET claim_expires_at = v_now + v_lease WHERE id = p_id;
      END IF;
      RETURN jsonb_build_object('outcome', 'extended', 'claimed_at', v_claimed_at, 'expires_at', v_now + v_lease);
    END IF;
    IF v_live THEN
      RETURN jsonb_build_object('outcome', 'held', 'holder', v_holder);
    END IF;
    IF v_expires IS NOT NULL AND v_agent = p_agent AND v_instance IS NOT DISTINCT FROM p_instance THEN
      RETURN jsonb_build_object('outcome', 'not_held', 'expired', true, 'expired_at', v_expires);
    END IF;
    RETURN jsonb_build_object('outcome', 'not_claimed');
  END IF;

  -- release
  IF v_live AND NOT v_mine THEN
    RETURN jsonb_build_object('outcome', 'held', 'holder', v_holder);
  END IF;
  IF p_subject = 'message' THEN
    UPDATE pm.chat_messages SET claim_instance = NULL, claimed_at = NULL, claim_expires_at = NULL WHERE id = p_id;
  ELSE
    UPDATE pm.chat_conversations SET holder_agent_id = NULL, holder_instance = NULL, claimed_at = NULL, claim_expires_at = NULL WHERE id = p_id;
  END IF;
  RETURN jsonb_build_object('outcome', CASE WHEN v_mine THEN 'released' ELSE 'not_claimed' END);
END;
$$;

REVOKE ALL ON FUNCTION pm.chat_claim(text, uuid, uuid, text, text, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.chat_claim(text, uuid, uuid, text, text, integer) TO service_role;

