-- ---------------------------------------------------------------------------
-- Host keys
-- ---------------------------------------------------------------------------
ALTER TABLE pm.api_keys
  ADD COLUMN IF NOT EXISTS host_agent_ids uuid[];

COMMENT ON COLUMN pm.api_keys.host_agent_ids IS
  'A host key (scope agents.host, an Owner''s): the agents it serves. It reads their events and holds leases in their names, nothing else.';

INSERT INTO pm.permission_modules (permission_key, module_id) VALUES
  ('agents.host', 'agents')
ON CONFLICT (permission_key) DO UPDATE SET module_id = EXCLUDED.module_id;

-- The host feed: events routed to any of p_member_ids (the agents a host key
-- serves), and, with p_agent_events, agent events of those agents. The same
-- order, horizon and retention as pm.event_feed_read.
CREATE OR REPLACE FUNCTION pm.event_feed_read_host(
  p_after_txid bigint,
  p_after_seq bigint,
  p_limit integer,
  p_member_ids uuid[],
  p_member_types text[],
  p_agent_events boolean DEFAULT false,
  p_agent_event_types text[] DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = pm
AS $$
DECLARE
  v_xmin bigint := pg_snapshot_xmin(pg_current_snapshot())::text::bigint;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 1000);
  v_txid bigint := coalesce(p_after_txid, v_xmin);
  v_seq bigint := CASE WHEN p_after_txid IS NULL THEN 0 ELSE coalesce(p_after_seq, 0) END;
  v_state pm.event_feed_state;
  v_rows jsonb;
  v_count integer;
  v_last jsonb;
BEGIN
  SELECT * INTO v_state FROM pm.event_feed_state WHERE id;
  IF FOUND AND (v_txid, v_seq) < (v_state.pruned_txid, v_state.pruned_seq) THEN
    RETURN jsonb_build_object('resync', true, 'cursor', jsonb_build_array(v_xmin::text, '0'));
  END IF;

  WITH picked AS (
    (
      SELECT f.*
      FROM pm.event_feed f
      WHERE f.member_id = ANY (coalesce(p_member_ids, '{}'))
        AND f.event_type = ANY (coalesce(p_member_types, '{}'))
        AND (f.change_txid, f.seq) > (v_txid, v_seq)
        AND f.change_txid < v_xmin
      ORDER BY f.change_txid, f.seq
      LIMIT v_limit + 1
    )
    UNION ALL
    (
      SELECT f.*
      FROM pm.event_feed f
      WHERE coalesce(p_agent_events, false)
        AND f.event_type = 'agent_event.created'
        AND f.agent_id = ANY (coalesce(p_member_ids, '{}'))
        AND (f.change_txid, f.seq) > (v_txid, v_seq)
        AND f.change_txid < v_xmin
        AND (p_agent_event_types IS NULL OR f.agent_event_type = ANY (p_agent_event_types))
      ORDER BY f.change_txid, f.seq
      LIMIT v_limit + 1
    )
  ), ordered AS (
    SELECT p.*, row_number() OVER (ORDER BY p.change_txid, p.seq) AS n
    FROM picked p
    ORDER BY p.change_txid, p.seq
    LIMIT v_limit + 1
  )
  SELECT
    coalesce(jsonb_agg(jsonb_build_object(
      'txid', o.change_txid::text,
      'seq', o.seq::text,
      'type', o.event_type,
      'member_id', o.member_id,
      'agent_id', o.agent_id,
      'project_id', o.project_id,
      'subject_type', o.subject_type,
      'subject_id', o.subject_id,
      'created_at', o.created_at,
      'data', o.data,
      'agent_event', CASE WHEN o.event_type = 'agent_event.created'
        THEN (SELECT pm.agent_event_row(a) FROM pm.agent_activities a WHERE a.id = o.subject_id) END
    ) ORDER BY o.change_txid, o.seq) FILTER (WHERE o.n <= v_limit), '[]'::jsonb),
    count(*)
  INTO v_rows, v_count
  FROM ordered o;

  IF v_count > v_limit THEN
    v_last := v_rows -> (v_limit - 1);
    RETURN jsonb_build_object('resync', false, 'events', v_rows, 'has_more', true,
      'cursor', jsonb_build_array(v_last ->> 'txid', v_last ->> 'seq'));
  END IF;
  RETURN jsonb_build_object('resync', false, 'events', v_rows, 'has_more', false,
    'cursor', jsonb_build_array(greatest(v_xmin, v_txid)::text, CASE WHEN v_xmin > v_txid THEN '0' ELSE v_seq::text END));
END;
$$;

REVOKE ALL ON FUNCTION pm.event_feed_read_host(bigint, bigint, integer, uuid[], text[], boolean, text[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.event_feed_read_host(bigint, bigint, integer, uuid[], text[], boolean, text[]) TO service_role;

-- ---------------------------------------------------------------------------
-- Feed: the run's blocked state, the message's conversation
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.feed_agent_run()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status
     AND (OLD.blocked_at IS NULL) = (NEW.blocked_at IS NULL) THEN
    RETURN NULL;
  END IF;
  INSERT INTO pm.event_feed (event_type, member_id, agent_id, project_id, subject_type, subject_id, data)
  VALUES ('run.updated', NEW.agent_id, NEW.agent_id, NEW.project_id, 'run', NEW.id, jsonb_build_object(
    'run', jsonb_build_object(
      'id', NEW.id,
      'status', NEW.status,
      'previous_status', CASE WHEN TG_OP = 'UPDATE' THEN OLD.status END,
      'task_id', NEW.task_id,
      'project_id', NEW.project_id,
      'parent_run_id', NEW.parent_run_id,
      'instance_id', NEW.instance_id,
      'blocked', NEW.blocked_at IS NOT NULL
    ),
    'actor_id', pm.webhook_actor_id()
  ));
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.feed_agent_run() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS feed_agent_run ON pm.agent_runs;
CREATE TRIGGER feed_agent_run
  AFTER INSERT OR UPDATE OF status, blocked_at ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.feed_agent_run();

CREATE OR REPLACE FUNCTION pm.feed_chat_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF NEW.direction <> 'inbound' OR NEW.agent_id IS NULL OR NEW.status NOT IN ('pending', 'notified', 'context') THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.agent_id IS NOT DISTINCT FROM NEW.agent_id
     AND OLD.status IN ('pending', 'notified', 'context') THEN
    RETURN NULL;
  END IF;
  INSERT INTO pm.event_feed (event_type, member_id, agent_id, subject_type, subject_id, data)
  VALUES ('chat.message', NEW.agent_id, NEW.agent_id, 'chat_message', NEW.id, jsonb_build_object(
    'message', jsonb_build_object(
      'id', NEW.id,
      'status', NEW.status,
      'connection_id', NEW.connection_id,
      'conversation_id', NEW.conversation_id,
      'thread_id', NEW.thread_id,
      'chat_conversation_id', NEW.chat_conversation_id,
      'created_at', NEW.created_at
    )
  ));
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.feed_chat_message() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Blocked runs a signed-in member is waited on for (Needs you)
-- ---------------------------------------------------------------------------
-- Runs blocked now (waiting, blocked_at set) whose agent the caller manages
-- (an Owner, team.manage, one of its owners) or whose live task the caller
-- is assigned to, while the AI agents module is on. Newest first, at most 100.
CREATE OR REPLACE FUNCTION pm.my_blocked_runs()
RETURNS TABLE (
  run_id uuid, agent_id uuid, agent_name text, task_id uuid, task_title text, project_id uuid,
  title text, blocked_reason text, blocked_at timestamptz, instance_id text
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT r.id, r.agent_id, a.name, r.task_id, t.title, r.project_id, r.title, r.blocked_reason, r.blocked_at, r.instance_id
  FROM pm.agent_runs r
  JOIN pm.team_members a ON a.id = r.agent_id
  LEFT JOIN pm.tasks t ON t.id = r.task_id
  WHERE r.status = 'waiting' AND r.blocked_at IS NOT NULL
    AND pm.module_enabled('agents')
    AND pm.current_team_member_id() IS NOT NULL
    AND (r.task_id IS NULL OR t.deleted_at IS NULL)
    AND (r.project_id IS NULL OR EXISTS (SELECT 1 FROM pm.projects p WHERE p.id = r.project_id AND p.deleted_at IS NULL))
    AND (pm.member_manages_agent(r.agent_id, pm.current_team_member_id())
      OR (r.task_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM pm.task_assignees ta WHERE ta.task_id = r.task_id AND ta.member_id = pm.current_team_member_id())))
  ORDER BY r.blocked_at DESC
  LIMIT 100
$$;

REVOKE ALL ON FUNCTION pm.my_blocked_runs() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.my_blocked_runs() TO authenticated, service_role;

-- ============================================================
-- SECURITY FIXES (20261127002400_security_fixes.sql)
-- ============================================================


-- ---------------------------------------------------------------------------
-- Portal PIN: one atomic check per guess
-- ---------------------------------------------------------------------------
-- The PIN check read the recent misses, compared, then wrote the miss, in
-- three requests with no lock: thousands of parallel guesses all read "under
-- the limit" before any miss landed, and a miss from an address the inet
-- column refused (X-Forwarded-For: x) was never counted at all. Now one
-- function locks the portal's settings row, applies the limits, compares and
-- records the miss in one transaction. The limits match src/lib/portal-pin.ts:
-- 5 misses per visitor (address) in 15 minutes, 20 per portal in an hour and
-- 100 per portal in a day, whatever the address. A text that is not an
-- address is stored as null (one shared bucket), never refused.
CREATE TABLE IF NOT EXISTS pm.portal_pin_misses (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  portal_settings_id uuid NOT NULL REFERENCES pm.portal_settings(id) ON DELETE CASCADE,
  ip inet,
  missed_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE pm.portal_pin_misses IS
  'Wrong portal PIN guesses, for the limiter in pm.check_portal_pin only. Rows older than a day are dropped as the portal is checked.';

CREATE INDEX IF NOT EXISTS portal_pin_misses_portal_at ON pm.portal_pin_misses (portal_settings_id, missed_at DESC);

ALTER TABLE pm.portal_pin_misses ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.portal_pin_misses FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.portal_pin_misses TO service_role;

-- Answers {"result": "ok" | "required" | "invalid" | "locked" | "not_found"},
-- with retry_after_seconds when locked. Checked before the comparison, so a
-- locked visitor learns nothing even with the right PIN.
CREATE OR REPLACE FUNCTION pm.check_portal_pin(p_portal_settings_id uuid, p_pin text, p_ip text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_pin text;
  v_ip inet;
  v_now timestamptz := clock_timestamp();
  v_at timestamptz;
  v_retry integer := 0;
BEGIN
  -- One guess at a time per portal: the row lock holds until the miss is written.
  SELECT s.pin INTO v_pin FROM pm.portal_settings s WHERE s.id = p_portal_settings_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('result', 'not_found');
  END IF;
  IF coalesce(v_pin, '') = '' THEN
    RETURN jsonb_build_object('result', 'ok');
  END IF;
  IF coalesce(p_pin, '') = '' THEN
    RETURN jsonb_build_object('result', 'required');
  END IF;
  BEGIN
    v_ip := nullif(btrim(p_ip), '')::inet;
  EXCEPTION WHEN others THEN
    v_ip := NULL;
  END;

  DELETE FROM pm.portal_pin_misses m
  WHERE m.portal_settings_id = p_portal_settings_id AND m.missed_at < v_now - interval '1 day';

  -- The lock lifts when the limit-th newest miss in the window ages out.
  SELECT m.missed_at INTO v_at FROM pm.portal_pin_misses m
  WHERE m.portal_settings_id = p_portal_settings_id AND m.ip IS NOT DISTINCT FROM v_ip
    AND m.missed_at > v_now - interval '15 minutes'
  ORDER BY m.missed_at DESC OFFSET 4 LIMIT 1;
  IF FOUND THEN
    v_retry := greatest(v_retry, ceil(extract(epoch FROM (v_at + interval '15 minutes' - v_now)))::integer);
  END IF;
  SELECT m.missed_at INTO v_at FROM pm.portal_pin_misses m
  WHERE m.portal_settings_id = p_portal_settings_id AND m.missed_at > v_now - interval '1 hour'
  ORDER BY m.missed_at DESC OFFSET 19 LIMIT 1;
  IF FOUND THEN
    v_retry := greatest(v_retry, ceil(extract(epoch FROM (v_at + interval '1 hour' - v_now)))::integer);
  END IF;
  SELECT m.missed_at INTO v_at FROM pm.portal_pin_misses m
  WHERE m.portal_settings_id = p_portal_settings_id AND m.missed_at > v_now - interval '1 day'
  ORDER BY m.missed_at DESC OFFSET 99 LIMIT 1;
  IF FOUND THEN
    v_retry := greatest(v_retry, ceil(extract(epoch FROM (v_at + interval '1 day' - v_now)))::integer);
  END IF;
  IF v_retry > 0 THEN
    RETURN jsonb_build_object('result', 'locked', 'retry_after_seconds', greatest(1, v_retry));
  END IF;

  IF p_pin = v_pin THEN
    RETURN jsonb_build_object('result', 'ok');
  END IF;
  INSERT INTO pm.portal_pin_misses (portal_settings_id, ip, missed_at) VALUES (p_portal_settings_id, v_ip, v_now);
  RETURN jsonb_build_object('result', 'invalid');
END;
$$;

REVOKE ALL ON FUNCTION pm.check_portal_pin(uuid, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.check_portal_pin(uuid, text, text) TO service_role;

-- ---------------------------------------------------------------------------
-- Chat account links: a code from the chat for links a stranger started
-- ---------------------------------------------------------------------------
-- A link the bot sends to someone it does not know names nobody, so it could
-- be forwarded to another person ("connect your Telegram") and bind the
-- sender's chat account to whoever clicked it. Such a link now carries a
-- short code shown only in that chat (stored hashed with the link's token);
-- the confirm page asks for it, and a few wrong codes use the link up. Links
-- made before this, and links a harness asks for, have no code and confirm
-- as before.
ALTER TABLE pm.identity_link_requests
  ADD COLUMN IF NOT EXISTS confirm_code_hash text,
  ADD COLUMN IF NOT EXISTS code_misses integer NOT NULL DEFAULT 0;

COMMENT ON COLUMN pm.identity_link_requests.confirm_code_hash IS
  'For a link a stranger started in a chat: sha256 of the token and the code the bot showed there. Confirming needs the code.';

-- ============================================================
-- LIMITS AND SETUP SECURITY (20261127002500_agent_limits_security.sql)
-- ============================================================
-- Agent limits and setup security (deep security review of 2.0.50, findings
-- 3, 8 and 9). Additive and safe to run twice; works with the previous
-- release's code, which never reads the new columns, table or functions.
--
-- - Spend only goes up for a run: pm.agent_runs keeps the larger cost_usd,
--   tokens_in and tokens_out when an update would lower them (the server
--   refuses such an update first, 409 spend_decrease; this is the backstop).
-- - A run's spend is the larger of what it reports itself and the usage
--   attached to it (pm.agent_spend_facts), so a small cost on the run never
--   hides the usage reported under it.
-- - Two more per-agent limits on pm.agent_limits: write_rate_per_minute
--   (writes a minute across all the agent's keys) and send_rate_per_minute
--   (chat out, notifications, questions and approvals). Null is no limit, as
--   for every limit; agents made before keep none.
-- - pm.agent_write_gate: one call per write from an agent. It refuses the
--   write while the agent's budget is spent or one of its unfinished runs is
--   past max_run_spend_cents, and counts the write (and a send) in windows
--   of their own. Server only.
-- - pm.api_keys.ai_setup_session_id: the AI setup session that made a key,
--   so the setup screen lists every key a session made, with Revoke.
-- - pm.ai_setup_confirms: what an AI setup session asked for that waits on
--   the Owner's yes in the app (powers beyond the agent's template that
--   touch money, people, settings, acting for someone, keys or webhooks,
--   and a webhook to an address no live webhook uses yet).

-- ---------------------------------------------------------------------------
-- Spend only goes up for a run
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pm.agent_runs_spend_only_up()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pm
AS $$
BEGIN
  IF OLD.cost_usd IS NOT NULL AND (NEW.cost_usd IS NULL OR NEW.cost_usd < OLD.cost_usd) THEN
    NEW.cost_usd := OLD.cost_usd;
  END IF;
  IF OLD.tokens_in IS NOT NULL AND (NEW.tokens_in IS NULL OR NEW.tokens_in < OLD.tokens_in) THEN
    NEW.tokens_in := OLD.tokens_in;
  END IF;
  IF OLD.tokens_out IS NOT NULL AND (NEW.tokens_out IS NULL OR NEW.tokens_out < OLD.tokens_out) THEN
    NEW.tokens_out := OLD.tokens_out;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.agent_runs_spend_only_up() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS agent_runs_spend_only_up ON pm.agent_runs;
CREATE TRIGGER agent_runs_spend_only_up
  BEFORE UPDATE OF cost_usd, tokens_in, tokens_out ON pm.agent_runs
  FOR EACH ROW EXECUTE FUNCTION pm.agent_runs_spend_only_up();

-- ---------------------------------------------------------------------------
-- Spend facts: a run counts the larger of its own report and its usage
-- ---------------------------------------------------------------------------
-- The same rule as before (20261125000800_agent_spend.sql), except for a run
-- with usage attached: its cost and tokens are the larger of the run's own
-- and the usage's, never the smaller, so neither report can hide the other.
CREATE OR REPLACE FUNCTION pm.agent_spend_facts(p_from timestamptz, p_to timestamptz, p_agent_ids uuid[] DEFAULT NULL)
RETURNS TABLE (
  source text,
  source_id text,
  agent_id uuid,
  project_id uuid,
  model text,
  provider text,
  labels text[],
  at timestamptz,
  tokens_in bigint,
  tokens_out bigint,
  tokens_cached bigint,
  cost_usd numeric,
  principal_id uuid
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pm
AS $$
  with usage_in as (
    select a.id, a.agent_id, a.project_id, a.labels, a.metadata as m, a.principal_id,
           coalesce(agent_analytics_ts(a.metadata->>'recorded_at'), a.created_at) as at
    from agent_activities a
    where a.activity_type = 'usage.recorded'
      and a.agent_id is not null
      and a.created_at >= p_from - interval '1 day'
      and (p_agent_ids is null or a.agent_id = any (p_agent_ids))
      and coalesce(agent_analytics_ts(a.metadata->>'recorded_at'), a.created_at) >= p_from
      and coalesce(agent_analytics_ts(a.metadata->>'recorded_at'), a.created_at) < p_to
  ),
  ledger as (
    select distinct u.agent_id from usage_in u
  ),
  runs as (
    select r.id, r.agent_id, r.project_id, r.model, r.provider, r.started_at, r.tokens_in, r.tokens_out, r.cost_usd, r.principal_id
    from agent_runs r
    where r.started_at >= p_from and r.started_at < p_to
      and (p_agent_ids is null or r.agent_id = any (p_agent_ids))
  ),
  run_usage as (
    select r.id,
           sum(agent_analytics_int(a.metadata->>'input_tokens')) as tin,
           sum(agent_analytics_int(a.metadata->>'output_tokens')) as tout,
           sum(agent_analytics_int(a.metadata->>'cached_tokens')) as tcached,
           sum(agent_analytics_num(a.metadata->>'cost_usd')) filter (where agent_analytics_num(a.metadata->>'cost_usd') > 0) as cost
    from runs r
    join agent_activities a on a.metadata->>'run_id' = r.id::text and a.agent_id = r.agent_id
    where a.activity_type = 'usage.recorded'
    group by r.id
  ),
  run_turns as (
    select r.id,
           sum(agent_analytics_int(a.metadata->'tokens'->>'input')) filter (where a.metadata->'tokens' ? 'input') as tin,
           sum(agent_analytics_int(a.metadata->'tokens'->>'output')) filter (where a.metadata->'tokens' ? 'output') as tout
    from runs r
    join agent_activities a on a.metadata->>'run_id' = r.id::text and a.agent_id = r.agent_id
    where a.activity_type = 'turn.completed'
      and a.metadata->>'tokens_scope' = 'turn'
      and coalesce(r.tokens_in, 0) + coalesce(r.tokens_out, 0) = 0
    group by r.id
  )
  select 'run'::text, r.id::text, r.agent_id, r.project_id, r.model, r.provider, '{}'::text[], r.started_at,
    (case when u.id is not null then greatest(coalesce(r.tokens_in, 0), coalesce(u.tin, 0))
          when coalesce(r.tokens_in, 0) + coalesce(r.tokens_out, 0) > 0 then coalesce(r.tokens_in, 0)
          when l.agent_id is null then coalesce(t.tin, 0)
          else 0 end)::bigint,
    (case when u.id is not null then greatest(coalesce(r.tokens_out, 0), coalesce(u.tout, 0))
          when coalesce(r.tokens_in, 0) + coalesce(r.tokens_out, 0) > 0 then coalesce(r.tokens_out, 0)
          when l.agent_id is null then coalesce(t.tout, 0)
          else 0 end)::bigint,
    (case when coalesce(r.tokens_in, 0) + coalesce(r.tokens_out, 0) > 0 then 0
          when u.id is not null then coalesce(u.tcached, 0)
          else 0 end)::bigint,
    nullif(greatest(coalesce(r.cost_usd, 0), coalesce(u.cost, 0)), 0),
    r.principal_id
  from runs r
  left join run_usage u on u.id = r.id
  left join run_turns t on t.id = r.id
  left join ledger l on l.agent_id = r.agent_id
  union all
  select 'usage'::text, u.id::text, u.agent_id, u.project_id, u.m->>'model', u.m->>'provider', coalesce(u.labels, '{}'::text[]), u.at,
    agent_analytics_int(u.m->>'input_tokens')::bigint,
    agent_analytics_int(u.m->>'output_tokens')::bigint,
    agent_analytics_int(u.m->>'cached_tokens')::bigint,
    case when agent_analytics_num(u.m->>'cost_usd') > 0 then agent_analytics_num(u.m->>'cost_usd') end,
    u.principal_id
  from usage_in u
  where u.m->>'run_id' is null
  union all
  select 'turn'::text, a.id::text, a.agent_id, a.project_id, a.metadata->>'model', null::text, '{}'::text[],
    coalesce(agent_analytics_ts(a.metadata->>'started_at'), a.created_at),
    (case when a.metadata->'tokens' ? 'input' then agent_analytics_int(a.metadata->'tokens'->>'input') else 0 end)::bigint,
    (case when a.metadata->'tokens' ? 'output' then agent_analytics_int(a.metadata->'tokens'->>'output') else 0 end)::bigint,
    0::bigint,
    null::numeric,
    a.principal_id
  from agent_activities a
  where a.activity_type = 'turn.completed'
    and a.agent_id is not null
    and a.metadata->>'tokens_scope' = 'turn'
    and (a.metadata->'tokens' ? 'input' or a.metadata->'tokens' ? 'output')
    and a.metadata->>'run_id' is null
    and a.created_at >= p_from - interval '1 day'
    and (p_agent_ids is null or a.agent_id = any (p_agent_ids))
    and coalesce(agent_analytics_ts(a.metadata->>'started_at'), a.created_at) >= p_from
    and coalesce(agent_analytics_ts(a.metadata->>'started_at'), a.created_at) < p_to
    and not exists (select 1 from ledger l where l.agent_id = a.agent_id)
$$;

REVOKE ALL ON FUNCTION pm.agent_spend_facts(timestamptz, timestamptz, uuid[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION pm.agent_spend_facts(timestamptz, timestamptz, uuid[]) TO authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Limits: writes and sends a minute, per agent
-- ---------------------------------------------------------------------------
ALTER TABLE pm.agent_limits
  ADD COLUMN IF NOT EXISTS write_rate_per_minute integer,
  ADD COLUMN IF NOT EXISTS send_rate_per_minute integer;

ALTER TABLE pm.agent_limits DROP CONSTRAINT IF EXISTS agent_limits_write_rates;
ALTER TABLE pm.agent_limits
  ADD CONSTRAINT agent_limits_write_rates CHECK (
    (write_rate_per_minute IS NULL OR write_rate_per_minute BETWEEN 1 AND 10000)
    AND (send_rate_per_minute IS NULL OR send_rate_per_minute BETWEEN 1 AND 10000)
  );

COMMENT ON COLUMN pm.agent_limits.write_rate_per_minute IS
  'Writes a minute the agent may make across all its keys (429 write_rate_limited after that). Null: no limit of its own.';
COMMENT ON COLUMN pm.agent_limits.send_rate_per_minute IS
  'Chat messages out, notifications, questions and approvals a minute (429 send_rate_limited after that). Null: no limit of its own.';

-- An agent's limits with what counts against them now (as 20261125000800),
-- now with every limit: max_run_spend_cents and the write and send rates.
CREATE OR REPLACE FUNCTION pm.agent_limit_state(p_agent_id uuid, p_with_usage boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_limits pm.agent_limits%ROWTYPE;
  v_period text;
  v_from timestamptz;
  v_to timestamptz;
  v_spent_usd numeric := 0;
  v_spent_tokens bigint := 0;
  v_running integer := 0;
  v_claims integer := 0;
BEGIN
  SELECT * INTO v_limits FROM pm.agent_limits WHERE agent_id = p_agent_id;
  v_period := coalesce(v_limits.budget_period, 'month');
  v_from := date_trunc(v_period, now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  v_to := (date_trunc(v_period, now() AT TIME ZONE 'UTC') + ('1 ' || v_period)::interval) AT TIME ZONE 'UTC';
  IF p_with_usage OR v_limits.budget_usd IS NOT NULL OR v_limits.budget_tokens IS NOT NULL THEN
  SELECT coalesce(sum(s.spent_usd), 0), coalesce(sum(s.spent_tokens), 0)
    INTO v_spent_usd, v_spent_tokens
  FROM pm.agent_spend(v_from, v_to, ARRAY[p_agent_id]) s;
  END IF;
  IF p_with_usage OR v_limits.max_concurrent_runs IS NOT NULL THEN
  SELECT count(*) INTO v_running FROM pm.agent_runs r
  WHERE r.agent_id = p_agent_id AND r.status = 'running' AND r.updated_at > now() - interval '2 hours';
  SELECT count(*) INTO v_claims FROM pm.tasks t
  WHERE t.claimed_by = p_agent_id AND t.claim_expires_at > now() AND t.deleted_at IS NULL;
  END IF;
  RETURN jsonb_build_object(
    'limits', CASE WHEN v_limits.agent_id IS NULL THEN NULL ELSE jsonb_build_object(
      'max_concurrent_runs', v_limits.max_concurrent_runs,
      'rate_per_minute', v_limits.rate_per_minute,
      'budget_usd', v_limits.budget_usd,
      'budget_tokens', v_limits.budget_tokens,
      'budget_period', v_limits.budget_period,
      'budget_alerted_period', v_limits.budget_alerted_period,
      'max_run_spend_cents', v_limits.max_run_spend_cents,
      'write_rate_per_minute', v_limits.write_rate_per_minute,
      'send_rate_per_minute', v_limits.send_rate_per_minute) END,
    'period_start', v_from,
    'spent_usd', round(v_spent_usd, 4),
    'spent_tokens', v_spent_tokens,
    'running_runs', v_running,
    'live_claims', v_claims);
END;
$$;

REVOKE ALL ON FUNCTION pm.agent_limit_state(uuid, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_limit_state(uuid, boolean) TO service_role;

CREATE TABLE IF NOT EXISTS pm.agent_write_windows (
  agent_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  bucket text NOT NULL,
  window_start timestamptz NOT NULL,
  request_count integer NOT NULL,
  PRIMARY KEY (agent_id, bucket),
  CONSTRAINT agent_write_windows_bucket_check CHECK (bucket IN ('write', 'send')),
  CONSTRAINT agent_write_windows_count_check CHECK (request_count > 0)
);

COMMENT ON TABLE pm.agent_write_windows IS
  'The current minute of writes and sends per agent, for pm.agent_write_gate only. Server only.';

ALTER TABLE pm.agent_write_windows ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.agent_write_windows FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.agent_write_windows TO service_role;

-- ---------------------------------------------------------------------------
-- One gate per write from an agent
-- ---------------------------------------------------------------------------
-- Answers {"refused": null} when the write may go on, else the reason and
-- its numbers: budget_exceeded (the budget this period is spent),
-- run_spend_exceeded (an unfinished run of the agent is past
-- max_run_spend_cents), write_rate_limited or send_rate_limited (with
-- reset_at). The budget and run checks come first and count nothing; the
-- windows count the write, and the send when p_send. An agent without limits
-- answers at once. Server only.
CREATE OR REPLACE FUNCTION pm.agent_write_gate(p_agent_id uuid, p_send boolean DEFAULT false, p_window_seconds integer DEFAULT 60)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_limits pm.agent_limits%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_period text;
  v_from timestamptz;
  v_to timestamptz;
  v_spent_usd numeric := 0;
  v_spent_tokens bigint := 0;
  v_run_id uuid;
  v_run_spent numeric;
  v_window pm.agent_write_windows%ROWTYPE;
  v_bucket text;
  v_limit integer;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;
  IF p_window_seconds <= 0 THEN RAISE EXCEPTION 'Invalid window'; END IF;
  SELECT * INTO v_limits FROM pm.agent_limits WHERE agent_id = p_agent_id;
  IF v_limits.agent_id IS NULL THEN RETURN jsonb_build_object('refused', null); END IF;

  IF v_limits.budget_usd IS NOT NULL OR v_limits.budget_tokens IS NOT NULL THEN
    v_period := coalesce(v_limits.budget_period, 'month');
    v_from := date_trunc(v_period, now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
    v_to := (date_trunc(v_period, now() AT TIME ZONE 'UTC') + ('1 ' || v_period)::interval) AT TIME ZONE 'UTC';
    SELECT coalesce(sum(s.spent_usd), 0), coalesce(sum(s.spent_tokens), 0)
      INTO v_spent_usd, v_spent_tokens
    FROM pm.agent_spend(v_from, v_to, ARRAY[p_agent_id]) s;
    IF (v_limits.budget_usd IS NOT NULL AND v_spent_usd >= v_limits.budget_usd)
       OR (v_limits.budget_tokens IS NOT NULL AND v_spent_tokens >= v_limits.budget_tokens) THEN
      RETURN jsonb_build_object(
        'refused', 'budget_exceeded',
        'budget_usd', v_limits.budget_usd,
        'budget_tokens', v_limits.budget_tokens,
        'budget_period', v_period,
        'period_start', v_from,
        'spent_usd', round(v_spent_usd, 4),
        'spent_tokens', v_spent_tokens);
    END IF;
  END IF;

  IF v_limits.max_run_spend_cents IS NOT NULL THEN
    SELECT r.id, greatest(coalesce(r.cost_usd, 0), coalesce(u.cost, 0))
      INTO v_run_id, v_run_spent
    FROM pm.agent_runs r
    LEFT JOIN LATERAL (
      SELECT sum(agent_analytics_num(a.metadata->>'cost_usd')) FILTER (WHERE agent_analytics_num(a.metadata->>'cost_usd') > 0) AS cost
      FROM pm.agent_activities a
      WHERE a.activity_type = 'usage.recorded' AND a.agent_id = r.agent_id AND a.metadata->>'run_id' = r.id::text
    ) u ON true
    WHERE r.agent_id = p_agent_id AND r.status IN ('running', 'waiting')
      AND greatest(coalesce(r.cost_usd, 0), coalesce(u.cost, 0)) * 100 > v_limits.max_run_spend_cents
    ORDER BY r.started_at
    LIMIT 1;
    IF v_run_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'refused', 'run_spend_exceeded',
        'run_id', v_run_id,
        'spent_usd', round(v_run_spent, 4),
        'max_run_spend_cents', v_limits.max_run_spend_cents);
    END IF;
  END IF;

  FOREACH v_bucket IN ARRAY ARRAY['write', 'send'] LOOP
    v_limit := CASE v_bucket WHEN 'write' THEN v_limits.write_rate_per_minute ELSE v_limits.send_rate_per_minute END;
    CONTINUE WHEN v_limit IS NULL OR (v_bucket = 'send' AND NOT coalesce(p_send, false));
    INSERT INTO pm.agent_write_windows (agent_id, bucket, window_start, request_count)
    VALUES (p_agent_id, v_bucket, v_now, 1)
    ON CONFLICT (agent_id, bucket) DO UPDATE
    SET window_start = CASE WHEN agent_write_windows.window_start + make_interval(secs => p_window_seconds) <= v_now THEN v_now ELSE agent_write_windows.window_start END,
        request_count = CASE WHEN agent_write_windows.window_start + make_interval(secs => p_window_seconds) <= v_now THEN 1 ELSE agent_write_windows.request_count + 1 END
    RETURNING * INTO v_window;
    IF v_window.request_count > v_limit THEN
      RETURN jsonb_build_object(
        'refused', v_bucket || '_rate_limited',
        'limit', v_limit,
        'reset_at', v_window.window_start + make_interval(secs => p_window_seconds));
    END IF;
  END LOOP;
  RETURN jsonb_build_object('refused', null);
END;
$$;

REVOKE ALL ON FUNCTION pm.agent_write_gate(uuid, boolean, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_write_gate(uuid, boolean, integer) TO service_role;

-- ---------------------------------------------------------------------------
-- AI setup: the keys a session made, and what waits on the Owner
-- ---------------------------------------------------------------------------
ALTER TABLE pm.api_keys
  ADD COLUMN IF NOT EXISTS ai_setup_session_id uuid REFERENCES pm.ai_setup_sessions(id) ON DELETE SET NULL;

COMMENT ON COLUMN pm.api_keys.ai_setup_session_id IS
  'The AI setup session that made this key, so the setup screen lists it with Revoke. Null for every other key.';

CREATE INDEX IF NOT EXISTS idx_api_keys_ai_setup_session ON pm.api_keys (ai_setup_session_id) WHERE ai_setup_session_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS pm.ai_setup_confirms (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES pm.ai_setup_sessions(id) ON DELETE CASCADE,
  -- The Owner whose session it is: the only one who may say yes.
  member_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  agent_id uuid REFERENCES pm.team_members(id) ON DELETE CASCADE,
  kind text NOT NULL,
  api_key_id uuid REFERENCES pm.api_keys(id) ON DELETE CASCADE,
  webhook_endpoint_id uuid REFERENCES pm.webhook_endpoints(id) ON DELETE CASCADE,
  scopes text[] NOT NULL DEFAULT '{}',
  host text,
  status text NOT NULL DEFAULT 'pending',
  created_at timestamptz NOT NULL DEFAULT now(),
  decided_at timestamptz,
  decided_by uuid REFERENCES pm.team_members(id) ON DELETE SET NULL,
  CONSTRAINT ai_setup_confirms_kind_check CHECK (kind IN ('key_scopes', 'webhook')),
  CONSTRAINT ai_setup_confirms_status_check CHECK (status IN ('pending', 'allowed', 'declined')),
  CONSTRAINT ai_setup_confirms_shape_check CHECK (
    (kind = 'key_scopes' AND api_key_id IS NOT NULL AND cardinality(scopes) > 0)
    OR (kind = 'webhook' AND webhook_endpoint_id IS NOT NULL)
  ),
  CONSTRAINT ai_setup_confirms_host_length CHECK (host IS NULL OR length(host) <= 255)
);

COMMENT ON TABLE pm.ai_setup_confirms IS
  'What an AI setup session asked for that waits on its Owner''s yes in the app: sensitive powers for a key, or a webhook to a new address (made switched off). Server only.';

CREATE INDEX IF NOT EXISTS idx_ai_setup_confirms_session ON pm.ai_setup_confirms (session_id, created_at);

ALTER TABLE pm.ai_setup_confirms ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.ai_setup_confirms FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.ai_setup_confirms TO service_role;

-- ============================================================
-- CHAT RELAY HEARTBEAT (20261127002600_chat_relay_heartbeat.sql)
-- ============================================================
-- Chat relay heartbeat: when a Discord relay last checked in.
--
-- The Discord relay said hello only when it connected, so a relay that
-- stopped (its host down, the process killed) left the connection reading
-- Connected for days. Relays from this release on send a heartbeat every
-- 5 minutes; the app stamps relay_seen_at on each one. Once a relay has
-- sent one, a connection with nothing from it for 15 minutes reads Not
-- receiving. A relay that never sends one (an older relay) leaves this null
-- and is judged as before.
--
-- Additive and safe to run twice. The previous release's code never reads
-- or writes the column.

ALTER TABLE pm.chat_connections
  ADD COLUMN IF NOT EXISTS relay_seen_at timestamptz;

COMMENT ON COLUMN pm.chat_connections.relay_seen_at IS
  'The last heartbeat from this connection''s relay (Discord), or null when its relay sends none. Set by the server only.';

-- ============================================================
-- NOTIFICATIONS CENTER (20261127002700_notifications_center.sql)
-- ============================================================
-- Notifications center: an agent's blocked comment is a Needs you item, and
-- Updates know how many they hold.
--
-- - pm.task_comments gains blocked (an agent says it is stuck on the task)
--   and blocked_task_status (the task's status when it said so). Only an
--   agent's comment is ever blocked: an agent sends blocked: true on the
--   comment, or starts it with "[BLOCKED]", the older convention. A person's
--   comment never is, whatever it says.
-- - pm.my_blocked_comments: the blocked comments that wait on the signed-in
--   member (the agents they manage, the tasks they are assigned to or made),
--   while the AI agents module is on. One stays until it is answered (a
--   later comment from a person, or the agent writes again) or the task
--   moves (its status changes, it is done or goes to Trash).
-- - pm.notification_view_count: how many Updates a member's view holds
--   (updates, unread or done), for "Show 24 more of 76". Server only.
--
-- Additive and safe to run twice. The previous release's code writes
-- comments as before (blocked fills itself from the "[BLOCKED]" prefix) and
-- never reads the new columns.

ALTER TABLE pm.task_comments
  ADD COLUMN IF NOT EXISTS blocked boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS blocked_task_status text;

COMMENT ON COLUMN pm.task_comments.blocked IS
  'An agent says it is stuck on this task: a Needs you item for the task''s people and the agent''s managers until answered or the task moves. Only ever true on an agent''s comment.';
COMMENT ON COLUMN pm.task_comments.blocked_task_status IS
  'The task''s status when the agent said it was blocked; once the task moves on, the block is over.';

-- Blocked only from an agent: the prefix counts as the flag, a person's
-- comment is never blocked, and the task's status is kept with the block.
CREATE OR REPLACE FUNCTION pm.task_comment_blocked()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.text ~* '^\s*\[blocked\]' THEN
    NEW.blocked := true;
  END IF;
  IF NEW.blocked AND NOT EXISTS (SELECT 1 FROM pm.team_members m WHERE m.id = NEW.user_id AND m.role = 'agent') THEN
    NEW.blocked := false;
  END IF;
  IF NOT NEW.blocked THEN
    NEW.blocked_task_status := NULL;
  ELSIF TG_OP = 'INSERT' OR NOT OLD.blocked THEN
    NEW.blocked_task_status := (SELECT t.status FROM pm.tasks t WHERE t.id = NEW.task_id);
  ELSE
    NEW.blocked_task_status := OLD.blocked_task_status;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION pm.task_comment_blocked() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS task_comment_blocked ON pm.task_comments;
CREATE TRIGGER task_comment_blocked
  BEFORE INSERT OR UPDATE OF blocked, blocked_task_status ON pm.task_comments
  FOR EACH ROW EXECUTE FUNCTION pm.task_comment_blocked();

-- Agents' "[BLOCKED]" comments from before, on tasks still open: blocked, as
-- of the task's status now. Only rows not yet marked.
UPDATE pm.task_comments c
SET blocked = true
FROM pm.tasks t, pm.team_members m
WHERE c.blocked = false
  AND c.deleted_at IS NULL
  AND c.text ~* '^\s*\[blocked\]'
  AND t.id = c.task_id AND t.deleted_at IS NULL AND t.status <> 'done'
  AND m.id = c.user_id AND m.role = 'agent';

CREATE INDEX IF NOT EXISTS idx_task_comments_blocked
  ON pm.task_comments (created_at DESC)
  WHERE blocked AND deleted_at IS NULL;

-- Blocked comments that wait on the signed-in member, newest first, at most
-- 100. Same audience as pm.my_blocked_runs, plus whoever made the task.
CREATE OR REPLACE FUNCTION pm.my_blocked_comments()
RETURNS TABLE (
  comment_id uuid, task_id uuid, task_title text, project_id uuid,
  agent_id uuid, agent_name text, text text, created_at timestamptz
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT c.id, c.task_id, t.title, t.project_id, c.user_id, a.name, c.text, c.created_at
  FROM pm.task_comments c
  JOIN pm.tasks t ON t.id = c.task_id
  JOIN pm.team_members a ON a.id = c.user_id AND a.role = 'agent'
  WHERE c.blocked AND c.deleted_at IS NULL
    AND t.deleted_at IS NULL AND t.status <> 'done'
    AND t.status IS NOT DISTINCT FROM c.blocked_task_status
    AND pm.module_enabled('agents')
    AND pm.current_team_member_id() IS NOT NULL
    AND EXISTS (SELECT 1 FROM pm.projects p WHERE p.id = t.project_id AND p.deleted_at IS NULL)
    -- Answered (a person wrote after it) or the agent wrote again: over.
    AND NOT EXISTS (
      SELECT 1 FROM pm.task_comments l
      JOIN pm.team_members w ON w.id = l.user_id
      WHERE l.task_id = c.task_id AND l.deleted_at IS NULL
        AND (l.created_at, l.id) > (c.created_at, c.id)
        AND (w.role <> 'agent' OR l.user_id = c.user_id))
    AND (pm.member_manages_agent(c.user_id, pm.current_team_member_id())
      OR t.created_by = pm.current_team_member_id()
      OR EXISTS (SELECT 1 FROM pm.task_assignees ta WHERE ta.task_id = c.task_id AND ta.member_id = pm.current_team_member_id()))
  ORDER BY c.created_at DESC
  LIMIT 100
$$;

REVOKE ALL ON FUNCTION pm.my_blocked_comments() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.my_blocked_comments() TO authenticated, service_role;

-- How many Updates a member's view holds: the same rows pm.notification_feed
-- lists (receipts, cleared and snoozed left out), without paging.
CREATE OR REPLACE FUNCTION pm.notification_view_count(p_member_id uuid, p_view text DEFAULT 'updates')
RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT count(*)::integer
  FROM pm.team_member_notifications n
  WHERE n.user_id = p_member_id
    AND n.cleared_at IS NULL
    AND NOT pm.notification_is_receipt(n.category)
    AND CASE p_view
      WHEN 'done' THEN n.done_at IS NOT NULL
      WHEN 'unread' THEN n.done_at IS NULL AND NOT n.is_read
      ELSE n.done_at IS NULL
    END
    AND NOT EXISTS (
      SELECT 1 FROM pm.member_snoozes s
      WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
    )
$$;

REVOKE ALL ON FUNCTION pm.notification_view_count(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_view_count(uuid, text) TO service_role;

-- ============================================================
-- FOLLOW-UPS FOR AGENTS (20261127002900_agents_followups.sql)
-- ============================================================
-- Follow-ups for agents (2.0.54): an announce comment counts as a send, and
-- the watchdog's alarm speaks plainly and reaches whoever a question was
-- asked of. Additive and safe to run twice; the previous release's code
-- works with it.

-- ---------------------------------------------------------------------------
-- One send from an agent, counted on its own
-- ---------------------------------------------------------------------------
-- A write that also reaches people (a task comment posted with notify) was
-- counted as a write by pm.agent_write_gate already; this counts it in the
-- send bucket too (send_rate_per_minute), across all the agent's keys.
-- Answers {"refused": null}, or send_rate_limited with its limit and
-- reset_at. An agent without a send rate answers at once. Server only.
CREATE OR REPLACE FUNCTION pm.agent_send_gate(p_agent_id uuid, p_window_seconds integer DEFAULT 60)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_limit integer;
  v_now timestamptz := clock_timestamp();
  v_window pm.agent_write_windows%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;
  IF p_window_seconds <= 0 THEN RAISE EXCEPTION 'Invalid window'; END IF;
  SELECT l.send_rate_per_minute INTO v_limit FROM pm.agent_limits l WHERE l.agent_id = p_agent_id;
  IF v_limit IS NULL THEN RETURN jsonb_build_object('refused', null); END IF;
  INSERT INTO pm.agent_write_windows (agent_id, bucket, window_start, request_count)
  VALUES (p_agent_id, 'send', v_now, 1)
  ON CONFLICT (agent_id, bucket) DO UPDATE
  SET window_start = CASE WHEN agent_write_windows.window_start + make_interval(secs => p_window_seconds) <= v_now THEN v_now ELSE agent_write_windows.window_start END,
      request_count = CASE WHEN agent_write_windows.window_start + make_interval(secs => p_window_seconds) <= v_now THEN 1 ELSE agent_write_windows.request_count + 1 END
  RETURNING * INTO v_window;
  IF v_window.request_count > v_limit THEN
    RETURN jsonb_build_object(
      'refused', 'send_rate_limited',
      'limit', v_limit,
      'reset_at', v_window.window_start + make_interval(secs => p_window_seconds));
  END IF;
  RETURN jsonb_build_object('refused', null);
END;
$$;

REVOKE ALL ON FUNCTION pm.agent_send_gate(uuid, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.agent_send_gate(uuid, integer) TO service_role;

-- ---------------------------------------------------------------------------
-- The watchdog: plain words, and an expired ask reaches whoever was asked
-- ---------------------------------------------------------------------------
-- As before (every 5 minutes, each change made once), with three changes:
-- "<Agent> stopped responding. Its last check-in was 2 hours ago."; when it
-- comes back, a stopped-responding notice already read moves to done; and an
-- expired question or approval also tells the person it was asked of (or
-- the people of the group), once, as "<Asker>'s question to you expired
-- without an answer". Answers asked_told beside the rest.
CREATE OR REPLACE FUNCTION pm.run_watchdog()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  r record;
  v_person uuid;
  v_people uuid[];
  v_claims uuid[];
  v_stale integer;
  v_tell boolean;
  v_text text;
  v_title text;
  v_link text;
  v_workspace_paused boolean;
  v_offline integer := 0;
  v_online integer := 0;
  v_runs integer := 0;
  v_questions integer := 0;
  v_told integer := 0;
  v_asked integer := 0;
  v_webhooks integer := 0;
BEGIN
  -- One watchdog at a time; a run that overlaps the last one waits for the next.
  IF NOT pg_try_advisory_xact_lock(hashtext('pm.run_watchdog')) THEN
    RETURN jsonb_build_object('skipped', true);
  END IF;

  -- Agents that stopped responding, and agents that came back.
  IF pm.module_enabled('agents') THEN
    SELECT coalesce(bool_or(s.agents_paused_at IS NOT NULL), false) INTO v_workspace_paused FROM pm.business_settings s;

    FOR r IN
      SELECT a.id, a.name, h.reported_at, h.expected_interval_seconds AS interval_seconds
      FROM pm.agent_health h
      JOIN pm.team_members a ON a.id = h.member_id
      WHERE a.role = 'agent'
        AND a.delegate_of IS NULL
        AND coalesce(a.status, 'active') = 'active'
        AND a.agent_paused_at IS NULL
        AND NOT v_workspace_paused
        AND h.reported_at < now() - make_interval(secs => pm.heartbeat_stale_after_seconds(h.expected_interval_seconds))
        AND NOT EXISTS (SELECT 1 FROM pm.watchdog_marks w WHERE w.kind = 'agent_offline' AND w.subject_id = a.id)
      ORDER BY h.reported_at
    LOOP
      v_stale := pm.heartbeat_stale_after_seconds(r.interval_seconds);
      -- Claims that ran out while it was silent: those tasks are free again.
      SELECT coalesce(array_agg(t.id ORDER BY t.id), '{}') INTO v_claims
      FROM pm.tasks t
      WHERE t.claimed_by = r.id AND t.claim_expires_at <= now() AND t.claim_expires_at > r.reported_at
        AND t.status <> 'done' AND t.deleted_at IS NULL;
      -- An agent silent long before the watchdog first saw it is marked
      -- without a bell: nobody needs news that old.
      v_tell := now() - r.reported_at <= make_interval(secs => v_stale) + interval '1 day';
      v_people := CASE WHEN v_tell THEN pm.agent_people_to_tell(r.id) ELSE '{}'::uuid[] END;

      INSERT INTO pm.watchdog_marks (kind, subject_id, since, detail, notified_at)
      VALUES ('agent_offline', r.id, r.reported_at, jsonb_build_object('released_task_ids', to_jsonb(v_claims)),
        CASE WHEN cardinality(v_people) > 0 THEN now() END);

      PERFORM pm.emit_webhook_event('agent.offline', 'agent', r.id, '{}'::uuid[], ARRAY[r.id], jsonb_build_object(
        'agent', jsonb_build_object('id', r.id, 'name', r.name, 'reported_at', r.reported_at,
          'expected_interval_seconds', r.interval_seconds, 'stale_after_seconds', v_stale),
        'offline_since', r.reported_at,
        'released_task_ids', to_jsonb(v_claims),
        'project', NULL, 'project_id', NULL, 'task_id', NULL, 'actor_id', NULL));

      v_text := r.name || ' stopped responding. Its last check-in was ' || pm.watchdog_ago(r.reported_at) || ' ago.'
        || CASE cardinality(v_claims)
             WHEN 0 THEN ''
             WHEN 1 THEN ' Its claimed task went back to the queue.'
             ELSE ' Its ' || cardinality(v_claims) || ' claimed tasks went back to the queue.'
           END;
      FOREACH v_person IN ARRAY v_people LOOP
        PERFORM pm.upsert_notification(v_person, r.name || ' stopped responding', v_text, '/agent/' || r.id, 'member', r.id::text);
      END LOOP;
      v_offline := v_offline + 1;
    END LOOP;

    FOR r IN
      SELECT w.subject_id AS id, w.since, w.notified_at, a.name, h.reported_at, h.expected_interval_seconds AS interval_seconds
      FROM pm.watchdog_marks w
      JOIN pm.team_members a ON a.id = w.subject_id
      JOIN pm.agent_health h ON h.member_id = w.subject_id
      WHERE w.kind = 'agent_offline'
        AND h.reported_at >= now() - make_interval(secs => pm.heartbeat_stale_after_seconds(h.expected_interval_seconds))
    LOOP
      DELETE FROM pm.watchdog_marks WHERE kind = 'agent_offline' AND subject_id = r.id;
      PERFORM pm.emit_webhook_event('agent.online', 'agent', r.id, '{}'::uuid[], ARRAY[r.id], jsonb_build_object(
        'agent', jsonb_build_object('id', r.id, 'name', r.name, 'reported_at', r.reported_at,
          'expected_interval_seconds', r.interval_seconds, 'stale_after_seconds', pm.heartbeat_stale_after_seconds(r.interval_seconds)),
        'offline_since', r.since,
        'project', NULL, 'project_id', NULL, 'task_id', NULL, 'actor_id', NULL));
      IF r.notified_at IS NOT NULL THEN
        FOREACH v_person IN ARRAY pm.agent_people_to_tell(r.id) LOOP
          PERFORM pm.upsert_notification(v_person, r.name || ' is back', r.name || ' is responding again.', '/agent/' || r.id, 'member', r.id::text);
        END LOOP;
        -- The alarm is settled: one already read moves to done, so only "is back" stays.
        UPDATE pm.team_member_notifications SET done_at = now()
        WHERE entity_type = 'member' AND entity_id = r.id::text AND category = 'agent_offline'
          AND done_at IS NULL AND cleared_at IS NULL;
      END IF;
      v_online := v_online + 1;
    END LOOP;

    -- An agent removed, or no longer reporting at all, has nothing to come back from.
    DELETE FROM pm.watchdog_marks w
    WHERE w.kind = 'agent_offline'
      AND NOT EXISTS (
        SELECT 1 FROM pm.team_members a JOIN pm.agent_health h ON h.member_id = a.id
        WHERE a.id = w.subject_id AND a.role = 'agent' AND coalesce(a.status, 'active') = 'active'
      );
  END IF;

  -- Open questions past their time: stored as expired (the same update a
  -- read makes), which sends question.expired and clears the asked bells.
  -- A run one of them held is running again, its clock restarted.
  UPDATE pm.questions SET status = 'expired'
  WHERE status = 'open' AND expires_at <= now();
  GET DIAGNOSTICS v_questions = ROW_COUNT;

  -- Runs with no update for two hours: stored as timed_out, which sends
  -- run.finished. The run ends at its last update. A run waiting on a
  -- person is skipped while a question naming it is open; waiting with
  -- none, it gets seven days.
  -- While the AI agents module is off, agents cannot report, so nothing times out.
  IF pm.module_enabled('agents') THEN
    UPDATE pm.agent_runs run
    SET status = 'timed_out', finished_at = greatest(run.started_at, run.updated_at)
    WHERE (run.status = 'running' AND run.updated_at < now() - interval '2 hours')
       OR (run.status = 'waiting' AND run.updated_at < now() - interval '7 days'
           AND NOT pm.agent_run_has_open_question(run.id));
    GET DIAGNOSTICS v_runs = ROW_COUNT;
  END IF;

  -- Whoever asked hears once, however the expiry was stored, within a day.
  FOR r IN
    SELECT q.id, q.kind, q.question, q.asked_by, q.asked_to, q.asked_to_group, q.project_id, q.task_id,
      asker.name AS asker_name, asker.role AS asker_role, coalesce(target.name, g.name) AS target_name
    FROM pm.questions q
    JOIN pm.team_members asker ON asker.id = q.asked_by
    LEFT JOIN pm.team_members target ON target.id = q.asked_to
    LEFT JOIN pm.groups g ON g.id = q.asked_to_group
    WHERE q.status = 'expired' AND q.deleted_at IS NULL AND q.expires_at > now() - interval '1 day'
      AND NOT EXISTS (SELECT 1 FROM pm.watchdog_marks w WHERE w.kind = 'question_expired' AND w.subject_id = q.id)
    ORDER BY q.expires_at
  LOOP
    INSERT INTO pm.watchdog_marks (kind, subject_id, notified_at) VALUES ('question_expired', r.id, now());
    IF r.asker_role = 'agent' THEN
      v_people := pm.agent_people_to_tell(r.asked_by);
      v_title := r.asker_name || '''s ';
      v_link := '/agent/' || r.asked_by;
    ELSE
      SELECT coalesce(array_agg(m.id), '{}') INTO v_people FROM pm.team_members m
      WHERE m.id = r.asked_by AND coalesce(m.status, 'active') = 'active';
      v_title := 'Your ';
      v_link := '/my-tasks';
    END IF;
    IF r.task_id IS NOT NULL AND r.project_id IS NOT NULL THEN
      v_link := '/projects/' || r.project_id || '?task=' || r.task_id;
    END IF;
    v_title := v_title || CASE WHEN r.kind = 'approval' THEN 'approval request to ' ELSE 'question to ' END
      || coalesce(nullif(btrim(r.target_name), ''), 'a teammate')
      || CASE WHEN r.kind = 'approval' THEN ' expired without a decision' ELSE ' expired without an answer' END;
    FOREACH v_person IN ARRAY v_people LOOP
      -- Whoever was asked already knows.
      CONTINUE WHEN v_person IS NOT DISTINCT FROM r.asked_to;
      PERFORM pm.upsert_notification(v_person, v_title, left(r.question, 500), v_link, 'question', r.id::text);
      v_told := v_told + 1;
    END LOOP;
    -- Whoever it was asked of (a person, or a group's people) hears once
    -- too: the ask left their list when it expired.
    v_title := coalesce(nullif(btrim(r.asker_name), ''), 'A teammate') || '''s '
      || CASE WHEN r.kind = 'approval' THEN 'approval request to you expired without a decision' ELSE 'question to you expired without an answer' END;
    FOR v_person IN
      SELECT m.id FROM pm.team_members m
      WHERE m.role <> 'agent' AND coalesce(m.status, 'active') = 'active' AND m.id <> r.asked_by
        AND (m.id = r.asked_to
          OR (r.asked_to_group IS NOT NULL AND m.id IN (SELECT gm.member_id FROM pm.group_members gm WHERE gm.group_id = r.asked_to_group)))
      ORDER BY m.id
    LOOP
      PERFORM pm.upsert_notification(v_person, v_title, left(r.question, 500), v_link, 'question', r.id::text, 'question_expired', r.project_id, r.asked_by);
      v_asked := v_asked + 1;
    END LOOP;
  END LOOP;
  DELETE FROM pm.watchdog_marks WHERE kind = 'question_expired' AND since < now() - interval '2 days';

  -- Webhook endpoints that keep failing: 5 attempts in a row, or failing for
  -- a day. Told once; a success resets it (track_webhook_endpoint_health).
  IF pm.module_enabled('webhooks') THEN
    FOR r IN
      SELECT w.subject_id AS id, w.detail, e.name
      FROM pm.watchdog_marks w
      JOIN pm.webhook_endpoints e ON e.id = w.subject_id
      WHERE w.kind = 'webhook_failing' AND w.notified_at IS NULL AND e.is_active
        AND (w.failures >= 5 OR w.since <= now() - interval '24 hours')
    LOOP
      UPDATE pm.watchdog_marks SET notified_at = now(), updated_at = now()
      WHERE kind = 'webhook_failing' AND subject_id = r.id;
      FOR v_person IN
        SELECT m.id FROM pm.team_members m
        WHERE m.role <> 'agent' AND coalesce(m.status, 'active') = 'active'
          AND (m.role = 'owner' OR pm.member_has_permission(m.id, 'webhooks.manage', 'app'))
        ORDER BY m.id
      LOOP
        PERFORM pm.upsert_notification(v_person, 'Webhook ' || r.name || ' keeps failing',
          'Last error: ' || coalesce(r.detail ->> 'last_error', 'unknown'), '/settings/developers#webhooks', 'webhook', r.id::text);
      END LOOP;
      v_webhooks := v_webhooks + 1;
    END LOOP;
  END IF;
  DELETE FROM pm.watchdog_marks w
  WHERE w.kind = 'webhook_failing'
    AND NOT EXISTS (SELECT 1 FROM pm.webhook_endpoints e WHERE e.id = w.subject_id);

  RETURN jsonb_build_object(
    'agents_offline', v_offline,
    'agents_online', v_online,
    'runs_timed_out', v_runs,
    'questions_expired', v_questions,
    'askers_told', v_told,
    'asked_told', v_asked,
    'webhooks_failing', v_webhooks
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.run_watchdog() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.run_watchdog() TO service_role;

-- ============================================================
-- SETTINGS CLEANUP: SQUARE LOGO FOR THE DARK THEME (20261127003100_settings_cleanup.sql)
-- ============================================================
-- Settings cleanup: the brand's fourth logo slot. Settings > Workspace >
-- Brand now has a horizontal and a square logo, each for the light and the
-- dark theme. Three slots map onto the columns that were there (logo_light_path
-- and logo_dark_path are the horizontal logo, favicon_path the square logo for
-- the light theme); this adds the square logo for the dark theme.
--
-- Additive and safe to re-run: one nullable column, no data changes. NULL
-- means "use the light theme's square logo", so the previous release's code,
-- which never reads it, keeps working unchanged. The brand bucket already
-- accepts the PNG, JPEG and ICO files a square logo may be.

ALTER TABLE pm.workspace_brand ADD COLUMN IF NOT EXISTS logo_square_dark_path text;

COMMENT ON COLUMN pm.workspace_brand.logo_square_dark_path IS
  'Object path in the pm-brand bucket: the square logo for dark backgrounds (the tab icon in a dark browser). NULL uses favicon_path.';

-- ============================================================
-- NOTIFICATIONS GROUPS (20261127003300_notifications_groups.sql)
-- ============================================================
-- Notifications grouped and filtered, and one count for a blocked comment.
--
-- - pm.blocked_comments_for(member): the blocked comments that wait on a
--   member (20261127002700's pm.my_blocked_comments, now for any member, on
--   the server); pm.my_blocked_comments reads it for the signed-in one.
-- - pm.notification_announces_block: a task's comment notice (or its
--   agent's message) while a blocked comment on that task waits on the
--   reader is a receipt of that Needs you item, as a question's notice is.
--   pm.notification_feed, pm.notification_groups,
--   pm.notification_unread_count and pm.notification_view_count are
--   redefined to leave it out, so the bell counts the block once; once the
--   block is answered the notice is an update again.
-- - pm.notification_update_groups: a member's open Updates grouped by what
--   they are about (a task, a project; a notice about nothing is its own
--   group), the latest row of each with its counts, keyset paged, narrowed
--   to notices from agents or to some projects. pm.notification_group_total
--   counts those groups; pm.notification_group_rows lists one group's rows,
--   newest first. pm.notification_group_key is the one way a row's group is
--   named; pm.notification_open_updates is the rows they all start from.
--   Server only.
--
-- Additive and safe to run twice: functions only, every one CREATE OR
-- REPLACE with the same arguments and results. The previous release's code
-- reads the same functions with the same answers, less the receipts.

-- Blocked comments that wait on a member, newest first, at most 100. Same
-- audience as pm.my_blocked_runs, plus whoever made the task. Server only:
-- members read their own through pm.my_blocked_comments.
CREATE OR REPLACE FUNCTION pm.blocked_comments_for(p_member_id uuid)
RETURNS TABLE (
  comment_id uuid, task_id uuid, task_title text, project_id uuid,
  agent_id uuid, agent_name text, text text, created_at timestamptz
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT c.id, c.task_id, t.title, t.project_id, c.user_id, a.name, c.text, c.created_at
  FROM pm.task_comments c
  JOIN pm.tasks t ON t.id = c.task_id
  JOIN pm.team_members a ON a.id = c.user_id AND a.role = 'agent'
  WHERE c.blocked AND c.deleted_at IS NULL
    AND t.deleted_at IS NULL AND t.status <> 'done'
    AND t.status IS NOT DISTINCT FROM c.blocked_task_status
    AND pm.module_enabled('agents')
    AND p_member_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM pm.projects p WHERE p.id = t.project_id AND p.deleted_at IS NULL)
    -- Answered (a person wrote after it) or the agent wrote again: over.
    AND NOT EXISTS (
      SELECT 1 FROM pm.task_comments l
      JOIN pm.team_members w ON w.id = l.user_id
      WHERE l.task_id = c.task_id AND l.deleted_at IS NULL
        AND (l.created_at, l.id) > (c.created_at, c.id)
        AND (w.role <> 'agent' OR l.user_id = c.user_id))
    AND (pm.member_manages_agent(c.user_id, p_member_id)
      OR t.created_by = p_member_id
      OR EXISTS (SELECT 1 FROM pm.task_assignees ta WHERE ta.task_id = c.task_id AND ta.member_id = p_member_id))
  ORDER BY c.created_at DESC
  LIMIT 100
$$;

REVOKE ALL ON FUNCTION pm.blocked_comments_for(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.blocked_comments_for(uuid) TO service_role;

-- The signed-in member's own: what Needs you lists.
CREATE OR REPLACE FUNCTION pm.my_blocked_comments()
RETURNS TABLE (
  comment_id uuid, task_id uuid, task_title text, project_id uuid,
  agent_id uuid, agent_name text, text text, created_at timestamptz
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT * FROM pm.blocked_comments_for(pm.current_team_member_id())
$$;

REVOKE ALL ON FUNCTION pm.my_blocked_comments() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.my_blocked_comments() TO authenticated, service_role;

-- A notice that announces a blocked comment waiting on its reader: the
-- comment notice (or the agent's own message) about that task, while the
-- block is open. Needs you lists the block, so the notice is a receipt for
-- as long: never shown in Updates, never counted. Once answered it is an
-- update like any other.
CREATE OR REPLACE FUNCTION pm.notification_announces_block(
  p_member_id uuid, p_entity_type text, p_entity_id text, p_category text, p_actor_id uuid
) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  -- Looks at the one task the notice is about (the partial index below), with
  -- the same rules as pm.blocked_comments_for, so a feed pays one indexed
  -- probe per comment notice, never a scan of every comment.
  SELECT CASE
    WHEN p_entity_type IS DISTINCT FROM 'task' OR p_category NOT IN ('task_comments', 'agent_message') THEN false
    WHEN p_member_id IS NULL OR p_entity_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN false
    WHEN NOT pm.module_enabled('agents') THEN false
    ELSE EXISTS (
      SELECT 1
      FROM pm.task_comments c
      JOIN pm.tasks t ON t.id = c.task_id
      JOIN pm.team_members a ON a.id = c.user_id AND a.role = 'agent'
      WHERE c.task_id = p_entity_id::uuid
        AND c.blocked AND c.deleted_at IS NULL
        AND (p_actor_id IS NULL OR p_actor_id = c.user_id)
        AND t.deleted_at IS NULL AND t.status <> 'done'
        AND t.status IS NOT DISTINCT FROM c.blocked_task_status
        AND EXISTS (SELECT 1 FROM pm.projects p WHERE p.id = t.project_id AND p.deleted_at IS NULL)
        AND NOT EXISTS (
          SELECT 1 FROM pm.task_comments l
          JOIN pm.team_members w ON w.id = l.user_id
          WHERE l.task_id = c.task_id AND l.deleted_at IS NULL
            AND (l.created_at, l.id) > (c.created_at, c.id)
            AND (w.role <> 'agent' OR l.user_id = c.user_id))
        AND (pm.member_manages_agent(c.user_id, p_member_id)
          OR t.created_by = p_member_id
          OR EXISTS (SELECT 1 FROM pm.task_assignees ta WHERE ta.task_id = c.task_id AND ta.member_id = p_member_id)))
  END
$$;

-- Open blocked comments by task: what the receipt check and Needs you read.
CREATE INDEX IF NOT EXISTS idx_task_comments_blocked_open ON pm.task_comments (task_id) WHERE blocked AND deleted_at IS NULL;

REVOKE ALL ON FUNCTION pm.notification_announces_block(uuid, text, text, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_announces_block(uuid, text, text, text, uuid) TO service_role;

-- How many Updates a member's view holds: the same rows pm.notification_feed
-- lists (receipts, cleared and snoozed left out), without paging.
CREATE OR REPLACE FUNCTION pm.notification_view_count(p_member_id uuid, p_view text DEFAULT 'updates')
RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT count(*)::integer
  FROM pm.team_member_notifications n
  WHERE n.user_id = p_member_id
    AND n.cleared_at IS NULL
    AND NOT pm.notification_is_receipt(n.category)
    AND NOT pm.notification_announces_block(n.user_id, n.entity_type, n.entity_id, n.category, n.actor_id)
    AND CASE p_view
      WHEN 'done' THEN n.done_at IS NOT NULL
      WHEN 'unread' THEN n.done_at IS NULL AND NOT n.is_read
      ELSE n.done_at IS NULL
    END
    AND NOT EXISTS (
      SELECT 1 FROM pm.member_snoozes s
      WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
    )
$$;

REVOKE ALL ON FUNCTION pm.notification_view_count(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_view_count(uuid, text) TO service_role;

-- The group a notice belongs to: what it is about ("task:<id>"), or itself
-- when it is about nothing.
CREATE OR REPLACE FUNCTION pm.notification_group_key(p_entity_type text, p_entity_id text, p_id uuid)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = pm
AS $$
  SELECT CASE WHEN p_entity_type IS NOT NULL AND p_entity_id IS NOT NULL
    THEN p_entity_type || ':' || p_entity_id ELSE 'notification:' || p_id::text END
$$;

REVOKE ALL ON FUNCTION pm.notification_group_key(text, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_group_key(text, text, uuid) TO service_role;

-- A member's open Updates (not done, receipts, cleared and snoozed left
-- out), narrowed to notices from agents and to some projects when asked.
CREATE OR REPLACE FUNCTION pm.notification_open_updates(
  p_member_id uuid,
  p_from_agents boolean DEFAULT false,
  p_project_ids uuid[] DEFAULT NULL
) RETURNS SETOF pm.team_member_notifications
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT n.*
  FROM pm.team_member_notifications n
  WHERE n.user_id = p_member_id
    AND n.cleared_at IS NULL
    AND n.done_at IS NULL
    AND NOT pm.notification_is_receipt(n.category)
    AND NOT pm.notification_announces_block(n.user_id, n.entity_type, n.entity_id, n.category, n.actor_id)
    AND NOT EXISTS (
      SELECT 1 FROM pm.member_snoozes s
      WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
    )
    AND (NOT coalesce(p_from_agents, false)
      OR EXISTS (SELECT 1 FROM pm.team_members a WHERE a.id = n.actor_id AND a.role = 'agent'))
    AND (p_project_ids IS NULL OR cardinality(p_project_ids) = 0 OR n.project_id = ANY (p_project_ids))
$$;

REVOKE ALL ON FUNCTION pm.notification_open_updates(uuid, boolean, uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_open_updates(uuid, boolean, uuid[]) TO service_role;

-- Updates grouped: the latest row of each group with how many it holds and
-- how many are unread, newest group first, keyset paged on the latest
-- row's (created_at, id).
CREATE OR REPLACE FUNCTION pm.notification_update_groups(
  p_member_id uuid,
  p_limit integer DEFAULT 30,
  p_before_at timestamptz DEFAULT NULL,
  p_before_id uuid DEFAULT NULL,
  p_from_agents boolean DEFAULT false,
  p_project_ids uuid[] DEFAULT NULL
) RETURNS TABLE (
  id uuid,
  title text,
  message text,
  link text,
  is_read boolean,
  entity_type text,
  entity_id text,
  category text,
  project_id uuid,
  actor_id uuid,
  created_at timestamptz,
  group_key text,
  group_count integer,
  unread_count integer
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  WITH ranked AS (
    SELECT o.*,
      pm.notification_group_key(o.entity_type, o.entity_id, o.id) AS gkey,
      row_number() OVER (PARTITION BY pm.notification_group_key(o.entity_type, o.entity_id, o.id) ORDER BY o.created_at DESC, o.id DESC) AS rn,
      count(*) OVER (PARTITION BY pm.notification_group_key(o.entity_type, o.entity_id, o.id)) AS cnt,
      count(*) FILTER (WHERE NOT o.is_read) OVER (PARTITION BY pm.notification_group_key(o.entity_type, o.entity_id, o.id)) AS unread
    FROM pm.notification_open_updates(p_member_id, p_from_agents, p_project_ids) o
  )
  SELECT r.id, r.title, r.message, r.link, r.is_read, r.entity_type, r.entity_id, r.category, r.project_id, r.actor_id,
    r.created_at, r.gkey, r.cnt::integer, r.unread::integer
  FROM ranked r
  WHERE r.rn = 1
    AND (p_before_at IS NULL OR (r.created_at, r.id) < (p_before_at, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
  ORDER BY r.created_at DESC, r.id DESC
  LIMIT least(greatest(coalesce(p_limit, 30), 1), 100)
$$;

REVOKE ALL ON FUNCTION pm.notification_update_groups(uuid, integer, timestamptz, uuid, boolean, uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_update_groups(uuid, integer, timestamptz, uuid, boolean, uuid[]) TO service_role;

-- How many groups those Updates make, with the same filters.
CREATE OR REPLACE FUNCTION pm.notification_group_total(
  p_member_id uuid,
  p_from_agents boolean DEFAULT false,
  p_project_ids uuid[] DEFAULT NULL
) RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT count(DISTINCT pm.notification_group_key(o.entity_type, o.entity_id, o.id))::integer
  FROM pm.notification_open_updates(p_member_id, p_from_agents, p_project_ids) o
$$;

REVOKE ALL ON FUNCTION pm.notification_group_total(uuid, boolean, uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_group_total(uuid, boolean, uuid[]) TO service_role;

-- One group's open Updates, newest first, keyset paged on (created_at, id).
CREATE OR REPLACE FUNCTION pm.notification_group_rows(
  p_member_id uuid,
  p_group_key text,
  p_limit integer DEFAULT 30,
  p_before_at timestamptz DEFAULT NULL,
  p_before_id uuid DEFAULT NULL
) RETURNS SETOF pm.team_member_notifications
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT o.*
  FROM pm.notification_open_updates(p_member_id, false, NULL) o
  WHERE pm.notification_group_key(o.entity_type, o.entity_id, o.id) = p_group_key
    AND (p_before_at IS NULL OR (o.created_at, o.id) < (p_before_at, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
  ORDER BY o.created_at DESC, o.id DESC
  LIMIT least(greatest(coalesce(p_limit, 30), 1), 100)
$$;

REVOKE ALL ON FUNCTION pm.notification_group_rows(uuid, text, integer, timestamptz, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_group_rows(uuid, text, integer, timestamptz, uuid) TO service_role;

-- The foundation's Updates feed, groups and unread count, as before, with a
-- notice announcing an open blocked comment left out (it is a receipt while
-- the block waits in Needs you).

-- A member's Updates: view updates (not done), unread, or done (newest
-- done first). Receipts, cleared and snoozed rows never show. Keyset paged
-- on (created_at, id), or (done_at, id) for done.
CREATE OR REPLACE FUNCTION pm.notification_feed(
  p_member_id uuid,
  p_view text DEFAULT 'updates',
  p_limit integer DEFAULT 30,
  p_before_at timestamptz DEFAULT NULL,
  p_before_id uuid DEFAULT NULL
) RETURNS SETOF pm.team_member_notifications
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT n.*
  FROM pm.team_member_notifications n
  WHERE n.user_id = p_member_id
    AND n.cleared_at IS NULL
    AND NOT pm.notification_is_receipt(n.category)
    AND NOT pm.notification_announces_block(n.user_id, n.entity_type, n.entity_id, n.category, n.actor_id)
    AND CASE p_view
      WHEN 'done' THEN n.done_at IS NOT NULL
      WHEN 'unread' THEN n.done_at IS NULL AND NOT n.is_read
      ELSE n.done_at IS NULL
    END
    AND NOT EXISTS (
      SELECT 1 FROM pm.member_snoozes s
      WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
    )
    AND (
      p_before_at IS NULL
      OR (CASE WHEN p_view = 'done' THEN n.done_at ELSE n.created_at END, n.id) < (p_before_at, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
    )
  ORDER BY CASE WHEN p_view = 'done' THEN n.done_at ELSE n.created_at END DESC, n.id DESC
  LIMIT least(greatest(coalesce(p_limit, 30), 1), 100)
$$;

REVOKE ALL ON FUNCTION pm.notification_feed(uuid, text, integer, timestamptz, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_feed(uuid, text, integer, timestamptz, uuid) TO service_role;

-- The same Updates grouped by what they are about (entity type and id; a
-- notice about nothing is its own group): the latest row of each group, how
-- many it holds and how many are unread, newest group first, keyset paged
-- on the latest row's (created_at, id).
CREATE OR REPLACE FUNCTION pm.notification_groups(
  p_member_id uuid,
  p_limit integer DEFAULT 30,
  p_before_at timestamptz DEFAULT NULL,
  p_before_id uuid DEFAULT NULL
) RETURNS TABLE (
  id uuid,
  title text,
  message text,
  link text,
  is_read boolean,
  entity_type text,
  entity_id text,
  category text,
  project_id uuid,
  actor_id uuid,
  created_at timestamptz,
  group_key text,
  group_count integer,
  unread_count integer
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  WITH open_rows AS (
    SELECT n.*,
      CASE WHEN n.entity_type IS NOT NULL AND n.entity_id IS NOT NULL
        THEN n.entity_type || ':' || n.entity_id ELSE 'notification:' || n.id::text END AS gkey
    FROM pm.team_member_notifications n
    WHERE n.user_id = p_member_id
      AND n.cleared_at IS NULL
      AND n.done_at IS NULL
      AND NOT pm.notification_is_receipt(n.category)
      AND NOT pm.notification_announces_block(n.user_id, n.entity_type, n.entity_id, n.category, n.actor_id)
      AND NOT EXISTS (
        SELECT 1 FROM pm.member_snoozes s
        WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
      )
  ), ranked AS (
    SELECT o.*,
      row_number() OVER (PARTITION BY o.gkey ORDER BY o.created_at DESC, o.id DESC) AS rn,
      count(*) OVER (PARTITION BY o.gkey) AS cnt,
      count(*) FILTER (WHERE NOT o.is_read) OVER (PARTITION BY o.gkey) AS unread
    FROM open_rows o
  )
  SELECT r.id, r.title, r.message, r.link, r.is_read, r.entity_type, r.entity_id, r.category, r.project_id, r.actor_id,
    r.created_at, r.gkey, r.cnt::integer, r.unread::integer
  FROM ranked r
  WHERE r.rn = 1
    AND (p_before_at IS NULL OR (r.created_at, r.id) < (p_before_at, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
  ORDER BY r.created_at DESC, r.id DESC
  LIMIT least(greatest(coalesce(p_limit, 30), 1), 100)
$$;

REVOKE ALL ON FUNCTION pm.notification_groups(uuid, integer, timestamptz, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_groups(uuid, integer, timestamptz, uuid) TO service_role;

-- How many of a member's Updates are unread: the Notifications count.
CREATE OR REPLACE FUNCTION pm.notification_unread_count(p_member_id uuid)
RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT count(*)::integer
  FROM pm.team_member_notifications n
  WHERE n.user_id = p_member_id
    AND n.cleared_at IS NULL
    AND n.done_at IS NULL
    AND NOT n.is_read
    AND NOT pm.notification_is_receipt(n.category)
    AND NOT pm.notification_announces_block(n.user_id, n.entity_type, n.entity_id, n.category, n.actor_id)
    AND NOT EXISTS (
      SELECT 1 FROM pm.member_snoozes s
      WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
    )
$$;

REVOKE ALL ON FUNCTION pm.notification_unread_count(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_unread_count(uuid) TO service_role;

-- ============================================================
-- NOTIFICATIONS DELIVERY (20261127003500_notifications_delivery.sql)
-- ============================================================
-- Notifications delivery: email and the person's own chat, from one server
-- delivery point, as each person chose in Settings > Notifications.
--
-- - pm.team_members gains chat_notifications_enabled and
--   chat_notification_prefs: the chat switch and its choice per kind, beside
--   the email ones. "needs_you" is the kind for what waits on the person (a
--   question or approval asked, an agent's findings, an inbox decision): on
--   by default for email and chat once the person turns that channel on.
--   In the app every notice always shows.
-- - pm.notification_pref_key: the kind a notice is chosen by (its category,
--   or needs_you for a notice that announces a Needs you item; null for a
--   kind nobody chooses, which goes nowhere but the app). Mirrored by
--   deliveryKeyOf in src/lib/notification-defaults.ts.
-- - pm.notification_deliveries: the queue. A notice raised for a person
--   (inserted, or raised again unread) adds one pending row per channel they
--   asked for (never for invoice drafts by email: the morning summary sends
--   those). pm.claim_notification_deliveries leases due rows,
--   pm.complete_notification_delivery records the outcome (sent, skipped
--   with why, or failed after three tries, a minute apart and growing).
--   Server only.
-- - pm.notification_delivery_kick: pg_cron asks the app to deliver every
--   minute while something is due (POST /api/internal/notifications/deliver,
--   the scheduler secret in Vault, as webhook retries and schedules do).
-- - pm.notification_updates_list: the Updates list the API pages by offset
--   (view updates, unread or done, with its filters and total), with the
--   same rows the app lists: receipts, snoozed and a blocked comment's
--   notice left out. pm.blocked_comments_for and
--   pm.notification_announces_block are defined here as in
--   20261127003300_notifications_groups.sql (the same text), so this file
--   stands on its own.
--
-- Additive and safe to run twice. The previous release's code never reads
-- the new columns or table; it keeps emailing app notices as before until
-- the new code delivers them through the queue.

ALTER TABLE pm.team_members
  ADD COLUMN IF NOT EXISTS chat_notifications_enabled boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS chat_notification_prefs jsonb NOT NULL DEFAULT '{}'::jsonb;

COMMENT ON COLUMN pm.team_members.chat_notifications_enabled IS
  'Send notifications to the person''s own chat (a DM from a bot they linked an account on). Off until they turn it on.';
COMMENT ON COLUMN pm.team_members.chat_notification_prefs IS
  'Chat on or off per kind ({"task_comments": true}); needs_you is on unless set false. Only read while chat_notifications_enabled.';

-- The kind a notice is chosen by. Mirrors deliveryKeyOf.
CREATE OR REPLACE FUNCTION pm.notification_pref_key(p_category text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = pm
AS $$
  SELECT CASE
    WHEN p_category IN ('question_asked', 'approval_requested', 'findings_nudge', 'inbox_decision') THEN 'needs_you'
    WHEN p_category IN (
      'task_created', 'task_deleted', 'task_status', 'task_assignments', 'task_updates', 'task_subtasks', 'task_comments',
      'project_created', 'project_deleted', 'project_updates', 'project_contacts', 'portal_settings', 'portal_updates',
      'time_entries', 'invoice_drafts', 'entity_files', 'contact_created', 'contact_deleted', 'contact_updates',
      'team_members', 'api_keys', 'lead_created', 'lead_deleted', 'lead_status', 'lead_updates', 'lead_interactions',
      'lead_proposals', 'lead_contacts', 'lead_conversions', 'agent_suggestions', 'agent_goals', 'agent_autonomous', 'agent_activity'
    ) THEN p_category
    ELSE NULL
  END
$$;

REVOKE ALL ON FUNCTION pm.notification_pref_key(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_pref_key(text) TO service_role;

CREATE TABLE IF NOT EXISTS pm.notification_deliveries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  notification_id uuid NOT NULL REFERENCES pm.team_member_notifications(id) ON DELETE CASCADE,
  member_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  channel text NOT NULL CHECK (channel IN ('email', 'chat')),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sending', 'sent', 'skipped', 'failed')),
  attempts integer NOT NULL DEFAULT 0,
  next_attempt_at timestamptz NOT NULL DEFAULT now(),
  lease_expires_at timestamptz,
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz
);

COMMENT ON TABLE pm.notification_deliveries IS
  'Email and chat deliveries of notifications, one row per notice raised and channel; the app sends them (POST /api/internal/notifications/deliver).';

-- One open delivery per notice and channel: raising it again while one waits adds nothing.
CREATE UNIQUE INDEX IF NOT EXISTS idx_notification_deliveries_open
  ON pm.notification_deliveries (notification_id, channel)
  WHERE status IN ('pending', 'sending');
CREATE INDEX IF NOT EXISTS idx_notification_deliveries_due
  ON pm.notification_deliveries (next_attempt_at)
  WHERE status IN ('pending', 'sending');
CREATE INDEX IF NOT EXISTS idx_notification_deliveries_member
  ON pm.notification_deliveries (member_id, created_at DESC);

ALTER TABLE pm.notification_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.notification_deliveries FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.notification_deliveries TO service_role;

-- A notice raised for a person: one pending delivery per channel they asked for.
CREATE OR REPLACE FUNCTION pm.enqueue_notification_deliveries()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_key text := pm.notification_pref_key(NEW.category);
  v_member record;
BEGIN
  IF v_key IS NULL OR NEW.is_read OR NEW.done_at IS NOT NULL OR NEW.cleared_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.created_at IS NOT DISTINCT FROM NEW.created_at THEN
    RETURN NULL;
  END IF;
  SELECT m.role, m.status, m.email_notifications_enabled, m.email_notification_prefs,
         m.chat_notifications_enabled, m.chat_notification_prefs
    INTO v_member
  FROM pm.team_members m WHERE m.id = NEW.user_id;
  IF NOT FOUND OR v_member.role = 'agent' OR coalesce(v_member.status, 'active') <> 'active' THEN
    RETURN NULL;
  END IF;
  -- Invoice drafts by email are the morning summary's (pm.billing_draft_notices).
  IF v_member.email_notifications_enabled AND v_key <> 'invoice_drafts'
     AND (v_member.email_notification_prefs -> v_key = 'true'::jsonb OR (jsonb_typeof(v_member.email_notification_prefs -> v_key) IS DISTINCT FROM 'boolean' AND v_key = 'needs_you')) THEN
    INSERT INTO pm.notification_deliveries (notification_id, member_id, channel)
    VALUES (NEW.id, NEW.user_id, 'email')
    ON CONFLICT (notification_id, channel) WHERE status IN ('pending', 'sending') DO NOTHING;
  END IF;
  IF v_member.chat_notifications_enabled
     AND (v_member.chat_notification_prefs -> v_key = 'true'::jsonb OR (jsonb_typeof(v_member.chat_notification_prefs -> v_key) IS DISTINCT FROM 'boolean' AND v_key = 'needs_you')) THEN
    INSERT INTO pm.notification_deliveries (notification_id, member_id, channel)
    VALUES (NEW.id, NEW.user_id, 'chat')
    ON CONFLICT (notification_id, channel) WHERE status IN ('pending', 'sending') DO NOTHING;
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION pm.enqueue_notification_deliveries() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS enqueue_notification_deliveries ON pm.team_member_notifications;
CREATE TRIGGER enqueue_notification_deliveries
  AFTER INSERT OR UPDATE OF created_at ON pm.team_member_notifications
  FOR EACH ROW EXECUTE FUNCTION pm.enqueue_notification_deliveries();

-- Leases due deliveries to one sender, oldest first: their notice and
-- person with them. A notice read, done or cleared meanwhile is skipped,
-- not sent. Answers what to send.
CREATE OR REPLACE FUNCTION pm.claim_notification_deliveries(p_limit integer DEFAULT 25, p_member_ids uuid[] DEFAULT NULL)
RETURNS TABLE (
  delivery_id uuid, channel text, attempts integer, member_id uuid, member_email text, member_name text,
  notification_id uuid, title text, message text, link text, category text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
BEGIN
  -- Seen in the app before it went out: nothing to tell.
  UPDATE pm.notification_deliveries d
  SET status = 'skipped', last_error = 'Read in the app first', finished_at = now(), lease_expires_at = NULL
  FROM pm.team_member_notifications n
  WHERE d.notification_id = n.id AND d.status IN ('pending', 'sending')
    AND (n.is_read OR n.done_at IS NOT NULL OR n.cleared_at IS NOT NULL);

  RETURN QUERY
  WITH due AS (
    SELECT d.id
    FROM pm.notification_deliveries d
    WHERE ((d.status = 'pending' AND d.next_attempt_at <= now())
        OR (d.status = 'sending' AND coalesce(d.lease_expires_at, '-infinity') <= now()))
      AND (p_member_ids IS NULL OR d.member_id = ANY (p_member_ids))
    ORDER BY d.next_attempt_at, d.created_at
    LIMIT least(greatest(coalesce(p_limit, 25), 1), 100)
    FOR UPDATE SKIP LOCKED
  ), leased AS (
    UPDATE pm.notification_deliveries d
    SET status = 'sending', attempts = d.attempts + 1, lease_expires_at = now() + interval '2 minutes'
    FROM due WHERE d.id = due.id
    RETURNING d.id, d.channel, d.attempts, d.member_id, d.notification_id
  )
  SELECT l.id, l.channel, l.attempts, l.member_id, m.email, m.name, n.id, n.title, n.message, n.link, n.category
  FROM leased l
  JOIN pm.team_members m ON m.id = l.member_id
  JOIN pm.team_member_notifications n ON n.id = l.notification_id;
END;
$$;

REVOKE ALL ON FUNCTION pm.claim_notification_deliveries(integer, uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.claim_notification_deliveries(integer, uuid[]) TO service_role;

-- Records how one went: sent, skipped (and why: no email set up, no linked
-- chat), or failed, tried again after 1, then 5 minutes, failed for good
-- after the third try.
CREATE OR REPLACE FUNCTION pm.complete_notification_delivery(p_delivery_id uuid, p_outcome text, p_error text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  v_attempts integer;
  v_status text;
BEGIN
  IF p_outcome NOT IN ('sent', 'skipped', 'failed') THEN
    RAISE EXCEPTION 'outcome must be sent, skipped or failed' USING ERRCODE = 'check_violation';
  END IF;
  SELECT attempts INTO v_attempts FROM pm.notification_deliveries WHERE id = p_delivery_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  v_status := CASE WHEN p_outcome = 'failed' AND v_attempts < 3 THEN 'pending' ELSE p_outcome END;
  UPDATE pm.notification_deliveries
  SET status = v_status,
      last_error = CASE WHEN p_outcome = 'sent' THEN NULL ELSE left(p_error, 500) END,
      lease_expires_at = NULL,
      next_attempt_at = CASE WHEN v_status = 'pending' THEN now() + make_interval(mins => CASE WHEN v_attempts <= 1 THEN 1 ELSE 5 END) ELSE next_attempt_at END,
      finished_at = CASE WHEN v_status = 'pending' THEN NULL ELSE now() END
  WHERE id = p_delivery_id;
  RETURN v_status;
END;
$$;

REVOKE ALL ON FUNCTION pm.complete_notification_delivery(uuid, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.complete_notification_delivery(uuid, text, text) TO service_role;

-- pg_cron, every minute: asks the app to deliver while something is due.
-- Idle minutes make no request. Returns the pg_net request id, or null.
CREATE OR REPLACE FUNCTION pm.notification_delivery_kick()
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  app_url text;
  secret text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pm.notification_deliveries d
    WHERE (d.status = 'pending' AND d.next_attempt_at <= now())
       OR (d.status = 'sending' AND coalesce(d.lease_expires_at, '-infinity') <= now())
  ) THEN
    RETURN NULL;
  END IF;

  SELECT decrypted_secret INTO app_url FROM vault.decrypted_secrets WHERE name = 'pm_webhook_scheduler_url';
  SELECT decrypted_secret INTO secret FROM vault.decrypted_secrets WHERE name = 'pm_webhook_scheduler_secret';
  IF app_url IS NULL OR secret IS NULL THEN
    RAISE NOTICE 'webhook_scheduler_url or webhook_scheduler_secret is missing from Vault; notification emails and chats wait for the app';
    RETURN NULL;
  END IF;

  RETURN net.http_post(
    url := rtrim(app_url, '/') || '/api/internal/notifications/deliver',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || secret),
    body := '{"source":"pg_cron"}'::jsonb,
    timeout_milliseconds := 60000
  );
END;
$$;

REVOKE ALL ON FUNCTION pm.notification_delivery_kick() FROM PUBLIC, anon, authenticated, service_role;

-- Supabase only: skipped where pg_cron or pg_net is unavailable (PGlite).
-- Re-running cron.schedule updates the job in place.
DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron')
     AND EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_net') THEN
    CREATE EXTENSION IF NOT EXISTS pg_cron;
    CREATE EXTENSION IF NOT EXISTS pg_net;
    PERFORM cron.schedule('pm-notification-deliveries', '* * * * *', $job$SELECT pm.notification_delivery_kick();$job$);
  ELSE
    RAISE NOTICE 'pg_cron or pg_net is unavailable here; notification deliveries will not be kicked';
  END IF;
END;
$do$;

-- Blocked comments that wait on a member, newest first, at most 100. Same
-- audience as pm.my_blocked_runs, plus whoever made the task. Server only:
-- members read their own through pm.my_blocked_comments.
CREATE OR REPLACE FUNCTION pm.blocked_comments_for(p_member_id uuid)
RETURNS TABLE (
  comment_id uuid, task_id uuid, task_title text, project_id uuid,
  agent_id uuid, agent_name text, text text, created_at timestamptz
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT c.id, c.task_id, t.title, t.project_id, c.user_id, a.name, c.text, c.created_at
  FROM pm.task_comments c
  JOIN pm.tasks t ON t.id = c.task_id
  JOIN pm.team_members a ON a.id = c.user_id AND a.role = 'agent'
  WHERE c.blocked AND c.deleted_at IS NULL
    AND t.deleted_at IS NULL AND t.status <> 'done'
    AND t.status IS NOT DISTINCT FROM c.blocked_task_status
    AND pm.module_enabled('agents')
    AND p_member_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM pm.projects p WHERE p.id = t.project_id AND p.deleted_at IS NULL)
    -- Answered (a person wrote after it) or the agent wrote again: over.
    AND NOT EXISTS (
      SELECT 1 FROM pm.task_comments l
      JOIN pm.team_members w ON w.id = l.user_id
      WHERE l.task_id = c.task_id AND l.deleted_at IS NULL
        AND (l.created_at, l.id) > (c.created_at, c.id)
        AND (w.role <> 'agent' OR l.user_id = c.user_id))
    AND (pm.member_manages_agent(c.user_id, p_member_id)
      OR t.created_by = p_member_id
      OR EXISTS (SELECT 1 FROM pm.task_assignees ta WHERE ta.task_id = c.task_id AND ta.member_id = p_member_id))
  ORDER BY c.created_at DESC
  LIMIT 100
$$;

REVOKE ALL ON FUNCTION pm.blocked_comments_for(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.blocked_comments_for(uuid) TO service_role;

-- A notice that announces a blocked comment waiting on its reader: the
-- comment notice (or the agent's own message) about that task, while the
-- block is open. Needs you lists the block, so the notice is a receipt for
-- as long: never shown in Updates, never counted. Once answered it is an
-- update like any other.
CREATE OR REPLACE FUNCTION pm.notification_announces_block(
  p_member_id uuid, p_entity_type text, p_entity_id text, p_category text, p_actor_id uuid
) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  -- Looks at the one task the notice is about (the partial index below), with
  -- the same rules as pm.blocked_comments_for, so a feed pays one indexed
  -- probe per comment notice, never a scan of every comment.
  SELECT CASE
    WHEN p_entity_type IS DISTINCT FROM 'task' OR p_category NOT IN ('task_comments', 'agent_message') THEN false
    WHEN p_member_id IS NULL OR p_entity_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN false
    WHEN NOT pm.module_enabled('agents') THEN false
    ELSE EXISTS (
      SELECT 1
      FROM pm.task_comments c
      JOIN pm.tasks t ON t.id = c.task_id
      JOIN pm.team_members a ON a.id = c.user_id AND a.role = 'agent'
      WHERE c.task_id = p_entity_id::uuid
        AND c.blocked AND c.deleted_at IS NULL
        AND (p_actor_id IS NULL OR p_actor_id = c.user_id)
        AND t.deleted_at IS NULL AND t.status <> 'done'
        AND t.status IS NOT DISTINCT FROM c.blocked_task_status
        AND EXISTS (SELECT 1 FROM pm.projects p WHERE p.id = t.project_id AND p.deleted_at IS NULL)
        AND NOT EXISTS (
          SELECT 1 FROM pm.task_comments l
          JOIN pm.team_members w ON w.id = l.user_id
          WHERE l.task_id = c.task_id AND l.deleted_at IS NULL
            AND (l.created_at, l.id) > (c.created_at, c.id)
            AND (w.role <> 'agent' OR l.user_id = c.user_id))
        AND (pm.member_manages_agent(c.user_id, p_member_id)
          OR t.created_by = p_member_id
          OR EXISTS (SELECT 1 FROM pm.task_assignees ta WHERE ta.task_id = c.task_id AND ta.member_id = p_member_id)))
  END
$$;

-- Open blocked comments by task: what the receipt check and Needs you read.
CREATE INDEX IF NOT EXISTS idx_task_comments_blocked_open ON pm.task_comments (task_id) WHERE blocked AND deleted_at IS NULL;

REVOKE ALL ON FUNCTION pm.notification_announces_block(uuid, text, text, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_announces_block(uuid, text, text, text, uuid) TO service_role;

-- The Updates list the API pages by offset: the rows the app lists for a
-- view (updates, unread or done), narrowed by category, entity type or
-- read, newest first, with how many match in all (total, on every row).
CREATE OR REPLACE FUNCTION pm.notification_updates_list(
  p_member_id uuid,
  p_view text,
  p_category text DEFAULT NULL,
  p_entity_type text DEFAULT NULL,
  p_is_read boolean DEFAULT NULL,
  p_limit integer DEFAULT 25,
  p_offset integer DEFAULT 0
) RETURNS TABLE (item jsonb, total integer)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  WITH listed AS (
    SELECT n.*
    FROM pm.team_member_notifications n
    WHERE n.user_id = p_member_id
      AND n.cleared_at IS NULL
      AND NOT pm.notification_is_receipt(n.category)
      AND NOT pm.notification_announces_block(n.user_id, n.entity_type, n.entity_id, n.category, n.actor_id)
      AND CASE p_view
        WHEN 'done' THEN n.done_at IS NOT NULL
        WHEN 'unread' THEN n.done_at IS NULL AND NOT n.is_read
        ELSE n.done_at IS NULL
      END
      AND (p_category IS NULL OR n.category = p_category)
      AND (p_entity_type IS NULL OR n.entity_type = p_entity_type)
      AND (p_is_read IS NULL OR n.is_read = p_is_read)
      AND NOT EXISTS (
        SELECT 1 FROM pm.member_snoozes s
        WHERE s.member_id = p_member_id AND s.item_kind = 'notification' AND s.item_id = n.id AND s.until > now()
      )
  )
  SELECT to_jsonb(l), (count(*) OVER ())::integer
  FROM listed l
  ORDER BY CASE WHEN p_view = 'done' THEN l.done_at ELSE l.created_at END DESC, l.id DESC
  LIMIT least(greatest(coalesce(p_limit, 25), 1), 100)
  OFFSET greatest(coalesce(p_offset, 0), 0)
$$;

REVOKE ALL ON FUNCTION pm.notification_updates_list(uuid, text, text, text, boolean, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pm.notification_updates_list(uuid, text, text, text, boolean, integer, integer) TO service_role;

-- ============================================================
-- CLEANUP PROJECTS: GROUPS IN TRASH (20261127003700_cleanup_projects.sql)
-- ============================================================
-- Cleanup of the work screens: groups join Trash.
--
-- A group moved to Trash (DELETE /api/v1/groups/{id}, the trash_group tool,
-- the group page) is listed in Settings > Trash and comes back with Restore
-- (POST /api/v1/trash/groups/{id}/restore, restore_from_trash), exactly as it
-- was: its members, leads, owned agents, audiences, inbox handling and
-- initiatives are rows that Trash never touches. Only an Owner or someone
-- with groups.manage moves or restores one (can_trash_record). A restore is
-- refused while another live group uses its short name or outside id.
--
-- While it is in Trash a group grants nothing. Every grant already reads
-- only live groups (agent audiences, who manages an agent, inbox access);
-- this also leaves trashed groups out of who hears about an agent
-- (agent_people_to_tell) and of an initiative's webhook members.
-- Questions already asked to it stay answerable by its members.
--
-- Replaces trash_record_types, can_trash_record, trash_restore_blocker,
-- trash_entity_type, list_trash, agent_people_to_tell and
-- initiative_webhook_members with their newest bodies plus the group rule,
-- and adds the Trash live-sync trigger on pm.groups. No new functions; each
-- keeps the grants it has (CREATE OR REPLACE leaves them as they are). Additive and safe to run twice. The previous
-- release's code still moves groups to Trash with its own update and never
-- lists or restores them.

CREATE OR REPLACE FUNCTION pm.trash_record_types()
RETURNS text[]
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT ARRAY[
    'projects', 'tasks', 'task_comments', 'reminders', 'project_credentials',
    'entity_files', 'portal_updates', 'portal_update_attachments', 'contacts', 'leads',
    'lead_interactions', 'lead_proposals', 'lead_fields',
    'project_time_entries', 'project_invoices', 'invoice_payments', 'project_hourly_rates',
    'project_retainers', 'project_retainer_amounts', 'task_files', 'task_templates',
    'initiatives', 'initiative_entries', 'groups'
  ]
$$;

CREATE OR REPLACE FUNCTION pm.can_trash_record(p_table text, p_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  me uuid := pm.current_team_member_id();
  allowed boolean := false;
BEGIN
  IF me IS NULL THEN
    RETURN false;
  END IF;
  CASE p_table
    WHEN 'projects' THEN
      SELECT pm.has_permission('projects.manage') AND (
        pm.has_permission('projects.read_all')
        OR EXISTS (SELECT 1 FROM pm.project_members WHERE project_id = p_id AND member_id = me)
      ) INTO allowed;
    WHEN 'tasks' THEN
      -- A subtask can also go by whoever manages its parent as an assignee.
      SELECT pm.can_access_project(project_id) AND (
        pm.has_permission('tasks.manage_all') OR (
          parent_task_id IS NOT NULL AND pm.has_permission('tasks.manage_assigned') AND EXISTS (
            SELECT 1 FROM pm.task_assignees assignment
            WHERE assignment.task_id = tasks.parent_task_id AND assignment.member_id = me
          )
        )
      ) INTO allowed FROM pm.tasks WHERE id = p_id;
    WHEN 'task_comments' THEN
      SELECT pm.can_access_task(task_id) AND (user_id = me OR pm.has_permission('tasks.manage_all'))
      INTO allowed FROM pm.task_comments WHERE id = p_id;
    WHEN 'task_files' THEN
      SELECT pm.can_access_task(task_id) AND (added_by = me OR pm.has_permission('files.manage'))
      INTO allowed FROM pm.task_files WHERE id = p_id;
    WHEN 'reminders' THEN
      SELECT pm.can_see_reminder(owner_id, project_id, task_id)
        AND (owner_id = me OR created_by = me OR pm.has_permission('tasks.manage_all'))
      INTO allowed FROM pm.reminders WHERE id = p_id;
    WHEN 'project_credentials' THEN
      SELECT pm.has_permission('credentials.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_credentials WHERE id = p_id;
    WHEN 'entity_files' THEN
      SELECT pm.can_access_file_entity(entity_type, entity_id) AND (
        pm.has_permission('files.manage') OR (uploaded_by = me AND visibility = 'internal')
      ) INTO allowed FROM pm.entity_files WHERE id = p_id;
    WHEN 'portal_updates' THEN
      SELECT pm.has_permission('portal.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.portal_updates WHERE id = p_id;
    WHEN 'portal_update_attachments' THEN
      SELECT pm.has_permission('portal.manage') AND pm.can_access_project(update_row.project_id)
      INTO allowed
      FROM pm.portal_update_attachments attachment
      JOIN pm.portal_updates update_row ON update_row.id = attachment.update_id
      WHERE attachment.id = p_id AND update_row.deleted_at IS NULL;
    WHEN 'contacts' THEN
      SELECT pm.has_permission('contacts.manage') INTO allowed;
    WHEN 'leads' THEN
      SELECT pm.has_permission('leads.manage') INTO allowed;
    WHEN 'lead_interactions' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_interactions WHERE id = p_id;
    WHEN 'lead_proposals' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_proposals WHERE id = p_id;
    WHEN 'lead_fields' THEN
      SELECT pm.has_permission('leads.manage') AND pm.can_access_lead(lead_id)
      INTO allowed FROM pm.lead_fields WHERE id = p_id;
    WHEN 'project_time_entries' THEN
      SELECT pm.can_access_project(project_id) AND (
        pm.has_permission('time.manage_all') OR (
          pm.has_permission('time.manage_own')
          AND member_id = me
          AND approval_status IN ('draft', 'pending', 'rejected')
        )
      ) INTO allowed FROM pm.project_time_entries WHERE id = p_id;
    WHEN 'project_invoices' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_invoices WHERE id = p_id;
    WHEN 'invoice_payments' THEN
      -- People remove only payments recorded by hand, as remove_invoice_payment.
      SELECT (pm.has_permission('invoices.record_payments') OR pm.has_permission('invoices.manage'))
        AND pm.can_access_project(invoice.project_id)
        AND invoice.deleted_at IS NULL
        AND payment.recorded_via = 'app'
      INTO allowed
      FROM pm.invoice_payments payment
      JOIN pm.project_invoices invoice ON invoice.id = payment.invoice_id
      WHERE payment.id = p_id;
    WHEN 'project_hourly_rates' THEN
      SELECT pm.has_permission('billing.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_hourly_rates WHERE id = p_id;
    WHEN 'project_retainers' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(project_id)
      INTO allowed FROM pm.project_retainers WHERE id = p_id;
    WHEN 'project_retainer_amounts' THEN
      SELECT pm.has_permission('invoices.manage') AND pm.can_access_project(retainer.project_id)
        AND retainer.deleted_at IS NULL
      INTO allowed
      FROM pm.project_retainer_amounts amount
      JOIN pm.project_retainers retainer ON retainer.id = amount.retainer_id
      WHERE amount.id = p_id;
    WHEN 'task_templates' THEN
      -- Company-wide: templates.manage. A project's: whoever manages the
      -- project (projects.manage) or templates.manage, on a project they can open.
      SELECT CASE
          WHEN task_templates.project_id IS NULL THEN pm.has_permission('templates.manage')
          ELSE pm.can_access_project(task_templates.project_id)
            AND (pm.has_permission('templates.manage') OR pm.has_permission('projects.manage'))
        END
      INTO allowed FROM pm.task_templates WHERE id = p_id;
    WHEN 'initiatives' THEN
      -- Whoever manages projects, or whoever made it, on a project they can open.
      SELECT pm.can_access_project(project_id) AND (pm.has_permission('projects.manage') OR created_by = me)
      INTO allowed FROM pm.initiatives WHERE id = p_id;
    WHEN 'initiative_entries' THEN
      -- Its author, or whoever manages projects, while they may read the log.
      SELECT pm.can_access_project(project_id) AND pm.has_permission('tasks.read')
        AND coalesce(pm.current_team_member_role(), '') <> 'guest'
        AND (created_by = me OR pm.has_permission('projects.manage'))
      INTO allowed FROM pm.initiative_entries WHERE id = p_id;
    WHEN 'groups' THEN
      -- An Owner or whoever holds Manage groups, as the groups routes.
      SELECT pm.has_permission('groups.manage') AND EXISTS (SELECT 1 FROM pm.groups WHERE id = p_id) INTO allowed;
    ELSE
      allowed := false;
  END CASE;
  RETURN coalesce(allowed, false);
END;
$$;

CREATE OR REPLACE FUNCTION pm.trash_restore_blocker(p_table text, p_id uuid)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  project_gone boolean := false;
  task_gone boolean := false;
  lead_gone boolean := false;
  parent_gone boolean := false;
  payment pm.invoice_payments;
  invoice pm.project_invoices;
  v_number text;
BEGIN
  CASE p_table
    WHEN 'tasks' THEN
      -- A subtask comes back after its parent.
      SELECT p.deleted_at IS NOT NULL, coalesce(parent.deleted_at IS NOT NULL, false) INTO project_gone, task_gone
      FROM pm.tasks t JOIN pm.projects p ON p.id = t.project_id
      LEFT JOIN pm.tasks parent ON parent.id = t.parent_task_id
      WHERE t.id = p_id;
    WHEN 'task_comments', 'task_files' THEN
      EXECUTE format('SELECT t.deleted_at IS NOT NULL OR coalesce(parent.deleted_at IS NOT NULL, false), p.deleted_at IS NOT NULL
        FROM pm.%I c JOIN pm.tasks t ON t.id = c.task_id JOIN pm.projects p ON p.id = t.project_id
        LEFT JOIN pm.tasks parent ON parent.id = t.parent_task_id
        WHERE c.id = $1', p_table)
      INTO task_gone, project_gone USING p_id;
    WHEN 'reminders' THEN
      SELECT coalesce(t.deleted_at IS NOT NULL OR parent.deleted_at IS NOT NULL, false), coalesce(p.deleted_at IS NOT NULL, false)
      INTO task_gone, project_gone
      FROM pm.reminders r
      LEFT JOIN pm.tasks t ON t.id = r.task_id
      LEFT JOIN pm.tasks parent ON parent.id = t.parent_task_id
      LEFT JOIN pm.projects p ON p.id = r.project_id
      WHERE r.id = p_id;
    WHEN 'project_credentials', 'portal_updates', 'project_time_entries', 'project_invoices',
         'project_hourly_rates', 'project_retainers', 'task_templates', 'initiatives' THEN
      EXECUTE format('SELECT p.deleted_at IS NOT NULL FROM pm.%I c
        JOIN pm.projects p ON p.id = c.project_id WHERE c.id = $1', p_table)
      INTO project_gone USING p_id;
    WHEN 'portal_update_attachments' THEN
      SELECT u.deleted_at IS NOT NULL INTO parent_gone
      FROM pm.portal_update_attachments a JOIN pm.portal_updates u ON u.id = a.update_id WHERE a.id = p_id;
      IF parent_gone THEN
        RETURN 'Restore the portal update it belongs to first.';
      END IF;
    WHEN 'invoice_payments' THEN
      SELECT p.deleted_at IS NOT NULL, i.deleted_at IS NOT NULL INTO project_gone, parent_gone
      FROM pm.invoice_payments pay
      JOIN pm.project_invoices i ON i.id = pay.invoice_id
      JOIN pm.projects p ON p.id = i.project_id
      WHERE pay.id = p_id;
      IF parent_gone AND NOT project_gone THEN
        RETURN 'Restore the invoice it belongs to first.';
      END IF;
    WHEN 'project_retainer_amounts' THEN
      SELECT p.deleted_at IS NOT NULL, r.deleted_at IS NOT NULL INTO project_gone, parent_gone
      FROM pm.project_retainer_amounts a
      JOIN pm.project_retainers r ON r.id = a.retainer_id
      JOIN pm.projects p ON p.id = r.project_id
      WHERE a.id = p_id;
      IF parent_gone AND NOT project_gone THEN
        RETURN 'Restore the retainer it belongs to first.';
      END IF;
    WHEN 'initiative_entries' THEN
      SELECT p.deleted_at IS NOT NULL, i.deleted_at IS NOT NULL INTO project_gone, parent_gone
      FROM pm.initiative_entries e
      JOIN pm.initiatives i ON i.id = e.initiative_id
      JOIN pm.projects p ON p.id = e.project_id
      WHERE e.id = p_id;
      IF parent_gone AND NOT project_gone THEN
        RETURN 'Restore the initiative it belongs to first.';
      END IF;
    WHEN 'entity_files' THEN
      SELECT CASE f.entity_type
          WHEN 'project' THEN EXISTS (SELECT 1 FROM pm.projects WHERE id = f.entity_id AND deleted_at IS NOT NULL)
          WHEN 'lead' THEN EXISTS (SELECT 1 FROM pm.leads WHERE id = f.entity_id AND deleted_at IS NOT NULL)
          WHEN 'contact' THEN EXISTS (SELECT 1 FROM pm.contacts WHERE id = f.entity_id AND deleted_at IS NOT NULL)
          ELSE false
        END
      INTO parent_gone
      FROM pm.entity_files f WHERE f.id = p_id;
      IF parent_gone THEN
        RETURN 'Restore the project, lead or contact this file belongs to first.';
      END IF;
    WHEN 'lead_interactions', 'lead_proposals', 'lead_fields' THEN
      EXECUTE format('SELECT l.deleted_at IS NOT NULL FROM pm.%I c
        JOIN pm.leads l ON l.id = c.lead_id WHERE c.id = $1', p_table)
      INTO lead_gone USING p_id;
    ELSE
      NULL;
  END CASE;
  IF coalesce(project_gone, false) THEN
    RETURN 'Restore the project it belongs to first.';
  ELSIF coalesce(task_gone, false) THEN
    RETURN 'Restore the task it belongs to first.';
  ELSIF coalesce(lead_gone, false) THEN
    RETURN 'Restore the lead it belongs to first.';
  END IF;

  -- Clashes with what was added while it was in Trash.
  CASE p_table
    WHEN 'project_time_entries' THEN
      IF EXISTS (
        SELECT 1 FROM pm.project_time_entries entry
        JOIN pm.project_time_entries other
          ON other.project_id = entry.project_id AND other.member_id = entry.member_id AND other.id <> entry.id
        WHERE entry.id = p_id AND entry.end_time IS NULL
          AND other.end_time IS NULL AND other.deleted_at IS NULL
      ) THEN
        RETURN 'This timer is still running and a newer one is running on the same project. Stop that one first.';
      END IF;
    WHEN 'project_invoices' THEN
      SELECT * INTO invoice FROM pm.project_invoices WHERE id = p_id;
      IF invoice.status <> 'cancelled' THEN
        SELECT other.invoice_number INTO v_number
        FROM pm.invoice_time_entry_allocations mine
        JOIN pm.invoice_time_entry_allocations theirs
          ON theirs.time_entry_id = mine.time_entry_id AND theirs.invoice_id <> mine.invoice_id
        JOIN pm.project_invoices other ON other.id = theirs.invoice_id
        WHERE mine.invoice_id = p_id AND other.status <> 'cancelled' AND other.deleted_at IS NULL
          AND mine.start_offset_hours < theirs.start_offset_hours + theirs.allocated_hours - 0.000001
          AND theirs.start_offset_hours < mine.start_offset_hours + mine.allocated_hours - 0.000001
        LIMIT 1;
        IF FOUND THEN
          RETURN 'Some of its hours are on invoice ' || v_number || ' now. Take them off that invoice first.';
        END IF;
        IF EXISTS (
          SELECT 1 FROM pm.invoice_time_entry_allocations allocation
          JOIN pm.project_time_entries entry ON entry.id = allocation.time_entry_id
          WHERE allocation.invoice_id = p_id AND entry.deleted_at IS NOT NULL
        ) THEN
          RETURN 'Some of its time is in Trash. Restore that time first.';
        END IF;
        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements(COALESCE(NULLIF(invoice.line_items, 'null'::jsonb), '[]'::jsonb)) line
          JOIN pm.project_retainers retainer ON retainer.id::text = line.value->>'retainer_id' AND retainer.deleted_at IS NULL
          JOIN pm.project_retainer_periods handled
            ON handled.retainer_id = retainer.id
           AND handled.period_start = GREATEST(date_trunc('month', (line.value->>'service_start_date')::date)::date, retainer.start_date)
          WHERE COALESCE(line.value->>'service_start_date', '') ~ '^\d{4}-\d{2}-\d{2}$'
            AND handled.status = 'invoiced' AND handled.invoice_id IS NOT NULL AND handled.invoice_id <> p_id
        ) THEN
          RETURN 'Its retainer period is on another invoice now.';
        END IF;
      END IF;
      -- Paid hours that are not linked to time entries cannot be checked
      -- against what was billed since; counting them again would under-bill.
      IF invoice.status = 'paid'
         AND (
           (jsonb_array_length(COALESCE(NULLIF(invoice.line_items, 'null'::jsonb), '[]'::jsonb)) = 0 AND invoice.invoice_type = 'hourly'
            AND NOT EXISTS (SELECT 1 FROM pm.invoice_time_entry_allocations a WHERE a.invoice_id = p_id))
           OR EXISTS (
             SELECT 1 FROM jsonb_array_elements(COALESCE(NULLIF(invoice.line_items, 'null'::jsonb), '[]'::jsonb)) line
             WHERE line.value->>'item_type' = 'hourly'
               AND NOT EXISTS (SELECT 1 FROM pm.invoice_time_entry_allocations a
                               WHERE a.invoice_id = p_id AND a.line_item_id = line.value->>'id')
           )
         )
         AND EXISTS (
           SELECT 1 FROM pm.project_invoices other
           WHERE other.project_id = invoice.project_id AND other.id <> p_id AND other.deleted_at IS NULL
             AND other.status <> 'cancelled' AND other.created_at > invoice.deleted_at
             AND (other.invoice_type = 'hourly' OR EXISTS (
               SELECT 1 FROM jsonb_array_elements(COALESCE(NULLIF(other.line_items, 'null'::jsonb), '[]'::jsonb)) line
               WHERE line.value->>'item_type' = 'hourly'))
         ) THEN
        RETURN 'Hours were invoiced after this invoice went to Trash, and its own hours are not linked to time entries, so restoring it could count hours twice. Check the hourly invoices first.';
      END IF;
    WHEN 'project_hourly_rates' THEN
      IF EXISTS (
        SELECT 1 FROM pm.project_hourly_rates rate
        JOIN pm.project_hourly_rates other
          ON other.project_id = rate.project_id AND other.effective_at = rate.effective_at AND other.id <> rate.id
        WHERE rate.id = p_id AND other.deleted_at IS NULL
      ) THEN
        RETURN 'Another rate now starts at the same time. Change or delete that one first.';
      END IF;
    WHEN 'lead_fields' THEN
      IF EXISTS (
        SELECT 1 FROM pm.lead_fields field
        JOIN pm.lead_fields other
          ON other.lead_id = field.lead_id AND other.field_key = field.field_key AND other.id <> field.id
        WHERE field.id = p_id AND other.deleted_at IS NULL
      ) THEN
        RETURN 'This field has been set again since. Change or delete that one first.';
      END IF;
    WHEN 'project_retainer_amounts' THEN
      IF EXISTS (
        SELECT 1 FROM pm.project_retainer_amounts amount
        JOIN pm.project_retainer_amounts other
          ON other.retainer_id = amount.retainer_id AND other.effective_date = amount.effective_date AND other.id <> amount.id
        WHERE amount.id = p_id AND other.deleted_at IS NULL
      ) THEN
        RETURN 'Another amount now starts on the same date. Change or delete that one first.';
      END IF;
    WHEN 'invoice_payments' THEN
      SELECT * INTO payment FROM pm.invoice_payments WHERE id = p_id;
      SELECT * INTO invoice FROM pm.project_invoices WHERE id = payment.invoice_id;
      IF invoice.status NOT IN ('sent', 'overdue', 'paid') THEN
        RETURN 'Its invoice is ' || invoice.status || ' now, so it cannot take a payment.';
      END IF;
      IF payment.amount > pm.invoice_total(invoice) - COALESCE((
        SELECT sum(other.amount) FROM pm.invoice_payments other
        WHERE other.invoice_id = invoice.id AND other.deleted_at IS NULL
      ), 0) + 0.005 THEN
        RETURN 'Its invoice no longer has enough outstanding for this payment.';
      END IF;
      IF payment.external_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM pm.invoice_payments other
        WHERE other.invoice_id = payment.invoice_id AND other.external_id = payment.external_id
          AND other.deleted_at IS NULL AND other.id <> payment.id
      ) THEN
        RETURN 'This payment was recorded again after it was removed.';
      END IF;
    WHEN 'groups' THEN
      -- Its short name or outside id was taken while it was in Trash.
      IF EXISTS (
        SELECT 1 FROM pm.groups g JOIN pm.groups other ON other.id <> g.id AND other.deleted_at IS NULL
          AND (other.slug = g.slug OR (g.external_id IS NOT NULL AND other.external_id = g.external_id))
        WHERE g.id = p_id
      ) THEN
        RETURN 'Another group now uses its short name. Rename that one first.';
      END IF;
    ELSE
      NULL;
  END CASE;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION pm.trash_entity_type(p_table text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE p_table
    WHEN 'projects' THEN 'project'
    WHEN 'tasks' THEN 'task'
    WHEN 'task_subtasks' THEN 'subtask'
    WHEN 'task_comments' THEN 'comment'
    WHEN 'task_files' THEN 'task_file'
    WHEN 'reminders' THEN 'reminder'
    WHEN 'project_credentials' THEN 'credential'
    WHEN 'entity_files' THEN 'entity_file'
    WHEN 'portal_updates' THEN 'portal_update'
    WHEN 'portal_update_attachments' THEN 'portal_update_attachment'
    WHEN 'contacts' THEN 'contact'
    WHEN 'leads' THEN 'lead'
    WHEN 'lead_interactions' THEN 'lead_interaction'
    WHEN 'lead_proposals' THEN 'lead_proposal'
    WHEN 'lead_fields' THEN 'lead_field'
    WHEN 'project_time_entries' THEN 'time_entry'
    WHEN 'project_invoices' THEN 'invoice'
    WHEN 'invoice_payments' THEN 'invoice_payment'
    WHEN 'project_hourly_rates' THEN 'project_hourly_rate'
    WHEN 'project_retainers' THEN 'retainer'
    WHEN 'project_retainer_amounts' THEN 'retainer_amount'
    WHEN 'task_templates' THEN 'task_template'
    WHEN 'initiatives' THEN 'initiative'
    WHEN 'initiative_entries' THEN 'initiative_entry'
    WHEN 'groups' THEN 'group'
    ELSE p_table
  END
$$;

CREATE OR REPLACE FUNCTION pm.list_trash(p_types text[] DEFAULT NULL, p_limit integer DEFAULT 500)
RETURNS TABLE (
  record_type text,
  id uuid,
  label text,
  context text,
  project_id uuid,
  deleted_at timestamptz,
  deleted_by uuid,
  deleted_by_name text,
  blocker text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
DECLARE
  spec record;
  is_service boolean := coalesce(auth.role(), '') = 'service_role';
BEGIN
  IF NOT is_service AND pm.current_team_member_id() IS NULL THEN
    RETURN;
  END IF;
  FOR spec IN
    SELECT * FROM (VALUES
      ('projects', 'r.name', 'NULL', 'r.id', ''),
      ('tasks', 'r.title', 'CASE WHEN parent.id IS NULL THEN p.name ELSE ''Subtask of '' || parent.title END', 'r.project_id',
        'LEFT JOIN pm.projects p ON p.id = r.project_id LEFT JOIN pm.tasks parent ON parent.id = r.parent_task_id'),
      ('task_comments', 'left(r.text, 120)', 't.title', 't.project_id', 'LEFT JOIN pm.tasks t ON t.id = r.task_id'),
      ('task_files', 'r.name', 't.title', 't.project_id', 'LEFT JOIN pm.tasks t ON t.id = r.task_id'),
      ('task_templates', 'r.name', 'coalesce(p.name, ''Task templates'')', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('initiatives', 'r.name', 'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('initiative_entries', 'r.title', 'i.name', 'r.project_id', 'LEFT JOIN pm.initiatives i ON i.id = r.initiative_id'),
      ('reminders', 'r.title', 'coalesce(t.title, p.name)', 'r.project_id',
        'LEFT JOIN pm.tasks t ON t.id = r.task_id LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('project_credentials', 'r.label', 'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('entity_files', 'r.name',
        'CASE r.entity_type WHEN ''project'' THEN (SELECT name FROM pm.projects WHERE id = r.entity_id)
           WHEN ''lead'' THEN (SELECT name FROM pm.leads WHERE id = r.entity_id)
           WHEN ''contact'' THEN (SELECT name FROM pm.contacts WHERE id = r.entity_id) END',
        'CASE WHEN r.entity_type = ''project'' THEN r.entity_id END', ''),
      ('portal_updates', 'r.title', 'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('portal_update_attachments', 'r.name', 'u.title', 'u.project_id', 'LEFT JOIN pm.portal_updates u ON u.id = r.update_id'),
      ('contacts', 'r.name', 'NULL', 'NULL', ''),
      ('leads', 'r.name', 'NULL', 'NULL', ''),
      ('lead_interactions', 'r.title', 'l.name', 'NULL', 'LEFT JOIN pm.leads l ON l.id = r.lead_id'),
      ('lead_proposals', 'r.title', 'l.name', 'NULL', 'LEFT JOIN pm.leads l ON l.id = r.lead_id'),
      ('lead_fields', 'r.field_key || '': '' || left(r.value, 80)', 'l.name', 'NULL', 'LEFT JOIN pm.leads l ON l.id = r.lead_id'),
      ('project_time_entries',
        'coalesce(nullif(btrim(r.description), ''''), ''Time entry'') || '' ('' || to_char(r.start_time AT TIME ZONE pm.workspace_timezone(), ''Mon FMDD, YYYY'') || '')''',
        'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('project_invoices', 'r.invoice_number || '' ('' || pm.format_money(r.amount, r.currency, true) || '')''', 'p.name', 'r.project_id',
        'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('invoice_payments', '''Payment of '' || pm.format_money(r.amount, i.currency, true) || '' on '' || i.invoice_number', 'p.name', 'i.project_id',
        'LEFT JOIN pm.project_invoices i ON i.id = r.invoice_id LEFT JOIN pm.projects p ON p.id = i.project_id'),
      ('project_hourly_rates', 'pm.format_money(r.hourly_rate, NULL, true) || ''/hr from '' || to_char(r.effective_at AT TIME ZONE pm.workspace_timezone(), ''Mon FMDD, YYYY'')',
        'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('project_retainers', 'r.name', 'p.name', 'r.project_id', 'LEFT JOIN pm.projects p ON p.id = r.project_id'),
      ('project_retainer_amounts', 'rt.name || '': '' || pm.format_money(r.amount, rt.currency, true) || '' from '' || to_char(r.effective_date, ''Mon FMDD, YYYY'')',
        'p.name', 'rt.project_id',
        'LEFT JOIN pm.project_retainers rt ON rt.id = r.retainer_id LEFT JOIN pm.projects p ON p.id = rt.project_id'),
      ('groups', 'r.name', '''Team groups''', 'NULL', '')
    ) AS specs(record_type, label_sql, context_sql, project_sql, join_sql)
  LOOP
    CONTINUE WHEN p_types IS NOT NULL AND NOT spec.record_type = ANY (p_types);
    RETURN QUERY EXECUTE format(
      'SELECT %L::text, r.id, (%s)::text, (%s)::text, (%s)::uuid, r.deleted_at, r.deleted_by, m.name::text,
              pm.trash_restore_blocker(%L, r.id)
       FROM pm.%I r %s
       LEFT JOIN pm.team_members m ON m.id = r.deleted_by
       WHERE r.deleted_at IS NOT NULL AND ($1 OR pm.can_trash_record(%L, r.id))
       ORDER BY r.deleted_at DESC
       LIMIT %s',
      spec.record_type, spec.label_sql, spec.context_sql, spec.project_sql, spec.record_type,
      spec.record_type, spec.join_sql, spec.record_type, greatest(1, least(coalesce(p_limit, 500), 2000)))
    USING is_service;
  END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION pm.agent_people_to_tell(p_agent_id uuid)
RETURNS uuid[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  WITH named AS (
    SELECT o.member_id AS id FROM pm.agent_owners o WHERE o.agent_id = p_agent_id
    UNION
    SELECT gm.member_id FROM pm.agent_owner_groups g
    JOIN pm.groups owning ON owning.id = g.group_id AND owning.deleted_at IS NULL
    JOIN pm.group_members gm ON gm.group_id = g.group_id
    WHERE g.agent_id = p_agent_id
    UNION
    SELECT a.delegate_of FROM pm.team_members a WHERE a.id = p_agent_id AND a.delegate_of IS NOT NULL
  ), people AS (
    SELECT m.id FROM named JOIN pm.team_members m ON m.id = named.id
    WHERE m.role <> 'agent' AND coalesce(m.status, 'active') = 'active'
  )
  SELECT coalesce(
    (SELECT array_agg(id ORDER BY id) FROM people),
    (SELECT array_agg(m.id ORDER BY m.id) FROM pm.team_members m WHERE m.role = 'owner' AND coalesce(m.status, 'active') = 'active'),
    '{}'
  )
$$;

CREATE OR REPLACE FUNCTION pm.initiative_webhook_members(p_initiative pm.initiatives, p_also uuid[] DEFAULT '{}')
RETURNS uuid[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pm
AS $$
  SELECT coalesce(array_agg(DISTINCT m ORDER BY m) FILTER (WHERE m IS NOT NULL), '{}')
  FROM (
    SELECT p_initiative.owner_member_id AS m
    UNION ALL SELECT p_initiative.created_by
    UNION ALL SELECT gm.member_id FROM pm.group_members gm
      JOIN pm.groups g ON g.id = gm.group_id AND g.deleted_at IS NULL
      WHERE gm.group_id = p_initiative.owner_group_id
    UNION ALL SELECT unnest(coalesce(p_also, '{}'))
  ) members
$$;


DROP TRIGGER IF EXISTS record_trash_event ON pm.groups;
CREATE TRIGGER record_trash_event AFTER UPDATE OF deleted_at ON pm.groups
  FOR EACH ROW WHEN (OLD.deleted_at IS DISTINCT FROM NEW.deleted_at)
  EXECUTE FUNCTION pm.record_trash_event();

-- ============================================================
-- CHAT ANSWERS (20261127004100_chat_answers.sql)
-- ============================================================
-- Answering from chat: a question or approval the app delivers to a
-- person's own chat (Telegram, Slack) carries buttons (Approve and Reject,
-- or the question's choices); pressing one answers it as that person.
--
-- - pm.chat_answer_tokens: one row per button. The provider sends back only
--   the token; the row holds its hash, the question, the person, the choice,
--   the connection and the message it is on. Every button of one message
--   shares a batch, and pressing any one uses the whole batch: single use.
--   A token ends with the question or after 7 days (expires_at), checked
--   when pressed (no job runs). Server only.
-- - questions.decided_via gains chat: an approval decided with a button in
--   the person's own chat, checked as it would be in the app.
--
-- Additive and safe to run twice. The previous release's code never sends
-- buttons and never reads the table.

ALTER TABLE pm.questions DROP CONSTRAINT IF EXISTS questions_decided_via_check;
ALTER TABLE pm.questions
  ADD CONSTRAINT questions_decided_via_check CHECK (
    decided_via IS NULL OR (decided_via IN ('app', 'api_key', 'agent', 'act_for', 'chat') AND kind = 'approval')
  );

COMMENT ON COLUMN pm.questions.decided_via IS
  'How an approval was decided: app (signed in), api_key (the person''s own key with approvals.decide), agent (the agent asked, with its own key), act_for (an agent acting for the person, with approvals.decide on its key and held by the person) or chat (the person, with a button on the app''s message in their own linked chat). Null on a plain question, an open approval, or one decided before this was recorded.';

CREATE TABLE IF NOT EXISTS pm.chat_answer_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  batch uuid NOT NULL,
  question_id uuid NOT NULL REFERENCES pm.questions(id) ON DELETE CASCADE,
  member_id uuid NOT NULL REFERENCES pm.team_members(id) ON DELETE CASCADE,
  connection_id uuid NOT NULL REFERENCES pm.chat_connections(id) ON DELETE CASCADE,
  choice text NOT NULL CHECK (char_length(choice) BETWEEN 1 AND 200),
  conversation_id text,
  external_message_id text,
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE pm.chat_answer_tokens IS
  'Answer buttons on the app''s chat messages: one per button, the token hashed, single use per message (batch), bound to the question, the person, the choice and the connection.';

CREATE INDEX IF NOT EXISTS idx_chat_answer_tokens_batch ON pm.chat_answer_tokens (batch);
CREATE INDEX IF NOT EXISTS idx_chat_answer_tokens_question ON pm.chat_answer_tokens (question_id);

ALTER TABLE pm.chat_answer_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pm.chat_answer_tokens FROM PUBLIC, anon, authenticated;
GRANT ALL ON pm.chat_answer_tokens TO service_role;
